DEMO_DIVS = [(482, "RU0009029540", 34.84), (117, "RU0009029540", 37.0), (330, "RU0009024277", 541.0), (150, "RU0009024277", 514.0)]
# (дней назад, сумма) — пополнения счёта
DEMO_DEPOSITS = [(730, 1800000)]   # дальше счёт досыпается автоматически, когда не хватает на покупку


def _demo_fmt(x, nd=2):
    return ("%." + str(nd) + "f") % x if x is not None else ""


def demo_rows(today=None):
    """Строки отчёта: [дата, тип, ISIN, тикер, название, кол-во, цена, сумма, валюта, комиссия, НКД] — по возрастанию даты."""
    today = today or date.today()
    info = {i[0]: i for i in DEMO_INSTRUMENTS}
    day = lambda n: today - timedelta(days=n)
    ev = []   # (дата, порядок, строка)

    def nkd_at(isin, d):
        _, _, _, _, cv, per, last = info[isin]
        ago = (today - d).days
        k = 0
        while last + k * per < ago:
            k += 1
        prev = last + k * per                 # дней назад до предыдущего купона
        return cv * (prev - ago) / per

    for n, amt in DEMO_DEPOSITS:
        ev.append((day(n), 0, [day(n), "Пополнение", "", "", "", "", "", amt, "RUB", "", ""]))
    held = defaultdict(list)                  # isin -> [(дата, ±кол-во)]
    for n, op, isin, qty, price in DEMO_TRADES:
        _, tick, name, kind = info[isin][:4]
        d = day(n)
        if kind == "bond":
            nk = nkd_at(isin, d)
            amount = qty * (price / 100.0 * 1000.0 + nk)
        else:
            nk, amount = 0.0, qty * price
        comm = round(amount * 0.0005, 2)
        ev.append((d, 1, [d, op, isin, tick, name, qty, price, round(amount, 2), "RUB", comm, ""]))
        held[isin].append((d, qty if op == "Покупка" else -qty))

    def qty_at(isin, d):
        return sum(q for dd, q in held[isin] if dd <= d)

    income = defaultdict(float)               # год -> облагаемый доход (для НДФЛ)
    for isin, _, name, kind, cv, per, last in DEMO_INSTRUMENTS:
        if kind != "bond":
            continue
        k = 0
        while last + k * per <= 730:
            d = day(last + k * per)
            q = qty_at(isin, d - timedelta(days=1))
            if q > 0:
                amt = round(q * cv, 2)
                ev.append((d, 2, [d, "Купон", isin, info[isin][1], name, "", "", amt, "RUB", "", ""]))
                income[d.year] += amt
            k += 1
    for n, isin, per_share in DEMO_DIVS:
        d = day(n)
        q = qty_at(isin, d - timedelta(days=1))
        if q > 0:
            amt = round(q * per_share, 2)
            ev.append((d, 2, [d, "Дивиденд", isin, info[isin][1], info[isin][2], "", "", amt, "RUB", "", ""]))
            income[d.year] += amt
    for y, inc in sorted(income.items()):     # НДФЛ удерживается в конце года за прошедшие выплаты
        d = date(y, 12, 25)
        if d < today and d >= day(730):
            paid = sum(r[7] for dd, _, r in ev if r[1] in ("Купон", "Дивиденд") and dd.year == y and dd <= d)
            ev.append((d, 3, [d, "НДФЛ", "", "", "", "", "", round(paid * 0.13, 2), "RUB", "", ""]))
    ev.sort(key=lambda e: (e[0], e[1]))
    cash, topups = 0.0, []
    for d, _, r in ev:                        # пополнения «по необходимости», круглыми суммами
        sign = {"Покупка": -1, "Продажа": 1, "НДФЛ": -1}.get(r[1], 1)
        delta = sign * r[7] - (r[9] or 0)
        if cash + delta < 0:
            need = int(-(cash + delta) // 50000 + 1) * 50000
            topups.append((d - timedelta(days=1), 0, [d - timedelta(days=1), "Пополнение", "", "", "", "", "", need, "RUB", "", ""]))
            cash += need
        cash += delta
    ev = sorted(ev + topups, key=lambda e: (e[0], e[1]))
    out = []
    for d, _, r in ev:
        r = list(r)
        r[0] = d.strftime("%d.%m.%Y")
        out.append(["" if v is None else (_demo_fmt(v).replace(".", ",") if isinstance(v, float) else str(v)) for v in r])
    return out


def demo_csv(today=None):
    """Тот же отчёт в виде CSV-текста (формат шаблона импорта)."""
    head = ["Дата", "Тип операции", "ISIN", "Тикер", "Название", "Количество", "Цена", "Сумма", "Валюта", "Комиссия", "НКД"]
    return "\n".join(";".join(r) for r in [head] + demo_rows(today)) + "\n"


class _NoClient:
    ready = False


def demo_active():
    return any(x.get("demo") or x.get("id") == DEMO_ID for x in imports_list())


def demo_remove():
    """Убирает только демо-импорт и его данные. Возвращает True, если что-то было удалено."""
    if not demo_active():
        return False
    store().put("imports", [x for x in imports_list() if not (x.get("demo") or x.get("id") == DEMO_ID)])
    store().ops_clear(DEMO_ID)
    mem_clear()
    return True


def demo_seed():
    """Справочные записи для бумаг демо (иначе без токена нет ни ISIN, ни параметров облигации). Кэш истекает — обновляем при обращении."""
    st = store()
    put = []
    for isin, tick, name, kind, *_ in DEMO_INSTRUMENTS:
        uid = "imp:" + isin
        if st.get("inst:" + uid, ttl=20 * DAY) is None:
            put.append(("inst:" + uid, {"uid": uid, "figi": "", "ticker": tick, "isin": isin, "name": name, "type": kind,
                                        "cur": "rub", "sector": "", "logo": "", "color": "", "country": "RU", "cls": ""}))
        if kind == "bond" and st.get("bond:" + uid, ttl=6 * 3600) is None and isin in DEMO_BOND_PARAMS:
            mat, cpy, fl = DEMO_BOND_PARAMS[isin]
            put.append(("bond:" + uid, {"nominal": 1000.0, "initial": 1000.0, "cur": "rub", "maturity": mat, "call": None,
                                        "placement": None, "cpy": cpy, "aci": 0.0, "floating": fl, "amort": False,
                                        "perpetual": False, "risk": "", "sector": "", "name": name}))
    if put:
        st.put_many(put)


def demo_enable():
    raw = demo_csv().encode("utf-8")
    tables = read_tables("demo.csv", raw)
    mapping = guess_mapping(tables[0][0])
    ops, _ = rows_to_ops([r for r in tables[0][1:] if any(r)], mapping, tables[0][0])
    ops, _ids = finalize_import(_NoClient(), ops, keep_demo=True)
    kinds = {i[0]: "INSTRUMENT_TYPE_" + i[3].upper() for i in DEMO_INSTRUMENTS}
    for o in ops:
        ident = (o.get("instrumentUid") or "").replace("imp:", "")
        if ident in kinds:
            o["instrumentKind"] = kinds[ident]
    store().ops_clear(DEMO_ID)
    store().ops_put(DEMO_ID, ops)
    demo_seed()
    lst = [x for x in imports_list() if x.get("id") != DEMO_ID]
    lst.append({"id": DEMO_ID, "name": DEMO_NAME, "broker": "Демо", "demo": True, "created": utc_now_str(),
                "files": [{"name": "demo.csv", "count": len(ops), "at": utc_now_str()}]})
    store().put("imports", lst)
    mem_clear()
    return len(ops)


def _api_demo_enable(cfg, body):
    n = demo_enable()
    return {"ok": True, "id": DEMO_ID, "count": n}


def _api_demo_disable(cfg, body):
    return {"ok": True, "removed": demo_remove()}


def _api_demo_status(cfg, acc, q, force):
    on = demo_active()
    if on:
        demo_seed()
    return {"active": on, "id": DEMO_ID, "name": DEMO_NAME}


API_GET["/api/demo/status"] = _api_demo_status
API_POST["/api/demo/enable"] = _api_demo_enable
API_POST["/api/demo/disable"] = _api_demo_disable
# ═══════════════════════════════ отчёт брокера Т-Инвестиций (xlsx) ═══════════════════════════════
#
# Общий импортёр берёт первую найденную таблицу (раздел 1.1 «сделки») и ломает учёт: РЕПО-ноги считает
# настоящими сделками, не видит раздел 2 «Операции с денежными средствами» и теряет входящие остатки.
# Здесь — отдельный разбор отчёта «Отчет о сделках и операциях» АО «ТБанк»:
#   1.1  сделки без РЕПО (id по «Номеру сделки»)              -> BUY / SELL + отдельная комиссия
#   2.   денежные операции (пополнения, выплаты, налоги…)      -> операции со стабильным хэш-id;
#        строки-«зеркала» сделок («Покупка/продажа», «Комиссия за сделки», «DFP/RFP») пропускаются,
#        РЕПО сворачивается в дневное нетто типа «прочее» (на остаток денег влияет, на аналитику — нет)
#   3.1  остатки по бумагам: входящий остаток -> синтетическая «входящая» операция на начало периода;
#        движение без сделок (переводы, DFP) -> синтетическая операция на границе периода
#   4.1  соответствие «Код актива» -> ISIN
# Синтетические операции помечены полем _opening и снимаются автоматически, когда добавлен более ранний файл
# (см. import_merge_ops), поэтому два соседних отчёта склеиваются без разрывов.

TB_REPO_RE = re.compile(r"^\s*репо", re.I)
TB_MIRROR_OPS = ("покупка/продажа", "комиссия за сделки", "dfp/rfp")
TB_SEC_TITLE_RE = re.compile(r"^(\d)\.(\d)?\s+\S")
TB_EXPECT = {
    "1.1": ("номер сделки", "дата заключения", "вид сделки", "код актива", "количество"),
    "2": ("дата исполнения", "операция", "сумма зачисления", "сумма списания"),
    "3.1": ("код актива", "isin", "входящий остаток", "исходящий остаток"),
}
TB_KIND_RU = {"buy": "покупок", "sell": "продаж", "coupons": "купонов", "dividends": "дивидендов", "deposits": "пополнений",
              "withdrawals": "выводов", "fee_broker": "комиссий", "fee_service": "обслуживание", "margin_fee": "маржа",
              "tax_trade": "налогов", "tax_dividend": "налогов с дивидендов", "tax_coupon": "налогов с купонов",
              "repayments": "погашений", "sec_in": "входящих бумаг", "sec_out": "списаний бумаг", "other": "прочее",
              "varmargin": "вариационная маржа"}


def tb_norm(s):
    return re.sub(r"\s+", " ", str(s or "").replace("\xa0", " ")).strip().lower()


def tb_detect(tables):
    """Таблица отчёта «Отчет о сделках и операциях» брокера Т-Инвестиций (АО «ТБанк», ранее «Тинькофф») или None."""
    for t in tables[:3]:
        head = " ".join(tb_norm(r[0]).replace("ё", "е") for r in t[:25] if r)
        if "отчет о сделках и операциях" in head and re.search(r"тбанк|т-банк|тинькофф|т-инвест", head):
            if any(tb_norm(r[0]).startswith("1.1 информация о совершенных") for r in t[:80] if r):
                return t
    return None


def tb_sections(rows):
    """{'1.1': [строки…], '2': [...]} — строки между заголовками разделов; ключ — номер раздела."""
    out, cur = {}, None
    for r in rows:
        c0 = str(r[0]).strip() if r else ""
        m = TB_SEC_TITLE_RE.match(c0) if c0 and not any(str(x).strip() for x in r[1:]) else None
        if m:
            cur = m.group(1) + ("." + m.group(2) if m.group(2) else "")
            out.setdefault(cur, [])
            continue
        if cur is not None:
            out[cur].append(r)
    return out


def tb_cols(row, expect):
    """Карта {заголовок: колонка}, если строка — заголовок таблицы (содержит все нужные подписи)."""
    cm = {}
    for i, c in enumerate(row):
        k = tb_norm(c)
        if k and k not in cm:
            cm[k] = i
    return cm if all(e in cm for e in expect) else None


def tb_cell(row, cm, key):
    i = cm.get(key)
    return str(row[i]).strip() if i is not None and i < len(row) and row[i] is not None else ""


def tb_num(s):
    v = parse_num(s)
    return v if v is not None else 0.0


def tb_dt(d, t=""):
    """«дд.мм.гггг» + «чч:мм:сс» -> datetime."""
    dt = parse_date(d)
    if not dt:
        return None
    m = re.match(r"^(\d{1,2}):(\d{2})(?::(\d{2}))?", str(t or "").strip())
    if m and dt.hour == 0 and dt.minute == 0 and dt.second == 0:
        dt = dt.replace(hour=min(int(m.group(1)), 23), minute=int(m.group(2)), second=int(m.group(3) or 0))
    return dt


def tb_iso(dt):
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")


def tb_period(rows):
    for r in rows[:30]:
        m = re.search(r"за период\s+(\d{2}\.\d{2}\.\d{4})\s*-\s*(\d{2}\.\d{2}\.\d{4})", str(r[0]) if r else "")
        if m:
            return parse_date(m.group(1)), parse_date(m.group(2))
    return None, None


def tb_hash_id(prefix, parts, seen):
    """Стабильный id по содержимому строки; одинаковые строки внутри файла различаются порядковым номером."""
    h = hashlib.sha1("|".join(str(p) for p in parts).encode("utf-8")).hexdigest()[:14]
    n = seen[h] = seen.get(h, 0) + 1
    return "%s-%s%s" % (prefix, h, "" if n == 1 else "-%d" % n)


def uniq_op_id(xid, seen):
    """id перевода бумаг: при совпадении (одна бумага, одна секунда) — суффикс -2, -3...; прежние id не меняются."""
    base, n = xid, 1
    while xid in seen:
        n += 1
        xid = "%s-%d" % (base, n)
    seen.add(xid)
    return xid


def tb_deals(rows):
    """Строки раздела 1.1/1.2 -> список сделок (все виды, включая РЕПО; фильтрует вызывающий)."""
    out, cm = [], None
    for r in rows:
        h = tb_cols(r, TB_EXPECT["1.1"])
        if h:
            cm = h
            continue
        if not cm:
            continue
        num, kind = tb_cell(r, cm, "номер сделки"), tb_cell(r, cm, "вид сделки")
        if not num or not kind:
            continue
        dt = tb_dt(tb_cell(r, cm, "дата заключения"), tb_cell(r, cm, "время"))
        if not dt:
            continue
        # биржевой и клиринговый сбор отдельно с клиента не списываются (в «Комиссии за сделки» раздела 2 — только брокерская)
        comm = abs(tb_num(tb_cell(r, cm, "комиссия брокера")))
        out.append({"num": num, "kind": kind, "repo": bool(TB_REPO_RE.match(kind)), "dt": dt,
                    "name": tb_cell(r, cm, "наименование актива"), "code": tb_cell(r, cm, "код актива"),
                    "qty": abs(tb_num(tb_cell(r, cm, "количество"))), "net": tb_num(tb_cell(r, cm, "сумма (без нкд)")),
                    "nkd": tb_num(tb_cell(r, cm, "нкд")), "total": tb_num(tb_cell(r, cm, "сумма сделки")),
                    "cur": norm_cur(tb_cell(r, cm, "валюта расчетов")), "comm": comm})
    return out


def tb_cash_section(rows):
    """Раздел 2 -> (остатки {cur: (входящий, исходящий)}, строки-операции)."""
    bal, ops, cur, cm, bm = {}, [], None, None, None
    for r in rows:
        nz = [(i, str(c).strip()) for i, c in enumerate(r) if str(c).strip()]
        if not nz:
            continue
        b = tb_cols(r, ("валюта", "входящий остаток", "исходящий остаток"))
        if b:
            bm = b
            continue
        h = tb_cols(r, TB_EXPECT["2"])
        if h:
            cm = h
            continue
        if len(nz) == 1 and re.fullmatch(r"[A-Z]{3}", nz[0][1]):
            cur, cm = nz[0][1].lower(), None
            continue
        if bm is not None and cm is None and re.fullmatch(r"[A-Z]{3}", tb_cell(r, bm, "валюта")):
            bal[tb_cell(r, bm, "валюта").lower()] = (tb_num(tb_cell(r, bm, "входящий остаток")),
                                                     tb_num(tb_cell(r, bm, "исходящий остаток")))
            continue
        if cm is None or cur is None:
            continue
        op = tb_cell(r, cm, "операция")
        if not op:
            continue
        ops.append({"cur": cur, "d": tb_cell(r, cm, "дата"), "t": tb_cell(r, cm, "время совершения"),
                    "x": tb_cell(r, cm, "дата исполнения"), "op": op,
                    "cr": tb_num(tb_cell(r, cm, "сумма зачисления")), "db": tb_num(tb_cell(r, cm, "сумма списания")),
                    "note": tb_cell(r, cm, "примечание")})
    return bal, ops


def tb_note(note):
    """Из «Тип КД: …, Наименование: …, ISIN: …» -> (тип КД, название, ISIN)."""
    kd = re.search(r"Тип КД:\s*(.*?)(?:,\s*(?:Наименование|ISIN|Референс|Дата)\b|$)", note or "")
    nm = re.search(r"Наименование:\s*(.*?),\s*ISIN:", note or "")
    isin = re.search(r"ISIN:\s*([A-Z]{2}[A-Z0-9]{9}\d)", note or "")
    return (kd.group(1).strip() if kd else ""), (nm.group(1).strip() if nm else ""), (isin.group(1) if isin else "")


def tb_cash_type(op, note):
    """Строка раздела 2 -> (вид операции, подпись); None для строк-зеркал сделок."""
    o, kd = tb_norm(op), tb_norm(tb_note(note)[0])
    if o in TB_MIRROR_OPS:
        return None
    if o.startswith("выплата доходов по корпоративным"):
        if "частичн" in kd or "амортиз" in kd:
            return "BOND_REPAYMENT", "Амортизация"
        if "погашен" in kd:
            return "BOND_REPAYMENT_FULL", "Погашение"
        if "дивиденд" in kd:
            return "DIVIDEND", "Дивиденды"
        if "облигац" in kd or "купон" in kd:
            return "COUPON", "Купон"
        return "DIVIDEND", "Выплата дохода"
    if o.startswith("возмещение дохода по сделке репо"):
        return "COUPON", "Возмещение дохода по сделке РЕПО"
    if o == "пополнение счета":
        return "INPUT", "Пополнение счёта"
    if o == "вывод средств":
        return "OUTPUT", "Вывод средств"
    if o.startswith("перевод зачисление"):
        return "INPUT", "Перевод (зачисление)"
    if o.startswith("перевод списание"):
        return "OUTPUT", "Перевод (списание)"
    if o.startswith("налог (дивиденд"):
        return "DIVIDEND_TAX", "Налог с дивидендов"
    if o.startswith("налог"):
        return "TAX", "Налог"
    if o.startswith("комиссия по тарифу"):
        return "SERVICE_FEE", "Комиссия по тарифу"
    if "комиссия" in o and "пфи" in o:
        return "BROKER_FEE", "Комиссия за сделки с производными"
    if o.startswith("вариационная маржа"):
        return "VARMARGIN", "Вариационная маржа"
    if "маржин" in o:
        return "MARGIN_FEE", "Маржинальная комиссия"
    if o.startswith("отражение требований по непокрытой"):
        return "UNCOVERED", "Требования по непокрытой позиции"
    if o == "репо":
        return "REPO", "РЕПО"
    return "OTHER", op


def tb_positions(rows):
    """Раздел 3.1 -> {isin: {name, code, open, close, plan}}."""
    out, cm = {}, None
    for r in rows:
        h = tb_cols(r, TB_EXPECT["3.1"])
        if h:
            cm = h
            continue
        if not cm:
            continue
        isin, code = tb_cell(r, cm, "isin").upper(), tb_cell(r, cm, "код актива")
        key = isin or code
        if not key or not tb_cell(r, cm, "исходящий остаток"):
            continue
        p = out.setdefault(key, {"name": tb_cell(r, cm, "наименование актива"), "code": code, "open": 0.0, "close": 0.0, "plan": 0.0})
        p["open"] += tb_num(tb_cell(r, cm, "входящий остаток"))
        p["close"] += tb_num(tb_cell(r, cm, "исходящий остаток"))
        p["plan"] += tb_num(tb_cell(r, cm, "плановый исходящий остаток"))
    return out


def tb_isin_map(sections):
    """«Код актива» -> ISIN по разделам 3.1 и 4.1."""
    m = {}
    for sec in ("3.1", "4.1"):
        cm = None
        for r in sections.get(sec) or []:
            h = tb_cols(r, ("код актива", "isin"))
            if h:
                cm = h
                continue
            if cm:
                code, isin = tb_cell(r, cm, "код актива"), tb_cell(r, cm, "isin").upper()
                if code and ISIN_RE.match(isin):
                    m[code] = isin
    return m


def tb_deriv_codes(sections):
    """Коды фьючерсов/опционов из раздела 4.3: их «сделки» — не деньги и не бумаги (расчёты идут вариационной маржой)."""
    out, cm = set(), None
    for r in sections.get("4.3") or []:
        h = tb_cols(r, ("код контракта",))
        if h:
            cm = h
            continue
        if cm and tb_cell(r, cm, "код контракта"):
            out.add(tb_cell(r, cm, "код контракта"))
    return out


def tb_qty_str(q):
    return str(int(round(q))) if abs(q - round(q)) < 1e-9 else ("%.9f" % q).rstrip("0").rstrip(".")


def tbank_parse(table, splits=None):
    """Разбор отчёта Т-Инвестиций. Возвращает (ops, meta): ops в том же формате, что и у общего импортёра
    (с полем _ident для поиска бумаги), meta — период, остатки и счётчики для сверки и предпросмотра."""
    d_from, d_to = tb_period(table)
    sections = tb_sections(table)
    isin_of = tb_isin_map(sections)
    # у «Кода актива» бывает вид ISIN, но не ISIN (SU26238RMFS4 у ОФЗ) — таблица 3.1/4.1 главнее
    ident = lambda code: isin_of.get(code) or code
    deals = tb_deals(sections.get("1.1") or [])
    pending = tb_deals(sections.get("1.2") or [])
    pos = tb_positions(sections.get("3.1") or [])
    deriv = tb_deriv_codes(sections)
    bal, cash_rows = tb_cash_section(sections.get("2") or [])
    if d_from is None:
        dts = [x["dt"] for x in deals] + [parse_date(x["x"]) for x in cash_rows if parse_date(x["x"])]
        if not dts:
            raise ApiError("В отчёте Т-Инвестиций не нашёл период и операции.", 400)
        d_from, d_to = min(dts), max(dts)
    start = d_from.replace(hour=0, minute=0, second=0)
    period = {"from": start.strftime("%Y-%m-%d"), "to": (d_to or d_from).strftime("%Y-%m-%d")}
    ops, stat, xids = [], defaultdict(int), set()

    # ── сделки (раздел 1.1) ──
    dq_trade, dq_repo, first_unit, nums = defaultdict(float), defaultdict(float), {}, defaultdict(int)
    day_deals = defaultdict(list)
    for x in deals:
        low = x["kind"].lower()
        sign = 1 if "покуп" in low else -1 if "продаж" in low else 0
        isin = ident(x["code"])
        if x["repo"]:
            stat["repo"] += 1
            if sign and x["qty"]:
                dq_repo[isin] += sign * x["qty"]
            continue
        if x["code"] in deriv:
            stat["deriv_deals"] += 1
            continue
        if not sign or not x["qty"]:
            stat["unknown_deal"] += 1
            continue
        dq_trade[isin] += sign * x["qty"]
        total = abs(x["total"]) or abs(x["net"]) + abs(x["nkd"])
        unit = (abs(x["net"]) + abs(x["nkd"])) / x["qty"]
        first_unit.setdefault(isin, unit)
        day_deals[isin].append((x["dt"], sign * x["qty"], total / x["qty"]))
        nums[x["num"]] += 1
        base = "tb-" + re.sub(r"[^0-9A-Za-z]", "", x["num"]) + ("" if nums[x["num"]] == 1 else "-%d" % nums[x["num"]])
        o = {"id": base, "date": tb_iso(x["dt"]), "type": "OPERATION_TYPE_" + ("BUY" if sign > 0 else "SELL"),
             "payment": to_money(round(-sign * total, 9), x["cur"]), "name": x["name"] or x["code"], "_ident": isin,
             "quantity": tb_qty_str(x["qty"]), "quantityDone": tb_qty_str(x["qty"]),
             "price": to_money(round(unit, 9), x["cur"])}
        ops.append(o)
        stat["buy" if sign > 0 else "sell"] += 1
        if x["comm"]:
            ops.append({"id": base + "-f", "date": o["date"], "type": "OPERATION_TYPE_BROKER_FEE",
                        "payment": to_money(-round(x["comm"], 9), x["cur"]),
                        "name": "Комиссия: " + (x["name"] or x["code"]), "_ident": isin})

    # ── денежные операции (раздел 2) ──
    repo_net, cash_seen, redeemed = defaultdict(float), {}, set()
    for x in cash_rows:
        if tb_norm(x["note"]) == "план":
            stat["planned"] += 1
            continue
        typ = tb_cash_type(x["op"], x["note"])
        if typ is None:
            stat["mirror"] += 1
            continue
        kind, label = typ
        amount = round(x["cr"] - x["db"], 9)
        dt = tb_dt(x["d"], x["t"]) if x["d"] else parse_date(x["x"])
        if not dt:
            stat["skipped"] += 1
            continue
        if kind == "REPO":
            repo_net[(dt.strftime("%Y-%m-%d"), x["cur"])] += amount
            continue
        _kd, nm, isin = tb_note(x["note"])
        o = {"id": tb_hash_id("tb", (x["cur"], x["d"], x["t"], x["x"], x["op"], x["cr"], x["db"], x["note"]), cash_seen),
             "date": tb_iso(dt), "payment": to_money(amount, x["cur"]), "name": nm or label}
        if kind in ("COUPON", "DIVIDEND", "BOND_REPAYMENT", "BOND_REPAYMENT_FULL", "DIVIDEND_TAX"):
            o["_ident"] = isin or nm
            if kind == "BOND_REPAYMENT_FULL" and isin:
                redeemed.add(isin)
        if kind == "VARMARGIN":
            o["type"] = "OPERATION_TYPE_" + ("ACCRUING_VARMARGIN" if amount >= 0 else "WRITING_OFF_VARMARGIN")
        elif kind in ("UNCOVERED", "OTHER"):
            o["type"], o["name"] = "OPERATION_TYPE_X_" + kind, label
        else:
            o["type"] = "OPERATION_TYPE_" + kind
        ops.append(o)
        stat[classify(o["type"])] += 1
    for (day, cur), v in sorted(repo_net.items()):
        if abs(v) >= 0.005:
            ops.append({"id": "tb-repo-%s-%s" % (day, cur), "date": day + "T00:00:00Z", "type": "OPERATION_TYPE_X_REPO",
                        "payment": to_money(round(v, 2), cur), "name": "Расчёты по сделкам РЕПО (нетто за день)"})
            stat["repo_cash"] += 1

    # ── входящие остатки и движение бумаг без сделок ──
    lent_end = defaultdict(float)  # бумаги, ушедшие в РЕПО и ещё не вернувшиеся к концу периода (вторые ноги из 1.2)
    for x in pending:
        if x["repo"] and re.match(r"^\s*репо\s*2", x["kind"], re.I):
            lent_end[ident(x["code"])] += x["qty"] if "покуп" in x["kind"].lower() else -x["qty"]
    # сплиты Мосбиржи внутри периода: количество на их день умножается, поэтому «лишних» бумаг без сделки не возникает
    sp = splits if splits is not None else splits_by_isin(period["from"], period["to"], set(pos) | set(dq_trade) | set(lent_end), isin_of)
    meta_pos = {}
    for isin, p in pos.items():
        key = isin if ISIN_RE.match(isin) else ident(p["code"])
        econ_close = p["close"] + lent_end.get(key, 0.0)
        econ_open = p["open"] + lent_end.get(key, 0.0) + dq_repo.get(key, 0.0)
        meta_pos[key] = {"name": p["name"], "open": p["open"], "close": p["close"], "plan": p["plan"], "econ_open": econ_open,
                         "econ_close": econ_close,
                         "resid": econ_close - split_walk(econ_open, day_deals.get(key, ()), sp.get(key, ()))}
    for key in set(dq_trade) | set(lent_end):
        if key not in meta_pos:  # бумаги нет в 3.1 (нулевые остатки)
            eo = lent_end.get(key, 0.0) + dq_repo.get(key, 0.0)
            meta_pos[key] = {"name": "", "open": 0.0, "close": 0.0, "plan": 0.0, "econ_open": eo,
                             "econ_close": lent_end.get(key, 0.0),
                             "resid": lent_end.get(key, 0.0) - split_walk(eo, day_deals.get(key, ()), sp.get(key, ()))}
    day_deals = {k: sorted(v, key=lambda z: z[0]) for k, v in day_deals.items()}
    name_of = {ident(x["code"]): x["name"] for x in deals + pending if x["name"]}
    open_iso = tb_iso(start)
    end_dt = datetime.strptime(period["to"], "%Y-%m-%d").replace(hour=23, minute=59, second=59)
    tag = {"_opening": True, "_period": [period["from"], period["to"]]}
    for key, p in sorted(meta_pos.items()):
        nm = p["name"] or name_of.get(key) or key
        unit = first_unit.get(key, 0.0)
        if p["econ_open"] > 1e-6:
            q = p["econ_open"]
            ops.append(dict({"id": "tb-open-sec-%s-%s" % (key, period["from"]), "date": open_iso,
                             "type": "OPERATION_TYPE_INPUT_SECURITIES", "payment": to_money(0, "rub"),   # деньги не двигаются: оценка — в price
                             "name": nm, "_ident": key, "quantity": tb_qty_str(q), "quantityDone": tb_qty_str(q),
                             "price": to_money(round(unit, 9), "rub"),
                             "description": "Входящий остаток на начало периода (раздел 3.1 отчёта)"}, **tag))
            stat["opening_sec"] += 1
        r = p["resid"]
        if key in redeemed and p["econ_close"] < 0.5 and r < -0.5:
            r = 0.0  # списание бумаг — это погашение, его уже учтёл денежный раздел
        if abs(r) <= 1e-6:
            r = 0.0
        # FIFO не знает коротких позиций: если продаж больше, чем бумаг на руках (продажа «с плеча» с покрытием через
        # секунды), недостающее довносим входящей операцией перед продажей и снимаем после покупки-покрытия
        run, short, extra = p["econ_open"] + max(r, 0.0), 0.0, []
        for t, dq, u in split_timeline(day_deals.get(key, ()), sp.get(key, ())):
            if dq is None:
                run *= u
                short *= u
                continue
            if dq < 0:
                take = min(run, -dq)
                run -= take
                if -dq - take > 1e-6:
                    extra.append((True, -dq - take, t - timedelta(seconds=1), u))
                    short += -dq - take
            else:
                c = min(short, dq)
                if c > 1e-6:
                    extra.append((False, c, t + timedelta(seconds=1), u))
                    short -= c
                run += dq - c
        if short > 1e-6:
            extra.append((False, short, end_dt, unit))
        if r > 0:
            extra.append((True, r, start.replace(second=1), unit))
        elif r < 0:
            extra.append((False, -r, end_dt, unit))
        for sec_in, qty_x, when, u in extra:
            xid = "tb-xfer-%s-%s-%s" % ("in" if sec_in else "out", key, tb_iso(when))
            xid = uniq_op_id(xid, xids)
            ops.append({"id": xid,
                        "date": tb_iso(when), "type": "OPERATION_TYPE_" + ("INPUT_SECURITIES" if sec_in else "OUTPUT_SECURITIES"),
                        "payment": to_money(0, "rub"), "name": nm, "_ident": key,   # перевод бумаг не двигает деньги; оценка — в price
                        "quantity": tb_qty_str(qty_x), "quantityDone": tb_qty_str(qty_x), "price": to_money(round(u, 9), "rub"),
                        "description": "Движение бумаг без сделки (раздел 3.1 отчёта): перевод, DFP, корпоративное действие или продажа без покрытия"})
            stat["xfer_in" if sec_in else "xfer_out"] += 1
    # входящий остаток денег: положительный — как пополнение на начало периода, отрицательный — служебная запись
    for cur, (b_in, _b_out) in sorted(bal.items()):
        if abs(b_in) >= 0.005:
            ops.append(dict({"id": "tb-open-cash-%s-%s" % (cur, period["from"]), "date": open_iso,
                             "type": "OPERATION_TYPE_INPUT" if b_in > 0 else "OPERATION_TYPE_X_OPENING",
                             "payment": to_money(round(b_in, 2), cur), "name": "Входящий остаток на начало периода"}, **tag))
            stat["opening_cash"] += 1
    ops.sort(key=lambda o: (o["date"], 0 if o.get("_opening") else 1))
    meta = {"format": "tbank", "title": "Отчёт брокера Т-Инвестиций", "period": period, "cash_open": {c: v[0] for c, v in bal.items()},
            "cash_close": {c: v[1] for c, v in bal.items()}, "pos": meta_pos, "stat": dict(stat)}
    return ops, meta


def tbank_reconcile(ops, meta):
    """Сверка операций с итогами самого отчёта: деньги по валютам и количество бумаг по ISIN.
    {'cash': {cur: (по отчёту, по операциям)}, 'pos': {isin: (по отчёту, по операциям)}, 'ok': bool}."""
    cash = defaultdict(float)
    for o in ops:                                   # все операции, как их суммирует портфель (переводы бумаг — с нулевой суммой)
        cash[cur_of(o["payment"])] += qf(o["payment"])
    work = []
    for o in sorted(ops, key=lambda o: o["date"]):
        w = dict(o)
        if w.get("_ident") and classify(w["type"]) in ("buy", "sell", "sec_in", "sec_out", "repayments"):
            w["instrumentUid"] = "imp:" + w["_ident"]
            w["_sec"] = w["_ident"]
        work.append(w)
    work = import_apply_splits(work, until=meta["period"]["to"])   # сплиты после конца периода отчёта в его остатках не видны
    held = {u[4:]: v["qty"] for u, v in fifo(work).items()}
    res = {"cash": {c: (meta["cash_close"].get(c, 0.0), cash.get(c, 0.0)) for c in set(meta["cash_close"]) | set(cash)},
           "pos": {k: (p["econ_close"], held.get(k, 0.0)) for k, p in meta["pos"].items()}}
    for k, q in held.items():
        res["pos"].setdefault(k, (0.0, q))
    res["ok"] = all(abs(a - b) < 1.0 for a, b in res["cash"].values()) and all(abs(a - b) < 0.5 for a, b in res["pos"].values())
    return res


def tbank_try(filename, raw):
    """(ops, meta), если файл — отчёт Т-Инвестиций; иначе None (тогда работает общий импортёр)."""
    fn = (filename or "").lower()
    if not (fn.endswith((".xlsx", ".xlsm")) or raw[:2] == b"PK"):
        return None
    try:
        tables = read_tables(filename, raw)
    except Exception:  # noqa: BLE001 — не xlsx/битый файл: пусть разбирается общий импортёр и скажет понятную ошибку
        return None
    t = tb_detect(tables)
    return tbank_parse(t) if t else None


def tbank_preview(ops, meta):
    """Предпросмотр: что нашли, что пропустили, сошлись ли деньги и бумаги с итогами отчёта, куда предложить добавить."""
    kinds = defaultdict(int)
    for o in ops:
        kinds[classify(o["type"])] += 1
    rec = tbank_reconcile(ops, meta)
    bad_cash = {c: [a, b] for c, (a, b) in rec["cash"].items() if abs(a - b) >= 1.0}
    bad_pos = sorted(((abs(a - b), k, a, b) for k, (a, b) in rec["pos"].items() if abs(a - b) >= 0.5), reverse=True)
    st = meta["stat"]
    mine = [x for x in imports_list() if x.get("format") == meta["format"]]  # добавлять предлагаем только к счетам того же брокера
    return {"format": meta["format"], "title": meta["title"], "period": meta["period"], "count": len(ops),
            "kinds": dict(kinds), "kinds_ru": TB_KIND_RU, "repo_skipped": st.get("repo", 0), "mirror_skipped": st.get("mirror", 0),
            "opening_sec": st.get("opening_sec", 0), "xfer": st.get("xfer_in", 0) + st.get("xfer_out", 0),
            "cash_ok": not bad_cash, "cash_bad": bad_cash, "pos_total": len(rec["pos"]), "pos_bad": len(bad_pos),
            "pos_worst": [[k, a, b] for _, k, a, b in bad_pos[:5]],
            "sample": [[o["date"][:10], op_type(o), o.get("name") or "", op_qty(o), qf(o["payment"]), cur_of(o["payment"])]
                       for o in ops if not o.get("_opening") and classify(o["type"]) != "other"][:12],
            "targets": [{"id": x["id"], "name": x.get("name") or ""} for x in mine]}


def import_preview_any(filename, raw):
    hit = broker_try(filename, raw)
    res = tbank_preview(*hit) if hit else import_preview(filename, raw)
    dup = find_duplicate_import(raw, hit[0] if hit else None)
    if dup:
        res["duplicate_of"] = dup
    return res


def import_ops_any(filename, raw, table, header_row, mapping):
    """(ops, пропущено строк, формат, meta): отчёт Т-Инвестиций разбирается своим парсером, остальное — по выбранным колонкам."""
    hit = broker_try(filename, raw)
    if hit:
        return hit[0], hit[1]["stat"].get("skipped", 0), hit[1]["format"], hit[1]
    ops, skipped = import_ops(filename, raw, table, header_row, mapping)
    return ops, skipped, "", None
# ═══════════════════════════════ отчёт брокера ВТБ (xlsx) ═══════════════════════════════
#
# «Отчет Банка ВТБ (ПАО) за период … о сделках, операциях и состоянии счетов Клиента». Разбор по той же схеме, что у отчёта
# Т-Инвестиций (10b_tbank_report.py): свои парсер и сверка, общие finalize_import / слияние файлов в один счёт.
#   «Заключенные…» и «Завершенные…» сделки    -> BUY / SELL, объединяются и дедуплицируются по «№ сделки»
#                                                 (сделка, заключённая в конце периода, завершится уже в следующем файле)
#   «Движение денежных средств»                -> пополнения/выводы, купоны, дивиденды, погашения, налоги, вознаграждение брокера;
#                                                 «Сальдо расчетов по сделкам» — зеркало сделок, пропускается
#   «Отчёт об остатках ценных бумаг»           -> входящий остаток = служебная операция на начало периода (_opening)
#   «Движение ценных бумаг»                    -> «Расчеты по заключенным сделкам» — зеркало сделок; остальное — движение без сделки
# Комиссии берутся из денежного движения («Вознаграждение брокера»), а не из колонок сделок: это те же деньги, дважды не считаем.
# Деньги и бумаги сверяются с «Плановым исходящим остатком»: он включает сделки, заключённые, но ещё не рассчитанные.
# Ячейки с датой/суммой ридер xlsx отдаёт как «@xl<число>»: parse_date/parse_num понимают оба вида.

VT_TITLES = (("summary", "сводная информация по субсчету"), ("cashbal", "отчет об остатках денежных средств"),
             ("cash", "движение денежных средств"), ("secbal", "отчет об остатках ценных бумаг"),
             ("secmov", "движение ценных бумаг"), ("deals", "заключенные в отчетном периоде сделки"),
             ("done", "завершенные в отчетном периоде сделки"))
VT_ISIN_RE = re.compile(r"^(.*?),\s*[^,]*,\s*([A-Z]{2}[A-Z0-9]{9}\d)\s*$")


def vt_norm(s):
    return tb_norm(s).replace("ё", "е")


def vt_detect(tables):
    """Таблица отчёта Банка ВТБ (ПАО) о сделках, операциях и состоянии счетов Клиента или None."""
    for t in tables[:3]:
        head = " ".join(vt_norm(c) for r in t[:6] for c in r if str(c).strip())
        if "отчет банка втб" in head and "за период" in head:
            return t
    return None


def vt_sections(rows):
    """{'cash': [...], 'deals': [...]} — строки между заголовками разделов (заголовок — единственная ячейка строки)."""
    out, cur = {}, None
    for r in rows:
        nz = [str(c).strip() for c in r if str(c).strip()]
        if len(nz) == 1:
            low = vt_norm(nz[0])
            hit = next((k for k, p in VT_TITLES if low.startswith(p)), None)
            if hit:
                cur = hit
                out.setdefault(cur, [])
                continue
        if cur is not None:
            out[cur].append(r)
    return out


def vt_period(rows):
    for r in rows[:6]:
        for c in r:
            m = re.search(r"за период с\s+(\d{2}\.\d{2}\.\d{4})\s+по\s+(\d{2}\.\d{2}\.\d{4})", str(c))
            if m:
                return parse_date(m.group(1)), parse_date(m.group(2))
    return None, None


def vt_cols(row, *need):
    """Карта {заголовок: колонка}, если в строке есть заголовки, начинающиеся на все need (иначе None)."""
    cm = {}
    for i, c in enumerate(row):
        k = vt_norm(c)
        if k and k not in cm:
            cm[k] = i
    return cm if all(any(k.startswith(n) for k in cm) for n in need) else None


def vt_cell(row, cm, prefix, exact=False):
    for k, i in cm.items():
        if k == prefix if exact else k.startswith(prefix):
            return str(row[i]).strip() if i < len(row) and row[i] is not None else ""
    return ""


def vt_isin(cell):
    """«Наименование, № гос. регистрации, ISIN» -> (название, ISIN)."""
    m = VT_ISIN_RE.match(str(cell or "").strip())
    if m:
        return m.group(1).strip(), m.group(2)
    m = re.search(r"\b([A-Z]{2}[A-Z0-9]{9}\d)\b", str(cell or ""))
    return (str(cell or "").split(",")[0].strip(), m.group(1) if m else "")


def vt_balances(rows):
    """«Отчёт об остатках денежных средств» -> {cur: (входящий, исходящий, плановый)} по колонкам «Итого»."""
    out, head, itogo = {}, None, []
    for r in rows:
        h = vt_cols(r, "валюта", "входящий остаток", "исходящий остаток")
        if h:
            head = h
            continue
        if head and not itogo and any(vt_norm(c) == "итого" for c in r):
            itogo = [i for i, c in enumerate(r) if vt_norm(c) == "итого"]
            continue
        cur = str(r[1]).strip() if len(r) > 1 else ""
        if head and itogo and re.fullmatch(r"[A-Z]{3}", cur) and len(itogo) >= 2:
            plan_i = next((i for k, i in head.items() if k.startswith("плановый")), None)
            v = lambda i: tb_num(r[i]) if i is not None and i < len(r) else 0.0
            out[norm_cur(cur)] = (v(itogo[0]), v(itogo[1]), v(plan_i) if plan_i is not None else v(itogo[1]))
    return out


def vt_cash(rows):
    """«Движение денежных средств» -> список строк {d, amount, cur, op, note}."""
    out, cm = [], None
    for r in rows:
        h = vt_cols(r, "дата", "сумма", "валюта", "тип операции")
        if h:
            cm = h
            continue
        if not cm:
            continue
        op, d = vt_cell(r, cm, "тип операции"), parse_date(vt_cell(r, cm, "дата"))
        if not op or not d:
            continue
        out.append({"d": d, "amount": tb_num(vt_cell(r, cm, "сумма")), "cur": norm_cur(vt_cell(r, cm, "валюта")), "op": op,
                    "note": vt_cell(r, cm, "комментарий")})
    return out


def vt_deals(rows):
    out, cm = [], None
    for r in rows:
        h = vt_cols(r, "наименование ценной бумаги", "дата и время заключения", "вид сделки", "количество")
        if h:
            cm = h
            continue
        if not cm:
            continue
        name, isin = vt_isin(vt_cell(r, cm, "наименование ценной бумаги"))
        kind, dt = vt_cell(r, cm, "вид сделки"), parse_date(vt_cell(r, cm, "дата и время заключения"))
        num = vt_cell(r, cm, "№ сделки", exact=True)
        if not (isin and kind and dt and num):
            continue
        out.append({"num": num, "kind": kind, "dt": dt, "name": name, "isin": isin, "qty": abs(tb_num(vt_cell(r, cm, "количество"))),
                    "total": abs(tb_num(vt_cell(r, cm, "сумма сделки"))), "nkd": abs(tb_num(vt_cell(r, cm, "нкд по сделке"))),
                    "cur": norm_cur(vt_cell(r, cm, "валюта расчетов")), "repo": "репо" in vt_norm(kind)
                    or bool(vt_cell(r, cm, "ставка репо").strip("0.-, "))})
    return out


def vt_secbal(rows):
    """«Отчёт об остатках ценных бумаг» -> {isin: {name, open, close, plan}}."""
    out, cm = {}, None
    for r in rows:
        h = vt_cols(r, "наименование ценной бумаги", "входящий остаток", "исходящий остаток")
        if h:
            cm = h
            continue
        if not cm:
            continue
        name, isin = vt_isin(vt_cell(r, cm, "наименование ценной бумаги"))
        if not isin:
            continue
        p = out.setdefault(isin, {"name": name, "open": 0.0, "close": 0.0, "plan": 0.0})
        p["open"] += tb_num(vt_cell(r, cm, "входящий остаток"))
        p["close"] += tb_num(vt_cell(r, cm, "исходящий остаток"))
        p["plan"] += tb_num(vt_cell(r, cm, "плановый исходящий остаток"))
    return out


def vt_secmov(rows):
    out, cm = [], None
    for r in rows:
        h = vt_cols(r, "наименование ценной бумаги", "дата операции", "количество", "тип операции")
        if h:
            cm = h
            continue
        if not cm:
            continue
        name, isin = vt_isin(vt_cell(r, cm, "наименование ценной бумаги"))
        d = parse_date(vt_cell(r, cm, "дата операции"))
        if isin and d:
            out.append({"name": name, "isin": isin, "d": d, "qty": abs(tb_num(vt_cell(r, cm, "количество"))),
                        "op": vt_cell(r, cm, "тип операции"), "note": vt_cell(r, cm, "комментарий")})
    return out


def vt_cash_type(op, note, redeemed_full):
    """Строка денежного движения -> (вид, подпись); None — зеркало сделок."""
    o, n = vt_norm(op), vt_norm(note)
    if o.startswith("сальдо расчетов по сделкам"):
        return None
    if o.startswith("зачисление денежных"):
        return "INPUT", "Пополнение счёта"
    if o.startswith("списание денежных"):
        return "OUTPUT", "Вывод средств"
    if o.startswith("купонный доход"):
        return "COUPON", "Купон"
    if o.startswith("дивиденды"):
        return "DIVIDEND", "Дивиденды"
    if o.startswith("погашение"):
        return ("BOND_REPAYMENT_FULL", "Погашение") if redeemed_full else ("BOND_REPAYMENT", "Амортизация")
    if "ндфл" in o or o.startswith("налог"):
        if "дивиденд" in n:
            return "DIVIDEND_TAX", "Налог с дивидендов"
        if "купон" in n:
            return "BOND_TAX", "Налог с купона"
        return "TAX", "Налог"
    if o.startswith("вознаграждение брокера"):
        if "депозитар" in n or "обслуж" in n or "тариф" in n:
            return "SERVICE_FEE", "Обслуживание"
        return "BROKER_FEE", "Комиссия брокера"
    if "маржин" in o or "маржин" in n:
        return "MARGIN_FEE", "Маржинальная комиссия"
    if "комисс" in o or "вознагражд" in o:
        return "SERVICE_FEE", op
    return "OTHER", op


def vtb_parse(table, splits=None):
    """Разбор отчёта ВТБ -> (ops, meta) в том же виде, что tbank_parse (см. tbank_reconcile / tbank_preview)."""
    d_from, d_to = vt_period(table)
    if d_from is None:
        raise ApiError("В отчёте ВТБ не нашёл период.", 400)
    sec = vt_sections(table)
    period = {"from": d_from.strftime("%Y-%m-%d"), "to": (d_to or d_from).strftime("%Y-%m-%d")}
    start = d_from.replace(hour=0, minute=0, second=0)
    end_dt = (d_to or d_from).replace(hour=23, minute=59, second=59)
    bal = vt_balances(sec.get("cashbal") or [])
    cash_rows = vt_cash(sec.get("cash") or [])
    pos = vt_secbal(sec.get("secbal") or [])
    mov = vt_secmov(sec.get("secmov") or [])
    stat = defaultdict(int)
    ops, deal_seen, xids = [], {}, set()
    for x in vt_deals(sec.get("deals") or []) + vt_deals(sec.get("done") or []):  # «заключённые» + «завершённые», дедуп по номеру
        deal_seen.setdefault(x["num"], x)
    deals = sorted(deal_seen.values(), key=lambda z: z["dt"])
    dq, day_deals, first_unit = defaultdict(float), defaultdict(list), {}
    for x in deals:
        low = x["kind"].lower()
        sign = 1 if "покуп" in low else -1 if "продаж" in low else 0
        if x["repo"]:
            stat["repo"] += 1
            continue
        if not sign or not x["qty"]:
            stat["unknown_deal"] += 1
            continue
        unit = x["total"] / x["qty"]
        first_unit.setdefault(x["isin"], unit)
        dq[x["isin"]] += sign * x["qty"]
        day_deals[x["isin"]].append((x["dt"], sign * x["qty"], unit))
        ops.append({"id": "vtb-" + re.sub(r"[^0-9A-Za-z]", "", x["num"]), "date": tb_iso(x["dt"]),
                    "type": "OPERATION_TYPE_" + ("BUY" if sign > 0 else "SELL"),
                    "payment": to_money(round(-sign * x["total"], 9), x["cur"]), "name": x["name"], "_ident": x["isin"],
                    "quantity": tb_qty_str(x["qty"]), "quantityDone": tb_qty_str(x["qty"]),
                    "price": to_money(round(unit, 9), x["cur"])})
        stat["buy" if sign > 0 else "sell"] += 1
    # движение бумаг без сделки: «Расчеты по заключенным сделкам» — зеркало сделок
    redeemed, dm, xfer = set(), defaultdict(float), []
    for x in mov:
        low = vt_norm(x["op"] + " " + x["note"])
        if "расчеты по заключенным сделкам" in low:
            stat["mirror_sec"] += 1
            continue
        if "погашен" in low:
            redeemed.add(x["isin"])
            continue
        sign = 1 if any(w in low for w in ("зачисл", "ввод", "покупка", "поступ")) else -1 if any(
            w in low for w in ("списан", "вывод", "продаж")) else 0
        if not sign or not x["qty"]:
            stat["unknown_move"] += 1
            continue
        dm[x["isin"]] += sign * x["qty"]
        xfer.append((x, sign))
    cash_seen = {}
    for x in cash_rows:
        typ = vt_cash_type(x["op"], x["note"], False)
        if typ is None:
            stat["mirror"] += 1
            continue
        kind, label = typ
        _n, isin = vt_isin(x["note"]) if "ISIN" in x["note"] else ("", "")
        if kind == "BOND_REPAYMENT" and isin in redeemed:
            kind, label = "BOND_REPAYMENT_FULL", "Погашение"
        nm = re.search(r"(?:облигациям|акциям)\s+(.*?)\s+ISIN", x["note"])
        o = {"id": tb_hash_id("vtb", (x["cur"], x["d"].strftime("%Y%m%d"), x["amount"], x["op"], x["note"]), cash_seen),
             "date": tb_iso(x["d"]), "payment": to_money(round(x["amount"], 9), x["cur"]),
             "name": (nm.group(1) if nm else "") or label}
        if kind in ("COUPON", "DIVIDEND", "BOND_REPAYMENT", "BOND_REPAYMENT_FULL", "DIVIDEND_TAX") and isin:
            o["_ident"] = isin
        o["type"] = "OPERATION_TYPE_X_OTHER" if kind == "OTHER" else "OPERATION_TYPE_" + kind
        if kind == "OTHER":
            o["name"] = label
        ops.append(o)
        stat[classify(o["type"])] += 1
    # остатки: входящий = операция на начало периода; всё, что не объяснено сделками, — движение без сделки
    open_iso = tb_iso(start)
    tag = {"_opening": True, "_period": [period["from"], period["to"]]}
    sp = splits if splits is not None else splits_by_isin(period["from"], period["to"], set(pos) | set(dq))
    meta_pos = {}
    for isin in set(pos) | set(dq):
        p = pos.get(isin) or {"name": "", "open": 0.0, "close": 0.0, "plan": 0.0}
        econ_open, econ_close = p["open"], p["plan"] if isin in pos else dq[isin]
        meta_pos[isin] = {"name": p["name"], "open": p["open"], "close": p["close"], "plan": p["plan"], "econ_open": econ_open,
                          "econ_close": econ_close, "resid": econ_close - split_walk(econ_open, day_deals.get(isin, ()), sp.get(isin, ())) - dm.get(isin, 0.0)}
    name_of = {x["isin"]: x["name"] for x in deals}
    for isin, p in sorted(meta_pos.items()):
        nm, unit = p["name"] or name_of.get(isin) or isin, first_unit.get(isin, 0.0)
        r = p["resid"]
        if isin in redeemed and p["econ_close"] < 0.5 and r < -0.5:
            r = 0.0  # погашение: бумаги списаны, это учёл денежный раздел
        if abs(r) <= 1e-6:
            r = 0.0
        if p["econ_open"] > 1e-6:
            ops.append(dict({"id": "vtb-open-sec-%s-%s" % (isin, period["from"]), "date": open_iso,
                             "type": "OPERATION_TYPE_INPUT_SECURITIES", "payment": to_money(0, "rub"),
                             "name": nm, "_ident": isin, "quantity": tb_qty_str(p["econ_open"]),
                             "quantityDone": tb_qty_str(p["econ_open"]), "price": to_money(round(unit, 9), "rub"),
                             "description": "Входящий остаток на начало периода (отчёт об остатках ценных бумаг)"}, **tag))
            stat["opening_sec"] += 1
        # продажи без покрытия FIFO не знает: недостающее довносим входящей операцией перед продажей и снимаем после покрытия
        run, short, extra = p["econ_open"] + max(r, 0.0), 0.0, []
        for t, q, u in split_timeline(day_deals.get(isin, ()), sp.get(isin, ())):
            if q is None:
                run *= u
                short *= u
                continue
            if q < 0:
                take = min(run, -q)
                run -= take
                if -q - take > 1e-6:
                    extra.append((True, -q - take, t - timedelta(seconds=1), u))
                    short += -q - take
            else:
                c = min(short, q)
                if c > 1e-6:
                    extra.append((False, c, t + timedelta(seconds=1), u))
                    short -= c
                run += q - c
        if short > 1e-6:
            extra.append((False, short, end_dt, unit))
        # движение без сделки с известной датой — отдельными операциями, остаток нерасшифрованного — на границе периода
        for x, sign in xfer:
            if x["isin"] == isin:
                extra.append((sign > 0, x["qty"], x["d"].replace(hour=0, minute=0, second=1), unit))
        if r > 0:
            extra.append((True, r, start.replace(second=1), unit))
        elif r < 0:
            extra.append((False, -r, end_dt, unit))
        for sec_in, qty_x, when, u in extra:
            xid = "vtb-xfer-%s-%s-%s" % ("in" if sec_in else "out", isin, tb_iso(when))
            xid = uniq_op_id(xid, xids)
            ops.append({"id": xid, "date": tb_iso(when),
                        "type": "OPERATION_TYPE_" + ("INPUT_SECURITIES" if sec_in else "OUTPUT_SECURITIES"),
                        "payment": to_money(0, "rub"), "name": nm, "_ident": isin,
                        "quantity": tb_qty_str(qty_x), "quantityDone": tb_qty_str(qty_x), "price": to_money(round(u, 9), "rub"),
                        "description": "Движение бумаг без сделки (отчёт ВТБ): перевод, корпоративное действие или продажа без покрытия"})
            stat["xfer_in" if sec_in else "xfer_out"] += 1
    for cur, (b_in, _b_out, _b_plan) in sorted(bal.items()):
        if abs(b_in) >= 0.005:
            ops.append(dict({"id": "vtb-open-cash-%s-%s" % (cur, period["from"]), "date": open_iso,
                             "type": "OPERATION_TYPE_INPUT" if b_in > 0 else "OPERATION_TYPE_X_OPENING",
                             "payment": to_money(round(b_in, 2), cur), "name": "Входящий остаток на начало периода"}, **tag))
            stat["opening_cash"] += 1
    ops.sort(key=lambda o: (o["date"], 0 if o.get("_opening") else 1))
    meta = {"format": "vtb", "title": "Отчёт брокера ВТБ", "period": period, "cash_open": {c: v[0] for c, v in bal.items()},
            "cash_close": {c: v[2] for c, v in bal.items()}, "pos": meta_pos, "stat": dict(stat)}
    return ops, meta


def broker_try(filename, raw):
    """(ops, meta) для отчёта известного брокера (Т-Инвестиции, ВТБ); иначе None — тогда общий импортёр."""
    fn = (filename or "").lower()
    if not (fn.endswith((".xlsx", ".xlsm")) or raw[:2] == b"PK"):
        return None
    try:
        tables = read_tables(filename, raw)
    except Exception:  # noqa: BLE001 — битый файл: пусть скажет общий импортёр
        return None
    t = tb_detect(tables)
    if t:
        return tbank_parse(t)
    t = vt_detect(tables)
    return vtb_parse(t) if t else None
# ═══════════════════════════════ сплиты в импорте отчётов ═══════════════════════════════
# В отчётах брокеров количество бумаг после сплита/консолидации «появляется без сделки» (3.1 на начало периода — до сплита,
# на конец — после). Список сплитов берём у Мосбиржи (ISS statistics/engines/stock/splits), сопоставляем бумагу по ISIN
# (secid в списке бывает тикером или самим ISIN) и:
#   1) при разборе отчёта количество на день сплита умножается на after/before, поэтому «движения без сделки» не возникает;
#   2) при слиянии файлов (finalize_import) в счёт вставляется пара служебных операций X_CONV_OUT / X_CONV_IN (как в 07a_conversions),
#      которая переносит лоты FIFO в новое количество и сохраняет стоимость и срок владения. Пара идемпотентна по id.
# Нет сети — работаем как раньше, без сплитов.

SPLITS_URL = "https://iss.moex.com/iss/statistics/engines/stock/splits.json?iss.meta=off"
SECURITY_URL = "https://iss.moex.com/iss/securities/%s.json?iss.meta=off&iss.only=description"


def moex_splits_list():
    """[{date, secid, before, after}] из ISS (кэш на сутки). При ошибке сети — [] (пустой результат не кэшируется)."""
    st = store()
    v = st.get("moex:splits", ttl=DAY)
    if v is not None:
        return v
    try:
        data = json.loads(http_text(SPLITS_URL))["splits"]
        cols = data["columns"]
        rows = []
        for r in data["data"]:
            d = dict(zip(cols, r))
            if d.get("tradedate") and d.get("secid") and d.get("before") and d.get("after"):
                rows.append({"date": str(d["tradedate"])[:10], "secid": str(d["secid"]), "before": float(d["before"]),
                             "after": float(d["after"])})
    except Exception:  # noqa: BLE001 — нет сети/сбой источника: импорт идёт без сплитов
        return []
    st.put("moex:splits", rows)
    return rows


def moex_secid_isin(secid):
    """ISIN по коду бумаги Мосбиржи (кэш на месяц); пустая строка, если узнать не удалось."""
    st = store()
    v = st.get("moex:secisin:" + secid, ttl=30 * DAY)
    if v is not None:
        return v
    try:
        data = json.loads(http_text(SECURITY_URL % urllib.parse.quote(secid)))["description"]
        cols = data["columns"]
        isin = ""
        for r in data["data"]:
            d = dict(zip(cols, r))
            if d.get("name") == "ISIN":
                isin = str(d.get("value") or "")
    except Exception:  # noqa: BLE001
        return ""
    st.put("moex:secisin:" + secid, isin)
    return isin


def splits_by_isin(d_from, d_to, wanted, secid_isin=None):
    """{ключ бумаги: [(дата 'ГГГГ-ММ-ДД', коэффициент after/before)]} для сплитов в [d_from; d_to] (строки дат) по нужным бумагам
    wanted (ISIN или тикеры, как они записаны в операциях). secid_isin — известные соответствия «код -> ISIN» из самого отчёта."""
    wanted = set(w for w in wanted if w)
    if not wanted:
        return {}
    rows = [r for r in moex_splits_list() if d_from <= r["date"] <= d_to and r["before"] and r["before"] != r["after"]]
    known = dict(secid_isin or {})
    need = sorted({r["secid"] for r in rows if r["secid"] not in wanted and r["secid"] not in known and not ISIN_RE.match(r["secid"])})
    for sid, isin in pool_map(lambda x: (x, moex_secid_isin(x)), need, workers=4):
        known[sid] = isin
    out = {}
    for r in rows:
        sid = r["secid"]
        key = sid if sid in wanted else known.get(sid)
        if key in wanted:
            out.setdefault(key, []).append((r["date"], r["after"] / r["before"]))
    return {k: sorted(v) for k, v in out.items()}


def split_label(before, after):
    f = lambda x: str(int(x)) if x == int(x) else str(x)
    return "Сплит %s:%s (Мосбиржа)" % (f(before), f(after)) if after >= before else "Консолидация %s:%s (Мосбиржа)" % (f(before), f(after))


def import_apply_splits(ops, until=None):
    """Вставляет в операции счёта пары X_CONV_OUT / X_CONV_IN на дни сплитов по всей истории (после слияния файлов).
    Ранее вставленные пары (id split:…) пересчитываются заново; бумаги, которых на день сплита не было, пропускаются."""
    ops = [o for o in ops if not str(o.get("id") or "").startswith("split:")]
    dates = sorted(o["date"][:10] for o in ops if o.get("date"))
    if not dates:
        return ops
    by_sec = defaultdict(list)
    for o in ops:
        if o.get("_sec") and classify(o["type"]) in ("buy", "sell", "sec_in", "sec_out", "repayments"):
            by_sec[o["_sec"]].append(o)
    # конец диапазона — сегодня: бумага могла остаться в портфеле, а сплит случиться уже после последней операции
    sp = splits_by_isin(dates[0], until or max(dates[-1], datetime.now(timezone.utc).strftime("%Y-%m-%d")), by_sec)
    zero = to_money(0, "rub")
    for sec, evs in sp.items():
        rows = sorted(by_sec[sec], key=lambda o: o["date"])
        for idx, (day, ratio) in enumerate(evs):
            qty, ei = 0.0, 0
            for o in rows:
                d = o["date"][:10]
                if d >= day:
                    break
                while ei < idx and evs[ei][0] <= d:   # предыдущие сплиты этой бумаги уже сработали
                    qty *= evs[ei][1]
                    ei += 1
                k, q = classify(o["type"]), op_qty(o)
                if k in ("buy", "sec_in"):
                    qty += q
                elif k in ("sell", "sec_out"):
                    qty -= q
                elif k == "repayments" and op_type(o) == "BOND_REPAYMENT_FULL":
                    qty = 0.0
            while ei < idx:
                qty *= evs[ei][1]
                ei += 1
            if qty <= 1e-6:
                continue
            new_q = qty * ratio
            new_q = int(round(new_q)) if abs(new_q - round(new_q)) < 1e-6 else round(new_q, 6)
            sample = max(rows, key=lambda o: o["date"])
            uid = sample.get("instrumentUid") or sample.get("figi")
            before, after = (1, ratio) if ratio >= 1 else (round(1 / ratio), 1)
            cv = {"from_key": uid, "to_key": uid, "ratio": ratio, "label": split_label(before, after), "source": "moex_split",
                  "old_uids": [uid], "new_uid": uid, "old_qty": qty, "new_qty": new_q}
            base = {"date": day + "T00:00:01Z", "state": "OPERATION_STATE_EXECUTED", "payment": dict(zero), "_conv": cv, "_sec": sec,
                    "name": sample.get("name") or sec, "instrumentUid": sample.get("instrumentUid"), "figi": sample.get("figi"),
                    "instrumentKind": sample.get("instrumentKind") or "INSTRUMENT_TYPE_SHARE"}
            cid = "split:%s:%s" % (sec, day)
            qs = lambda x: str(int(x)) if x == int(x) else repr(x)
            # «in» на секунду позже «out»: хранилище отдаёт операции по (дата, ключ), а ':in' < ':out' по алфавиту
            ops.append(dict(base, id=cid + ":out", type="OPERATION_TYPE_X_CONV_OUT", quantity=qs(qty), quantityDone=qs(qty)))
            ops.append(dict(base, id=cid + ":in", date=day + "T00:00:02Z", type="OPERATION_TYPE_X_CONV_IN",
                            quantity=qs(new_q), quantityDone=qs(new_q)))
    ops.sort(key=lambda o: (o["date"], 0 if o.get("_opening") else 1))
    return ops


def split_walk(run, events, splits):
    """Количество на конец периода: стартовое run, сделки events [(время, ±кол-во, …)], в дни сплитов количество умножается."""
    items = sorted([(x[0], 1, x[1]) for x in events] + [(datetime.strptime(d, "%Y-%m-%d"), 0, r) for d, r in splits],
                   key=lambda z: (z[0], z[1]))
    for _t, kind, v in items:
        run = run * v if kind == 0 else run + v
    return run


def split_timeline(events, splits):
    """Сделки (время, ±кол-во, цена) вперемешку с маркерами сплитов (время, None, коэффициент) в хронологическом порядке."""
    return sorted(list(events) + [(datetime.strptime(d, "%Y-%m-%d"), None, r) for d, r in splits],
                  key=lambda z: (z[0], 0 if z[1] is None else 1))
# ═══════════════════════════════ счета и сводка ═══════════════════════════════

_mem, _mem_lock = {}, threading.Lock()


def mem_get(key, ttl):
    with _mem_lock:
        hit = _mem.get(key)
    return hit[1] if hit and time.time() - hit[0] < ttl else None


def mem_put(key, val):
    with _mem_lock:
        _mem[key] = (time.time(), val)
    return val


def mem_clear(persist=True):
    """Сбрасывает кэш в памяти; persist=True — ещё и сохранённые результаты отчётов (после смены данных счетов)."""
    with _mem_lock:
        _mem.clear()
    if not persist:
        return
    try:
        store().write("DELETE FROM kv WHERE k LIKE 'res:%'")
    except Exception:  # noqa: BLE001
        pass


def imports_list():
    return store().get("imports") or []


def fetch_operations(client, cfg, acc, opened=None, full=False):
    """Инкрементальная загрузка: первый раз — вся история, дальше — только последние ~10 дней."""
    st = store()
    key = token_key(cfg) + ":" + acc
    meta = None if full else st.get("sync:" + key)
    now = datetime.now(timezone.utc)
    if full:
        st.ops_clear(key)
    if meta:
        frm = (datetime.strptime(meta[:19], "%Y-%m-%dT%H:%M:%S") - timedelta(days=10)).strftime("%Y-%m-%dT%H:%M:%SZ")
    else:
        frm = (opened or "2006-01-01T00:00:00Z")[:19] + "Z"
    items = client.operations(acc, frm, now.strftime("%Y-%m-%dT%H:%M:%SZ"))
    st.ops_put(key, items)
    st.put("sync:" + key, now.strftime("%Y-%m-%dT%H:%M:%SZ"))
    return st.ops(key)


def account_data(cfg, a, force=False):
    """(портфель как список строк позиций + итоги, операции, маржа) для одного счёта, с кэшем 90 с."""
    key = ("acc", token_key(cfg), a["id"])
    hit = None if force else mem_get(key, 90)
    if hit:
        return hit
    with key_lock(key):
        hit = None if force else mem_get(key, 90)
        return hit or _account_data(cfg, a, key)


def _account_data(cfg, a, key):
    client = TInvest(cfg)
    if a["kind"] == "import":
        ops = store().ops(a["id"])
        res = {"port": None, "ops": ops, "margin": None}
    else:
        with ThreadPoolExecutor(max_workers=3) as ex:
            fp = ex.submit(client.portfolio, a["id"])
            fo = ex.submit(fetch_operations, client, cfg, a["id"], a.get("opened"))
            fm = ex.submit(client.margin, a["id"])
            res = {"port": fp.result(), "ops": fo.result(), "margin": fm.result()}
    for o in res["ops"]:
        o["_acc"], o["_accname"] = a["id"], a["name"]
    return mem_put(key, res)


def _op_inst_keys(ops):
    """Собирает пары (instrumentUid, figi) из операций, исключая синтетические imp:-ключи."""
    return {(o.get("instrumentUid"), o.get("figi")) for o in ops
            if (o.get("instrumentUid") or o.get("figi")) and not str(o.get("instrumentUid") or "").startswith("imp:")}


def list_accounts(cfg, force=False):
    key = ("accounts", token_key(cfg))
    hit = None if force else mem_get(key, 60)
    if hit:
        return hit
    with key_lock(key):
        hit = None if force else mem_get(key, 60)
        return hit or _list_accounts(cfg, key)


def _list_accounts(cfg, key):
    client = TInvest(cfg)
    accs = []
    if client.ready:
        for x in client.accounts():
            accs.append({"id": x["id"], "name": x.get("name") or x["id"], "kind": "tinvest",
                         "type": {"ACCOUNT_TYPE_TINKOFF_IIS": "ИИС", "ACCOUNT_TYPE_INVEST_BOX": "Копилка"}.get(x.get("type"), ""),
                         "closed": x.get("status") == "ACCOUNT_STATUS_CLOSED", "opened": x.get("openedDate")})

        def tot(a):
            try:
                p = client.portfolio(a["id"])
                return qf(p.get("totalAmountPortfolio")), len(p.get("positions") or [])
            except ApiError:
                return 0.0, 0
        for a, (t, n) in zip(accs, pool_map(tot, accs)):
            a["total"], a["empty"] = t, (t < 0.01 and n == 0)
            a["broker_id"], a["broker_name"] = "tinvest", BROKERS["tinvest"]
    for imp in imports_list():
        a = {"id": imp["id"], "name": imp["name"], "kind": "import", "type": imp.get("broker") or "",
             "closed": False, "opened": None}
        a["broker_id"], a["broker_name"] = broker_of_account(imp)
        try:
            ops = store().ops(imp["id"])
            rows = imported_positions(client, ops, instruments(client, _op_inst_keys(ops)))
            a["total"] = sum((r["value_rub"] or 0) for r in rows)
        except Exception:  # noqa: BLE001
            a["total"] = 0.0
        a["empty"] = a["total"] < 0.01
        accs.append(a)
    if not accs:
        raise ApiError("Нет счетов: добавьте API-токен в «Настройках» или импортируйте отчёт брокера.", 404)
    return mem_put(key, accs)


def selection(cfg, acc, force=False):
    accs = list_accounts(cfg, force)
    if acc == "all":
        sel = [a for a in accs if not a["empty"]] or accs
    else:
        sel = [a for a in accs if a["id"] == acc] or [accs[0]]
    data = pool_map(lambda a: account_data(cfg, a, force), sel, workers=4)
    return accs, sel, data


def build_summary(cfg, acc, period, force=False):
    client = TInvest(cfg)
    accs, sel, data = selection(cfg, acc, force)
    ops = sorted([o for d in data for o in d["ops"]], key=lambda o: o.get("date") or "")
    keys = set()
    for d in data:
        for x in (d["port"] or {}).get("positions") or []:
            keys.add((x.get("instrumentUid"), x.get("figi")))
    keys |= _op_inst_keys(ops)
    names = instruments(client, keys)
    lists, extra = [], {"daily": 0.0, "has_daily": False, "yield_w": 0.0}
    for a, d in zip(sel, data):
        if d["port"] is not None:
            rows = tinvest_positions(d["port"], names)
            p = d["port"]
            if p.get("dailyYield"):
                extra["daily"] += qf(p["dailyYield"])
                extra["has_daily"] = True
            store().snap(token_key(cfg) + ":" + a["id"], qf(p.get("totalAmountPortfolio")))
        else:
            rows = imported_positions(client, d["ops"], names)
        lists.append(rows)
    rows = merge_positions(lists)
    t = totals_from_rows(rows)
    total = sum(qf((d["port"] or {}).get("totalAmountPortfolio")) for d in data if d["port"] is not None) + \
        sum(sum((r["value_rub"] or 0) for r in lst) for lst, d in zip(lists, data) if d["port"] is None)
    res = analyze(ops, names, period, total)
    # оптимизатор тарифов Т-Инвестиций — только по счетам Т-Инвестиций; стоимость для порогов тарифов — все счета Т
    t_ids = {a["id"] for a in sel if broker_of_account(a)[0] == "tinvest"}
    if t_ids:
        t_value = sum((a.get("total") or 0) for a in accs if broker_of_account(a)[0] == "tinvest" and not a.get("closed"))
        res["fee_model"] = fee_model(ops, names, t_value, t_accs=t_ids)
        res["fee_model"]["other_accounts"] = [a["name"] for a in sel if a["id"] not in t_ids]
    else:
        res["fee_model"] = None
    bt = cfg.get("broker_tariffs") if isinstance(cfg.get("broker_tariffs"), dict) else {}
    res["broker_fees"] = []
    for a in sel:
        bid, bname = broker_of_account(a)
        if bid == "tinvest":
            continue
        tid = bt.get(a["id"]) or ""
        tar = broker_tariff(bid, tid)
        row = broker_account_fees(a["id"], ops, names, tar)
        row.update(id=a["id"], name=a["name"], broker_id=bid, broker_name=bname, tariff_id=tid if tar else "",
                   tariffs=[{"id": x["id"], "name": x["name"]} for x in BROKER_TARIFFS.get(bid, {}).get("tariffs") or []])
        res["broker_fees"].append(row)
    cost = sum(r.get("cost_rub") or 0 for r in rows if r["type"] not in ("currency", "futures"))
    upnl = sum(r.get("pnl_rub") or 0 for r in rows if r["type"] not in ("currency",))
    res["portfolio"] = {"total": total, "shares": t["shares"], "bonds": t["bonds"], "etf": t["etf"],
                        "currencies": t["currencies"], "futures": t["futures"], "options": t["options"], "sp": t["sp"],
                        "other": t["other"], "upnl": upnl, "yield_pct": upnl / cost * 100 if cost else 0.0,
                        "daily": extra["daily"] if extra["has_daily"] else None,
                        "daily_pct": extra["daily"] / (total - extra["daily"]) * 100 if extra["has_daily"] and total - extra["daily"] else None,
                        "positions": rows}
    res["concentration"] = portfolio_concentration(rows)
    if len(sel) == 1 and data[0]["margin"]:
        m = data[0]["margin"]
        res["margin"] = {k: qf(m.get(k)) for k in ("liquidPortfolio", "startingMargin", "minimalMargin",
                                                   "fundsSufficiencyLevel", "amountOfMissingFunds", "correctedMargin")}
    res["accounts"] = accs
    res["account"] = "all" if acc == "all" else sel[0]["id"]
    res["selected"] = [a["id"] for a in sel]
    res["sandbox"] = cfg["sandbox"]
    res["token"] = bool(cfg["token"])
    res["updated"] = datetime.now().strftime("%H:%M")
    return res


BONDS_TTL, HIST_TTL = 600, 900
_bg = set()
_bg_lock = threading.Lock()


def cached_result(kind, cfg, acc, ttl, compute, force=False):
    """Результат тяжёлого отчёта (bonds/hist) по счёту. Свежий — из памяти; иначе последний сохранённый в базе отдаётся
    сразу с признаком stale=True, а пересчёт идёт в фоне (один на ключ). Без сохранённого — считаем и ждём.
    force=True — всегда считаем заново."""
    key = (kind, token_key(cfg), acc)
    skey = "res:%s:%s:%s" % (kind, token_key(cfg), acc)
    if not force:
        hit = mem_get(key, ttl)
        if hit:
            return hit
    st = store()

    def run():
        with key_lock(key):
            if not force:
                hit = mem_get(key, ttl)
                if hit:
                    return hit
            res = compute()
            mem_put(key, res)
            try:
                st.put(skey, {"t": time.time(), "v": res})
            except Exception:  # noqa: BLE001
                pass
            return res
    if not force:
        try:
            saved = st.get(skey)
        except Exception:  # noqa: BLE001
            saved = None
        if saved and saved.get("v") is not None and time.time() - saved.get("t", 0) < ttl:
            return mem_put(key, saved["v"])
        if saved and saved.get("v") is not None:
            with _bg_lock:
                start = key not in _bg
                _bg.add(key)
            if start:

                def bg():
                    try:
                        run()
                    except Exception:  # noqa: BLE001
                        pass
                    finally:
                        _bg.discard(key)
                threading.Thread(target=bg, daemon=True).start()
            v = dict(saved["v"])
            v["stale"] = True
            return v
    return run()


def build_bonds(cfg, acc, force=False):
    ratings_start()          # обновит рейтинги, если данным больше 12 часов
    def compute():
        s = build_summary(cfg, acc, "all")
        rep_ = bonds_report(TInvest(cfg), s["portfolio"]["positions"])
        try:
            expert_start([r["name"] for r in rep_["rows"]])      # дозапросит рейтинги Эксперт РА по эмитентам портфеля
        except Exception:  # noqa: BLE001
            pass
        return rep_
    hit = cached_result("bonds", cfg, acc, BONDS_TTL, compute, force)
    st = ratings_status()
    stamp = repr(ratings_stamp())                    # меняется и при обновлении рейтингов с сайтов агентств
    if hit.get("ratings_stamp") != stamp:
        hit["ratings"] = apply_ratings(hit["rows"])
        hit["ratings_stamp"] = stamp
    hit["ratings_info"] = st
    return hit


def build_history_for(cfg, acc, force=False):
    def compute():
        client = TInvest(cfg)
        accs, sel, data = selection(cfg, acc)
        ops = sorted([o for d in data for o in d["ops"]], key=lambda o: o.get("date") or "")
        keys = _op_inst_keys(ops)
        names = instruments(client, keys)
        total = sum(qf((d["port"] or {}).get("totalAmountPortfolio")) for d in data if d["port"] is not None)
        if any(d["port"] is None for d in data):
            total += sum(sum((r["value_rub"] or 0) for r in imported_positions(client, d["ops"], names)) for d in data if d["port"] is None)
        held, zero = None, set()
        if all(d["port"] is not None for d in data):     # текущие позиции — для проверки обменов бумаг
            held = defaultdict(float)
            for d in data:
                for x in d["port"].get("positions") or []:
                    ids = {x.get("instrumentUid"), x.get("positionUid"), x.get("figi")} - {None, ""}
                    for i in ids:
                        held[i] += qf(x.get("quantity"))
                    if qf(x.get("quantity")) > 0 and x.get("currentPrice") and not qf(x.get("currentPrice")) and not qf(x.get("currentNkd")):
                        zero |= ids
        return build_history(client, ops, names, total, held, zero) or {"days": []}
    return cached_result("hist", cfg, acc, HIST_TTL, compute, force)


def operations_csv(data):
    buf = io.StringIO()
    w = csv.writer(buf, delimiter=";")
    w.writerow(["Дата", "Тип", "Категория", "Название", "Тикер", "Кол-во", "Цена", "Сумма", "Валюта", "Комиссия", "Результат", "Счёт"])
    for r in data["ops"]:
        r = r[:11] + r[12:13]
        w.writerow([("" if not x else str(round(x, 9)).replace(".", ",")) if isinstance(x, (int, float)) else x for x in r])
    return buf.getvalue().encode("utf-8-sig")


# ═══════════════════════════════ логотипы ═══════════════════════════════

_logo_lock = threading.Lock()


def logo_bytes(name):
    base = re.sub(r"[^A-Za-z0-9_.-]", "", name or "").replace(".png", "")
    if not base:
        return None
    path = os.path.join(LOGO_DIR, base + ".png")
    miss = path + ".miss"
    if os.path.exists(path):
        with open(path, "rb") as f:
            return f.read()
    if os.path.exists(miss) and time.time() - os.path.getmtime(miss) < 3 * DAY:
        return None
    try:
        data = ext_open(LOGO_CDN + base + "x160.png", headers={"User-Agent": "Mozilla/5.0"}, timeout=15)[1]
        if not data.startswith(b"\x89PNG"):
            raise OSError("not png")
        with _logo_lock:
            os.makedirs(LOGO_DIR, exist_ok=True)
            with open(path, "wb") as f:
                f.write(data)
        return data
    except Exception:  # noqa: BLE001
        os.makedirs(LOGO_DIR, exist_ok=True)
        open(miss, "w").close()
        return None




def warmup_start():
    """Фоновый прогрев при запуске сервера: сводка, облигации, история (счета all) и каталог облигаций.
    Общие блокировки (key_lock) и кэши не дают дублировать работу с первыми запросами пользователя."""
    def job():
        try:
            cfg = load_config()
            if not (cfg.get("token") or "").strip() and not imports_list():
                return
            for fn in (lambda: build_summary(cfg, "all", "all"), lambda: tcat(),
                       lambda: build_bonds(cfg, "all"), lambda: build_history_for(cfg, "all")):
                try:
                    fn()
                except Exception:  # noqa: BLE001
                    pass
        except Exception:  # noqa: BLE001
            pass
    threading.Thread(target=job, daemon=True, name="warmup").start()
# ═══════════════ единая точка исходящих запросов за ПУБЛИЧНЫМИ данными (Мосбиржа, ФНС, ЦБ, рейтинги, МСФО, логотипы) ═══════════════
# Публичные данные идут через сервер данных (DS_DEFAULT; для разработки и тестов — TINVEST_DATA_SERVER / TINVEST_DATA_KEY):
# GET|POST {сервер}/v1/fetch?url=... Сервер кэширует ответы и сам ходит к источникам. При любой неудаче сервера
# (нет связи, таймаут, 5xx, 401/403) запрос выполняется напрямую, а сервер на 5 минут считается недоступным.
# Сервер по умолчанию — DS_DEFAULT; он требует личный ключ из Telegram-бота (7 дней), см. «вход по ключу» ниже
# (/api/auth/*). В интерфейсе адрес не меняется; «off» в TINVEST_DATA_SERVER (разработка) отключает сервер совсем.
# API Т-Инвестиций сюда НЕ входит: он всегда идёт напрямую, токен на сервер данных не передаётся. Уведомления Telegram — отдельный вызов POST /v1/notify (13j_watch.py).

EXT_UA = {"User-Agent": "Mozilla/5.0 (compatible; tinvest-analytics)"}
_ext_ctx = []
DS_DOWN_SECS = 300
DS_DEFAULT = "https://aurora-bot.duckdns.org:8443/tinvest"
DS_BOT_DEFAULT = "tanalyticbot"
AUTH_TTL = 60
SECRET_KEYS.add("data_key")
DEFAULT_CONFIG.setdefault("data_server", "")
DEFAULT_CONFIG.setdefault("data_key", "")
_ds_state = {"down_until": 0.0, "error": "", "hit": 0, "miss": 0, "stale": 0, "direct": 0}
_ds_lock = threading.Lock()
_ds_bypass = {}                          # host -> до какого времени не ходить через сервер (источник заблокировал сервер: 429/captcha)
_direct_block = {}                       # host -> [до какого времени не ходить и напрямую, число подряд отказов]
DS_BYPASS_DEFAULT, DS_BYPASS_MIN, DS_BYPASS_MAX = 300, 30, 1800
DIRECT_BLOCK_BASE, DIRECT_BLOCK_MAX = 120, 1800
_ds_conf_cache = [0.0, ("", "")]
_auth = {"need_login": False, "at": 0.0, "res": None, "bot": DS_BOT_DEFAULT}


def ds_conf():
    """(адрес сервера без «/», ключ). Настройки приложения важнее переменных окружения. Короткий кэш: вызывается на каждый запрос."""
    now = time.time()
    if now - _ds_conf_cache[0] < 2.0:
        return _ds_conf_cache[1]
    try:
        cfg = load_config()
    except Exception:  # noqa: BLE001
        cfg = {}
    # адрес в config.json учитывается, только если это URL (ручная правка для своего сервера); старое «off» из прежних
    # версий настроек больше не отключает сервер — данные рынка всегда берутся с сервера по умолчанию
    own = str(cfg.get("data_server") or "").strip()
    url = (own if re.match(r"https?://[^/\s]+", own) else
           os.environ.get("TINVEST_DATA_SERVER") or DS_DEFAULT).strip().rstrip("/")
    key = str(cfg.get("data_key") or os.environ.get("TINVEST_DATA_KEY") or "").strip()
    if not re.match(r"https?://[^/\s]+", url):          # в т.ч. «off»: сервер отключён
        url = ""
    _ds_conf_cache[:] = [now, (url, key)]
    return url, key


def ds_reset():
    _ds_conf_cache[0] = 0.0
    with _ds_lock:
        _ds_state["down_until"] = 0.0
        _ds_state["error"] = ""
    _auth_reset()


def _auth_reset():
    with _ds_lock:
        _auth["need_login"] = False
        _auth["at"] = 0.0
        _auth["res"] = None


def _ds_is_timeout(e):
    """Тайм-аут чтения (сервер жив, но этот ответ долгий), а не отказ соединения."""
    r = getattr(e, "reason", None)
    return isinstance(e, (TimeoutError, socket.timeout)) or isinstance(r, (TimeoutError, socket.timeout)) or "timed out" in str(e)


def _ds_down(msg):
    with _ds_lock:
        _ds_state["down_until"] = time.time() + DS_DOWN_SECS
        _ds_state["error"] = msg


def _ssl():
    if not _ext_ctx:                     # те же настройки проверки сертификатов, что и для API Т-Инвестиций (свой CA, корпоративный прокси)
        try:
            c = load_config()
            ctx = make_ssl_context(c.get("ca_file") or "", c.get("verify_ssl", True))
        except Exception:  # noqa: BLE001
            ctx = make_ssl_context()
        _ext_ctx.append(ctx)
    return _ext_ctx[0]


def _cookie_header(jar):
    return "; ".join("%s=%s" % kv for kv in jar.items()) if jar else ""


def _jar_update(jar, set_cookies):
    for c in set_cookies or []:
        nv = c.split(";", 1)[0]
        if "=" in nv:
            k, v = nv.split("=", 1)
            jar[k.strip()] = v.strip()


def _ds_host_refused(err):
    """403 сервера «host not allowed» (сайта нет в его списке) — это не отказ в ключе: сервер для остальных запросов не отключаем.
    Иначе один такой запрос раз в минуту (например, курс BTC в бегущей строке) держал бы сервер выключенным постоянно."""
    try:
        return (json.loads(err.read().decode("utf-8", "replace")) or {}).get("error") == "host not allowed"
    except Exception:  # noqa: BLE001
        return False


def _ds_note_bypass(host, hdr):
    """Сервер сообщил, что источник его заблокировал (X-Upstream-Blocked: секунды; 0 — одиночный отказ, хост не замораживаем)."""
    try:
        secs = int(float(hdr)) if hdr is not None else DS_BYPASS_DEFAULT
    except ValueError:
        secs = DS_BYPASS_DEFAULT
    if secs <= 0 and hdr is not None:
        return
    with _ds_lock:
        _ds_bypass[host] = time.time() + min(max(secs, DS_BYPASS_MIN), DS_BYPASS_MAX)


def _ds_bypassed(host):
    with _ds_lock:
        t = _ds_bypass.get(host, 0.0)
        if t and t <= time.time():
            _ds_bypass.pop(host, None)
            return False
        return bool(t)


def _direct_wait(host):
    with _ds_lock:
        b = _direct_block.get(host)
        return max(0, int(b[0] - time.time()) + 1) if b and b[0] > time.time() else 0


def _direct_note_fail(host, err):
    """Прямой запрос отклонён: 429 всегда, 403/451 — только для хоста, который уже обходит сервер. Пауза: Retry-After или 120 с, 240 … до 1800."""
    if err.code != 429 and not (err.code in (403, 451) and _ds_bypassed(host)):
        return
    ra = _retry_after_sec(getattr(err, "headers", None))
    with _ds_lock:
        n = _direct_block.get(host, [0.0, 0])[1]
        d = min(max(ra, 30), 21600) if ra is not None else min(DIRECT_BLOCK_BASE * (2 ** n), DIRECT_BLOCK_MAX)
        _direct_block[host] = [time.time() + d, n + 1]


def _retry_after_sec(headers):
    """Retry-After в секундах: число или HTTP-дата (RFC 7231); None, если заголовка нет или он не разбирается."""
    try:
        v = (headers.get("Retry-After") or "").strip()
    except AttributeError:
        return None
    if not v:
        return None
    try:
        return float(v)
    except ValueError:
        pass
    try:
        from email.utils import parsedate_to_datetime
        dt = parsedate_to_datetime(v)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return max(0.0, (dt - datetime.now(timezone.utc)).total_seconds())
    except (TypeError, ValueError, IndexError, OverflowError):
        return None


def _direct_note_ok(host):
    with _ds_lock:
        _direct_block.pop(host, None)


def _ds_request(srv, key, url, data, headers, timeout):
    """Запрос через сервер данных. Возвращает (статус, тело, content-type, set-cookie[], X-Cache) либо None (нужен прямой запрос).
    Ответ источника (в т.ч. 404) приходит с заголовком X-Cache; его отсутствие значит, что ответил сам сервер (ошибка)."""
    hd = {"User-Agent": EXT_UA["User-Agent"]}
    if key:
        hd["X-Client-Key"] = key
    for k, v in (headers or {}).items():
        if k.lower() in ("referer", "cookie", "accept", "accept-language"):
            hd["X-Up-" + k.title()] = v
        elif k.lower() == "content-type":
            hd["Content-Type"] = v
    req = urllib.request.Request(srv + "/v1/fetch?url=" + urllib.parse.quote(url, safe=""), data=data, headers=hd,
                                 method="POST" if data is not None else "GET")
    try:
        with urllib.request.urlopen(req, timeout=timeout + 5, context=_ssl()) as r:
            body = r.read()
            return (r.status, body, r.headers.get("Content-Type") or "", r.headers.get_all("X-Set-Cookie") or [],
                    r.headers.get("X-Cache") or "miss")
    except urllib.error.HTTPError as e:
        if e.headers.get("X-Cache"):                   # настоящий ответ источника (404 и т.п.): повторять напрямую не нужно
            return e.code, e.read(), e.headers.get("Content-Type") or "", [], e.headers.get("X-Cache")
        if e.headers.get("X-Upstream-Blocked") is not None:    # источник заблокировал сервер: этот хост пока ходим напрямую
            _ds_note_bypass((urllib.parse.urlparse(url).hostname or "").lower(), e.headers.get("X-Upstream-Blocked"))
            return None
        if e.headers.get("X-Upstream-Error"):         # сервер жив, но источник не ответил: пробуем напрямую, сервер не «роняем»
            return None
        if e.code == 403 and _ds_host_refused(e):     # сайта нет в списке сервера: этот запрос — напрямую, ключ тут ни при чём
            return None
        if e.code == 401:                              # ключ не принят: UI попросит войти; этот запрос всё же выполняем напрямую
            with _ds_lock:
                _auth["need_login"] = True
                _auth["res"] = None
        _ds_down("сервер ответил %d%s" % (e.code, " (неверный ключ)" if e.code in (401, 403) else ""))
        return None
    except Exception as e:  # noqa: BLE001
        if _ds_is_timeout(e):                          # медленный ответ одного запроса — не повод отключать сервер для всех
            return None
        _ds_down("нет связи с сервером: %s" % (getattr(e, "reason", None) or type(e).__name__))
        return None


DS_PARSED_V = 1


def ds_parsed(name, params=None, timeout=20):
    """Готовый разбор страницы источника с сервера данных: GET {сервер}/v1/parsed/<name>?... -> data либо None.
    None: сервер выключен/недоступен, старый сервер (404), ok:false, другая версия формата. Тогда вызывающий разбирает страницу сам."""
    srv, key = ds_conf()
    if not srv or time.time() < _ds_state["down_until"]:
        return None
    q = ("?" + urllib.parse.urlencode(params)) if params else ""
    hd = {"User-Agent": EXT_UA["User-Agent"]}
    if key:
        hd["X-Client-Key"] = key
    try:
        req = urllib.request.Request(srv + "/v1/parsed/" + name + q, headers=hd)
        with urllib.request.urlopen(req, timeout=timeout + 5, context=_ssl()) as r:
            j = json.loads(r.read().decode("utf-8", "replace"))
    except urllib.error.HTTPError as e:
        if e.code in (401, 403):
            with _ds_lock:
                _auth["need_login"] = e.code == 401 or _auth["need_login"]
                _auth["res"] = None
            _ds_down("сервер ответил %d" % e.code)
        return None                                    # 404 (старый сервер), 5xx источника и т.п. — не «роняем» сервер
    except Exception as e:  # noqa: BLE001
        if _ds_is_timeout(e):                          # медленный ответ одного запроса — не повод отключать сервер для всех
            return None
        _ds_down("нет связи с сервером: %s" % (getattr(e, "reason", None) or type(e).__name__))
        return None
    if not isinstance(j, dict) or j.get("ok") is not True or j.get("v") != DS_PARSED_V:
        return None
    return j.get("data")


def ext_open(url, data=None, headers=None, timeout=25, jar=None):
    """Запрос публичных данных -> (статус, байты, content-type). При HTTP-ошибке источника бросает urllib.error.HTTPError
    (как и прежний urlopen). jar — dict с cookie сессии (обновляется из ответа), нужен, например, raexpert (CSRF)."""
    headers = dict(headers or {})
    if jar:
        headers["Cookie"] = _cookie_header(jar)
    srv, key = ds_conf()
    host = (urllib.parse.urlparse(url).hostname or "").lower()
    if srv and time.time() >= _ds_state["down_until"] and not _ds_bypassed(host):
        res = _ds_request(srv, key, url, data, headers, timeout)
        if res is not None:
            status, body, ct, cookies, xc = res
            with _ds_lock:
                _ds_state[xc if xc in ("hit", "stale") else "miss"] += 1
            if jar is not None:
                _jar_update(jar, cookies)
            if status >= 400:
                raise urllib.error.HTTPError(url, status, "HTTP %d" % status, {"Content-Type": ct}, io.BytesIO(body))
            return status, body, ct
    wait = _direct_wait(host)
    if wait:                                            # источник ограничил и прямые запросы: сети не касаемся
        raise urllib.error.HTTPError(url, 429, "Источник %s временно ограничил запросы, повтор через %d с" % (host, wait),
                                     {"Retry-After": str(wait)}, io.BytesIO(b""))
    with _ds_lock:
        _ds_state["direct"] += 1
    hd = dict(EXT_UA)
    hd.update(headers)
    req = urllib.request.Request(url, data=data, headers=hd)
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=_ssl()) as r:
            body = r.read()
            if jar is not None:
                _jar_update(jar, r.headers.get_all("Set-Cookie"))
            result = r.status, body, r.headers.get("Content-Type") or ""
    except urllib.error.HTTPError as e:
        _direct_note_fail(host, e)
        raise
    _direct_note_ok(host)
    return result


def ds_status():
    srv, key = ds_conf()
    with _ds_lock:
        st = dict(_ds_state)
    down = bool(srv) and time.time() < st["down_until"]
    now = time.time()
    with _ds_lock:
        bypass = {h: int(t - now) + 1 for h, t in _ds_bypass.items() if t > now}
    return {"mode": "direct" if not srv else ("down" if down else "server"), "url": srv, "key_set": bool(key), "bypass": bypass,
            "hit": st["hit"], "miss": st["miss"], "stale": st["stale"], "direct": st["direct"],
            "error": st["error"] if down else "", "retry_in": max(0, int(st["down_until"] - time.time())) if down else 0}


def ds_get(cfg, acc, q, force):
    return ds_status()


def ds_test(cfg, body):
    """Проверка сервера: GET /v1/health. Поля url/key из формы; пустой ключ = сохранённый."""
    url = ds_conf()[0]
    key = str(body.get("key") or "").strip() or ds_conf()[1]
    if not re.match(r"https?://[^/\s]+", url):
        raise ApiError("Сервер данных отключён (TINVEST_DATA_SERVER=off).", 400)
    hd = {"User-Agent": EXT_UA["User-Agent"]}
    if key:
        hd["X-Client-Key"] = key
    try:
        with urllib.request.urlopen(urllib.request.Request(url + "/v1/health", headers=hd), timeout=10, context=_ssl()) as r:
            j = json.loads(r.read().decode("utf-8", "replace"))
    except urllib.error.HTTPError as e:
        raise ApiError("Сервер ответил %d%s" % (e.code, ": неверный или отсутствующий ключ" if e.code in (401, 403) else ""), 400)
    except Exception as e:  # noqa: BLE001
        raise ApiError("Не удалось подключиться: %s" % (getattr(e, "reason", None) or type(e).__name__), 400)
    if not isinstance(j, dict) or not j.get("ok"):
        raise ApiError("Это не сервер данных TAnalytic.", 400)
    return {"ok": True, "version": j.get("version", ""), "uptime": j.get("uptime", 0), "cache_items": j.get("cache_items", 0)}


# ─────────────── вход по ключу из Telegram-бота ───────────────
def _auth_http(srv, path, key):
    """GET {srv}{path} -> (код, dict). Бросает исключение при сетевой ошибке/таймауте."""
    hd = {"User-Agent": EXT_UA["User-Agent"]}
    if key:
        hd["X-Client-Key"] = key
    try:
        with urllib.request.urlopen(urllib.request.Request(srv + path, headers=hd), timeout=10, context=_ssl()) as r:
            code, raw = r.status, r.read()
    except urllib.error.HTTPError as e:
        code, raw = e.code, e.read()
    try:
        j = json.loads(raw.decode("utf-8", "replace"))
    except ValueError:
        j = None
    return code, (j if isinstance(j, dict) else {})


def _auth_eval(srv, key):
    """Состояние доступа по ответу сервера (без кэша)."""
    base = {"state": "ok", "error": "", "expires": None, "username": "", "bot": _auth["bot"], "server": srv,
            "plan": "pro", "pro_until": None, "trial": False}   # свой сервер / общий ключ / старый сервер: всё доступно
    try:
        if not key:                                    # без ключа пускаем, только если сервер открытый
            code, j = _auth_http(srv, "/v1/health", "")
            if code >= 500 or code == 0:
                return dict(base, state="offline", error="сервер ответил %d" % code)
            if j.get("bot"):
                base["bot"] = str(j["bot"])
            if j.get("auth") in ("keys", "key") or code in (401, 403):
                return dict(base, state="need_login", error="nokey")
            return base
        code, j = _auth_http(srv, "/v1/auth/check", key)
    except Exception as e:  # noqa: BLE001
        return dict(base, state="offline", error="нет связи с сервером: %s" % (getattr(e, "reason", None) or type(e).__name__))
    if j.get("bot"):
        base["bot"] = str(j["bot"])
    if code == 200 and j.get("ok", True):
        plan = str(j.get("plan") or "")
        if "pro_until" not in j:            # старый сервер отдавал заглушку plan="free" без тарифов — всё доступно
            plan = "pro"
        pu = j.get("pro_until")
        return dict(base, expires=j.get("expires"), username=str(j.get("username") or ""),
                    plan="free" if plan == "free" else "pro",
                    pro_until=pu if isinstance(pu, (int, float)) and not isinstance(pu, bool) else None,
                    trial=bool(j.get("trial")) and plan != "free")
    if code == 401 or code == 403:
        err = str(j.get("error") or "")
        return dict(base, state="need_login", error=err if err in ("expired", "banned") else "invalid")
    if code == 404:                                    # старый сервер без /v1/auth/check: доступ не ограничен
        return base
    return dict(base, state="offline", error="сервер ответил %d" % code)


def auth_status(force=False):
    srv, key = ds_conf()
    if not srv:                                        # сервер отключён: приложение работает напрямую
        return {"state": "ok", "error": "", "expires": None, "username": "", "bot": _auth["bot"], "server": "",
                "plan": "pro", "pro_until": None, "trial": False}
    now = time.time()
    with _ds_lock:
        if not force:
            if _auth["need_login"]:
                return {"state": "need_login", "error": "invalid" if key else "nokey", "expires": None, "username": "",
                        "bot": _auth["bot"], "server": srv}
            if _auth["res"] and now - _auth["at"] < AUTH_TTL and _auth["res"].get("server") == srv:
                r = _auth["res"]
                if not (r["state"] == "ok" and r["expires"] and r["expires"] <= now):
                    return dict(r)
    res = _auth_eval(srv, key)
    with _ds_lock:
        _auth["bot"] = res["bot"]
        _auth["need_login"] = res["state"] == "need_login"
        _auth["res"] = dict(res)
        _auth["at"] = time.time()
    return res


def auth_status_get(cfg, acc, q, force):
    return auth_status(force)


def auth_login(cfg, body):
    key = "".join(str(body.get("key") or "").split()).upper()
    if not key:
        raise ApiError("Введите ключ из бота.", 400)
    srv = ds_conf()[0]
    if not srv:
        raise ApiError("Сервер данных отключён в настройках: вход не нужен.", 400)
    res = _auth_eval(srv, key)
    if res["state"] == "need_login":
        msgs = {"expired": "Ключ истёк — получите новый в боте", "banned": "Доступ ограничен"}
        err = res["error"]
        return 401, {"error": msgs.get(err, "Неверный ключ"), "code": err, "bot": res["bot"]}
    if res["state"] == "offline":
        raise ApiError("Не удалось проверить ключ: %s." % res["error"], 502)
    c = load_config()
    c["data_key"] = key
    save_config(c)
    ds_reset()
    with _ds_lock:
        _auth["bot"] = res["bot"]
        _auth["res"] = dict(res)
        _auth["at"] = time.time()
    return res


def auth_logout(cfg, body):
    c = load_config()
    c["data_key"] = ""
    save_config(c)
    ds_reset()
    return {"state": "need_login", "error": "nokey", "expires": None, "username": "", "bot": _auth["bot"], "server": ds_conf()[0]}


API_GET["/api/auth/status"] = auth_status_get
API_POST["/api/auth/login"] = auth_login
API_POST["/api/auth/logout"] = auth_logout
API_GET["/api/dataserver"] = ds_get
API_POST["/api/dataserver/test"] = ds_test


def http_bytes(url, timeout=30):
    return ext_open(url, timeout=timeout)[1]


def http_text(url, timeout=25):
    return ext_open(url, timeout=timeout)[1].decode("utf-8", "replace")
# ═══════════════════ внешние данные: кредитные рейтинги, КБД, ключевая ставка ═══════════════════
# Наружу уходят только обезличенные GET-запросы к публичным страницам (t.me, cbr.ru, moex.com):
# ни токен, ни состав портфеля никуда не передаются.


# ── кредитные рейтинги (каналы @ru_ratings и @issuerRatings: АКРА, Эксперт РА, НКР, НРА) ──

RT_CHANNELS = ("ru_ratings", "issuerRatings")        # порядок = приоритет при равной дате записей
RATING_CH = "https://t.me/s/"
RT_LINK_HOSTS = ("acra-ratings.ru", "raexpert.ru", "ratings.ru", "ra-national.ru", "t.me")
RATING_SCALE = ["AAA", "AA+", "AA", "AA-", "A+", "A", "A-", "BBB+", "BBB", "BBB-", "BB+", "BB", "BB-",
                "B+", "B", "B-", "CCC", "CC", "C", "D"]
RT_KEY, RT_DAYS, RT_MAX_PAGES, RT_TTL, RT_OLD = "ratings_v3", 430, 280, 12 * 3600, 600      # RT_MAX_PAGES — на каждый канал
_L = "[AАBВCС]"
_NOTLET = "(?<![A-Za-zА-Яа-яЁё])"
_RATING_PATS = [re.compile(p) for p in (
    _NOTLET + "(" + _L + "{1,3})([+\\-−–]?)\\s?(?i:\\(RU\\))",
    _NOTLET + "ru(" + _L + "{1,3})([+\\-−–]?)(?![A-Za-zА-Яа-яЁё])(?!\\.[a-z])",
    _NOTLET + "(" + _L + "{1,3})([+\\-−–]?)\\.ru",
    _NOTLET + "(" + _L + "{1,3})([+\\-−–]?)\\|ru\\|")]
_LAT = str.maketrans({"А": "A", "В": "B", "С": "C"})
_Q_STOP = ("стабильн", "позитивн", "негативн", "развива", "наблюдени", "эксперт", "акра", "нкр", "нра", "рейтинг",
           "подробнее")
_LEGAL = {"пао", "ао", "ооо", "оао", "зао", "мфк", "мкк", "пко", "нко", "гк", "группа", "компания", "холдинг",
          "корпорация", "бо", "бп", "кс", "обл", "серия", "серии", "выпуск", "сфо"}
_rt_state = {"running": False, "progress": "", "error": ""}
_rt_lock = threading.Lock()
_rt_idx = {}


def _rating_token(t):
    best = None
    for p in _RATING_PATS:
        m = p.search(t)
        if m and (best is None or m.start() < best.start()):
            best = m
    if not best:
        return None
    v = (best.group(1) + best.group(2)).translate(_LAT).upper().replace("−", "-").replace("–", "-")
    return v if v in RATING_SCALE else None


def _rating_issuer(t):
    for m in re.finditer(r"[«\"“]([^»\"”]{2,70})[»\"”]", t):
        q = m.group(1).strip()
        ql = q.lower().replace("c", "с")
        if any(w in ql for w in _Q_STOP) or "|" in q or re.fullmatch(r"[A-Za-z0-9 ]{1,3}", q):
            continue
        return q
    m = re.search(r"(?:ПАО|АО|ООО|МФК|МКК|ПКО|НКО|ОАО|ЗАО)\s+([А-ЯЁA-Z][\wЁё\-]+(?:\s+[А-ЯЁA-Z][\wЁё\-]+)?)", t)
    if not m:
        m = re.search(r"рейтинг\w*\s+(?:кредитоспособности\s+|облигаци\w+\s+|выпуск\w*\s+)*"
                      r"([А-ЯЁA-Z][^,.«»\n]{2,55}?)\s+(?:на\s+уровне|до\s+уровня)", t, re.I)
        if not m:
            return None
        c = re.split(r"\s+(?:серии|серий|классов?)\b", m.group(1), flags=re.I)[0].strip()
        return c if c and not re.search(r"\d", c) and len(c.split()) <= 6 else None
    words = []
    for w in m.group(1).split():
        if w.upper() in ("НА", "ДО", "ПО", "И", "С", "В", "ПРОГНОЗ", "СЕРИИ", "СЕРИЯ", "ВЫПУСКА", "ОБЛИГАЦИЙ", "КЛАССА"):
            break
        words.append(w)
    return " ".join(words) or None


# Окончания для грубого стемминга: «Ульяновской»/«Ульяновская» и «Томска»/«Томск» дают одну основу,
# а разные компании с общим началом («Интерлизинг» и «ИнтерФудГрупп») — разные ключи.
_NAME_ENDINGS = ("иями", "ями", "ами", "ого", "его", "ому", "ему", "ыми", "ими", "ой", "ей", "ий", "ый", "ая", "яя",
                 "ое", "ее", "ые", "ие", "ых", "их", "ом", "ем", "ам", "ям", "ах", "ях", "ою", "ую", "юю",
                 "а", "я", "у", "ю", "е", "ы", "и", "о", "ь", "й")


def _name_stem(t):
    if not re.match(r"[а-я]", t):
        return t
    for e in _NAME_ENDINGS:
        if t.endswith(e) and len(t) - len(e) >= 4:
            return t[:-len(e)]
    return t


def name_tokens(s):
    """Основы слов названия (без правовых форм, номеров и падежных окончаний): ключи эмитента для группировки и журнала."""
    out = set()
    for i, t in enumerate(re.findall(r"[a-zа-я0-9]+", (s or "").lower().replace("ё", "е"))):
        if t in _LEGAL or (i == 0 and t == "банк") or len(t) < 2 or any(ch.isdigit() for ch in t):
            continue
        out.add(_name_stem(t))
    return frozenset(out)


_SERIES_TOK = re.compile(r"^(?:бо|боп|бп|п|кс|обл|р|с)?\d+[а-я]?\d*$")        # п01, боп1, бо01: хвост серии выпуска


def name_words(s):
    """Полные нормализованные слова названия по порядку (без правовых форм и слов с цифрами); «Банк» в начале остаётся.
    Если ничего не осталось («А101 001Р-01»), берутся слова с буквы с цифрами внутри, кроме признаков серии."""
    toks = [t for t in re.findall(r"[a-zа-я0-9]+", (s or "").lower().replace("ё", "е")) if t not in _LEGAL and len(t) >= 2]
    out = tuple(t for t in toks if not any(ch.isdigit() for ch in t))
    return out or tuple(t for t in toks if t[0].isalpha() and not _SERIES_TOK.match(t))


def _words_key(w):
    return "".join(sorted(set(w)))


def _words_match(bw, iw):
    """Сравнение названий по полным словам: (100, ...) — равны; иначе приблизительный балл (<100) или None.
    Совпадение только по префиксу допустимо, если одно слово — сокращение другого (капитал ~ кап, сбербанк ~ сберб)."""
    bs, is_ = frozenset(bw), frozenset(iw)
    if not bs or not is_:
        return None
    if bs == is_:
        return 100.0
    bj, ij = "".join(bw), "".join(iw)
    lo, hi = (bj, ij) if len(bj) <= len(ij) else (ij, bj)
    if len(lo) >= 5 and hi.startswith(lo):                          # «ГазпромКап» ~ «Газпром капитал»
        return float(min(len(lo), 90))
    small, big = (bs, is_) if len(bs) <= len(is_) else (is_, bs)
    sc = 0
    used = set()
    for w in small:
        hit = w if w in big else next((x for x in big if x not in used and min(len(w), len(x)) >= 4
                                       and (x.startswith(w) or w.startswith(x))), None)
        if hit is None:
            return None
        used.add(hit)
        sc += min(len(w), len(hit))
    rest = big - used
    if sc < 5 or (sc < 6 and any(len(x) > 2 for x in rest)):
        return None
    return float(min(sc, 90))


def parse_rating_post(text):
    low = text.lower()
    head = low[:80]
    agency = next((a for pat, a in ((r"\bакра\b", "АКРА"), (r"эксперт\s+ра", "Эксперт РА"), (r"\bнкр\b", "НКР"),
                                    (r"\bнра\b", "НРА")) if re.search(pat, head)), None)
    if not agency or re.search(r"ожидаем|\.sf|структурир|сфо|\bкласс|esg|\.gq|качеств|надежност|некредитн|\.am", low):
        return None
    issuer = _rating_issuer(text)
    if not issuer:
        return None
    level = "bond" if re.search(r"облигаци|выпуск", low) else "issuer"
    if "отозва" in low:
        return {"agency": agency, "issuer": issuer, "level": level, "withdrawn": True}
    v = _rating_token(re.split(r"(?i)\bранее\b", text)[0])
    if not v:
        return None
    om = re.search(r"прогноз.{0,40}?(стабильн|позитивн|негативн|развивающ)", low)
    return {"agency": agency, "issuer": issuer, "level": level, "rating": v,
            "outlook": {"стабильн": "стабильный", "позитивн": "позитивный", "негативн": "негативный",
                        "развивающ": "развивающийся"}.get(om.group(1), "") if om else ""}


def rt_safe_url(u):
    """Ссылка на пресс-релиз: только https:// и хосты агентств/Telegram, иначе пустая строка."""
    u = (u or "").strip()
    try:
        pu = urllib.parse.urlsplit(u)
    except ValueError:
        return ""
    h = (pu.hostname or "").lower()
    if pu.scheme != "https" or not h or pu.username or pu.password:
        return ""
    return u if any(h == d or h.endswith("." + d) for d in RT_LINK_HOSTS) else ""


def rt_post_url(src, post):
    return "https://t.me/%s/%s" % (src or "issuerRatings", post) if post else None


_RR_AGENCY = (("акра", "АКРА"), ("эксперт", "Эксперт РА"), ("нкр", "НКР"), ("нра", "НРА"))
_RR_FIELDS = {"🏢": "co", "📝": "txt", "📊": "rt", "📅": "dt", "🔗": "url"}
_RR_RU = re.compile(r"(?i)\bru|\.ru|\(ru\)|\|ru\|")
_RT_SKIP = r"ожидаем|\.sf|структурир|сфо|\bкласс|esg|\.gq|качеств|надежност|некредитн|\.am"
_RR_OUT = {"стабильн": "стабильный", "позитивн": "позитивный", "негативн": "негативный", "развивающ": "развивающийся"}


def _ru_fields(text, links=None):
    """Разбор поста ru_ratings: (агентство, {поле: значение}). Поля: co 🏢, txt 📝, rt 📊, dt 📅, url 🔗."""
    lines = [x.strip() for x in (text or "").split("\n") if x.strip()]
    if not lines:
        return None, {}
    m = re.match(r"рейтинг\s+от\s+(.+)", lines[0], re.I)
    if not m:
        return None, {}
    nm = m.group(1).lower()
    agency = next((a for k, a in _RR_AGENCY if nm.startswith(k)), None)
    f = {}
    for ln in lines[1:]:
        for em, k in _RR_FIELDS.items():
            if ln.startswith(em):
                f.setdefault(k, ln[len(em):].strip())
                break
    url = rt_safe_url(f.get("url", ""))
    if not url:
        url = next((rt_safe_url(u) for u in links or [] if rt_safe_url(u)), "")
    f["url"] = url
    return agency, f


def _ru_body(agency, f):
    """Текст релиза для общих разборщиков: «📝» (Эксперт РА) либо «📊»/«🏢» (АКРА, НКР, НРА — текст в первой строке)."""
    parts = [f.get(k) for k in ("txt", "co", "rt") if f.get(k)]
    if "txt" not in f and "rt" in f:
        parts = [f["rt"]] + ([f["co"]] if f.get("co") else [])
    return " ".join(parts)


def _ru_iso(f, iso):
    m = re.fullmatch(r"(\d\d)\.(\d\d)\.(\d{4})", f.get("dt", ""))
    return "%s-%s-%s" % (m.group(3), m.group(2), m.group(1)) if m else (iso or "")[:10]


def parse_ru_ratings_post(text, links=None, iso=None):
    """Пост @ru_ratings -> {agency, issuer, level, rating, outlook, date, url} (или withdrawn=True), либо None.
    Структура: «Рейтинг от <агентство>», затем строки 🏢 эмитент, 📝 релиз, 📊 рейтинг, 📅 дата, 🔗 ссылка."""
    agency, f = _ru_fields(text, links)
    if not agency:
        return None
    body = _ru_body(agency, f)
    r = parse_rating_post("%s\n%s" % (agency, body))
    if not r and f.get("co") and "txt" not in f and _RR_RU.search(f.get("rt", "")) \
            and not re.search(_RT_SKIP, body.lower()):        # регионы и т. п.: только «🏢 название» и «📊 ruA (Стабильный)»
        v = _rating_token(f["rt"])
        if v:
            r = {"issuer": f["co"], "level": "issuer", "rating": v, "outlook": ""}
    if not r:
        return None
    date_ = _ru_iso(f, iso)
    if not date_:
        return None
    r = dict(r, issuer=re.sub(r"\s+", " ", re.sub(r"[«»\"“”]", "", r["issuer"])).strip())      # вложенные кавычки: «НК «РОСНЕФТЬ»
    out = {"agency": agency, "issuer": r["issuer"], "level": r["level"], "date": date_, "url": f.get("url", "")}
    if r.get("withdrawn"):
        out["withdrawn"] = True
        return out
    v = _rating_token(f.get("rt", "")) if _RR_RU.search(f.get("rt", "")) else None
    out["rating"] = v or r["rating"]
    om = re.search(r"(стабильн|позитивн|негативн|развивающ)", (f.get("rt") or "").lower())
    out["outlook"] = _RR_OUT[om.group(1)] if om else r.get("outlook", "")
    return out


RT_LOG_KEY, RT_LOG_DAYS = "ratings_log_v1", 730        # журнал рейтинговых действий: отдельно от ratings_v1
_RT_D = re.compile(r"(?<![A-Za-zА-Яа-яЁё])(?:ru\s?D(?![A-Za-zА-Яа-я])|D\s?\(RU\)|D\.ru|RD(?![A-Za-z]))")
_RT_ACTIONS = {"присвоен", "подтверждён", "повышен", "понижен", "отозван", "под наблюдением", "прогноз изменён"}


def _rt_tok_d(t):
    return "D" if _RT_D.search(t or "") else _rating_token(t or "")


def parse_rating_action(text):
    """Рейтинговое действие из поста: {agency, issuer, level, action, rating, prev, outlook, watch, url} или None.
    Шире parse_rating_post: понимает дефолтные уровни (D/RD), «ранее ...», «с X до Y», статус «под наблюдением»."""
    r = parse_rating_post(text)
    low = text.lower()
    head = low[:80]
    if not r:
        agency = next((a for pat, a in ((r"\bакра\b", "АКРА"), (r"эксперт\s+ра", "Эксперт РА"), (r"\bнкр\b", "НКР"),
                                        (r"\bнра\b", "НРА")) if re.search(pat, head)), None)
        if not agency or re.search(r"ожидаем|\.sf|структурир|сфо|\bкласс|esg|\.gq|качеств|надежност|некредитн|\.am", low):
            return None
        issuer = _rating_issuer(text)
        if not issuer or not _RT_D.search(re.split(r"(?i)\bранее\b", text)[0]):
            return None
        r = {"agency": agency, "issuer": issuer, "level": "bond" if re.search(r"облигаци|выпуск", low) else "issuer",
             "rating": "D", "outlook": ""}
    first = re.split(r"\n", text.strip())[0]
    fl = first.lower()
    parts = re.split(r"(?i)\bранее\b", first, maxsplit=1)
    prev = None
    if len(parts) > 1:
        prev = _rt_tok_d(parts[1])
    else:
        m = re.search(r"(?i)\bс\s+(\S+?)\s+до\s+(\S+)", first)
        if m:
            prev = _rt_tok_d(m.group(1))
            r = dict(r, rating=_rt_tok_d(m.group(2)) or r.get("rating"))     # НКР: «с AA.ru до AA-.ru» — новый уровень второй
    watch = ""
    if re.search(r"сн[яя]л\w*\s+статус|снят\w*\s+статус", fl):
        watch = "removed"
    elif re.search(r"статус\w*\s+[«\"“]под наблюдением", fl) and re.search(r"присво|продли|установил|ввел|ввело", fl):
        watch = "set"
    elif "под наблюдением" in fl and "ранее" not in fl.split("под наблюдением")[0]:
        watch = "set"
    if "отозва" in fl:
        act = "отозван"
    elif re.search(r"повысил", fl):
        act = "повышен"
    elif re.search(r"понизил|снизил", fl):
        act = "понижен"
    elif watch == "set" and re.search(r"присво\w+\s+статус|установил\w*\s+статус", fl):
        act = "под наблюдением"
    elif re.search(r"изменил\w*\s+прогноз|изменив\s+прогноз|прогноз\w*\s+(?:по рейтингу\s+)?(?:был\s+)?изменен|пересмотрел\w*\s+прогноз", fl):
        act = "прогноз изменён"
    elif "подтверд" in fl:
        act = "подтверждён"
    elif "присво" in fl:
        act = "присвоен"
    elif watch == "set":
        act = "под наблюдением"
    else:
        return None
    um = re.search(r"https?://\S+", text[len(first):])
    om = re.search(r"прогноз.{0,60}?\bна\s+[«\"“]?(стабильн|позитивн|негативн|развивающ)", fl)
    if om:
        r = dict(r, outlook={"стабильн": "стабильный", "позитивн": "позитивный", "негативн": "негативный",
                             "развивающ": "развивающийся"}[om.group(1)])
    out = {"agency": r["agency"], "issuer": r["issuer"], "level": r["level"], "action": act,
           "rating": r.get("rating"), "prev": prev, "outlook": r.get("outlook") or "", "watch": watch,
           "url": um.group(0).rstrip(".,)") if um else ""}
    if act == "понижен" and out["rating"] and prev and out["rating"] == prev:
        out["action"] = "прогноз изменён"
    return out


def rating_log_add(log, pid, iso, text, src="issuerRatings", links=None):
    url = ""
    if src == "ru_ratings":                      # пост ru_ratings: действие читается из «📝»/«📊», дата — из «📅», ссылка — пресс-релиз
        agency, f = _ru_fields(text, links)
        if not agency:
            return
        a = parse_rating_action("%s: %s\n" % (agency, _ru_body(agency, f)))
        iso, url = _ru_iso(f, iso), f.get("url", "")
    else:
        a = parse_rating_action(text)
    if not a:
        return
    toks = sorted(name_tokens(a["issuer"]))
    if not toks:
        return
    a.update(post=pid, date=iso[:10], tokens=toks, src=src, url=url or rt_safe_url(a.get("url")))
    log["events"].append(a)


def rating_log_trim(log):
    old = (date.today() - timedelta(days=RT_LOG_DAYS)).isoformat()
    evs = sorted((e for e in log["events"] if e["date"] >= old), key=lambda e: (e["date"], e.get("src") or "", e["post"]))
    ru = [e for e in evs if e.get("src") == "ru_ratings"]

    def dup(e):       # то же действие уже есть из ru_ratings (даты постов могут различаться на пару дней)
        if e.get("src") == "ru_ratings":
            return False
        d0 = date.fromisoformat(e["date"])
        return any(x["agency"] == e["agency"] and x["tokens"] == e["tokens"] and x["action"] == e["action"]
                   and x["level"] == e["level"] and x.get("rating") == e.get("rating") and x.get("prev") == e.get("prev")
                   and abs((date.fromisoformat(x["date"]) - d0).days) <= 2 for x in ru)
    log["events"] = [e for e in evs if not dup(e)]


def tg_parse_page(s, channel):
    """HTML зеркала t.me/s/<канал> -> (ids, посты [(id, iso, текст, [ссылки])])."""
    import html as _html
    ids, posts = [], []
    for blk in s.split("tgme_widget_message_wrap")[1:]:
        m = re.search(r'data-post="%s/(\d+)"' % re.escape(channel), blk, re.I)
        if not m:
            continue
        ids.append(int(m.group(1)))
        t = re.search(r'tgme_widget_message_text[^>]*>(.*?)</div>', blk, re.S)
        d = re.search(r'<time datetime="([^"]+)"', blk)
        if t and d:
            raw = t.group(1)
            links = [_html.unescape(h) for h in re.findall(r'<a\s[^>]*href="([^"]+)"', raw)]
            txt = _html.unescape(re.sub(r"<br/?>", "\n", re.sub(r"<(?!br)[^>]+>", "", raw)))
            posts.append((int(m.group(1)), d.group(1), txt, links))
    return ids, posts


def tg_page(before=None, channel="ru_ratings"):
    return tg_parse_page(http_text("%s%s%s" % (RATING_CH, channel, "?before=%d" % before if before else "")), channel)


def rt_post_parse(channel, text, links, iso):
    """Пост канала -> запись о рейтинге (как parse_rating_post + date/url) либо None."""
    if channel == "ru_ratings":
        return parse_ru_ratings_post(text, links, iso)
    r = parse_rating_post(text)
    if r:
        um = re.search(r"https?://\S+", text)
        r = dict(r, date=iso[:10], url=rt_safe_url(um.group(0).rstrip(".,)")) if um else "")
    return r


def rt_merge(items, key, rec):
    """Положить запись в items: из того же канала — всегда (посты идут по возрастанию), из другого — только если свежее
    по дате, при равной дате побеждает канал с меньшим индексом в RT_CHANNELS (ru_ratings)."""
    old = items.get(key)
    if old:
        osrc, nsrc = old.get("src") or "issuerRatings", rec["src"]
        if osrc != nsrc:
            rk = lambda c: RT_CHANNELS.index(c) if c in RT_CHANNELS else 99
            if (rec["date"], -rk(nsrc)) < (old["date"], -rk(osrc)):
                return
            if not rec.get("url") and old.get("url") and old.get("rating") == rec.get("rating"):
                rec = dict(rec, url=old["url"])
    items[key] = rec


def _rt_scan(channel, base_id, cutoff):
    got, before, pages = {}, None, 0
    while pages < RT_MAX_PAGES:
        ids, posts = None, None
        for _ in range(3):
            try:
                ids, posts = tg_page(before, channel)
                break
            except Exception:  # noqa: BLE001
                time.sleep(1.5)
        if ids is None:
            raise OSError("не удалось загрузить канал @%s (нет доступа к t.me)" % channel)
        if not ids:
            break
        pages += 1
        for p in posts:
            got[p[0]] = p
        _rt_state["progress"] = "@%s: загружено страниц %d" % (channel, pages)
        mn = min(ids)
        oldest = min((p[1] for p in posts), default="9")
        if base_id and mn <= base_id:
            break
        if not base_id and oldest < cutoff:
            break
        if before is not None and mn >= before:
            break
        before = mn
        time.sleep(0.25)
    return got


def _ratings_run():
    st = store()
    try:
        try:
            sites_refresh(force=True)         # НКР: полный список эмитентов с сайта
        except Exception:  # noqa: BLE001
            pass
        data = st.get(RT_KEY) or {"items": {}, "max_ids": {}, "updated": 0}
        rlog = st.get(RT_LOG_KEY) or {"events": [], "max_id": 0}
        dm, lm = data.setdefault("max_ids", {}), rlog.setdefault("max_ids", {"issuerRatings": rlog.get("max_id", 0)})
        cutoff = (datetime.now(timezone.utc) - timedelta(days=RT_DAYS)).isoformat()
        items, errs, okc = data["items"], [], 0
        for ch in RT_CHANNELS:
            try:       # пока журнал пуст — догружаем канал до границы RT_DAYS
                got = _rt_scan(ch, min(dm.get(ch, 0), lm.get(ch, 0)), cutoff)
            except Exception as e:  # noqa: BLE001
                errs.append(str(e)[:120])
                continue
            okc += 1
            for pid in sorted(got):
                _, iso, text, links = got[pid]
                if pid > lm.get(ch, 0):
                    try:
                        rating_log_add(rlog, pid, iso, text, ch, links)
                    except Exception:  # noqa: BLE001
                        pass
                if pid <= dm.get(ch, 0):
                    continue
                try:
                    r = rt_post_parse(ch, text, links, iso)
                except Exception:  # noqa: BLE001
                    r = None
                if not r:
                    continue
                toks = _words_key(name_words(r["issuer"]))
                if not toks:
                    continue
                key = "%s|%s|%s" % (toks, r["agency"], r["level"])
                if r.get("withdrawn"):
                    if r["level"] == "issuer" and (key not in items or items[key]["date"] <= r["date"]):
                        items.pop(key, None)
                    continue
                rt_merge(items, key, {"issuer": r["issuer"], "agency": r["agency"], "level": r["level"],
                                      "rating": r["rating"], "outlook": r["outlook"], "date": r["date"], "post": pid,
                                      "src": ch, "url": r.get("url") or ""})
            if got:
                dm[ch] = max(dm.get(ch, 0), max(got))
                lm[ch] = max(lm.get(ch, 0), max(got))
        if not okc:
            raise OSError(errs[0] if errs else "не удалось загрузить каналы рейтингов")
        data["max_id"] = max(dm.values() or [0])
        data["updated"] = time.time()
        st.put(RT_KEY, data)
        rlog["max_id"] = lm.get("issuerRatings", rlog.get("max_id", 0))
        rating_log_trim(rlog)
        st.put(RT_LOG_KEY, rlog)
        _rt_state["error"] = "; ".join(errs)
        _rt_idx.clear()
    except Exception as e:  # noqa: BLE001
        _rt_state["error"] = str(e)[:200]
    finally:
        _rt_state["running"] = False
        _rt_state["progress"] = ""


def ratings_start(force=False):
    with _rt_lock:
        if _rt_state["running"]:
            return False
        if not force:
            d = store().get(RT_KEY)
            if d and time.time() - d.get("updated", 0) < RT_TTL:
                return False
        _rt_state["running"] = True
    threading.Thread(target=_ratings_run, daemon=True).start()
    return True


def ratings_status():
    d = store().get(RT_KEY) or {}
    return {"updated": d.get("updated"), "count": len(d.get("items") or {}), "running": _rt_state["running"],
            "progress": _rt_state["progress"], "error": _rt_state["error"]}


_RT_PREV = {"ratings_v3": ("ratings_v2", "ratings_v1")}


def _rt_src(key):
    """Хранилище рейтингов; пока новая версия пуста (после смены ключа идёт пересканирование) — берём прежнюю."""
    st = store()
    d = st.get(key)
    if d and d.get("items"):
        return d, 2
    for i, k in enumerate(_RT_PREV.get(key) or ((key[:-2] + "v1",) if key.endswith("_v2") else ())):
        old = st.get(k)
        if old and old.get("items"):
            return old, 1 + i * 10
    return d or {}, 2


def ratings_stamp():
    return _rating_index()["u"]


def _rating_index():
    (d, v1), (sd, v2), (ed, v3) = _rt_src(RT_KEY), _rt_src(SITE_KEY), _rt_src(EXP_KEY)
    stamp = (d.get("updated"), v1, sd.get("updated"), v2, len(ed.get("items") or {}), v3)
    if _rt_idx.get("u") != stamp:
        old = (date.today() - timedelta(days=RT_OLD)).isoformat()
        merged = {}
        for src in (d.get("items") or {}, sd.get("items") or {}, ed.get("items") or {}):
            for k, it in src.items():
                if it["date"] >= old and (k not in merged or it["date"] > merged[k]["date"]
                                          or (it["date"] == merged[k]["date"] and not (merged[k].get("url") or merged[k].get("post")))):
                    merged[k] = it
        items = [(it, name_words(it["issuer"])) for it in merged.values()]
        exact, inv = {}, {}
        for it, ws in items:
            if not ws:
                continue
            exact.setdefault(frozenset(ws), []).append(it)
            for t in {w[:4] for w in ws}:                              # кандидаты по 4-символьному префиксу слова
                inv.setdefault(t, []).append((it, ws))
        _rt_idx.clear()
        _rt_idx.update(u=stamp, items=items, exact=exact, inv=inv)
    return _rt_idx


def _rt_link(it):
    """url пресс-релиза (если есть), иначе ссылка на пост в Telegram, иначе None; плюс post/src записи."""
    post, src = it.get("post"), it.get("src") or ("issuerRatings" if it.get("post") else None)
    return {"url": rt_safe_url(it.get("url")) or rt_post_url(src, post) or None, "post": post, "src": src}


def rating_for(name):
    """Рейтинг эмитента по названию облигации. Точное совпадение названий — надёжно, частичное — approx."""
    bw = name_words(name)
    if not bw:
        return None
    ix = _rating_index()
    best = {}

    def put(it, sc):
        sc += 0.5 if it["level"] == "issuer" else 0
        cur = best.get(it["agency"])
        if cur is None or sc > cur[0] or (sc == cur[0] and it["date"] > cur[1]["date"]):
            best[it["agency"]] = (sc, it)
    bset = frozenset(bw)
    for it in ix.get("exact", {}).get(bset, []):
        put(it, 100.0)
    seen = set()
    for t in {w[:4] for w in bw}:
        for it, ws in ix.get("inv", {}).get(t, []):
            if id(it) in seen or frozenset(ws) == bset:
                continue
            seen.add(id(it))
            sc = _words_match(bw, ws)
            if sc:
                put(it, sc)
    if not best:
        return None
    allr = [{"agency": a, "rating": it["rating"], "issuer": it["issuer"], "date": it["date"], "outlook": it["outlook"],
             "approx": sc < 100, **_rt_link(it)} for a, (sc, it) in best.items()]
    pool = [x for x in allr if not x["approx"]] or allr                  # приблизительные не влияют на «худший», пока есть точные
    low = max(pool, key=lambda x: RATING_SCALE.index(x["rating"]))     # консервативно: худшая из оценок
    return {"v": low["rating"], "agency": low["agency"], "issuer": low["issuer"], "date": low["date"],
            "approx": low["approx"], "url": low["url"], "post": low["post"], "src": low["src"], "all": allr}


def apply_ratings(rows):
    dist = defaultdict(float)
    for r in rows:
        r["rating"] = best_rating(r.get("isin") or r.get("ticker"), r.get("name") or "")
        dist[rating_bucket(r["rating"]["v"] if r["rating"] else None)] += r.get("value_rub") or 0
    return sorted(dist.items(), key=lambda x: -x[1])


def rating_bucket(v):
    if not v:
        return "нет рейтинга"
    i = RATING_SCALE.index(v)
    return "AAA" if i == 0 else "AA" if i <= 3 else "A" if i <= 6 else "BBB" if i <= 9 else "BB и ниже"


# ── рейтинги напрямую с сайтов агентств (НКР — список эмитентов, Эксперт РА — поиск по эмитенту) ──
# АКРА и НРА с сайтов недоступны программам (у АКРА сервер отдаёт неполную цепочку сертификатов,
# у НРА — таймауты), поэтому их рейтинги идут только из канала @issuerRatings.

SITE_KEY, EXP_KEY = "ratings_site_v2", "ratings_expert_v2"
_exp_state = {"running": False}
_SERIES_WORDS = {"бо", "бп", "кс", "обл", "серия", "серии", "выпуск"}


def _strip(t):
    import html as _h
    return re.sub(r"\s+", " ", _h.unescape(re.sub(r"<[^>]+>", " ", t))).strip()


def nkr_fetch():
    s = http_text("https://ratings.ru/ratings/issuers/", timeout=45)
    items = {}
    for row in re.findall(r'<tr id="bx_[^"]+".*?</tr>', s, re.S):
        td = [_strip(x) for x in re.findall(r"<td[^>]*>(.*?)</td>", row, re.S)]
        if len(td) < 6:
            continue
        v = _rating_token(td[1])
        dm = re.search(r"(\d\d)\.(\d\d)\.(\d{4})", td[5])
        toks = _words_key(name_words(td[0]))
        if not v or not dm or not toks:
            continue
        items["%s|НКР|issuer" % toks] = {"issuer": td[0], "agency": "НКР", "level": "issuer", "rating": v,
                                         "outlook": td[2], "date": "%s-%s-%s" % (dm.group(3), dm.group(2), dm.group(1))}
    return items


def sites_refresh(force=False):
    st = store()
    d = st.get(SITE_KEY)
    if d and not force and time.time() - d.get("updated", 0) < RT_TTL:
        return
    items = nkr_fetch()
    if items:
        st.put(SITE_KEY, {"items": items, "updated": time.time()})
        _rt_idx.clear()


def _bond_query(name):
    words = [w for w in re.split(r"\s+", (name or "").strip())
             if w and not any(ch.isdigit() for ch in w) and w.lower().replace("ё", "е") not in _SERIES_WORDS]
    return " ".join(words[:3])


def _expert_session():
    return {}                                           # cookie сессии raexpert (CSRF-токен привязан к ней)


def expert_lookup(op, query, tokens):
    """Поиск эмитента на raexpert.ru, затем чтение страницы компании. Возвращает dict или None."""
    s = ext_open("https://raexpert.ru/", timeout=25, jar=op)[1].decode("utf-8", "replace")
    tok = re.search(r'name="CSRFToken" value="([^"]+)"', s)
    if not tok:
        return None
    res = ext_open("https://raexpert.ru/search/", urllib.parse.urlencode({"CSRFToken": tok.group(1), "search": query}).encode(),
                   {"Referer": "https://raexpert.ru/", "Content-Type": "application/x-www-form-urlencoded"},
                   timeout=30, jar=op)[1].decode("utf-8", "replace")
    seen, link = set(), None
    for href, name in re.findall(r'href="(/database/companies/[^"?]+?)/?"[^>]*>([^<]+)<', res):
        name = _strip(name)
        if href in seen or not name:
            continue
        seen.add(href)
        if frozenset(name_words(name)) == frozenset(tokens):
            link = (href, name)
            break
    if not link:
        return None
    c = ext_open("https://raexpert.ru" + link[0], timeout=30, jar=op)[1].decode("utf-8", "replace")
    m = re.search(r"(ru[^\s,<]+),\s*([А-Яа-я ]+?),\s*<a href=\"/releases/[^\"]+\">(\d\d)\.(\d\d)\.(\d{4})", c)
    if not m:
        return None
    v = _rating_token(m.group(1))
    if not v:
        return None
    return {"issuer": link[1], "agency": "Эксперт РА", "level": "issuer", "rating": v, "outlook": m.group(2).strip().lower(),
            "date": "%s-%s-%s" % (m.group(5), m.group(4), m.group(3))}


def _expert_run(names):
    try:
        st = store()
        d = st.get(EXP_KEY) or {"items": {}, "queried": {}}
        op = None
        now = time.time()
        for name in names:
            q = _bond_query(name)
            tokens = name_words(q)
            if not q or not tokens:
                continue
            qk = _words_key(tokens)
            ts = d["queried"].get(qk)
            if ts and now - ts < 3 * 86400:
                continue
            try:
                op = op or _expert_session()
                it = expert_lookup(op, q, tokens)
            except Exception:  # noqa: BLE001
                continue
            d["queried"][qk] = time.time()
            if it:
                d["items"]["%s|Эксперт РА|issuer" % qk] = it
            st.put(EXP_KEY, d)
            _rt_idx.clear()
            time.sleep(0.6)
    finally:
        _exp_state["running"] = False


def expert_start(names):
    with _rt_lock:
        if _exp_state["running"]:
            return
        d = store().get(EXP_KEY) or {"queried": {}}
        now = time.time()
        todo = []
        for n in names:
            qk = _words_key(name_words(_bond_query(n)))
            if qk and now - d["queried"].get(qk, 0) > 3 * 86400 and n not in todo:
                todo.append(n)
        if not todo:
            return
        _exp_state["running"] = True
    threading.Thread(target=_expert_run, args=(todo[:80],), daemon=True).start()


# ═══════════════════ каталог облигаций T-Invest (сектор, признаки, рейтинги по ISIN) ═══════════════════
# Только чтение справочника InstrumentsService/Bonds; без токена каталог пуст, а рейтинги берутся по названию.

TCAT_KEY, TCAT_TTL = "tcat_v2", 24 * 3600
_tcat = {"t": 0, "d": {}, "fail": 0, "tk": {}}
_tcat_lock = threading.Lock()


def _tcat_compact(b):
    rts = []
    for r in b.get("ratings") or []:
        rts.append([r.get("agencyName") or "", r.get("ratingLevel") or "", (r.get("ratingDate") or "")[:10],
                    r.get("forecast") or "", bool(r.get("isUnderWatch"))])
    return {"n": b.get("name") or "", "s": b.get("sector") or "", "fl": bool(b.get("floatingCouponFlag")),
            "am": bool(b.get("amortizationFlag")), "sub": bool(b.get("subordinatedFlag")),
            "pp": bool(b.get("perpetualFlag")), "rk": b.get("riskLevel") or "",
            "mat": (b.get("maturityDate") or "")[:10], "cur": (b.get("currency") or "").upper(),
            "tk": b.get("ticker") or "", "br": ((b.get("brand") or {}).get("name") if isinstance(b.get("brand"), dict) else None) or "", "r": rts}


def tcat():
    """dict ISIN -> компактная запись каталога; {} если токена нет или API недоступен."""
    if _tcat["d"] and time.time() - _tcat["t"] < TCAT_TTL:
        return _tcat["d"]
    with _tcat_lock:
        if _tcat["d"] and time.time() - _tcat["t"] < TCAT_TTL:
            return _tcat["d"]
        if not _tcat["d"]:
            try:
                hit = store().get(TCAT_KEY, ttl=TCAT_TTL)
            except Exception:  # noqa: BLE001
                hit = None
            if hit:
                _tcat.update(t=time.time(), d=hit)
                return hit
        if time.time() - _tcat["fail"] < 300:
            return _tcat["d"]
        try:
            cfg = load_config()
            if not (cfg.get("token") or "").strip():
                raise ApiError("нет токена", 400)
            ins = TInvest(cfg).call("InstrumentsService", "Bonds",
                                    {"instrumentStatus": "INSTRUMENT_STATUS_BASE"}, timeout=90).get("instruments") or []
            d = {b["isin"]: _tcat_compact(b) for b in ins if b.get("isin")}
            if d:
                store().put(TCAT_KEY, d)
                _tcat.update(t=time.time(), d=d)
        except Exception:  # noqa: BLE001
            _tcat["fail"] = time.time()
        return _tcat["d"]


def _tcat_get(k):
    """Запись каталога по ISIN или (запасной вариант) по тикеру."""
    d = tcat()
    k = (k or "").strip().upper()
    b = d.get(k)
    if b is None and d:
        if len(_tcat["tk"]) < len(d) // 2:
            _tcat["tk"] = {v["tk"].upper(): v for v in d.values() if v.get("tk")}
        b = _tcat["tk"].get(k)
    return b


def tcat_info(isin):
    b = _tcat_get(isin)
    if not b:
        return None
    return {"sector": b["s"] or None, "floating": b["fl"], "amort": b["am"], "subordinated": b["sub"],
            "perpetual": b["pp"], "risk": b["rk"] or None, "name": b["n"], "maturity": b["mat"] or None,
            "currency": b["cur"] or None}


def _norm_level(s):
    s = (s or "").strip().translate(_LAT).upper().replace("−", "-").replace("–", "-")
    if s in RATING_SCALE:
        return s
    return _rating_token(s)


def best_rating(isin, name):
    """Как rating_for(name), но рейтинги из каталога по ISIN точные; недостающие агентства добавляются по названию."""
    base = rating_for(name or "")
    b = _tcat_get(isin)
    cat = {}
    if b:
        for ag, lv, dt, fc, watch in b["r"]:
            v = _norm_level(lv)
            if not v or not ag:
                continue
            cur = cat.get(ag)
            if cur is None or dt >= cur["date"]:
                cat[ag] = {"agency": ag, "rating": v, "issuer": b["br"] or b["n"], "date": dt,
                           "outlook": (fc or "") + (" · под наблюдением" if watch else ""), "approx": False,
                           "url": None, "post": None, "src": None}
    if not cat:
        return base
    for x in (base or {}).get("all") or []:                    # пресс-релиз из канала: тот же уровень — берём ссылку, канал свежее — берём запись
        c = cat.get(x["agency"])
        if not c or x.get("approx") or not x.get("url"):
            continue
        if x["rating"] == c["rating"]:
            c.update(url=x["url"], post=x.get("post"), src=x.get("src"))
        elif (x.get("date") or "") > (c["date"] or ""):
            cat[x["agency"]] = x
    allr = list(cat.values())
    for x in (base or {}).get("all") or []:
        if x["agency"] not in cat and not x.get("approx"):     # по названию — только точные; приблизительные худший не выбирают
            allr.append(x)
    low = max(allr, key=lambda x: RATING_SCALE.index(x["rating"]))
    return {"v": low["rating"], "agency": low["agency"], "issuer": low["issuer"], "date": low["date"],
            "approx": low["approx"], "url": low.get("url"), "post": low.get("post"), "src": low.get("src"), "all": allr}
# ═══════════════════════════════ документы раскрытия: извлечение текста ═══════════════════════════════
# doc_text(bytes, ctype, name) -> {"text", "kind": html|pdf|docx|rtf|txt, "needs_ocr"}. Только stdlib, без сети.
# Вид определяется по сигнатуре (%PDF, PK + word/document.xml, {\rtf), затем по ctype/расширению, затем по началу текста.
# Весь текст после извлечения приводится к одному виду (_dt_norm): пробелы схлопнуты, табы между ячейками таблиц сохранены,
# нумерация пунктов («2.4.») остаётся в начале строки.
import codecs

_DT_W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
_DT_BLOCK = frozenset(("p", "div", "br", "tr", "li", "ul", "ol", "table", "h1", "h2", "h3", "h4", "h5", "h6", "blockquote", "pre", "section", "article"))
_DT_SKIP = frozenset(("script", "style", "noscript", "head", "template"))


def _dt_norm(text):
    """Единая нормализация: неразрывные пробелы, схлопывание пробелов, не более одной пустой строки подряд."""
    t = (text or "").replace("\r\n", "\n").replace("\r", "\n").replace("\x0b", "\n").replace("\x0c", "\n")
    t = re.sub("[\u200b\u200c\u200d\ufeff\u00ad]", "", t)
    t = re.sub("[\u00a0\u2000-\u200a\u202f\u205f\u3000]", " ", t)
    out = []
    for ln in t.split("\n"):
        ln = re.sub(r"[ \t]*\t[ \t]*", "\t", re.sub(r" {2,}", " ", ln)).strip(" \t")
        out.append(ln)
    return re.sub(r"\n{3,}", "\n\n", "\n".join(out)).strip()


class _DtHtml(HTMLParser):
    """HTML -> текст: блочные теги дают перевод строки, ячейки таблиц — табуляцию."""

    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.out = []
        self.stack = []        # открытые «скрываемые» теги

    def handle_starttag(self, tag, attrs):
        if tag == "body":
            self.stack = []    # незакрытый <head> не должен съесть тело
        if tag in _DT_SKIP:
            self.stack.append(tag)
        elif not self.stack and tag in _DT_BLOCK:
            self.out.append("\n")

    def handle_endtag(self, tag):
        if self.stack:
            if tag == self.stack[-1]:
                self.stack.pop()
            return
        if tag in ("td", "th"):
            self.out.append("\t")
        elif tag in _DT_BLOCK and tag != "br":
            self.out.append("\n")

    def handle_data(self, data):
        if not self.stack:
            self.out.append(re.sub(r"\s+", " ", data))


def _dt_html_text(s):
    p = _DtHtml()
    try:
        p.feed(s)
        p.close()
    except Exception:
        pass
    return "".join(p.out)


def _dt_decode(data, ctype=""):
    """Байты -> строка: BOM, charset из ctype / <meta>, затем utf-8, затем cp1251."""
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8", "replace")
    if data[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return data.decode("utf-16", "replace")
    cands = []
    m = re.search(r"charset\s*=\s*[\"']?([\w.-]+)", ctype or "", re.I)
    if not m:
        m = re.search(rb"charset\s*=\s*[\"']?([\w.-]+)", data[:4096], re.I)
    if m:
        cs = m.group(1)
        cands.append(cs.decode("ascii", "ignore") if isinstance(cs, bytes) else cs)
    cands += ["utf-8", "cp1251"]
    for cs in cands:
        try:
            codecs.lookup(cs)
            return data.decode(cs)
        except (LookupError, UnicodeDecodeError):
            continue
    return data.decode("cp1251", "replace")


def _dt_is_docx(data):
    try:
        with zipfile.ZipFile(io.BytesIO(data)) as z:
            return "word/document.xml" in z.namelist()
    except Exception:
        return False


def _dt_kind(data, ctype="", name=""):
    head = data[:1024].lstrip()
    if head[:4] == b"%PDF":
        return "pdf"
    if data[:4] == b"PK\x03\x04" and _dt_is_docx(data):
        return "docx"
    if head[:5] == b"{\\rtf":
        return "rtf"
    ct = (ctype or "").lower()
    ext = os.path.splitext((name or "").lower().split("?")[0])[1]
    if "pdf" in ct or ext == ".pdf":
        return "pdf"
    if "wordprocessingml" in ct or ext == ".docx":
        return "docx"
    if "rtf" in ct or ext == ".rtf":
        return "rtf"
    if "html" in ct or ext in (".htm", ".html", ".xhtml"):
        return "html"
    if "text/plain" in ct or ext == ".txt":
        return "txt"
    low = data[:2048].lower()
    if any(t in low for t in (b"<html", b"<body", b"<div", b"<p>", b"<p ")):
        return "html"
    return "txt"


def _dt_pdf(data):
    try:
        frags = pdf_text_fragments(data)
    except Exception:
        return ""
    lines, cur, last_y = [], [], None
    for f in frags:
        try:
            y, txt = float(f[1]), f[3]
        except Exception:
            continue
        if last_y is not None and abs(y - last_y) > 2.0:
            lines.append(" ".join(cur))
            cur = []
        cur.append(txt)
        last_y = y
    if cur:
        lines.append(" ".join(cur))
    return "\n".join(lines)


def _dt_docx_par(p):
    s = []
    for e in p.iter():
        if e.tag == _DT_W + "t":
            s.append(e.text or "")
        elif e.tag == _DT_W + "tab":
            s.append("\t")
        elif e.tag in (_DT_W + "br", _DT_W + "cr"):
            s.append("\n")
        elif e.tag == _DT_W + "noBreakHyphen":
            s.append("-")
    return "".join(s)


def _dt_docx_walk(el, out):
    for ch in el:
        if ch.tag == _DT_W + "p":
            out.append(_dt_docx_par(ch))
        elif ch.tag == _DT_W + "tr":
            cells = []
            for tc in ch.findall(_DT_W + "tc"):
                cells.append(" ".join(_dt_docx_par(p) for p in tc.iter(_DT_W + "p")))
            out.append("\t".join(cells))
        else:
            _dt_docx_walk(ch, out)


def _dt_docx(data):
    try:
        with zipfile.ZipFile(io.BytesIO(data)) as z:
            root = ET.fromstring(z.read("word/document.xml"))
    except Exception:
        return ""
    out = []
    _dt_docx_walk(root, out)
    return "\n".join(out)


_DT_RTF_TOK = re.compile(r"\\'([0-9a-fA-F]{2})|\\([a-zA-Z]+)(-?\d+)? ?|\\([^a-zA-Z])|([{}])|([^\\{}]+)", re.S)
_DT_RTF_DEST = frozenset(("fonttbl", "colortbl", "stylesheet", "info", "pict", "header", "footer", "headerl", "headerr", "footerl", "footerr",
                          "footnote", "filetbl", "listtable", "listoverridetable", "generator", "themedata", "colorschememapping",
                          "datastore", "latentstyles", "rsidtbl", "xmlnstbl", "object", "fldinst", "revtbl", "template"))
_DT_RTF_SYM = {"emdash": "\u2014", "endash": "\u2013", "bullet": "\u2022", "lquote": "\u2018", "rquote": "\u2019",
               "ldblquote": "\u201c", "rdblquote": "\u201d", "emspace": " ", "enspace": " ", "qmspace": " "}
_DT_RTF_NL = frozenset(("par", "line", "sect", "page", "row"))


def _dt_rtf(data):
    """Минимальный разбор RTF: \\'xx (кодовая страница), \\uN?, абзацы, табы; служебные группы отбрасываются."""
    s = data.decode("latin-1")
    m = re.search(r"\\ansicpg(\d+)", s[:4096])
    cp = "cp" + m.group(1) if m else "cp1251"
    try:
        codecs.lookup(cp)
    except LookupError:
        cp = "cp1251"

    def byte(b):
        return bytes([b]).decode(cp, "replace")

    out = []
    stack = []
    skip, uc, skip_n, at_start = False, 1, 0, False
    for m in _DT_RTF_TOK.finditer(s):
        hx, word, num, sym, br, txt = m.groups()
        if br == "{":
            stack.append((skip, uc))
            at_start = True
            continue
        if br == "}":
            if stack:
                skip, uc = stack.pop()
            at_start = False
            continue
        first, at_start = at_start, False
        if hx is not None:
            if skip:
                continue
            if skip_n:
                skip_n -= 1
                continue
            out.append(byte(int(hx, 16)))
        elif word is not None:
            if first and word in _DT_RTF_DEST:
                skip = True
            if skip:
                continue
            if word == "u" and num is not None:
                n = int(num)
                out.append(chr(n + 65536 if n < 0 else n))
                skip_n = uc
            elif word == "uc" and num is not None:
                uc = int(num)
            elif word in _DT_RTF_NL:
                out.append("\n")
            elif word in ("tab", "cell"):
                out.append("\t")
            elif word in _DT_RTF_SYM:
                out.append(_DT_RTF_SYM[word])
        elif sym is not None:
            if sym == "*" and first:
                skip = True
            if skip:
                continue
            if sym in "\\{}":
                out.append(sym)
            elif sym == "~":
                out.append(" ")
            elif sym in "\n\r":
                out.append("\n")
        elif txt is not None:
            if skip:
                continue
            txt = txt.replace("\r", "").replace("\n", "")
            if skip_n:
                k = min(skip_n, len(txt))
                txt, skip_n = txt[k:], skip_n - k
            out.append("".join(byte(ord(c)) if 0x80 <= ord(c) < 0x100 else c for c in txt))
    return "".join(out)


def doc_text(data, ctype="", name=""):
    """Байты документа -> {"text", "kind", "needs_ocr"}. Не бросает исключений на мусоре."""
    data = data or b""
    kind = _dt_kind(data, ctype, name)
    needs_ocr = False
    try:
        if kind == "pdf":
            raw = _dt_pdf(data)
            needs_ocr = len(re.findall(r"[^\W\d_]", raw)) < 20
        elif kind == "docx":
            raw = _dt_docx(data)
        elif kind == "rtf":
            raw = _dt_rtf(data)
        elif kind == "html":
            raw = _dt_html_text(_dt_decode(data, ctype))
        else:
            raw = _dt_decode(data, ctype)
    except Exception:
        raw = ""
    return {"text": _dt_norm(raw), "kind": kind, "needs_ocr": needs_ocr}
# ═══════════════════════════════ сообщения о раскрытии (714-П): классификация и поля ═══════════════════════════════
# Вход — уже извлечённый текст (doc_text из 12b). dc_extract(text, title, meta) -> {"kind", "inn", "ogrn", "event_date", "facts": [...], "warnings": [...]}.
# Виды: coupon_paid (выплаченные доходы), coupon_declared (начисленные/объявленные), default (неисполнение обязательств),
# buyback_result (итоги приобретения облигаций), other. Нумерация пунктов в разных формах отличается, поэтому нужный пункт
# ищется по тексту его заголовка (до двоеточия), а номер — запасной вариант.
# TODO: при нескольких ISIN в одном сообщении числа не делятся по блокам — каждому ISIN достаются общие значения (+ warning).

DC_PARSER_VERSION = "3"   # повышать при изменении логики разбора: сборщик (--reparse) перечитывает старые записи

_DC_MONTHS = {"янв": 1, "фев": 2, "мар": 3, "апр": 4, "мая": 5, "май": 5, "июн": 6, "июл": 7, "авг": 8, "сен": 9, "окт": 10, "ноя": 11, "дек": 12}
_DC_DATE_TXT = re.compile(r"(?<!\d)(\d{1,2})\s*[»\"”’']?\s*(январ[яь]|феврал[яь]|марта?|апрел[яь]|ма[йя]|июн[яь]|июл[яь]|август[а]?|сентябр[яь]|октябр[яь]|ноябр[яь]|декабр[яь])\s*(\d{4})", re.I)
_DC_DATE_NUM = re.compile(r"(?<![\d.])(\d{1,2})\.(\d{2})\.(\d{4})(?!\d)")
_DC_NUM = re.compile(r"\d{1,3}(?:[  ]\d{3})+(?:[.,]\d+)?|\d+(?:[.,]\d+)?")
_DC_ISIN = re.compile(r"\b(?:RU|SU)[0-9A-Z]{9}[0-9]\b")
_DC_ITEM = re.compile(r"^([1-4]\.\d{1,2})(?:\.(?=\s|$)|(?=\s|$))\s*")
_DC_RUB_AMT = re.compile(r"\d[\d  ]*(?:[.,]\d+)?\s*(?:\([^)]*\)\s*)?руб")
_DC_RATE = re.compile(r"(\d+(?:[.,]\d+)?)\s*%?\s*(?:\([^)]*\)\s*)?(?:процент\w*\s*)?годов", re.I)
_DC_ORD = (("девятнадцат", 19), ("восемнадцат", 18), ("семнадцат", 17), ("шестнадцат", 16), ("пятнадцат", 15), ("четырнадцат", 14),
           ("тринадцат", 13), ("двенадцат", 12), ("одиннадцат", 11), ("девяност", 90), ("девяно", 90), ("восьмидесят", 80), ("восемьдесят", 80),
           ("семидесят", 70), ("семьдесят", 70), ("шестидесят", 60), ("шестьдесят", 60), ("пятидесят", 50), ("пятьдесят", 50),
           ("сороков", 40), ("сорок", 40), ("тридцат", 30), ("двадцат", 20), ("сотый", 100), ("сто", 100), ("десят", 10),
           ("девят", 9), ("восьм", 8), ("седьм", 7), ("шест", 6), ("пят", 5), ("четв", 4), ("трет", 3), ("втор", 2), ("перв", 1))


def dc_parse_number(s):
    """Первое число в строке: пробелы/nbsp — разделители тысяч, запятая или точка — десятичные."""
    m = _DC_NUM.search(s or "")
    if not m:
        return None
    try:
        return float(re.sub(r"[  ]", "", m.group(0)).replace(",", "."))
    except ValueError:
        return None


def dc_parse_rub(s):
    """Рубли: «80 620 552,40 рублей», «18 (Восемнадцать) рублей 32 копейки», «10 170 000 рублей 00 копеек»."""
    s2 = re.sub(r"\([^)]*\)", " ", s or "")
    m = _DC_NUM.search(s2)
    if not m:
        return None
    v = dc_parse_number(m.group(0))
    if v is None:
        return None
    if not re.search(r"[.,]", m.group(0)):
        k = re.match(r"\s*(?:руб\w*\.?)?\s*(\d{1,2})\s*коп", s2[m.end():], re.I)
        if k:
            v += int(k.group(1)) / 100.0
    return v


def _dc_dates(s):
    """Все даты строки [(позиция, 'YYYY-MM-DD')] в порядке появления."""
    res = []
    for m in _DC_DATE_TXT.finditer(s or ""):
        res.append((m.start(), int(m.group(3)), _DC_MONTHS.get(m.group(2).lower()[:3]), int(m.group(1))))
    for m in _DC_DATE_NUM.finditer(s or ""):
        res.append((m.start(), int(m.group(3)), int(m.group(2)), int(m.group(1))))
    out = []
    for pos, y, mo, d in sorted(res):
        try:
            out.append((pos, date(y, mo, d).isoformat()))
        except (TypeError, ValueError):
            continue
    return out


def dc_parse_date(s):
    """Первая дата в строке -> 'YYYY-MM-DD' (месяцы словами в родительном, «16», г./года, dd.mm.yyyy)."""
    d = _dc_dates(s)
    return d[0][1] if d else None


def dc_sections(text):
    """{'2.4': текст пункта}: пункт длится до следующей строки, начинающейся с номера (в т.ч. «2.1\\t», «2.1 »)."""
    secs, cur = {}, None
    for ln in (text or "").split("\n"):
        m = _DC_ITEM.match(ln.strip())
        if m:
            cur = m.group(1)
            if cur in secs:
                cur = "~" + cur            # повтор номера не затирает первый пункт
            secs[cur] = [ln.strip()[m.end():]]
        elif re.match(r"^[1-4]\.\s+[А-ЯЁ]", ln.strip()):
            cur = None                     # заголовок раздела («3. Подпись») закрывает пункт
        elif cur is not None:
            secs[cur].append(ln.strip())
    return {k: "\n".join(v).strip() for k, v in secs.items()}


def dc_classify(title, text):
    s = ((title or "") + " " + (text or "")[:600]).lower()
    s = re.sub(r"\s+", " ", s)
    if ("реализации приобретенных" in s or "реализации приобретённых" in s
            or "продаже ранее приобретенных" in s or "вторичной продаже" in s):
        return "placement_result"
    if ("итогах приобретения" in s or "результатах приобретения" in s
            or "исполнении обязательств по приобретению" in s):
        return "buyback_result"
    if "неисполнение обязательств" in s:
        return "default"
    if "выплаченные доходы" in s or "выплаченных доходах" in s:
        return "coupon_paid"
    if "начисленные доходы" in s or "начисленных (объявленных) доходах" in s:
        return "coupon_declared"
    if ("завершении размещения" in s or "итогах размещения" in s or "результатах размещения" in s
            or ("дополнительн" in s and "размещ" in s and "облигац" in s)):
        return "placement_result"
    return "other"


def dc_load_fixture(path):
    """Файл фикстуры: строки «ключ: значение» (source, published, code, company, title), строка «---», затем текст."""
    with open(path, encoding="utf-8") as f:
        raw = f.read()
    head, sep, body = raw.partition("\n---\n")
    if not sep:
        return {}, raw
    meta = {}
    for ln in head.split("\n"):
        k, _, v = ln.partition(":")
        if _ and k.strip():
            meta[k.strip()] = v.strip()
    return meta, body.strip("\n")


def _dc_split(sec):
    """Пункт -> (заголовок, значение): по первому «:» (значение может идти со следующей строки), либо по «).» после
    стандартного заголовка без двоеточия (в нём нет цифр), либо по табу; иначе заголовок пуст."""
    i = sec.find(":")
    j = -1
    m = re.search(r"\)\s*\.\s", sec[:801])
    if m and m.start() >= 40 and not re.search(r"\d", sec[:m.start()]) and (i < 0 or m.start() < i):
        j = m.end()
    if j >= 0:
        return sec[:j], sec[j:]
    if 0 <= i <= 800:
        return sec[:i], sec[i + 1:]
    i = sec.find("\t")
    if i >= 0:
        return sec[:i], sec[i + 1:]
    return "", sec


def _dc_pick(secs, label_re, key=None):
    """Значение пункта по заголовку (регулярка, регистр не важен); не нашлось — по номеру key; иначе None."""
    for k, v in secs.items():
        if k[0] == "~":
            continue
        lab, val = _dc_split(v)
        if lab and re.search(label_re, lab, re.I | re.S):
            return val.strip()
    if key and key in secs:
        return _dc_split(secs[key])[1].strip()
    return None


def _dc_ordinal_words(s):
    """«Пятьдесят третий купонный период» -> 53 (слова непосредственно перед «купонн»); перебор с конца, пока слова — порядковое."""
    for m in reversed(list(re.finditer(r"((?:[а-яё]+\s+){1,3})купонн", s or "", re.I))):
        tot = 0
        for w in reversed(m.group(1).lower().split()):
            v = next((n for st, n in _DC_ORD if w.startswith(st)), None)
            if v is None:
                break
            tot += v
        if tot:
            return tot
    return None


def _dc_coupon_no(*texts):
    for t in texts:
        if not t:
            continue
        m = re.search(r"(?<![\d.])(\d+)\s*(?:-\s*\w{1,3})?\s*(?:\([^)]*\)\s*)?(?:отч[её]тн\w*\s*)?\(?купон", t, re.I)
        if m:
            return int(m.group(1))
        n = _dc_ordinal_words(t)
        if n:
            return n
    return None


def _dc_period(v):
    d = _dc_dates(v or "")
    if len(d) >= 2 and re.search(r"\bпо\b|оконч|[–—-]", v):
        return d[0][1], d[1][1]
    return None, None


def _dc_due(v):
    d = _dc_dates(v or "")
    if not d:
        return None
    if len(d) >= 2 and re.search(r"\bс\b.*\bпо\b", v, re.S):
        return d[-1][1]
    return d[0][1]


_DC_PCT = re.compile(r"(?<![\w.,])(\d+(?:[.,]\d+)?)\s*(?:\([^)]*\)\s*)?(?:%|процент)", re.I)


def _dc_rate(*texts):
    """Процентная ставка: число перед «%» / «процент…» (в т.ч. «15 (пятнадцать) процентов годовых»)."""
    for t in texts:
        m = _DC_PCT.search(t or "") or _DC_RATE.search(t or "")
        if m:
            return float(m.group(1).replace(",", "."))
    return None


_DC_AMT = re.compile(r"(?<![\w.,])(\d{1,3}(?:[ \u00a0\u202f]\d{3})+(?:[.,]\d+)?|\d+(?:[.,]\d+)?)")
_DC_CUR_TAIL = re.compile(r"\s*(?:(?:российск|китайск|американск|европейск)\w*\s+)?(руб|юан|долл|евро|коп)\w*\.?", re.I)
_DC_CUR_STEM = (("юан", "CNY"), ("долл", "USD"), ("евро", "EUR"), ("руб", "RUB"))


def _dc_cur_code(w):
    w = (w or "").lower()
    return next((c for st, c in _DC_CUR_STEM if w.startswith(st)), None)


def dc_amounts(s):
    """Денежные суммы строки [{v, cur, pos, end}]: число, за которым (после скобок со словами) следует руб/юан/долл/евро,
    либо скобка со словами «… рублей …». Числа с «%»/«процент» (ставки), копейки и номера периодов не считаются суммами."""
    s = s or ""
    out = []
    for m in _DC_AMT.finditer(s):
        tok = m.group(1)
        tail = s[m.end():m.end() + 400]
        if re.match(r"\s*%", tail):
            continue
        pm = re.match(r"\s*\(([^)]*)\)", tail)
        pw = pm.group(1) if pm else None
        rest_off = pm.end() if pm else 0
        if re.match(r"\s*процент", tail[rest_off:], re.I):
            continue
        cm = _DC_CUR_TAIL.match(tail, rest_off)
        if cm:
            if cm.group(1).lower() == "коп":
                continue
            cur = _dc_cur_code(cm.group(1))
            end_off = cm.end()
        elif pw and re.search(r"рубл|юан|доллар|евро", pw, re.I):
            cur = _dc_cur_code(re.search(r"рубл|юан|доллар|евро", pw, re.I).group(0))
            end_off = rest_off
        else:
            continue
        try:
            v = float(re.sub(r"[ \u00a0\u202f]", "", tok).replace(",", "."))
        except ValueError:
            continue
        if cur == "RUB" and not re.search(r"[.,]", tok):
            k = re.match(r"\s*\.?\s*(\d{1,2})\s*(?:\([^)]*\)\s*)?коп", tail[end_off:], re.I)
            if k:
                v += int(k.group(1)) / 100.0
        out.append({"v": v, "cur": cur, "pos": m.start(), "end": m.end() + end_off})
    return out


def _dc_ctx_kind(ctx):
    """Что описывает сумма по предшествующему тексту: 'coupon' / 'face' / None (последнее ключевое слово побеждает)."""
    sent = re.split(r"[.;\n]\s+(?=[А-ЯA-Z«\"])|\n", (ctx or "").strip())[-1].lower()   # начало последнего предложения важнее хвоста:
    head = sent[:70]                                                                       # «Размер части номинальной … купонного периода»
    if re.search(r"номинальн|погашен|амортиз", head) and not re.search(r"купон\w*\s+доход|процент", head):
        return "face"
    lc = (ctx or "").lower()[-160:]
    ci = max(lc.rfind("купон"), lc.rfind("процент"), lc.rfind("доход"))
    fi = max(lc.rfind("номинальн"), lc.rfind("погашен"), lc.rfind("амортиз"))
    if fi > ci:
        return "face"
    return "coupon" if ci >= 0 else None


def _dc_pay_kinds(*texts):
    """Виды выплат из текста категории: (купон, часть номинала, погашение номинала)."""
    lc = " ".join(t or "" for t in texts).lower()
    has_c = bool(re.search(r"купон|процент|доход", lc))
    has_a = bool(re.search(r"част\w*\s+номинальн|частичн|амортиз", lc))
    has_r = bool(re.search(r"погашени", lc)) or (bool(re.search(r"номинальн", lc)) and not has_a)
    return has_c, has_a, has_r


_DC_NUMQ = re.compile(r"(?<![\w.,\-–])(\d{1,3}(?:[ \u00a0\u202f]\d{3})+|\d+)(?![\w\-]|[.,]\d)")


def dc_parse_qty(s):
    """Количество бумаг: «в количестве N», число перед «штук/облигаций/бумаг», иначе первое отдельное число
    (номера вида 002P-03, БО-03 не берутся). Целое или None."""
    s2 = re.sub(r"\([^)]*\)", " ", s or "")
    m = re.search(r"количеств\w*\s*[:\-–]?\s*(\d{1,3}(?:[ \u00a0\u202f]\d{3})+|\d+)(?![\w\-]|[.,]\d)", s2, re.I)
    if not m:
        for c in _DC_NUMQ.finditer(s2):
            if re.match(r"\s*(?:шт|штук|облигац|бумаг|ценн|биржев|ед\b)", s2[c.end():c.end() + 30], re.I):
                m = c
                break
    if not m:
        m = _DC_NUMQ.search(s2)
    if not m:
        return None
    return int(re.sub(r"[ \u00a0\u202f]", "", m.group(1)))


def _dc_qty(total, per_bond, qty, qty_tol=0.0051):
    """Производные поля и проверки: qty_derived, total_matches, qty_integer, qty_out. Допуск на округление копеек
    на бумагу: qty_tol * qty."""
    r = {"qty_derived": None, "qty_out": qty, "checks": {}}
    if total and per_bond:
        ratio = total / per_bond
        q_est = int(round(ratio))
        r["qty_derived"] = q_est
        r["checks"]["qty_integer"] = q_est > 0 and (
            abs(ratio - q_est) < 0.01
            or (abs(per_bond * q_est - total) <= max(1.0, qty_tol * q_est) and abs(ratio - q_est) < 0.25)
        )
    if qty is not None and total is not None and per_bond is not None:
        r["checks"]["total_matches"] = abs(per_bond * qty - total) <= max(1.0, 0.5 * per_bond, qty_tol * qty)
    if qty is None:
        r["qty_out"] = r["qty_derived"]
    return r


def _dc_isins(*texts):
    out = []
    for t in texts:
        for m in _DC_ISIN.finditer(t or ""):
            if m.group(0) not in out:
                out.append(m.group(0))
    return out


def _dc_int(v):
    return None if v is None else int(round(v))


def _dc_paid(secs, text):
    cat = _dc_pick(secs, r"категория выплат", "2.2") or ""
    per_v = _dc_pick(secs, r"отчетный|отчётный", "2.3") or ""
    tot_v = _dc_pick(secs, r"общий размер выплаченных", "2.4") or ""
    pb_v = _dc_pick(secs, r"в расчете на одну|в расчёте на одну", "2.5") or ""
    qty_v = _dc_pick(secs, r"общее количество", "2.6") or ""
    due_v = _dc_pick(secs, r"дата, в которую", "2.9") or ""
    pct_v = _dc_pick(secs, r"^\s*(?:объем|объём|доля)\b", "2.10") or ""
    has_c, has_a, has_r = _dc_pay_kinds(cat)
    if not (has_c or has_a or has_r):
        has_c, has_a, has_r = _dc_pay_kinds(pb_v)
    has_face = has_a or has_r
    kinds = (["coupon"] if has_c else []) + (["amortization"] if has_a else []) + (["redemption"] if has_r and not has_a else [])
    pay = "+".join(kinds) or "other"
    warn = []
    f = {"payment": pay, "coupon_no": _dc_coupon_no(per_v)}
    f["period_from"], f["period_to"] = _dc_period(per_v)
    ta, pa = dc_amounts(tot_v), dc_amounts(pb_v)
    cur = (ta or pa or [{"cur": "RUB"}])[0]["cur"]
    t_cur = [a for a in ta if a["cur"] == cur]
    f["currency"] = cur
    f["total"] = t_cur[0]["v"] if t_cur else (dc_parse_rub(tot_v) if not ta and re.fullmatch(r"[\s\d.,\u00a0\u202f]*", tot_v.split("(")[0]) else None)
    comp = {"coupon": None, "face": None}
    prev = 0
    for a in pa:
        ctx, prev = pb_v[prev:a["pos"]], a["end"]
        if a["cur"] != cur:
            continue
        k = _dc_ctx_kind(ctx)
        if not has_c:
            k = "face"
        elif not has_face:
            k = "coupon"
        elif k is None:
            k = "coupon" if comp["coupon"] is None else "face"
        if comp[k] is None:
            comp[k] = a["v"]
        elif has_face and has_c:                          # слот уже занят — вторая сумма относится к другой части выплаты
            other = "face" if k == "coupon" else "coupon"
            if comp[other] is None:
                comp[other] = a["v"]
    if not pa and pb_v:
        m = re.match(r"\s*[-–—]?\s*(\d[\d \u00a0\u202f]*(?:[.,]\d+)?)\s*(?:\(|$|\.|;)", pb_v)
        if m:
            comp["face" if (has_face and not has_c) else "coupon"] = dc_parse_number(m.group(1))
    f["coupon_per_bond"], f["face_per_bond"] = comp["coupon"], comp["face"]
    f["per_bond"] = comp["coupon"] if comp["coupon"] is not None else comp["face"]
    parts = [x for x in (comp["coupon"], comp["face"]) if x is not None]
    f["per_bond_total"] = round(sum(parts), 6) if parts else None
    f["per_bond_rub"] = next((a["v"] for a in pa if a["cur"] == "RUB"), None) if cur != "RUB" else None
    f["total_rub"] = next((a["v"] for a in ta if a["cur"] == "RUB"), None) if cur != "RUB" else None
    f["qty"] = dc_parse_qty(qty_v)
    f["rate"] = _dc_rate(tot_v, pb_v)
    f["due_date"] = _dc_due(due_v)
    f["paid_pct"] = dc_parse_number(pct_v)
    q = _dc_qty(f["total"], f["per_bond_total"], f["qty"])
    f.update(qty_derived=q["qty_derived"], qty_out=q["qty_out"], checks=q["checks"])
    ck = q["checks"]
    if cur != "RUB" and f["per_bond_rub"] and f["total_rub"] and f["qty"] and f["total"] and f["per_bond_total"]:
        # выплата частью бумаг в валюте, частью — в рублях: количества складываются
        n = f["total"] / f["per_bond_total"] + f["total_rub"] / f["per_bond_rub"]
        if abs(n - f["qty"]) <= 1.5:
            ck["total_matches"] = True
            ck["split_currency"] = True
    qv = f["qty"]
    if qv is not None and qv > 0:
        if ck.get("total_matches"):
            f["conf"] = 1.0
        else:
            f["conf"] = 0.8
            warn.append("суммы не сходятся" if "total_matches" in ck else "суммы не извлечены")
    elif qv is None and ck.get("qty_integer"):
        f["conf"] = 0.8
    else:
        f["conf"] = 0.4
        if qv is None:
            warn.append("количество не найдено")
    f["warn"] = warn
    return f


_DC_PER_BOND_CTX = re.compile(r"на\s+одну|на\s+1\s|одн(?:ой|у)\s+(?:биржев\w+\s+)?облигаци|по\s+одной|на\s+каждую", re.I)


def _dc_decl_amounts(tot_v, pb_v):
    """(общая сумма, сумма на облигацию) для объявленных доходов. Берутся рублёвые суммы (число + руб), а не первое число
    пункта (номер периода, ставка). Если оба значения лежат в одном пункте — делим по словам «на одну облигацию»."""
    def first(v):
        a = [x for x in dc_amounts(v) if x["cur"] == "RUB"]
        return a[0]["v"] if a else None
    t, p = first(tot_v), first(pb_v)
    if tot_v and (not pb_v or pb_v == tot_v or p is None) and _DC_PER_BOND_CTX.search(tot_v):
        t = p = None
        prev = 0
        for a in dc_amounts(tot_v):
            ctx, prev = tot_v[prev:a["pos"]], a["end"]
            if a["cur"] != "RUB":
                continue
            if _DC_PER_BOND_CTX.search(ctx):
                p = a["v"] if p is None else p
            elif t is None:
                t = a["v"]
    if t is None and p is None and not dc_amounts(tot_v) and not dc_amounts(pb_v):
        t, p = dc_parse_rub(tot_v) if re.match(r"\s*\d", tot_v or "") else None, dc_parse_rub(pb_v) if re.match(r"\s*\d", pb_v or "") else None
    return t, p


def _dc_declared(secs, text):
    per_v = _dc_pick(secs, r"отчетный|отчётный", "2.5") or ""
    tot_v = _dc_pick(secs, r"^\s*общий размер", "2.6") or ""
    pb_v = _dc_pick(secs, r"в расчете на одну|в расчёте на одну|по одной облигации", "2.7") or ""
    due_v = _dc_pick(secs, r"дата, в которую", "2.9") or ""
    low = re.sub(r"\s+", " ", text.lower())
    undet = bool(re.search(r"не\s+определен", text, re.I))
    f = {"coupon_no": _dc_coupon_no(per_v, text)}
    f["period_from"], f["period_to"] = _dc_period(per_v)
    tot_a, pb_a = _dc_decl_amounts(tot_v, pb_v)
    f["total"] = None if undet else tot_a
    f["per_bond"] = None if undet else pb_a
    f["rate"] = _dc_rate(tot_v, pb_v)
    f["due_date"] = _dc_due(due_v)
    fm = re.search(r"по следующей формуле:?\s*(.+?)\s*(?:,\s*где\b|\n|$)", text)
    f["formula"] = fm.group(1).strip() if fm else None
    f["base"], f["spread"] = None, None
    if fm:
        blk = next((v for v in secs.values() if "по следующей формуле" in v), text)
        bl = blk.lower()
        f["base"] = "refinancing" if "ставки рефинансирования" in bl else "key" if "ключевой ставки" in bl else None
        sm = re.search(r"([+\-–−])\s*(\d+(?:[.,]\d+)?)\s*%", f["formula"])
        if sm:
            f["spread"] = float(sm.group(2).replace(",", ".")) * (1 if sm.group(1) == "+" else -1)
    f["undetermined"] = undet
    pm = re.search(r"[^\n]*обязан\w*\s+приобрести[^\n]*", text, re.I)
    f["put_note"] = re.sub(r"^\d+\.\d+\.?\s*", "", pm.group(0).strip()) if pm else None
    q = _dc_qty(f["total"], f["per_bond"], None)
    f.update(qty_derived=q["qty_derived"], qty_out=q["qty_out"], checks=q["checks"])
    if q["checks"].get("qty_integer"):
        f["conf"] = 0.9
    elif undet and f["period_from"]:
        f["conf"] = 0.7
    else:
        f["conf"] = 0.4
    return f


def _dc_obl_kind(seg):
    """Вид обязательства по тексту одного пункта. Частичное погашение проверяется раньше купона: в нём часто написано
    «в дату окончания N-го купонного периода»."""
    lo = (seg or "").lower()
    if re.search(r"амортизац|частичн\w*\s+(досрочн\w*\s+)?погашени|погашени\w*\s+част|част\w*\s+номинальн", lo):
        return "amortization"
    if re.search(r"приобретени|оферт", lo):
        return "offer"
    if "погашени" in lo and "номинал" in lo:
        return "redemption"
    if "купон" in lo or "процент" in lo:
        return "coupon"
    if "погашени" in lo:
        return "redemption"
    return "other"


def _dc_obligations(ob_v):
    """Несколько обязательств в одном сообщении («– Выплата купона … в размере X; – Частичное погашение … в размере Y») ->
    [{obligation, amount}] в порядке текста. Пусто — пункт не делится на части с суммами."""
    parts = [p for p in re.split(r"(?:^|\n)\s*[–—-]\s+|;\s*\n", ob_v or "") if p and p.strip()]
    out = []
    for p in parts:
        am = dc_amounts(p)
        if not am:
            continue
        out.append({"obligation": _dc_obl_kind(p), "amount": am[0]["v"]})
    return out if len(out) > 1 else ([{"obligation": _dc_obl_kind(parts[0] if parts else ob_v), "amount": out[0]["amount"]}] if out else [])


def _dc_default(secs, text):
    ob_v = _dc_pick(secs, r"содержание обязательства", "2.2") or ""
    due_v = _dc_pick(secs, r"дата, в которую", "2.3") or ""
    st_v = _dc_pick(secs, r"сведения о неисполнении", "2.4") or ""
    rs_v = _dc_pick(secs, r"причина неисполнения", "2.5") or ""
    obligations = _dc_obligations(ob_v)
    ob = obligations[0]["obligation"] if obligations else _dc_obl_kind(ob_v)
    amount = None
    # суммы — только через dc_amounts (числа рядом с «руб»), иначе «15-й купонный период: 681 890 рублей» дало бы 15
    m = re.search(r"общий размер[^:\n]*:\s*(.{0,200})", ob_v, re.I | re.S)
    if m:
        am = dc_amounts(m.group(1))
        amount = am[0]["v"] if am else None
    if amount is None:
        m = re.search(r"в размере\s+(.{0,160})", ob_v, re.I | re.S)
        am = dc_amounts(m.group(1)) if m else []
        amount = am[0]["v"] if am else None
    if amount is None:
        m = _DC_RUB_AMT.search(ob_v)
        amount = dc_parse_rub(ob_v[m.start():]) if m else None
    per_bond = None
    m = re.search(r"в расчете на одну[^:\n]*:([^\n]*)", ob_v, re.I)
    if m:
        mm = _DC_RUB_AMT.search(m.group(1))
        per_bond = dc_parse_rub(m.group(1)[mm.start():]) if mm else None
    qty = None
    m = re.search(r"общее количество[^:\n]*:\s*([^\n]*)", ob_v, re.I)
    if m:
        qty = dc_parse_qty(m.group(1))
    sl = st_v.lower()
    status = "default" if ("дефолт" in sl and "технический дефолт" not in sl) else "technical"
    if "технический дефолт" in text.lower():
        status = "technical"
    if len(obligations) > 1:
        amount = obligations[0]["amount"]
    f = {"obligation": ob, "obligations": obligations, "coupon_no": _dc_coupon_no(ob_v), "amount": amount, "per_bond": per_bond, "qty": qty,
         "rate": _dc_rate(ob_v), "due_date": _dc_due(due_v), "status": status, "reason": re.sub(r"\s+", " ", rs_v).strip()[:300]}
    q = _dc_qty(amount, per_bond, qty)
    f.update(qty_derived=q["qty_derived"], qty_out=q["qty_out"], checks=q["checks"])
    f["conf"] = 0.95 if amount is not None and due_v else 0.5
    return f


def _dc_bdays(a, b):
    """Рабочие дни (пн–пт, без праздников) между датами YYYY-MM-DD: (a, b]."""
    import datetime as _d
    x, y = _d.date.fromisoformat(a), _d.date.fromisoformat(b)
    n = 0
    while x < y:
        x += _d.timedelta(days=1)
        n += x.weekday() < 5
    return n


def _dc_default_age(f, ref_date):
    """Без явного слова «дефолт»: просрочка больше 10 рабочих дней от даты платежа — уже дефолт (ст. 17.1 39-ФЗ)."""
    f["overdue_bdays"] = None
    if f.get("due_date") and ref_date:
        f["overdue_bdays"] = _dc_bdays(f["due_date"], ref_date)
        if f["status"] == "technical" and f["overdue_bdays"] > 10:
            f["status"] = "default"


def _dc_buyback(secs, text, event_date):
    sec2 = " ".join(v for k, v in secs.items() if k.startswith("2."))
    body = sec2 or ((secs.get("2.1") or "") + " " + (secs.get("2.2") or ""))
    qty_v = _dc_pick(secs, r"количество\s+(?:фактически\s+)?(?:приобрет|выкуп)|фактически\s+(?:приобрет|выкуп)", None)
    qty = dc_parse_qty(qty_v) if qty_v else None
    if qty is None:
        m = re.search(r"(?:в\s+количестве|приобретено|выкуплено)\s*[:\-–]?\s*(\d{1,3}(?:[ \u00a0\u202f]\d{3})+|\d+)", body, re.I)
        qty = _dc_int(dc_parse_number(m.group(1))) if m else None
    if qty is None:
        for k, v in secs.items():
            if k.startswith("2.") and re.search(r"приобрет|выкуп", v, re.I):
                cand = dc_parse_qty(v)
                if cand:
                    qty = cand
                    break
    lb = body.lower()
    basis = ("put" if ("по требованию владельцев" in lb or "требованию их владельцев" in lb or "оферт" in lb)
             else "issuer" if ("по соглашению с владельцами" in lb or "по усмотрению" in lb) else None)
    d3 = dc_parse_date(_dc_pick(secs, r"дата\s+(?:приобретения|выкупа|наступления\s+события|исполнения)", "2.3") or "")
    return {"qty_bought": qty, "basis": basis, "date": event_date or d3, "conf": 1.0 if qty else 0.5, "checks": {}}


def _dc_placement(secs, text, title, event_date):
    sec2 = " ".join(v for k, v in secs.items() if k.startswith("2."))
    body = sec2 or text or ""
    low = ((title or "") + " " + body[:1200]).lower()
    if "реализации приобрет" in low or "продаже ранее приобрет" in low or "вторичной продаже" in low:
        subkind = "secondary"
    elif "дополнительн" in low or "доразмещ" in low:
        subkind = "additional"
    else:
        subkind = "primary"
    qty_v = _dc_pick(secs, r"количество\s+(?:фактически\s+)?(?:размещ|реализован|продан)|фактически\s+(?:размещ|реализован)", None)
    qty = dc_parse_qty(qty_v) if qty_v else None
    if qty is None:
        m = re.search(r"(?:размещено|реализовано|продано|в\s+количестве)\s*[:\-–]?\s*(\d{1,3}(?:[ \u00a0\u202f]\d{3})+|\d+)", body, re.I)
        qty = _dc_int(dc_parse_number(m.group(1))) if m else None
    d3 = dc_parse_date(_dc_pick(secs, r"дата\s+(?:фактического\s+)?(?:окончания|завершения|реализации|размещения|наступления)", "2.3") or "")
    return {"qty_placed": qty, "subkind": subkind, "date": d3 or event_date, "conf": 1.0 if qty else 0.5, "checks": {}}


def dc_extract(text, title="", meta=None):
    """Главная точка входа: классификация, реквизиты эмитента и факты по каждому ISIN."""
    meta = meta or {}
    title = title or meta.get("title", "")
    text = text or ""
    # «15, 47 руб.» — опечатка с пробелом после запятой: склеиваем, иначе сумма прочиталась бы как 47
    text = re.sub(r"(\d),[ \u00a0](\d{2})(?=\s*(?:руб|коп|\())", r"\1,\2", text)
    kind = dc_classify(title, text)
    secs = dc_sections(text)
    warnings = []
    m = re.search(r"(?<!\d)(\d{12}|\d{10})(?!\d)", secs.get("1.4", ""))
    if not m:
        m = re.search(r"ИНН[^\d]{0,80}(?<!\d)(\d{12}|\d{10})(?!\d)", text)
    inn = m.group(1) if m else None
    m = re.search(r"(?<!\d)(\d{15}|\d{13})(?!\d)", secs.get("1.3", ""))
    if not m:
        m = re.search(r"ОГРН[^\d]{0,80}(?<!\d)(\d{15}|\d{13})(?!\d)", text)
    ogrn = m.group(1) if m else None
    event_date = dc_parse_date(secs.get("1.7", ""))
    res = {"kind": kind, "inn": inn, "ogrn": ogrn, "event_date": event_date, "published": meta.get("published"),
           "code": meta.get("code"), "company": meta.get("company"), "facts": [], "warnings": warnings}
    if kind in ("buyback_result", "placement_result"):
        isins = _dc_isins(secs.get("2.1"), secs.get("2.2"), secs.get("2.3"))
    elif kind == "other":
        isins = _dc_isins(secs.get("2.4"), secs.get("2.1"))
    else:
        isins = _dc_isins(secs.get("2.1"))
    if not isins and kind != "other":
        isins = _dc_isins(text)
        if isins:
            warnings.append("ISIN найден вне пункта идентификации")
    if kind == "other":
        res["facts"] = [{"isin": i, "kind": kind, "conf": 0.0, "checks": {}} for i in isins]
        return res
    if not isins:
        warnings.append("ISIN не найден")
        return res
    if len(isins) > 1:
        warnings.append("несколько ISIN (%d): значения не разделены по блокам" % len(isins))
    if kind == "coupon_paid":
        f = _dc_paid(secs, text)
    elif kind == "coupon_declared":
        f = _dc_declared(secs, text)
    elif kind == "default":
        f = _dc_default(secs, text)
        _dc_default_age(f, event_date or dc_parse_date(meta.get("published") or ""))
    elif kind == "placement_result":
        f = _dc_placement(secs, text, title, event_date)
    else:
        f = _dc_buyback(secs, text, event_date)
    for w in f.get("warn") or []:
        warnings.append(w)
    if kind == "coupon_paid" and f["paid_pct"] is not None and f["paid_pct"] < 100:
        warnings.append("выплачено не полностью: %s%%" % f["paid_pct"])
    for i in isins:
        d = dict(f)
        d.pop("warn", None)
        d["checks"] = dict(f["checks"])
        d["isin"], d["kind"] = i, kind
        res["facts"].append(d)
    return res
# ── курс КБД сегодня, спред к КБД ──

_kbd_now = {"t": 0, "pts": []}


def kbd_curve():
    if time.time() - _kbd_now["t"] > 1800 or not _kbd_now["pts"]:
        try:
            j = json.loads(http_text("https://iss.moex.com/iss/engines/stock/zcyc.json?iss.meta=off&iss.only=yearyields"))
            pts = sorted((r[2], r[3]) for r in j["yearyields"]["data"])
            if pts:
                _kbd_now.update(t=time.time(), pts=pts)
        except Exception:  # noqa: BLE001
            pass
    return _kbd_now["pts"]


def _interp(pts, years):
    if not pts or years is None:
        return None
    if years <= pts[0][0]:
        return pts[0][1]
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if years <= x1:
            return y0 + (y1 - y0) * (years - x0) / (x1 - x0)
    return pts[-1][1]


def kbd_at(years):
    return _interp(kbd_curve(), years)


# ── скринер облигаций (Мосбиржа, ISS) ──

_scr = {"t": 0, "rows": []}
SCR_COLS_S = ("SECID,SHORTNAME,SECNAME,ISIN,FACEVALUE,FACEUNIT,COUPONPERCENT,NEXTCOUPON,MATDATE,OFFERDATE,"
              "LISTLEVEL,PREVLEGALCLOSEPRICE,YIELDATPREVWAPRICE,COUPONPERIOD,BONDSUBTYPE,ISSUESIZE,ACCRUEDINT,COUPONVALUE,PREVPRICE,BONDTYPE,COUPON_DETAILS")
SCR_COLS_M = "SECID,LAST,YIELD,WAPRICE,DURATION,VALTODAY,NUMTRADES,ZSPREAD,YIELDATWAPRICE,LASTCHANGEPRCNT"


def _iss_table(j, name):
    t = j[name]
    return [dict(zip(t["columns"], r)) for r in t["data"]]


def bond_cy(coupon_value, period, face, price):
    """Текущая доходность, %: годовой купон / чистая цена. Цена — в % номинала."""
    try:
        if not (coupon_value and period and face and price):
            return None
        return round(float(coupon_value) * (365.0 / float(period)) / float(face) * 100.0 / float(price) * 100.0, 2)
    except (TypeError, ValueError, ZeroDivisionError):
        return None


def bond_chg(m, s, price):
    """Изменение цены за день, %: LASTCHANGEPRCNT, иначе LAST к предыдущей цене."""
    v = m.get("LASTCHANGEPRCNT")
    if v:
        return round(float(v), 2)
    prev = s.get("PREVPRICE") or s.get("PREVLEGALCLOSEPRICE")
    last = m.get("LAST")
    if prev and last:
        return round((float(last) / float(prev) - 1) * 100, 2)
    return 0.0


def liq_tiers(rows):
    """L1 — верхние 20% по обороту среди торгуемых, L2 — следующие 40%, L3 — остальные и без оборота."""
    traded = sorted((r["turn"] for r in rows if (r.get("turn") or 0) > 0), reverse=True)
    n = len(traded)
    c1 = traded[max(0, int(n * 0.2 + 0.999999) - 1)] if n else None
    c2 = traded[max(0, int(n * 0.6 + 0.999999) - 1)] if n else None
    for r in rows:
        t = r.get("turn") or 0
        r["liq"] = "L1" if t > 0 and t >= c1 else "L2" if t > 0 and t >= c2 else "L3"
    return rows


def screener_rows():
    if time.time() - _scr["t"] < 600 and _scr["rows"]:
        return _scr["rows"]
    out = {}
    for board, kind in (("TQCB", "corp"), ("TQOB", "ofz")):
        j = json.loads(http_text(
            "https://iss.moex.com/iss/engines/stock/markets/bonds/boards/%s/securities.json?iss.meta=off"
            "&iss.only=securities,marketdata&securities.columns=%s&marketdata.columns=%s" % (board, SCR_COLS_S, SCR_COLS_M),
            timeout=60))
        md = {r["SECID"]: r for r in _iss_table(j, "marketdata")}
        for s in _iss_table(j, "securities"):
            m = md.get(s["SECID"], {})
            price = m.get("WAPRICE") or m.get("LAST") or s.get("PREVLEGALCLOSEPRICE")
            yld = m.get("YIELD") or m.get("YIELDATWAPRICE") or s.get("YIELDATPREVWAPRICE")
            if not price or not yld or not s.get("MATDATE") or s["MATDATE"].startswith("0000"):
                continue
            dur = (m.get("DURATION") or 0) / 365.0 or None
            end = s["MATDATE"]
            of = s.get("OFFERDATE")
            of = of if of and not of.startswith("0000") else None
            out[s["SECID"]] = {
                "id": s["SECID"], "isin": s.get("ISIN"), "name": s.get("SHORTNAME"), "full": s.get("SECNAME"),
                "kind": kind, "cur": (s.get("FACEUNIT") or "SUR").replace("SUR", "RUB"), "nominal": s.get("FACEVALUE"),
                "price": round(price, 3), "yield": round(float(yld), 2), "dur": round(dur, 2) if dur else None,
                "coupon": s.get("COUPONPERCENT"), "next": s.get("NEXTCOUPON"), "mat": end, "offer": of,
                "level": s.get("LISTLEVEL"), "turn": round(m.get("VALTODAY") or 0), "trades": m.get("NUMTRADES") or 0,
                "zs": m.get("ZSPREAD"), "cy": bond_cy(s.get("COUPONVALUE"), s.get("COUPONPERIOD"), s.get("FACEVALUE"), m.get("LAST") or price),
                "macdur": round(dur, 2) if dur else None, "chg": bond_chg(m, s, price), "sub": s.get("BONDSUBTYPE"), "size": s.get("ISSUESIZE"), "nkd": s.get("ACCRUEDINT"),
                "btype": s.get("BONDTYPE"), "cpn_det": s.get("COUPON_DETAILS")}
    rows = list(out.values())
    for r in rows:
        k = kbd_at(r["dur"]) if r["dur"] else None
        r["spread"] = round(r["yield"] - k, 2) if k is not None and r["cur"] == "RUB" else None
        r["rating"] = None
    liq_tiers(rows)
    _scr.update(t=time.time(), rows=rows)
    return rows


MKT_BUCKETS = ["AAA", "AA", "A", "BBB", "BB и ниже"]
MKT_DUR = [(0, 1, "0–1"), (1, 2, "1–2"), (2, 3, "2–3"), (3, 99, "3+")]
MKT_HIST_KEY = "mkt_stats_hist_v1"


def _med(xs):
    xs = sorted(xs)
    if not xs:
        return None
    n = len(xs)
    return round(xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2, 2)


def _cell(rs):
    return {"n": len(rs), "yield": _med([r["yield"] for r in rs]), "spread": _med([r["spread"] for r in rs if r.get("spread") is not None])}


def market_stats(rows):
    """Медианы доходности и спреда к КБД: рейтинг x дюрация, по секторам. Вселенная: рублёвые корпоративные с рейтингом."""
    now = time.time()
    uni = []
    for r in rows:
        if r.get("kind") != "corp" or r.get("cur") != "RUB" or not r.get("rating"):
            continue
        if not (0 < r["yield"] < 60):
            continue
        try:
            yrs = (datetime.strptime(r["mat"], "%Y-%m-%d").timestamp() - now) / 31557600.0
        except Exception:  # noqa: BLE001
            continue
        if yrs <= 0.1:
            continue
        d = r.get("dur") if r.get("dur") else yrs
        uni.append((rating_bucket(r["rating"]), d, r))
    grid = []
    for bk in MKT_BUCKETS:
        row = {"bucket": bk, "all": _cell([r for b, d, r in uni if b == bk]), "cells": []}
        for lo, hi, lab in MKT_DUR:
            row["cells"].append(dict(_cell([r for b, d, r in uni if b == bk and lo <= d < hi]), dur=lab))
        grid.append(row)
    sectors = {}
    for b, d, r in uni:
        if r.get("sector"):
            sectors.setdefault(r["sector"], []).append(r)
    sec = sorted(({"sector": k, **_cell(v)} for k, v in sectors.items()), key=lambda x: -x["n"])
    return {"grid": grid, "sectors": sec, "dur": [m[2] for m in MKT_DUR], "n": len(uni)}


MKT_HIST2_KEY = "mkt_stats_hist_v2"
_hist_lock = threading.Lock()


def _stats_history(stats):
    st = store()
    hist = st.get(MKT_HIST_KEY) or {}
    ok = [g for g in stats["grid"] if g["all"]["spread"] is not None and g["all"]["n"] >= 3]
    snap = {g["bucket"]: g["all"]["spread"] for g in ok}
    if snap:
        hist[date.today().isoformat()] = snap
        for k in sorted(hist)[:-400]:
            hist.pop(k, None)
        st.put(MKT_HIST_KEY, hist)
        # расширенная история (формат v1 не меняем): спред, доходность и число выпусков по корзинам + точки кривой КБД
        try:
            with _hist_lock:
                h2 = st.get(MKT_HIST2_KEY) or {}
                h2[date.today().isoformat()] = {
                    "sp": snap, "y": {g["bucket"]: g["all"]["yield"] for g in ok}, "n": {g["bucket"]: g["all"]["n"] for g in ok},
                    "k": {str(t): (round(kbd_at(t), 2) if kbd_at(t) is not None else None) for t in (1, 2, 5, 10)}}
                for k in sorted(h2)[:-800]:
                    h2.pop(k, None)
                st.put(MKT_HIST2_KEY, h2)
        except Exception:  # noqa: BLE001
            pass
    return hist


_fl_job = {"running": False}


def fl_spread_job(todo):
    """Фон: для флоатеров скринера без свежего кэша тянет график выплат (moex_bondization, кэш 24 ч) не чаще FL_SPREAD_RPS в секунду
    и кладёт спред в kv fl_spread1:<isin> (30 сут). Скринер читает кэш синхронно и ничего не ждёт."""
    try:
        for r in todo:
            isin = r["isin"]
            fresh = store().get("bondiz2:" + isin, ttl=BC_TTL) is not None
            try:
                bz = moex_bondization(isin)
                fl_spread_put(isin, r.get("full") or r.get("name"), bz, float(r.get("nominal") or 0) or None, r.get("kind"), r.get("cpn_det"))
            except Exception:  # noqa: BLE001
                pass
            if not fresh:
                time.sleep(1.0 / FL_SPREAD_RPS)
    finally:
        _fl_job["running"] = False


def fl_spread_kick(rows, cached):
    """Запускает фоновый расчёт спредов для флоатеров без кэша; одновременно не больше одного задания."""
    todo = [r for r in rows if r.get("floating") and r.get("isin") and r["isin"] not in cached and r.get("cur") == "RUB"]
    if not todo or _fl_job["running"]:
        return False
    _fl_job["running"] = True
    threading.Thread(target=fl_spread_job, args=(todo,), daemon=True, name="fl-spread").start()
    return True


def screener_payload():
    rows = screener_rows()
    br, ti = globals().get("best_rating"), globals().get("tcat_info")
    for r in rows:
        rt = None
        if br:
            try:
                ci0 = ti(r.get("isin")) if ti and r.get("isin") else None
                rt = br(r.get("isin"), (ci0 or {}).get("name") or r["name"])
            except Exception:  # noqa: BLE001
                rt = None
        if rt is None and not br:
            rt = rating_for(r["name"])
        r["rating"] = rt["v"] if rt else None
        r["rt_agency"] = rt["agency"] if rt else None
        r["rt_approx"] = bool(rt and rt["approx"])
        r["rt_links"] = [{"a": x["agency"], "r": x["rating"], "o": x.get("outlook") or "", "d": x.get("date") or "",
                          "u": x.get("url")} for x in (rt.get("all") or [])] if rt and any(x.get("url") for x in rt.get("all") or []) else None
        info = None
        if ti and r.get("isin"):
            try:
                info = ti(r["isin"])
            except Exception:  # noqa: BLE001
                info = None
        r["sector"] = info.get("sector") if info else None
        r["floating"] = info.get("floating") if info else None
        if r["floating"] is None and r.get("btype"):      # без справочника T-Invest — по типу облигации из ISS
            r["floating"] = "плава" in r["btype"].lower()
        r["amort"] = info.get("amort") if info else None
    today_s = date.today().isoformat()
    for r in rows:      # линкер, к чему считается доходность (оферта/погашение), дней до оферты
        try:
            r["linker"] = bool(DBX_LINKER_RE.match(r.get("id") or "")) and r.get("kind") == "ofz"
        except NameError:
            r["linker"] = bool(re.match(r"^SU52\d{3}", r.get("id") or "")) and r.get("kind") == "ofz"
        of = r.get("offer")
        up = bool(of and of >= today_s and (not r.get("mat") or of < r["mat"]))
        r["ytm_kind"] = "offer" if up else "mat"
        try:
            r["days_to_offer"] = (datetime.strptime(of, "%Y-%m-%d").date() - date.today()).days if up else None
        except Exception:  # noqa: BLE001
            r["days_to_offer"] = None
    try:        # спред флоатера к КС из кэша (без ожидания); недостающее считает фоновое задание
        fsp = fl_spread_cached()
        for r in rows:
            r["fl_label"] = fl_label(fsp.get(r.get("isin")), True) if r.get("floating") else None
            r["fl_base"] = (fsp.get(r.get("isin")) or {}).get("base") if r.get("floating") else None
        fl_spread_kick(rows, fsp)
    except Exception:  # noqa: BLE001
        pass
    stats = market_stats(rows)
    try:
        hist = _stats_history(stats)
    except Exception:  # noqa: BLE001
        hist = {}
    try:
        lq = bench_lqdt_yield()
    except Exception:  # noqa: BLE001
        lq = None
    try:        # ожидаемая инфляция (прогноз ЦБ, декабрь к декабрю) для переключателя «реальная доходность»
        ie, isrc = scr_infl_exp()
    except Exception:  # noqa: BLE001
        ie, isrc = None, ""
    return {"rows": rows, "kbd": kbd_curve(), "updated": _scr["t"], "ratings": ratings_status(), "stats": stats, "stats_hist": hist,
            "floor": {"lqdt": lq}, "infl_exp": ie, "infl_src": isrc}


def scr_infl_exp():
    """(ожидаемая инфляция, %; подпись источника). Прогноз ЦБ на текущий год, иначе на ближайший; нет прогноза — (None, '')."""
    fc = inflation_forecast()
    ys = fc.get("yearly") or []
    if not ys:
        return None, ""
    y0 = date.today().year
    pick = next((y for y in ys if y["year"] == y0), ys[0])
    return pick["mid"], "прогноз Банка России на %d г. (%s)" % (pick["year"], fc.get("as_of") or "")


# ── спарклайны цен: последние ~30 торговых дней, кэш на сутки ──
SPARK_URL = ("https://iss.moex.com/iss/history/engines/stock/markets/bonds/securities/%s.json?iss.meta=off&iss.only=history"
             "&marketprice_board=1&history.columns=TRADEDATE,CLOSE,LEGALCLOSEPRICE,BOARDID&from=%s")
SPARK_MAX_IDS, SPARK_DAYS = 60, 30
_spark_cache = {}
_spark_lock = threading.Lock()


def spark_parse(j, n=SPARK_DAYS):
    """Ответ ISS history -> цены закрытия по торговым дням (старые первыми, не больше n). По дню берётся первая площадка с ценой."""
    t = (j or {}).get("history") or {}
    cols = t.get("columns") or []
    by = {}
    for row in t.get("data") or []:
        r = dict(zip(cols, row))
        d = r.get("TRADEDATE")
        px = r.get("CLOSE") or r.get("LEGALCLOSEPRICE")
        if not d or not px or d in by:
            continue
        by[d] = round(float(px), 3)
    return [by[d] for d in sorted(by)][-n:]


def spark_payload(ids, budget=25.0):
    """{isin: [цены]} для списка бумаг. Идёт последовательно, при ошибке источника останавливается и отдаёт, что есть."""
    out, t0 = {}, time.time()
    frm = (date.today() - timedelta(days=60)).isoformat()
    seen = []
    for i in ids:
        i = (i or "").strip().upper()
        if re.match(r"^[A-Z0-9]{5,16}$", i) and i not in seen:
            seen.append(i)
    for i in seen[:SPARK_MAX_IDS]:
        key = (i, date.today())
        with _spark_lock:
            hit = _spark_cache.get(key)
        if hit is not None:
            out[i] = hit
            continue
        if time.time() - t0 > budget:
            break
        try:
            vals = spark_parse(json.loads(http_text(SPARK_URL % (i, frm), timeout=15)))
        except Exception:  # noqa: BLE001
            break
        with _spark_lock:
            for k in [k for k in _spark_cache if k[1] != date.today()]:
                _spark_cache.pop(k, None)
            _spark_cache[key] = vals
        out[i] = vals
    return out


def bond_movers(n=50):
    """Лидеры падения/роста цены за день по облигациям (из тех же данных, что и скринер)."""
    rows = screener_rows()
    mv = [r for r in rows if r.get("chg")]
    br = globals().get("best_rating")

    def item(r):
        rt = r.get("rating")
        if rt is None and br:
            try:
                x = br(r.get("isin"), r["name"])
                rt = x["v"] if x else None
            except Exception:  # noqa: BLE001
                rt = None
        return {"name": r["name"], "isin": r.get("isin") or r["id"], "chg": r["chg"], "price": r["price"],
                "turnover": r["turn"], "trades": r["trades"], "rating": rt}
    down = [item(r) for r in sorted(mv, key=lambda r: r["chg"])[:n]]
    up = [item(r) for r in sorted(mv, key=lambda r: -r["chg"])[:n]]
    return {"down": down, "up": up, "total": len(mv), "n": n, "updated": _scr["t"]}


def _api_movers(cfg, acc, q, force):
    try:
        n = max(5, min(200, int(q.get("n", 50))))
    except (TypeError, ValueError):
        n = 50
    return bond_movers(n)


API_GET["/api/movers"] = _api_movers


