_pri = {"t": 0, "rows": [], "err_t": 0, "err": ""}
PRI_ERR_TTL = 1800      # после отказа investmint не спрашиваем его снова полчаса (сайт закрыл доступ программам — HTTP 403)


# ВАЖНО: placements_parse (и _strip) дублируются в server/tinvest_server.py (эндпоинт /v1/parsed/investmint/placements).
# Менять синхронно; tests/test_parsed.py сверяет результаты на общем HTML-образце.
def placements_parse(s):
    """HTML investmint.ru/bond-placements/ -> список строк календаря размещений (по дате старта). Чистая функция."""
    rows, seen = [], set()
    for tr in re.findall(r"<tr>\s*<td class=\"min-w-56.*?</tr>", s, re.S):
        isin = re.search(r'font-mono text-xs">([A-Z0-9]{12})<', tr)
        issuer = re.search(r'font-medium">(.*?)</div>', tr, re.S)
        desc = re.search(r'text-muted-foreground">(.*?)</div>', tr, re.S)
        start = re.search(r'<time datetime="(\d{4}-\d\d-\d\d)"', tr)
        if not (issuer and start):
            continue
        end = re.search(r"Плановое окончание:\s*([^<]+)<", tr)
        tds = re.findall(r"<td[^>]*>(.*?)</td>", tr, re.S)
        link = re.search(r'href="(https://www\.moex\.com/[^"]+)"', tr)
        key = isin.group(1) if isin else _strip(issuer.group(1)) + start.group(1)
        if key in seen:
            continue
        seen.add(key)
        name = re.sub(r"(?i)\b(общество с ограниченной ответственностью|публичное акционерное общество|акционерное общество)\b", "",
                      _strip(issuer.group(1))).replace('"', "").strip(" ()")
        rows.append({"issuer": _strip(issuer.group(1)), "short": name, "desc": _strip(desc.group(1)) if desc else "",
                     "isin": isin.group(1) if isin else "", "start": start.group(1), "end": _strip(end.group(1)) if end else "",
                     "book": _strip(tds[2]) if len(tds) > 2 else "", "status": _strip(tds[3]) if len(tds) > 3 else "",
                     "link": link.group(1) if link else ""})
    rows.sort(key=lambda r: r["start"])
    return rows


def primary_rows():
    """Календарь будущих размещений (investmint). Ошибка источника -> исключение, но не чаще раза в PRI_ERR_TTL: в промежутке
    повторно бросаем запомненную ошибку, не обращаясь к сайту (вызывающие показывают её или работают без календаря)."""
    now = time.time()
    if now - _pri["t"] < 1800 and _pri["rows"]:
        return _pri["rows"]
    if now - _pri["err_t"] < PRI_ERR_TTL and _pri["err"]:
        raise ApiError(_pri["err"], 502)
    try:
        rows = ds_parsed("investmint/placements", timeout=40)       # разбор на сервере данных; None -> разбираем сами
        if not (isinstance(rows, list) and rows and all(isinstance(r, dict) and r.get("start") for r in rows)):
            rows = placements_parse(http_text("https://investmint.ru/bond-placements/", timeout=40))
    except Exception as e:  # noqa: BLE001
        code = getattr(e, "code", None)
        _pri.update(err_t=now, err=("investmint.ru закрыл доступ для программ (HTTP %d)" % code) if code in (401, 403, 429)
                    else "investmint.ru не ответил: %s" % (str(e)[:120] or type(e).__name__))
        raise ApiError(_pri["err"], 502)
    _pri.update(t=now, rows=rows, err_t=0, err="")
    return rows


def primary_parse_guide(desc, book=""):
    """Извлекает ориентир купона/доходности (%), срок (лет) и признак флоатера из текста объявления размещения."""
    s = ((desc or "") + " " + (book or "")).replace("\u00a0", " ")
    low = s.lower()
    floater = any(w in low for w in ("флоатер", "кс +", "кс+", "ключев", "ruonia", "плавающ", "переменн"))
    # Ставка купона / ориентир доходности: ищем число перед % (кроме «КС + 2%»)
    guide_y = None
    if not floater:
        for m in re.finditer(r"(?:до|ориентир|купон|ставк\w*|доходност\w*)?[^\d%]{0,20}(\d{1,2}(?:[.,]\d{1,2})?)\s*%", low):
            v = float(m.group(1).replace(",", "."))
            if 4.0 <= v <= 45.0:
                guide_y = v
                break
    # Срок обращения: «3 года», «2,5 лет», «18 мес»
    term = None
    m_yr = re.search(r"(\d{1,2}(?:[.,]\d{1,2})?)\s*(?:год[а]?|лет|г\.)", low)
    if m_yr:
        v = float(m_yr.group(1).replace(",", "."))
        if 0.25 <= v <= 30.0:
            term = v
    else:
        m_mo = re.search(r"(\d{1,3})\s*мес", low)
        if m_mo:
            v = int(m_mo.group(1)) / 12.0
            if 0.2 <= v <= 30.0:
                term = round(v, 2)
    return {"guide_y": guide_y, "term": term, "floater": floater}


def primary_nip_for(row, screener=None, rusfar=None, freeze_days=4):
    """Расчёт премии первички (NIP) к кривой того же эмитента и медиане аналогов по рейтингу/дюрации,
    плюс стоимость заморозки кэша на время сбора заявок (по RUSFAR / КС)."""
    scr = screener or []
    info = primary_parse_guide(row.get("desc"), row.get("book"))
    guide_y = row.get("guide_y") if row.get("guide_y") is not None else info["guide_y"]
    term = row.get("term") if row.get("term") is not None else info["term"]
    floater = bool(row.get("floater") or info["floater"])
    rt = row.get("rating")
    rt_v = rt.get("v") if isinstance(rt, dict) else (rt if isinstance(rt, str) else None)
    bucket = rating_bucket(rt_v) if rt_v else None
    toks = set(name_tokens(row.get("short") or row.get("issuer") or ""))
    # 1. Кривая того же эмитента (торгуемые рублёвые фиксы)
    iss_ys = []
    if toks and scr:
        for b in scr:
            if b.get("cur") not in (None, "RUB") or not (b.get("yield") and 0 < b["yield"] < 60):
                continue
            bt = set(name_tokens(b.get("name") or ""))
            if bt and (toks <= bt or bt <= toks or len(toks & bt) >= max(1, min(len(toks), len(bt)))):
                d_b = b.get("dur")
                if term is None or d_b is None or abs(d_b - term) <= 1.8:
                    iss_ys.append(b["yield"])
    # 2. Медиана аналогов по рейтингу и сроку
    peer_ys = []
    if bucket and bucket != "нет рейтинга" and scr:
        for b in scr:
            if b.get("kind") != "corp" or b.get("cur") not in (None, "RUB") or not (b.get("yield") and 0 < b["yield"] < 60):
                continue
            br = b.get("rating")
            br_v = br.get("v") if isinstance(br, dict) else (br if isinstance(br, str) else None)
            if rating_bucket(br_v) != bucket:
                continue
            d_b = b.get("dur")
            if term is not None and d_b is not None and abs(d_b - term) > 1.2:
                continue
            peer_ys.append(b["yield"])
    iss_y = round(_med(iss_ys), 2) if iss_ys else None
    peer_y = round(_med(peer_ys), 2) if peer_ys else None
    nip_iss = round((guide_y - iss_y) * 100) if (guide_y is not None and iss_y is not None) else None
    nip_peer = round((guide_y - peer_y) * 100) if (guide_y is not None and peer_y is not None) else None
    nip_bp = nip_iss if nip_iss is not None else nip_peer
    ref_src = "issuer" if nip_iss is not None else ("peer" if nip_peer is not None else None)
    rate_ref = rusfar if rusfar is not None else 16.0
    freeze_pct = round((rate_ref / 100.0) * (max(0, freeze_days) / 365.0) * 100.0, 3)
    freeze_drag_bp = round(freeze_pct / max(0.5, term or 2.0) * 100.0)
    net_nip_bp = (nip_bp - freeze_drag_bp) if nip_bp is not None else None
    return {"guide_y": guide_y, "term": term, "floater": floater, "bucket": bucket,
            "issuer_y": iss_y, "issuer_n": len(iss_ys), "peer_y": peer_y, "peer_n": len(peer_ys),
            "nip_issuer_bp": nip_iss, "nip_peer_bp": nip_peer, "nip_bp": nip_bp, "ref_src": ref_src,
            "freeze_days": freeze_days, "freeze_rate": round(rate_ref, 2),
            "freeze_cost_pct": freeze_pct, "freeze_drag_bp": freeze_drag_bp, "net_nip_bp": net_nip_bp}


_pri_scr_state = {"th": None, "t": 0.0}


def _pri_scr_kick():
    """Запускает фоновую загрузку скринера (не чаще раза в 2 минуты). -> True, пока загрузка идёт."""
    def run():
        try:
            screener_payload()
        except Exception:  # noqa: BLE001
            pass
    with _rt_lock:
        th = _pri_scr_state["th"]
        if th is not None and th.is_alive():
            return True
        if time.time() - _pri_scr_state["t"] < 120:
            return False
        _pri_scr_state["t"] = time.time()
        th = _pri_scr_state["th"] = threading.Thread(target=run, daemon=True)
    th.start()
    return True


def primary_payload():
    cal_error = None
    try:
        rows = primary_rows()
    except Exception as e:  # noqa: BLE001
        rows, cal_error = [], str(e)[:200]      # без календаря экран всё равно показывает размещения Мосбиржи и калькулятор
    scr = _scr.get("rows") or []
    scr_loading = False
    if not scr:
        scr_loading = _pri_scr_kick()       # скринер нужен для медиан по рейтингу: грузим в фоне, экран не ждёт
    rusfar = None
    try:
        kr = key_rate_series()
        if kr:
            rusfar = kr[-1][1]
    except Exception:  # noqa: BLE001
        pass
    out_rows = []
    for r in rows:
        item = dict(r)
        rt = rating_for(item["short"])
        item["rating"] = rt
        item["nip"] = primary_nip_for(item, scr, rusfar)
        out_rows.append(item)
    # Справочные медианы доходности по рейтинговым группам (для интерактивного калькулятора NIP)
    peer_med = {}
    if scr:
        by_b = {}
        for b in scr:
            if b.get("kind") == "corp" and b.get("cur") in (None, "RUB") and b.get("yield") and 0 < b["yield"] < 60:
                br = b.get("rating")
                bv = rating_bucket(br.get("v") if isinstance(br, dict) else br)
                if bv != "нет рейтинга":
                    by_b.setdefault(bv, []).append(b["yield"])
        peer_med = {k: round(_med(v), 2) for k, v in by_b.items() if v}
    try:
        primary_snapshot(out_rows)
    except Exception:  # noqa: BLE001
        pass
    return {"rows": out_rows, "updated": _pri["t"], "rusfar": rusfar, "peer_medians": peer_med, "cal_error": cal_error,
            "scr_loading": scr_loading}



# ── ключевая ставка ЦБ и КБД Мосбиржи (любые сроки из сетки кривой) ──

# v2: на каждую дату вся сетка {срок: доходность}; v1 хранил только 2 года (используем как запас, пока v2 докачивается)
KBD_KEY, KBD_OLD_KEY, KEY_KEY = "kbd_grid_v2", "kbd2y_v1", "keyrate_v1"
# ── снимки объявленных размещений (накопление: позже можно сравнить ориентир и итог) ──

PRI_SNAP_KEY = "pri_snap_v1"
_snap_lock = threading.Lock()


def primary_snapshot(rows):
    """Раз в день сохраняет список объявленных размещений; если состав и статусы не изменились — только отмечает проверку."""
    slim = [{"isin": r.get("isin"), "short": r.get("short"), "desc": r.get("desc"), "start": r.get("start"), "end": r.get("end"),
             "book": r.get("book"), "status": r.get("status"), "rating": (r.get("rating") or {}).get("v")} for r in rows]
    if not slim:
        return
    st = store()
    today = date.today().isoformat()
    with _snap_lock:
        d = st.get(PRI_SNAP_KEY) or {"days": {}}
        days = d.setdefault("days", {})
        last = days[max(days)] if days else None
        if last == slim and d.get("checked") == today:
            return
        if last != slim:
            days[today] = slim
        d["checked"] = today
        for k in sorted(days)[:-400]:
            days.pop(k, None)
        st.put(PRI_SNAP_KEY, d)


# ── первичка против вторички: как торгуются выпуски, размещённые за последние 12 месяцев ──

PRI_ISS_KEY, PRI_H_PREFIX, PRI_MAX, PRI_DAYS = "pri_issue_v1", "prih1:", 700, 365
_pri_h = {"running": False, "phase": "", "done": 0, "total": 0, "fin": 0, "err": None, "memo": (0, None)}
HIST_URL = ("https://iss.moex.com/iss/history/engines/stock/markets/bonds/securities/%s.json?iss.meta=off"
            "&iss.only=history,history.cursor&history.columns=BOARDID,TRADEDATE,VALUE,NUMTRADES,WAPRICE,LEGALCLOSEPRICE,CLOSE,"
            "YIELDCLOSE,YIELDATWAP&from=%s&till=%s&start=%d")


def _pri_dates(secid):
    j = json.loads(http_text("https://iss.moex.com/iss/securities/%s.json?iss.meta=off&iss.only=description"
                             "&description.columns=name,value" % secid, timeout=25))
    m = {r[0]: r[1] for r in j["description"]["data"]}
    ok = lambda v: v if v and re.match(r"^\d{4}-\d\d-\d\d$", v) and not v.startswith("0000") else ""  # noqa: E731
    return [ok(m.get("ISSUEDATE")), ok(m.get("STARTDATEMOEX"))]


def _day_add(d, n):
    return (datetime.strptime(d, "%Y-%m-%d") + timedelta(days=n)).strftime("%Y-%m-%d")


def _pri_history(secid, d0, today):
    """Цена и доходность в 1-й день торгов, через 7 и 30 дней. Цена — % от номинала (средневзвешенная по основной площадке дня)."""
    till = min(today, _day_add(d0, 50))
    rows, start = [], 0
    while start < 400:
        j = json.loads(http_text(HIST_URL % (secid, d0, till, start), timeout=30))
        t = j["history"]
        part = [dict(zip(t["columns"], r)) for r in t["data"]]
        rows += part
        if len(part) < 100:
            break
        start += 100
    best = {}
    for r in rows:
        px = r.get("WAPRICE") or r.get("LEGALCLOSEPRICE") or r.get("CLOSE")
        if not px or not r.get("TRADEDATE"):
            continue
        cur = best.get(r["TRADEDATE"])
        if cur is None or (r.get("VALUE") or 0) > (cur.get("VALUE") or 0):
            best[r["TRADEDATE"]] = dict(r, px=px)
    days = sorted(best)
    out = {"d0": None, "p0": None, "y0": None, "p7": None, "y7": None, "p30": None, "y30": None, "t": time.time()}
    if days:
        f = days[0]
        if f <= _day_add(d0, 14):
            out.update(d0=f, p0=round(best[f]["px"], 2), y0=best[f].get("YIELDCLOSE") or best[f].get("YIELDATWAP"))
            for k, n in (("7", 7), ("30", 30)):
                lo, hi = _day_add(f, n), _day_add(f, n + 7)
                c = [x for x in days if lo <= x <= hi]
                if c:
                    out["p" + k] = round(best[c[0]]["px"], 2)
                    out["y" + k] = best[c[0]].get("YIELDCLOSE") or best[c[0]].get("YIELDATWAP")
            out["done"] = today >= _day_add(f, 40)
    out["n_days"] = len(days)
    # выпуск без сделок вообще (ещё не торговался) — перепроверим позже
    out["done"] = bool(out.get("done"))
    return out


def _pri_candidates():
    st = store()
    iss = st.get(PRI_ISS_KEY) or {}
    cut = _day_add(date.today().isoformat(), -PRI_DAYS)
    c = []
    for sid, (a, b) in iss.items():
        ref = b or a
        if ref and ref >= cut:
            c.append((ref, sid))
    c.sort(reverse=True)
    return iss, [(sid, ref) for ref, sid in c[:PRI_MAX]]


def _pri_run():
    try:
        st = store()
        st_rows = _scr["rows"] or screener_rows()
        uni = {r["id"]: r for r in st_rows}
        iss = st.get(PRI_ISS_KEY) or {}
        miss = [s for s in uni if s not in iss]
        _pri_h.update(phase="Узнаю даты размещения выпусков", done=0, total=len(miss))
        for k in range(0, len(miss), 200):
            part = miss[k:k + 200]

            def one(s):
                try:
                    return s, _pri_dates(s)
                except Exception:  # noqa: BLE001
                    return s, None
            for s, v in pool_map(one, part, workers=8):
                if v is not None:
                    iss[s] = v
            st.put(PRI_ISS_KEY, iss)
            _pri_h["done"] = min(len(miss), k + 200)
        iss, cand = _pri_candidates()
        cand = [(s, ref) for s, ref in cand if s in uni]
        today = date.today().isoformat()
        todo = []
        for s, ref in cand:
            e = st.get(PRI_H_PREFIX + s)
            if e and (e.get("done") or time.time() - e.get("t", 0) < 12 * 3600):
                continue
            todo.append((s, ref))
        _pri_h.update(phase="Загружаю историю торгов новых выпусков", done=0, total=len(todo))

        def hist(x):
            try:
                return x[0], _pri_history(x[0], x[1], today)
            except Exception:  # noqa: BLE001
                return x[0], None
        for k in range(0, len(todo), 40):
            res = pool_map(hist, todo[k:k + 40], workers=8)
            st.put_many([(PRI_H_PREFIX + s, v) for s, v in res if v is not None])
            _pri_h["done"] = min(len(todo), k + 40)
        _pri_h["fin"] = time.time()
        _pri_h["err"] = None
    except Exception as e:  # noqa: BLE001
        _pri_h["err"] = str(e)[:200]
    finally:
        _pri_h.update(running=False, phase="", memo=(0, None))


def primary_stats_start(force=False):
    with _rt_lock:
        if _pri_h["running"]:
            return
        if not force and time.time() - _pri_h["fin"] < 6 * 3600:
            return
        _pri_h["running"] = True
    threading.Thread(target=_pri_run, daemon=True).start()


def _grp_stats(items):
    p0 = [x["p0"] for x in items if x["p0"] is not None]
    p7 = [x["p7"] for x in items if x["p7"] is not None]
    p30 = [x["p30"] for x in items if x["p30"] is not None]
    dn = [x["now"] - x["p0"] for x in items if x["now"] is not None and x["p0"] is not None]
    abv = lambda arr: round(100.0 * sum(1 for v in arr if v > 100.0) / len(arr), 1) if arr else None  # noqa: E731
    return {"n": len(items), "p0": _med(p0), "p7": _med(p7), "p30": _med(p30), "n30": len(p30),
            "above0": abv(p0), "above7": abv(p7), "above30": abv(p30),
            "below30": round(100.0 * sum(1 for v in p30 if v < 100) / len(p30), 1) if p30 else None,
            "d_now": _med(dn)}


def primary_stats_payload():
    memo = _pri_h["memo"]
    if memo[1] is not None and time.time() - memo[0] < 120 and not _pri_h["running"]:
        return dict(memo[1], loading=False)
    primary_stats_start()
    st = store()
    iss, cand = _pri_candidates()
    uni = {r["id"]: r for r in _scr["rows"]}
    items = []
    for sid, ref in cand:
        e = st.get(PRI_H_PREFIX + sid)
        r = uni.get(sid)
        if not e or not r or e.get("p0") is None:
            continue
        rt, ci = None, None
        try:
            ti = globals().get("tcat_info")
            ci = ti(r.get("isin")) if ti and r.get("isin") else None
            rt = best_rating(r.get("isin"), (ci or {}).get("name") or r["name"]) if r["kind"] == "corp" else None
        except Exception:  # noqa: BLE001
            rt = None
        sector = (ci or {}).get("sector") if r["kind"] == "corp" else None
        sane = lambda v, lo, hi: v if v is not None and lo <= v <= hi else None  # noqa: E731
        now_ok = r.get("price") if (r.get("yield") or 0) > 0 else None       # без доходности цена ненадёжна (индексируемый номинал и т. п.)
        if not (80 <= e["p0"] <= 120):
            continue
        items.append({"secid": sid, "isin": r.get("isin"), "name": r["name"], "kind": r["kind"], "d0": e["d0"], "p0": e["p0"], "y0": e.get("y0"),
                      "p7": sane(e.get("p7"), 50, 150), "p30": sane(e.get("p30"), 50, 150), "y30": e.get("y30"),
                      "now": sane(now_ok, 10, 150), "ynow": r.get("yield"),
                      "rating": rt["v"] if rt else None, "bucket": "ОФЗ" if r["kind"] == "ofz" else rating_bucket(rt["v"] if rt else None),
                      "sector": sector})
    by_b, by_s = {}, {}
    for x in items:
        by_b.setdefault(x["bucket"], []).append(x)
        if x["sector"]:
            by_s.setdefault(x["sector"], []).append(x)
    order = ["ОФЗ"] + MKT_BUCKETS + ["нет рейтинга"]
    buckets = [dict(_grp_stats(by_b[b]), bucket=b) for b in order if b in by_b]
    sectors = sorted((dict(_grp_stats(v), sector=k) for k, v in by_s.items() if len(v) >= 3), key=lambda g: -g["n"])[:12]
    aged = [x for x in items if x["now"] is not None and x["d0"] <= _day_add(date.today().isoformat(), -7)]
    aged.sort(key=lambda x: x["now"] - x["p0"])
    trim = lambda x: dict(x, delta=round(x["now"] - x["p0"], 2))  # noqa: E731
    by_m = {}
    for x in items:
        by_m.setdefault(x["d0"][:7], []).append(x)
    months = [dict(_grp_stats(v), m=k) for k, v in sorted(by_m.items())]
    snaps = (st.get(PRI_SNAP_KEY) or {}).get("days") or {}
    d30 = _day_add(date.today().isoformat(), -30)
    d90 = _day_add(date.today().isoformat(), -90)
    win30 = _grp_stats([x for x in items if (x.get("d0") or "") >= d30])
    win90 = _grp_stats([x for x in items if (x.get("d0") or "") >= d90])
    res = {"all": _grp_stats(items), "win30": win30, "win90": win90, "buckets": buckets, "sectors": sectors, "months": months,
           "worst": [trim(x) for x in aged[:8]], "best": [trim(x) for x in aged[::-1][:8]],
           "universe": len(cand), "ready": len(items), "snap_days": len(snaps), "updated": _pri_h["fin"], "err": _pri_h["err"]}
    if not _pri_h["running"]:
        _pri_h["memo"] = (time.time(), res)
    return dict(res, loading=_pri_h["running"], phase=_pri_h["phase"], done=_pri_h["done"], total=_pri_h["total"])


def _api_primary_stats(cfg, acc, q, force):
    return primary_stats_payload()


API_GET["/api/primary/stats"] = _api_primary_stats


RATE_TERM_MIN, RATE_TERM_MAX, RATE_TERMS_MAX = 0.25, 30.0, 6
_rates_state = {"running": False, "ended": 0.0}


def kbd_interp(grid, term):
    """Доходность КБД на срок term (лет): линейная интерполяция между соседними точками сетки {срок: доходность}.
    Вне диапазона сетки возвращает None (не экстраполируем и не тянем крайнее значение)."""
    pts = sorted((float(k), v) for k, v in (grid or {}).items() if v is not None)
    if not pts or term is None or term < pts[0][0] - 1e-9 or term > pts[-1][0] + 1e-9:
        return None
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if term <= x1 + 1e-9:
            return y0 if x1 == x0 else y0 + (y1 - y0) * (term - x0) / (x1 - x0)
    return pts[-1][1]


def parse_rate_terms(raw):
    """'1,2,5.5' -> [1.0, 2.0, 5.5]: только числа в 0.25..30, без повторов, по возрастанию, не больше 6; по умолчанию [2.0]."""
    out = set()
    for x in str(raw or "").replace(";", ",").split(","):
        try:
            t = round(float(x.strip().replace(",", ".")), 2)
        except ValueError:
            continue
        if RATE_TERM_MIN <= t <= RATE_TERM_MAX:
            out.add(t)
    return sorted(out)[:RATE_TERMS_MAX] or [2.0]


def key_rate_series():
    st = store()
    hit = st.get(KEY_KEY, ttl=6 * 3600)
    if hit:
        return hit
    frm = (date.today() - timedelta(days=900)).strftime("%d.%m.%Y")
    to = date.today().strftime("%d.%m.%Y")
    try:
        s = http_text("https://www.cbr.ru/hd_base/KeyRate/?UniDbQuery.Posted=True&UniDbQuery.From=%s&UniDbQuery.To=%s" % (frm, to))
    except Exception:  # noqa: BLE001
        old = st.get(KEY_KEY)          # сайт ЦБ недоступен — последний сохранённый ряд лучше, чем ошибка на каждом экране
        if old:
            return old
        raise
    rows = []
    for d, v in re.findall(r"<td>(\d\d\.\d\d\.\d{4})</td>\s*<td>([\d,]+)</td>", s):
        rows.append([datetime.strptime(d, "%d.%m.%Y").date().isoformat(), float(v.replace(",", "."))])
    rows.sort()
    if rows:
        st.put(KEY_KEY, rows)
    return rows


def _kbd_one(d):
    j = json.loads(http_text("https://iss.moex.com/iss/engines/stock/zcyc.json?iss.meta=off&iss.only=yearyields&date=" + d))
    g = {str(float(r[2])): r[3] for r in j["yearyields"]["data"] if r[3] is not None}
    return d, (g or None)


def _rates_run(days):
    try:
        st = store()
        cache = st.get(KBD_KEY) or {}
        today = date.today()
        need = []
        for i in range(days + 1):
            d = today - timedelta(days=i)
            if d.weekday() < 5 and d.isoformat() not in cache:
                need.append(d.isoformat())
        try:
            key_rate_series()
        except Exception:  # noqa: BLE001
            pass
        for k in range(0, len(need), 40):
            part = need[k:k + 40]
            for d, v in pool_map(lambda x: _safe(_kbd_one, x), part, workers=8):
                if d is None:
                    continue
                if v is not None or d < today.isoformat():
                    cache[d] = v
            st.put(KBD_KEY, cache)
    finally:
        _rates_state["ended"] = time.time()
        _rates_state["running"] = False


def _safe(fn, x):
    try:
        return fn(x)
    except Exception:  # noqa: BLE001
        return None, None


def rates_start(days):
    with _rt_lock:
        # недокачанные дни (сбой ISS, праздники) повторяем не чаще раза в 10 минут — иначе экран вечно «загружается»
        if _rates_state["running"] or time.time() - _rates_state["ended"] < 600:
            return
        _rates_state["running"] = True
    threading.Thread(target=_rates_run, args=(days,), daemon=True).start()


def rates_payload(days, terms=None):
    days = max(30, min(int(days or 365), 900))
    tl = terms if isinstance(terms, list) else parse_rate_terms(terms)
    st = store()
    cache = st.get(KBD_KEY) or {}
    old = st.get(KBD_OLD_KEY) or {}
    today = date.today()
    first = (today - timedelta(days=days)).isoformat()
    # сегодняшняя КБД появляется только после расчёта биржей — её отсутствие не считаем недокачкой
    miss = sum(1 for i in range(1, days + 1) if (today - timedelta(days=i)).weekday() < 5
               and (today - timedelta(days=i)).isoformat() not in cache)
    if today.weekday() < 5 and today.isoformat() not in cache:
        rates_start(days)
    if miss > 0:
        rates_start(days)
    try:
        keys = key_rate_series()
    except Exception:  # noqa: BLE001
        keys = st.get(KEY_KEY) or []
    grids = {}
    for d in set(cache) | set(old):
        if d < first:
            continue
        g = cache.get(d)
        if g:
            grids[d] = g
        elif d not in cache and old.get(d) is not None:
            grids[d] = {"2.0": old[d]}      # запас до докачки v2: только срок 2 года
    iso = sorted(grids)
    kbd = {("%g" % t): [] for t in tl}
    key, ki, last = [], 0, None
    for d in iso:
        while ki < len(keys) and keys[ki][0] <= d:
            last = keys[ki][1]
            ki += 1
        for t in tl:
            v = kbd_interp(grids[d], t)
            kbd["%g" % t].append(round(v, 2) if v is not None else None)
        key.append(last)
    return {"iso": iso, "labels": [datetime.strptime(d, "%Y-%m-%d").strftime("%d.%m.%Y") for d in iso],
            "kbd": kbd, "terms": tl, "key": key, "loading": _rates_state["running"] or (miss > 0 and not _rates_state["ended"]),
            "keys": [k for k in keys if k[0] >= first], "next_cbr": _next_cbr_safe()}


def _next_cbr_safe():
    """Ближайшее заседание ЦБ для экрана «Ставки»; без сети — None (экран не должен падать из-за календаря ЦБ)."""
    fn = globals().get("cbr_next_meeting")
    try:
        return fn(wait=False) if fn else None
    except Exception:  # noqa: BLE001
        return None




# ── кривая КБД на прошлые даты ──

def kbd_curve_on(d):
    """Кривая КБД на дату d (ISO; при выходном берётся ближайший прошлый торговый день). Кэш для прошлых дат навсегда."""
    st = store()
    key = "kbdc1:" + d
    v = st.get(key)
    if v:
        return v
    if d >= date.today().isoformat():
        return [list(p) for p in kbd_curve()]
    for k in range(0, 6):
        dd = _day_add(d, -k)
        j = json.loads(http_text("https://iss.moex.com/iss/engines/stock/zcyc.json?iss.meta=off&iss.only=yearyields&date=" + dd))
        pts = sorted((r[2], r[3]) for r in j["yearyields"]["data"])
        if pts:
            v = [list(p) for p in pts]
            st.put(key, v)
            return v
    return None


CURVE_TERMS = [0.25, 0.5, 1, 2, 3, 5, 7, 10, 15, 20]
CURVE_AGO = [(0, "Сегодня"), (30, "1 мес. назад"), (91, "3 мес. назад"), (182, "6 мес. назад"), (365, "12 мес. назад")]


def _term_lab(t):
    return "%d мес" % round(t * 12) if t < 1 else "%d г." % t


def kbd_curves_payload():
    today = date.today().isoformat()
    ds = [(_day_add(today, -n), lab) for n, lab in CURVE_AGO]

    def one(x):
        try:
            return kbd_curve_on(x[0])
        except Exception:  # noqa: BLE001
            return None
    res = pool_map(one, ds, workers=5)
    items = []
    for (d, lab), pts in zip(ds, res):
        if pts:
            items.append({"date": d, "label": lab, "y": [round(_interp(pts, t), 2) for t in CURVE_TERMS]})
    return {"terms": CURVE_TERMS, "labels": [_term_lab(t) for t in CURVE_TERMS], "items": items}


def _fmt_pp(v):
    return ("%.2f" % abs(v)).replace(".", ",")


def _curve_notes(cv):
    out = []
    its = cv.get("items") or []
    if len(its) < 2:
        return out
    now = its[0]
    i2, i10, i1 = CURVE_TERMS.index(2), CURVE_TERMS.index(10), CURVE_TERMS.index(1)
    for it in its[1:]:
        if it["label"] != "3 мес. назад":
            continue
        s0, s1 = it["y"][i10] - it["y"][i2], now["y"][i10] - now["y"][i2]
        if abs(s1 - s0) < 0.15:
            out.append("Форма кривой за 3 месяца почти не изменилась: разница между 10-летними и 2-летними ставками %s п.п." % _fmt_pp(s1))
        else:
            out.append("За 3 месяца кривая КБД стала %s: разница между 10-летними и 2-летними ставками %s с %s до %s п.п." % (
                "круче (длинные ставки выше коротких сильнее)" if s1 > s0 else "положе (длинные и короткие ставки сближаются)",
                "выросла" if s1 > s0 else "сократилась", ("-" if s0 < 0 else "") + _fmt_pp(s0), ("-" if s1 < 0 else "") + _fmt_pp(s1)))
        d1 = now["y"][i1] - it["y"][i1]
        if abs(d1) >= 0.1:
            out.append("Доходность 1-летних гособлигаций %s на %s п.п. (с %s до %s %%)." % (
                "выросла" if d1 > 0 else "снизилась", _fmt_pp(d1), _fmt_pp(it["y"][i1]), _fmt_pp(now["y"][i1])))
    yr = [it for it in its if it["label"] == "12 мес. назад"]
    if yr:
        d2 = now["y"][i2] - yr[0]["y"][i2]
        out.append("За год 2-летняя доходность КБД %s на %s п.п." % ("выросла" if d2 > 0 else "снизилась", _fmt_pp(d2)))
    return out


# ── история медианных спредов к КБД по рейтингам: накопленные снимки + разовое восстановление по истории торгов ──

BF_KEY = "mkt_bf_v1"
_bf = {"running": False, "last": 0}


def _bf_dates():
    t = date.today()
    ds = set()
    for n in [7 * k for k in range(1, 9)] + [91, 119, 147, 182]:
        d = t - timedelta(days=n)
        while d.weekday() > 4:
            d -= timedelta(days=1)
        ds.add(d.isoformat())
    return sorted(ds)


HB_URL = ("https://iss.moex.com/iss/history/engines/stock/markets/bonds/boards/TQCB/securities.json?iss.meta=off&date=%s&start=%d"
          "&iss.only=history,history.cursor&history.columns=SECID,YIELDCLOSE,YIELDATWAP,DURATION,MATDATE,NUMTRADES,VALUE,CURRENCYID")


def _bf_day(d, bucket_of):
    pts = kbd_curve_on(d)
    if not pts:
        return None

    def page(s):
        j = json.loads(http_text(HB_URL % (d, s), timeout=40))
        t = j["history"]
        return [dict(zip(t["columns"], r)) for r in t["data"]], j["history.cursor"]["data"][0][1]
    rows, total = page(0)
    starts = list(range(100, min(total, 6000), 100))
    for part, _ in pool_map(lambda s: _safe_pg(page, s), starts, workers=6):
        rows += part
    by = {}
    for r in rows:
        b = bucket_of.get(r["SECID"])
        y = r.get("YIELDCLOSE") or r.get("YIELDATWAP")
        if not b or not y or not r.get("DURATION") or not (r.get("NUMTRADES") or 0) or r.get("CURRENCYID") not in ("SUR", "RUB", None):
            continue
        if not (0 < y < 60) or not r.get("MATDATE") or r["MATDATE"] <= _day_add(d, 40):
            continue
        by.setdefault(b, []).append(y - _interp(pts, r["DURATION"] / 365.0))
    sp, nn = {}, {}
    for b, v in by.items():
        if len(v) >= 3:
            sp[b], nn[b] = _med(v), len(v)
    return {"sp": sp, "n": nn, "bf": True} if sp else None


def _safe_pg(fn, s):
    try:
        return fn(s)
    except Exception:  # noqa: BLE001
        return [], 0


def _bf_run():
    try:
        rows = _scr["rows"]
        if not rows or not any(r.get("rating") for r in rows):
            screener_payload()
            rows = _scr["rows"]
        bucket_of = {r["id"]: rating_bucket(r["rating"]) for r in rows if r.get("kind") == "corp" and r.get("cur") == "RUB" and r.get("rating")}
        st = store()
        bf = st.get(BF_KEY) or {}
        for d in _bf_dates():
            if d in bf:
                continue
            try:
                v = _bf_day(d, bucket_of)
            except Exception:  # noqa: BLE001
                v = None
            if v:
                bf[d] = v
                st.put(BF_KEY, bf)
        _bf["last"] = time.time()
    except Exception:  # noqa: BLE001
        _bf["last"] = time.time() - 3600 * 5
    finally:
        _bf["running"] = False


def spreads_backfill_start():
    with _rt_lock:
        if _bf["running"] or time.time() - _bf["last"] < 6 * 3600:
            return
        _bf["running"] = True
    threading.Thread(target=_bf_run, daemon=True).start()


def spreads_history_payload():
    st = store()
    live = st.get(MKT_HIST2_KEY) or {}
    old = st.get(MKT_HIST_KEY) or {}
    allh = dict(st.get(BF_KEY) or {})
    for d, sp in old.items():           # v1 (только спреды), если нет v2
        if d not in live:
            allh[d] = {"sp": sp}
    allh.update(live)
    days = sorted(allh)[-400:]
    series = {b: [(allh[d].get("sp") or {}).get(b) for d in days] for b in MKT_BUCKETS}
    series = {b: v for b, v in series.items() if any(x is not None for x in v)}
    return {"dates": days, "series": series, "bf": [d for d in days if allh[d].get("bf")]}


def _spread_notes(h):
    out = []
    ds = h["dates"]
    if len(ds) < 2:
        return ["История спредов накапливается: каждый день работы программы добавляет точку."]
    last = ds[-1]
    for b in ("AAA", "AA", "A", "BBB"):
        v = h["series"].get(b)
        if not v or v[-1] is None:
            continue
        tgt = _day_add(last, -30)
        cand = [i for i, d in enumerate(ds[:-1]) if d <= tgt and v[i] is not None]
        if not cand:
            cand = [i for i, d in enumerate(ds[:-1]) if v[i] is not None and d <= _day_add(last, -7)]
        if not cand:
            continue
        i = cand[-1]
        diff = v[-1] - v[i]
        days = (datetime.strptime(last, "%Y-%m-%d") - datetime.strptime(ds[i], "%Y-%m-%d")).days
        per = "за месяц" if 25 <= days <= 40 else "за %d дн." % days
        if abs(diff) < 0.1:
            out.append("Спред %s почти не изменился %s: %s п.п." % (b, per, _fmt_pp(v[-1])))
        else:
            out.append("Спред %s %s на %s п.п. %s (с %s до %s п.п.)." % (
                b, "расширился" if diff > 0 else "сузился", _fmt_pp(diff), per, _fmt_pp(v[i]), _fmt_pp(v[-1])))
    return out or ["Для вывода о динамике пока мало данных по спредам."]


def rates_extra_payload():
    spreads_backfill_start()
    h = spreads_history_payload()
    cv = kbd_curves_payload()
    return {"spreads": h, "curves": cv, "notes": _curve_notes(cv), "spread_notes": _spread_notes(h), "loading": _bf["running"]}


API_GET["/api/rates/extra"] = lambda cfg, acc, q, force: rates_extra_payload()


# ── ежедневная фоновая работа: снимок размещений и спреды (история копится, даже если разделы не открывали) ──

def _market_daily_loop():
    time.sleep(20)
    while True:
        try:
            primary_payload()
        except Exception:  # noqa: BLE001
            pass
        try:
            h = store().get(MKT_HIST2_KEY) or {}
            if date.today().isoformat() not in h:
                screener_payload()
            spreads_backfill_start()
            # статистика первички (тысячи запросов к ISS при первом расчёте) — только по открытию раздела «Первичка»
        except Exception:  # noqa: BLE001
            pass
        time.sleep(6 * 3600)


def _market_daily_start():
    threading.Thread(target=_market_daily_loop, daemon=True).start()


STARTUP_HOOKS.append(_market_daily_start)


# ── первичка: объёмы размещений («простыня» новых выпусков) ──
# Что нашли в ISS (проверено вживую):
#  * Корпоративные и региональные облигации размещаются на РЫНКЕ ndm (не bonds!), площадка PSAU «Размещение - адрес.»
#    (PAUS — в USD, PACY — в CNY). Размещение ОФЗ и аукционы — рынок bonds, площадки PACT/AUCT/PAYT.
#    Новый выпуск до начала торгов в bonds вообще не виден: /engines/stock/markets/bonds/securities/{secid} пуст.
#  * Сегодняшние обороты: /engines/stock/markets/ndm/boards/PSAU/securities.json (marketdata: VALTODAY — ₽ по цене сделок,
#    VOLTODAY — штуки, NUMTRADES). Это же — список всех бумаг, открытых на площадке размещения (около 80, большинство — «краны»
#    без сделок), поэтому «новый выпуск» отбираем по описанию: /iss/securities/{secid}.json (description: ISSUEDATE — дата
#    начала торгов, ISSUESIZE — объём выпуска в ШТУКАХ, FACEVALUE/INITIALFACEVALUE — номинал, MATDATE).
#  * Дневная история размещения: /iss/history/engines/stock/markets/ndm/boards/PSAU/securities.json?date=YYYY-MM-DD
#    (одна страница ≈ 80 строк; столбцы VALUE — ₽ по цене сделок, VOLUME — штуки, NUMTRADES, WAPRICE, CLOSE).
#    По конкретной бумаге — /iss/history/engines/stock/markets/{ndm|bonds}/securities/{secid}.json (все площадки сразу).
#  * Размещено: ISSUESIZEPLACED (штуки) есть только у бумаг, которые уже торгуются на bonds; для ndm-размещений берём сумму
#    VOLUME по площадке размещения. Объём в номинале = штуки × номинал (VALUE у дисконтных/структурных может быть заметно меньше).

PV_DAYS = 30
PV_ACTIVE_MAX_DAYS = 400   # старше — показываем активный выпуск, только если по нему были сделки размещения за PV_DAYS
PV_PLACE_NDM = ("PSAU", "PAUS", "PACY")
PV_PLACE_BONDS = ("PACT", "AUCT", "PAYT")
PV_PLACE = set(PV_PLACE_NDM) | set(PV_PLACE_BONDS)
PV_BOARD_NAMES = {"PSAU": "размещение", "PAUS": "размещение", "PACY": "размещение", "PACT": "размещение (аукцион)",
                  "AUCT": "размещение (аукцион)", "PAYT": "размещение (аукцион)", "TQCB": "Т+ корп.", "TQOB": "Т+ ОФЗ",
                  "TQIR": "Т+ ПИР", "TQRD": "Т+ Д", "TQOD": "Т+ USD", "TQOE": "Т+ EUR", "TQOY": "Т+ CNY", "TQUD": "Т+ USD Д",
                  "PSOB": "РПС", "PTOB": "РПС с ЦК", "PSDB": "РПС Д"}
PV_DAY_KEY, PV_DESC_KEY, PV_DAYS_KEY = "pv_day1:", "pv_desc1:", "pv_secdays1:"
PV_CUM_KEY = "pv_cum1:"       # кумулятив по площадкам размещения с даты старта: {from, last, q, v, n, first}
_pv = {"running": False, "res": None, "t": 0.0, "phase": "", "err": None}
_pv_lock = threading.Lock()
_pv_mem = {}          # короткий кэш по бумагам: ключ -> (время, значение)
PV_ISS = "https://iss.moex.com/iss/"


def pv_msk_now():
    return datetime.now(timezone(timedelta(hours=3)))


def pv_ttl(now=None):
    """Срок жизни живых данных: 5 минут в торговые часы (будни 7:00-23:50 МСК), иначе 30 минут."""
    n = now or pv_msk_now()
    return 300 if n.weekday() < 5 and 7 <= n.hour < 24 else 1800


def pv_num(v):
    try:
        return float(v) if v is not None and v != "" else None
    except (TypeError, ValueError):
        return None


def pv_date(v):
    return v if isinstance(v, str) and re.match(r"^\d{4}-\d\d-\d\d$", v) and not v.startswith("0000") else ""


def pv_table(j, name):
    """Таблица ISS как список словарей; отсутствующая или пустая -> []."""
    t = (j or {}).get(name) or {}
    cols = t.get("columns") or []
    return [dict(zip(cols, r)) for r in t.get("data") or []]


def pv_json(url, timeout=30):
    try:
        return json.loads(http_text(url, timeout=timeout))
    except (OSError, ValueError):      # ISS иногда рвёт соединение: одна повторная попытка
        time.sleep(0.5)
        return json.loads(http_text(url, timeout=timeout))


def pv_hist_parse(rows, board_only=None):
    """Строки истории ISS -> компактные записи. Пустые строки (площадка открыта, сделок нет) отбрасываются."""
    out = []
    for r in rows:
        b = r.get("BOARDID")
        d = pv_date(r.get("TRADEDATE"))
        if not d or not r.get("SECID") or (board_only and b not in board_only):
            continue
        v, q, n = pv_num(r.get("VALUE")) or 0.0, pv_num(r.get("VOLUME")) or 0.0, int(pv_num(r.get("NUMTRADES")) or 0)
        if not (v or q or n):
            continue
        out.append({"s": r["SECID"], "b": b, "d": d, "v": round(v, 2), "q": q, "n": n, "w": pv_num(r.get("WAPRICE")),
                    "c": pv_num(r.get("CLOSE")), "y": pv_num(r.get("YIELDCLOSE")) or pv_num(r.get("YIELDATWAP")),
                    "nm": r.get("SHORTNAME"), "f": pv_num(r.get("FACEVALUE"))})
    return out


def pv_paged(url, table, timeout=30, maxpages=30):
    """Все страницы таблицы ISS (по 100 строк)."""
    rows, start = [], 0
    for _ in range(maxpages):
        j = pv_json(url + ("&start=%d" % start if start else ""), timeout)
        part = pv_table(j, table)
        rows += part
        if len(part) < 100:
            break
        start += len(part)
    return rows


_PV_HCOLS = "BOARDID,TRADEDATE,SECID,SHORTNAME,NUMTRADES,VALUE,VOLUME,WAPRICE,CLOSE,YIELDCLOSE,YIELDATWAP,FACEVALUE"


def pv_day_fetch(d):
    """Площадка размещения PSAU за один день (прошедший)."""
    url = (PV_ISS + "history/engines/stock/markets/ndm/boards/PSAU/securities.json?iss.meta=off&iss.only=history"
           "&history.columns=%s&date=%s" % (_PV_HCOLS, d))
    return pv_hist_parse(pv_paged(url, "history"))


def pv_days_cached(dates, errs):
    """Дни окна: прошедшие дни хранятся в базе насовсем (вчерашний — 3 часа, пока площадка может поправить итоги)."""
    st = store()
    today = pv_msk_now().date().isoformat()
    res, need = {}, []
    for d in dates:
        e = st.get(PV_DAY_KEY + d, 3 * 3600 if d >= _day_add(today, -1) else None)
        if e is None:
            need.append(d)
        else:
            res[d] = e
    if need:
        def one(d):
            try:
                return d, pv_day_fetch(d)
            except Exception as ex:  # noqa: BLE001
                return d, str(ex)[:120]
        got = []
        for d, v in pool_map(one, need, workers=8):
            if isinstance(v, list):
                res[d] = v
                got.append((PV_DAY_KEY + d, v))
            else:
                errs.append("история %s: %s" % (d, v))
        if got:
            st.put_many(got)
    return res


def pv_range_fetch(mk, board, d1, d2):
    url = (PV_ISS + "history/engines/stock/markets/%s/boards/%s/securities.json?iss.meta=off&iss.only=history"
           "&history.columns=%s&from=%s&till=%s" % (mk, board, _PV_HCOLS, d1, d2))
    return pv_hist_parse(pv_paged(url, "history"))


def pv_other_boards(d1, d2, errs):
    """Остальные площадки размещения (USD, CNY, аукционы ОФЗ): мелкие, одним запросом за период; кэш на 3 часа."""
    st, out = store(), []
    for mk, b in [("ndm", x) for x in PV_PLACE_NDM[1:]] + [("bonds", x) for x in PV_PLACE_BONDS]:
        k = "pv_rng1:%s:%s" % (mk, b)
        e = st.get(k, 3 * 3600)
        if e is None:
            try:
                e = pv_range_fetch(mk, b, d1, d2)
                st.put(k, e)
            except Exception as ex:  # noqa: BLE001
                errs.append("площадка %s: %s" % (b, str(ex)[:100]))
                e = []
        out += e
    return out


def pv_parse_desc(j):
    m = {r.get("name"): r.get("value") for r in pv_table(j, "description")}
    face = pv_num(m.get("FACEVALUE")) or pv_num(m.get("INITIALFACEVALUE")) or 0.0
    init = pv_num(m.get("INITIALFACEVALUE")) or face
    return {"name": m.get("SHORTNAME") or "", "full": m.get("NAME") or "", "kind": m.get("ISSUENAME") or "", "isin": m.get("ISIN") or "",
            "issued": pv_date(m.get("ISSUEDATE")), "start": pv_date(m.get("STARTDATEMOEX")), "mat": pv_date(m.get("MATDATE")),
            "size": pv_num(m.get("ISSUESIZE")), "face": face, "face0": init, "cur": m.get("FACEUNIT") or "SUR",
            "ftype": m.get("FACEVALUE_TYPE") or "", "emitter": m.get("EMITTER_ID")}


def pv_desc_old(d, cut):
    """Описание выпуска с датой старта раньше окна: дата не меняется и в «первичку» выпуск уже не вернётся — хранить можно насовсем."""
    st = (d or {}).get("issued") or (d or {}).get("start") or ""
    return bool(st) and st < cut


def pv_desc(secid):
    st = store()
    cut = _day_add(pv_msk_now().date().isoformat(), -PV_DAYS)
    e = st.get(PV_DESC_KEY + secid)
    if e is not None and pv_desc_old(e, cut):
        return e
    e = st.get(PV_DESC_KEY + secid, 7 * 86400)
    if e is not None:
        return e
    j = pv_json(PV_ISS + "securities/%s.json?iss.meta=off&iss.only=description&description.columns=name,value" % secid, 25)
    e = pv_parse_desc(j)
    st.put(PV_DESC_KEY + secid, e)
    return e


def pv_issuer_name(full):
    """«Банк ВТБ ПАО КС-4-1328» -> «Банк ВТБ ПАО»: отбрасываем серию в конце для поиска рейтинга."""
    s = re.sub(r"\s+(?:[A-Za-zА-Яа-я0-9\-/]*\d[A-Za-zА-Яа-я0-9\-/.]*)\s*$", "", (full or "").strip())
    return s or (full or "")


def pv_live_parse(j):
    """ndm/bonds: бумаги + marketdata по площадкам -> {secid: [{b, today, vol, n, last, wap, yield, size, placed, ...}]}."""
    sec = {}
    for r in pv_table(j, "securities"):
        sec.setdefault(r.get("SECID"), {})[r.get("BOARDID")] = r
    out = {}
    for m in pv_table(j, "marketdata"):
        sid, b = m.get("SECID"), m.get("BOARDID")
        s = (sec.get(sid) or {}).get(b) or {}
        out.setdefault(sid, []).append({
            "b": b, "today": pv_num(m.get("VALTODAY_RUR")) or pv_num(m.get("VALTODAY")) or 0.0, "vol": pv_num(m.get("VOLTODAY")) or 0.0,
            "n": int(pv_num(m.get("NUMTRADES")) or 0), "last": pv_num(m.get("LAST")), "wap": pv_num(m.get("WAPRICE")),
            "yield": pv_num(m.get("YIELD")) or pv_num(m.get("YIELDATWAPRICE")) or pv_num(m.get("CLOSEYIELD")) or None,
            "status": m.get("TRADINGSTATUS"), "name": s.get("SHORTNAME"), "full": s.get("SECNAME"), "settle": pv_date(s.get("SETTLEDATE")),
            "size": pv_num(s.get("ISSUESIZE")), "placed": pv_num(s.get("ISSUESIZEPLACED")), "face": pv_num(s.get("FACEVALUE")),
            "cpn": pv_num(s.get("COUPONPERCENT")), "ctype": s.get("BONDTYPE"), "mat": pv_date(s.get("MATDATE")),
            "offer": pv_date(s.get("OFFERDATE")), "isin": s.get("ISIN")})
    return out


_PV_LS = "SECID,BOARDID,SHORTNAME,SECNAME,FACEVALUE,SETTLEDATE,MATDATE,OFFERDATE,ISSUESIZE,ISSUESIZEPLACED,COUPONPERCENT,BONDTYPE,ISIN"
_PV_LM = "SECID,BOARDID,VALTODAY,VALTODAY_RUR,VOLTODAY,NUMTRADES,LAST,WAPRICE,YIELD,YIELDATWAPRICE,CLOSEYIELD,TRADINGSTATUS"


def pv_live_board(mk, board):
    j = pv_json(PV_ISS + "engines/stock/markets/%s/boards/%s/securities.json?iss.meta=off&iss.only=securities,marketdata"
                "&securities.columns=%s&marketdata.columns=%s" % (mk, board, _PV_LS, _PV_LM), 40)
    return pv_live_parse(j)


def pv_live_secid(secid):
    """Вторичные торги по бумаге на рынке bonds (все площадки): оборот сегодня, доходность, купон, размещено (ISSUESIZEPLACED)."""
    k = "bm:" + secid
    c = _pv_mem.get(k)
    if c and time.time() - c[0] < pv_ttl():
        return c[1]
    j = pv_json(PV_ISS + "engines/stock/markets/bonds/securities/%s.json?iss.meta=off&iss.only=securities,marketdata"
                "&securities.columns=%s&marketdata.columns=%s" % (secid, _PV_LS, _PV_LM), 25)
    v = pv_live_parse(j).get(secid) or []
    _pv_mem[k] = (time.time(), v)
    return v


def pv_sec_hist(mk, secid, frm, till):
    """История выпуска по рынку (все площадки), записи pv_hist_parse. Общий источник для pv_secid_days и кумулятива."""
    return pv_hist_parse(pv_paged(PV_ISS + "history/engines/stock/markets/%s/securities/%s.json?iss.meta=off&iss.only=history"
                                  "&history.columns=%s&from=%s&till=%s" % (mk, secid, _PV_HCOLS, frm, till), "history"))


def pv_cum(secid, frm, today, mks, errs):
    """Размещено с даты старта по площадкам размещения (без сегодняшнего дня): {q, v, n, first, last}.
    Дни до позавчера неизменны — копим в базе (pv_cum1:) и докачиваем только новые; вчера может поправиться — держим в памяти 3 часа."""
    st = store()
    k = PV_CUM_KEY + secid
    yday, final_to = _day_add(today, -1), _day_add(today, -2)
    e = st.get(k)
    if not e or e.get("from") != frm or e.get("mks") != sorted(mks):
        e = {"from": frm, "mks": sorted(mks), "last": _day_add(frm, -1), "q": 0.0, "v": 0.0, "n": 0, "first": ""}
    tk = "cumtail:" + secid
    tail = _pv_mem.get(tk)
    tail_ok = tail and time.time() - tail[0] < 3 * 3600 and tail[2] == e["last"]
    if e["last"] < yday and not (e["last"] >= final_to and tail_ok):
        rows = []
        for mk in mks:
            try:
                rows += [r for r in pv_sec_hist(mk, secid, _day_add(e["last"], 1), yday) if r["b"] in PV_PLACE and r["d"] < today]
            except Exception as ex:  # noqa: BLE001
                errs.append("кумулятив %s %s: %s" % (secid, mk, str(ex)[:100]))
                return None
        fin = [r for r in rows if r["d"] <= final_to]
        if fin:
            e["q"] += sum(r["q"] for r in fin)
            e["v"] += sum(r["v"] for r in fin)
            e["n"] += sum(r["n"] for r in fin)
            e["first"] = e["first"] or min(r["d"] for r in fin)
        if e["last"] < final_to:
            e["last"] = final_to
            st.put(k, e)
        tl = [r for r in rows if r["d"] > final_to]
        tail = (time.time(), {"q": sum(r["q"] for r in tl), "v": sum(r["v"] for r in tl), "n": sum(r["n"] for r in tl),
                              "first": min([r["d"] for r in tl] or [""])}, e["last"])
        _pv_mem[tk] = tail
    t = tail[1] if tail and tail[2] == e["last"] else {"q": 0.0, "v": 0.0, "n": 0, "first": ""}
    return {"q": e["q"] + t["q"], "v": round(e["v"] + t["v"], 2), "n": e["n"] + t["n"], "first": e["first"] or t["first"]}


def pv_aggregate(day_rows):
    """Записи истории площадок размещения -> по бумаге: сумма штук, ₽, сделок, первый/последний день, дневной ряд."""
    out = {}
    for r in day_rows:
        if r["b"] not in PV_PLACE:
            continue
        a = out.setdefault(r["s"], {"q": 0.0, "v": 0.0, "n": 0, "first": r["d"], "last": r["d"], "name": r.get("nm"), "face": r.get("f"), "days": {}})
        a["q"] += r["q"]
        a["v"] += r["v"]
        a["n"] += r["n"]
        a["first"] = min(a["first"], r["d"])
        a["last"] = max(a["last"], r["d"])
        dd = a["days"].setdefault(r["d"], {"q": 0.0, "v": 0.0, "n": 0})
        dd["q"] += r["q"]
        dd["v"] += r["v"]
        dd["n"] += r["n"]
    return out


def pv_coupon_text(live, desc):
    """(текст, флоатер?) — формулу плавающего купона ISS не отдаёт: показываем тип."""
    ct = (live or {}).get("ctype") or ""
    cp = (live or {}).get("cpn")
    kind = (desc or {}).get("kind") or ""
    if "плавающ" in ct:
        return "флоатер", True
    if cp and cp > 0:
        return ("%.2f" % cp).replace(".", ",") + " %", False
    if "дисконт" in kind.lower():
        return "дисконт", False
    if "структурн" in kind.lower() or "структурн" in ct.lower():
        return "структурная", False
    return "", False


def pv_build_row(secid, desc, agg, today_place, bm, today, rating, cum=None, fx=None):
    """Одна строка «простыни». today_place — строки marketdata площадки размещения, bm — marketdata рынка bonds."""
    face = desc.get("face") or desc.get("face0") or 1000.0
    cur = (desc.get("cur") or "SUR").replace("SUR", "RUB")
    a = agg or {}
    live = None
    if bm:
        live = max(bm, key=lambda x: x.get("today") or 0)
    size_pcs = desc.get("size") or (live or {}).get("size")
    placed_moex = max([x.get("placed") or 0 for x in bm or []] or [0])
    tp_val = sum(x.get("today") or 0 for x in today_place or [])
    tp_vol = sum(x.get("vol") or 0 for x in today_place or [])
    tp_n = sum(x.get("n") or 0 for x in today_place or [])
    base = cum if cum is not None else a               # cum — кумулятив с даты старта (бумага сейчас открыта на площадке размещения)
    trades_pcs = (base.get("q") or 0) + tp_vol
    placed_pcs, src = (placed_moex, "moex") if placed_moex > trades_pcs else ((trades_pcs, "trades") if trades_pcs else (0.0, ""))
    sec_today = sum(x.get("today") or 0 for x in bm or [])
    pl_days = sorted(a.get("days") or {})
    start = desc.get("issued") or desc.get("start") or a.get("first") or ""
    try:
        days_on = max(0, (datetime.strptime(today, "%Y-%m-%d") - datetime.strptime(start, "%Y-%m-%d")).days) if start else None
    except ValueError:
        days_on = None
    if tp_val > 0 or (tp_n > 0) or (cum is not None and trades_pcs):
        status = "placing"
    elif trades_pcs:
        status = "placed"
    else:
        status = "upcoming"
    cpn, flt = pv_coupon_text(live, desc)
    return {"secid": secid, "isin": desc.get("isin") or secid, "name": desc.get("name") or a.get("name") or secid, "full": desc.get("full") or "",
            "rating": rating, "coupon": cpn, "floating": flt, "mat": desc.get("mat") or (live or {}).get("mat") or "",
            "offer": (live or {}).get("offer") or "", "start": start, "first_place": (base.get("first") or (pl_days[0] if pl_days else "")) or (today if tp_val > 0 else ""), "days_on": days_on,
            "face": face, "size_pcs": size_pcs, "size_rub": round(cur_to_rub(size_pcs * face, cur, fx), 2) if size_pcs else None,
            "placed_pcs": placed_pcs, "placed_rub": round(cur_to_rub(placed_pcs * face, cur, fx), 2) if placed_pcs else None, "placed_src": src,
            "placed_pct": round(100.0 * placed_pcs / size_pcs, 1) if size_pcs and placed_pcs else None,
            "place_value": round((base.get("v") or 0) + tp_val, 2), "place_trades": (base.get("n") or 0) + tp_n,
            "today_place": round(tp_val, 2), "today_sec": round(sec_today, 2), "today": round(tp_val + sec_today, 2),
            "today_trades": tp_n + sum(x.get("n") or 0 for x in bm or []),
            "price": (live or {}).get("wap") or (live or {}).get("last"), "yield": (live or {}).get("yield"),
            "status": status, "cur": cur}


def pv_upcoming(cal, known_isins, today):
    """Строки календаря Мосбиржи, которых ещё нет среди размещающихся (начало размещения сегодня или позже)."""
    out = []
    for r in cal:
        if r.get("start", "") < today or (r.get("isin") and r["isin"] in known_isins):
            continue
        out.append({"secid": r.get("isin") or "", "isin": r.get("isin") or "", "name": r.get("short") or r.get("issuer") or "",
                    "full": r.get("desc") or "", "rating": r.get("rating"), "coupon": "", "floating": False, "mat": "", "offer": "",
                    "start": r["start"], "first_place": "", "days_on": None, "face": None, "size_pcs": None, "size_rub": None, "placed_pcs": 0,
                    "placed_rub": None, "placed_src": "", "placed_pct": None, "place_value": 0, "place_trades": 0, "today_place": 0,
                    "today_sec": 0, "today": 0, "today_trades": 0, "price": None, "yield": None, "status": "upcoming", "cur": "RUB",
                    "book": r.get("book") or "", "end": r.get("end") or ""})
    return out


def _pv_rating(isin, name):
    try:
        r = best_rating(isin, name)
        return r
    except Exception:  # noqa: BLE001
        try:
            return rating_for(name)
        except Exception:  # noqa: BLE001
            return None


def pv_calendar_bg(out):
    """Календарь investmint в фоновом потоке: результат кладём в out (cal/err), пока основной конвейер грузит MOEX."""
    t0 = time.time()
    try:
        out["cal"] = primary_rows() or []
    except Exception as ex:  # noqa: BLE001
        out["err"] = "календарь: %s" % str(ex)[:100]
    out["t"] = time.time() - t0


def pv_bonds_batch():
    """Весь рынок bonds одним запросом (~3,5 тыс. бумаг, ≈1 МБ): {secid: [marketdata-строки по площадкам]}."""
    j = pv_json(PV_ISS + "engines/stock/markets/bonds/securities.json?iss.meta=off&iss.only=securities,marketdata"
                "&securities.columns=%s&marketdata.columns=%s" % (_PV_LS, _PV_LM), 60)
    return pv_live_parse(j)


def pv_compute():
    errs, tm = [], {}
    t0 = time.time()

    def lap(name):
        nonlocal t0
        t1 = time.time()
        tm[name] = round(t1 - t0, 2)
        t0 = t1
    cal_box = {}
    cal_th = threading.Thread(target=pv_calendar_bg, args=(cal_box,), daemon=True)
    cal_th.start()
    now = pv_msk_now()
    today = now.date().isoformat()
    cut = _day_add(today, -PV_DAYS)
    _pv["phase"] = "История площадки размещения"
    dates = [_day_add(today, -i) for i in range(1, PV_DAYS + 1)]
    dates = [d for d in dates if datetime.strptime(d, "%Y-%m-%d").weekday() < 5]
    byday = pv_days_cached(dates, errs)
    day_rows = [r for d in sorted(byday) for r in byday[d]] + [r for r in pv_other_boards(cut, _day_add(today, -1), errs) if (r.get("d") or "") < today]
    agg = pv_aggregate(day_rows)
    lap("history")
    descs = {}

    def d1(s):
        try:
            return s, pv_desc(s)
        except Exception as ex:  # noqa: BLE001
            return s, str(ex)[:100]

    def load_descs(secs, sink):
        for s, v in pool_map(d1, sorted(secs), workers=8):
            sink[s] = v
    pre = set(agg)                                      # описания бумаг с историей размещения грузим параллельно «сегодняшним» запросам
    pre_got = {}
    pre_th = threading.Thread(target=load_descs, args=(pre, pre_got), daemon=True)
    pre_th.start()
    _pv["phase"] = "Обороты сегодня"
    live = {}
    for mk, b in [("ndm", x) for x in PV_PLACE_NDM] + [("bonds", x) for x in PV_PLACE_BONDS]:
        try:
            for sid, ms in pv_live_board(mk, b).items():
                live.setdefault(sid, []).extend(ms)
        except Exception as ex:  # noqa: BLE001
            errs.append("сегодня %s: %s" % (b, str(ex)[:100]))
    bonds_all = None
    try:
        bonds_all = pv_bonds_batch()
    except Exception as ex:  # noqa: BLE001
        errs.append("рынок bonds: %s" % str(ex)[:100])
    lap("live")
    _pv["phase"] = "Календарь размещений"
    cal_th.join(60)
    lap("calendar_wait")
    tm["calendar"] = round(cal_box.get("t") or 0, 2)
    cal = cal_box.get("cal") or []
    if cal_box.get("err"):
        errs.append(cal_box["err"])
    elif "cal" not in cal_box:
        errs.append("календарь размещений investmint: не ответил вовремя")
    elif not cal:
        errs.append("календарь размещений investmint: 0 строк — возможно, изменилась разметка сайта")
    cal_isin = {r["isin"]: r for r in cal if r.get("isin")}
    cand = set(agg) | set(live)                         # всё, что сейчас открыто на площадке размещения, — независимо от даты старта
    for sid, ms in live.items():
        if any((m.get("today") or 0) > 0 or (m.get("n") or 0) > 0 or (m.get("settle") or "") >= cut for m in ms):
            cand.add(sid)
    cand |= set(cal_isin)
    _pv["phase"] = "Описания выпусков (%d)" % len(cand)
    pre_th.join()
    got = dict(pre_got)
    load_descs(cand - set(pre_got), got)
    for s, v in got.items():
        if isinstance(v, dict):
            descs[s] = v
        else:
            errs.append("описание %s: %s" % (s, v))
    lap("desc")
    old_cut = _day_add(today, -PV_ACTIVE_MAX_DAYS)

    def _alive(s):
        st0 = descs[s].get("issued") or descs[s].get("start") or ""
        return st0 >= old_cut or s in agg or any((m.get("today") or 0) > 0 or (m.get("n") or 0) > 0 for m in live[s])
    # открыты на площадке размещения сейчас: затянувшиеся размещения не теряем, но многолетние «висяки»
    # (региональные выпуски, годами числящиеся на PSAU без сделок) берём, только если по ним были сделки за PV_DAYS дней
    active = {s for s in live if s in descs and _alive(s)}
    new = [s for s, d in descs.items() if s in active or (d.get("issued") or d.get("start") or "") >= cut]
    _pv["phase"] = "Размещено с начала (%d)" % len(active)
    cums = {}

    def c1(s):
        d = descs[s]
        frm = d.get("issued") or d.get("start") or cut
        mks = sorted({"ndm" if m["b"] in PV_PLACE_NDM else "bonds" for m in live[s] if m["b"] in PV_PLACE}) or ["ndm"]
        try:
            return s, pv_cum(s, frm, today, mks, errs)
        except Exception as ex:  # noqa: BLE001
            errs.append("кумулятив %s: %s" % (s, str(ex)[:100]))
            return s, None
    for s, v in pool_map(c1, sorted(active), workers=8):
        if v is not None:
            cums[s] = v
    lap("cum")
    _pv["phase"] = "Вторичные торги (%d)" % len(new)
    bms = {}
    if bonds_all is not None:
        for s in new:
            bms[s] = bonds_all.get(s) or []           # нет в рынке bonds — торгов там ещё нет (как пустой ответ по бумаге)
    else:
        def b1(s):
            try:
                return s, pv_live_secid(s)
            except Exception as ex:  # noqa: BLE001
                return s, str(ex)[:100]
        for s, v in pool_map(b1, new, workers=8):
            if isinstance(v, list):
                bms[s] = v
            else:
                errs.append("торги %s: %s" % (s, v))
    lap("secondary")
    fx = {"RUB": 1.0}
    for s in new:
        c = ((descs[s] or {}).get("cur") or "SUR").replace("SUR", "RUB").upper()
        if c not in fx:
            try:
                fx[c] = tax_cbr_rate(c, today) or 1.0
            except Exception:  # noqa: BLE001
                fx[c] = 1.0
    rows = []
    for s in new:
        d = descs[s]
        tp = [m for m in live.get(s, []) if m["b"] in PV_PLACE]
        rt = _pv_rating(d.get("isin") or s, pv_issuer_name(d.get("full") or d.get("name")))
        row = pv_build_row(s, d, agg.get(s), tp, bms.get(s), today, rt, cums.get(s), fx=fx)
        if row["status"] == "upcoming" and (row["start"] or "") < today:
            continue                                    # открыт на площадке, но сделок не было и даты размещения в будущем нет
        rows.append(row)
    known = {r["isin"] for r in rows} | {r["secid"] for r in rows}
    for r in pv_upcoming(cal, known, today):
        r["rating"] = r["rating"] if r.get("rating") else None
        rows.append(r)
    rows.sort(key=lambda r: r.get("start") or "", reverse=True)
    rows.sort(key=lambda r: {"placing": 0, "upcoming": 1}.get(r["status"], 2))
    return {"rows": rows, "today": today, "window": PV_DAYS, "errors": errs[:10], "updated": time.time(), "timing": tm,
            "totals": {"placing": sum(1 for r in rows if r["status"] == "placing"), "today_rub": round(sum(r["today"] for r in rows), 2),
                       "size_rub": round(sum(r["size_rub"] or 0 for r in rows), 2)}}


def _pv_run():
    try:
        res = pv_compute()
        with _pv_lock:
            _pv.update(res=res, t=time.time(), err=None)
    except Exception as e:  # noqa: BLE001
        _pv["err"] = str(e)[:200]
    finally:
        _pv.update(running=False, phase="")


def primary_volumes_payload(force=False):
    with _pv_lock:
        fresh = _pv["res"] is not None and time.time() - _pv["t"] < pv_ttl() and not force
        if not fresh and not _pv["running"]:
            _pv["running"] = True
            threading.Thread(target=_pv_run, daemon=True).start()
        res = _pv["res"]
        running, phase, err = _pv["running"], _pv["phase"], _pv["err"]
    if res is None:
        return {"rows": [], "loading": running, "phase": phase, "error": None if running else (err or "нет данных"), "errors": []}
    return dict(res, loading=running, phase=phase, stale_error=err)


# ── по дням: история торгов выпуска по всем площадкам ──

def pv_days_merge(rows, live_rows, today):
    """Записи истории + сегодняшняя marketdata -> [{d, q, v, n, price, yield, place_v, sec_v, boards:[{b,label,q,v,n}]}] по возрастанию даты."""
    days = {}
    for r in rows:
        d = days.setdefault(r["d"], {"d": r["d"], "q": 0.0, "v": 0.0, "n": 0, "place_v": 0.0, "sec_v": 0.0, "px": None, "y": None, "_pv": -1, "boards": {}})
        d["q"] += r["q"]
        d["v"] += r["v"]
        d["n"] += r["n"]
        if r["b"] in PV_PLACE:
            d["place_v"] += r["v"]
        else:
            d["sec_v"] += r["v"]
        b = d["boards"].setdefault(r["b"], {"b": r["b"], "label": PV_BOARD_NAMES.get(r["b"], r["b"]), "place": r["b"] in PV_PLACE, "q": 0.0, "v": 0.0, "n": 0})
        b["q"] += r["q"]
        b["v"] += r["v"]
        b["n"] += r["n"]
        px = r.get("w") or r.get("c")
        if px and r["v"] > d["_pv"]:
            d["_pv"], d["px"] = r["v"], px
            d["y"] = r.get("y")
        elif d["y"] is None and r.get("y"):
            d["y"] = r["y"]
    for m in live_rows or []:
        if not ((m.get("today") or 0) or (m.get("vol") or 0) or (m.get("n") or 0)):
            continue
        d = days.setdefault(today, {"d": today, "q": 0.0, "v": 0.0, "n": 0, "place_v": 0.0, "sec_v": 0.0, "px": None, "y": None, "_pv": -1, "boards": {}, "live": True})
        d["live"] = True
        d["q"] += m.get("vol") or 0
        d["v"] += m.get("today") or 0
        d["n"] += m.get("n") or 0
        if m["b"] in PV_PLACE:
            d["place_v"] += m.get("today") or 0
        else:
            d["sec_v"] += m.get("today") or 0
        b = d["boards"].setdefault(m["b"], {"b": m["b"], "label": PV_BOARD_NAMES.get(m["b"], m["b"]), "place": m["b"] in PV_PLACE, "q": 0.0, "v": 0.0, "n": 0})
        b["q"] += m.get("vol") or 0
        b["v"] += m.get("today") or 0
        b["n"] += m.get("n") or 0
        px = m.get("wap") or m.get("last")
        if px and (m.get("today") or 0) > d["_pv"]:
            d["_pv"], d["px"] = m.get("today") or 0, px
            d["y"] = m.get("yield") or d["y"]
    out = []
    for k in sorted(days):
        d = days[k]
        d.pop("_pv", None)
        d["boards"] = sorted(d["boards"].values(), key=lambda x: -x["v"])
        for f in ("v", "place_v", "sec_v"):
            d[f] = round(d[f], 2)
        out.append(d)
    return out


def pv_secid_days(secid):
    """История торгов выпуска за всё время (обе рынка: ndm — размещение и РПС, bonds — вторичка) + сегодня."""
    k = "pvd:" + secid
    c = _pv_mem.get(k)
    if c and time.time() - c[0] < pv_ttl():
        return c[1]
    desc = pv_desc(secid)
    frm = desc.get("issued") or desc.get("start") or _day_add(pv_msk_now().date().isoformat(), -PV_DAYS)
    today = pv_msk_now().date().isoformat()
    errs, rows, live = [], [], []
    for mk in ("ndm", "bonds"):
        try:
            rows += pv_sec_hist(mk, secid, frm, today)
        except Exception as ex:  # noqa: BLE001
            errs.append("%s: %s" % (mk, str(ex)[:100]))
        try:
            j = pv_json(PV_ISS + "engines/stock/markets/%s/securities/%s.json?iss.meta=off&iss.only=securities,marketdata&securities.columns=%s"
                        "&marketdata.columns=%s" % (mk, secid, _PV_LS, _PV_LM), 25)
            live += pv_live_parse(j).get(secid) or []
        except Exception as ex:  # noqa: BLE001
            errs.append("сегодня %s: %s" % (mk, str(ex)[:100]))
    rows = [r for r in rows if r["d"] != today]            # сегодняшний день берём из marketdata (в истории он появляется вечером)
    days = pv_days_merge(rows, live, today)
    face = desc.get("face") or desc.get("face0") or 1000.0
    res = {"secid": secid, "name": desc.get("name"), "face": face, "size_pcs": desc.get("size"), "days": days, "errors": errs, "today": today,
           "total": {"q": sum(d["q"] for d in days), "v": round(sum(d["v"] for d in days), 2), "n": sum(d["n"] for d in days),
                     "place_v": round(sum(d["place_v"] for d in days), 2)}}
    if not errs:
        _pv_mem[k] = (time.time(), res)
    return res


def _api_primary_vol(cfg, acc, q, force):
    return primary_volumes_payload(force)


def _api_primary_days(cfg, acc, q, force):
    secid = (q.get("secid") or "").strip().upper()
    if not re.match(r"^[A-Z0-9]{4,20}$", secid):
        raise ApiError("Неверный код выпуска.", 400)
    return pv_secid_days(secid)


API_GET["/api/primary/volumes"] = _api_primary_vol
API_GET["/api/primary/days"] = _api_primary_days
# ═══════════════════ ссылки на документы выпуска (без обращения к сети) ═══════════════════


def bond_doc_links(isin, secid=None, inn=None):
    """Ссылки на раскрытие информации по выпуску. e-disclosure.ru закрыт для ботов, поэтому строим только ссылку
    на поиск по ИНН эмитента (без ИНН — по ISIN); страница выпуска на Мосбирже открывается по коду бумаги."""
    isin = (isin or "").strip().upper()
    secid = (secid or isin or "").strip().upper()
    inn = re.sub(r"\D", "", str(inn or ""))
    inn = inn if len(inn) in (10, 12) else ""
    q = inn or isin
    return {"inn": inn or None,
            # СКРИН открывает страницу раскрытия эмитента прямо по ИНН; поиск e-disclosure по ссылке не заполняется (страница на JS)
            "skrin": "https://disclosure.skrin.ru/disclosure/" + inn if inn else None,
            "edisclosure": "https://www.e-disclosure.ru/poisk-po-kompaniyam?query=" + urllib.parse.quote(q) if q else None,
            "moex": "https://www.moex.com/ru/issue.aspx?code=" + urllib.parse.quote(secid) if secid else None}
# ═══════════════════ карточка облигации: описание, история, денежный поток, аналоги ═══════════════════

_bc_univ = {"t": 0, "rows": []}
_bc_lock = threading.Lock()
BC_DESC = ("ISSUENAME", "ISSUEDATE", "MATDATE", "ISSUESIZE", "FACEVALUE", "INITIALFACEVALUE", "COUPONFREQUENCY",
           "COUPONPERCENT", "COUPONVALUE", "COUPONDATE", "BOND_TYPE", "BOND_SUBTYPE", "FACEVALUE_TYPE", "LISTLEVEL",
           "ISQUALIFIEDINVESTORS", "ISSUESIZEPLACED", "HASDEFAULT", "HASTECHNICALDEFAULT", "REGNUMBER", "TYPENAME", "EMITTER_ID")


def _bc_json(url, timeout=25):
    return json.loads(http_text(url, timeout=timeout))


def _bc_desc(isin):
    j = _bc_json("https://iss.moex.com/iss/securities/%s.json?iss.meta=off&iss.only=description" % isin)
    d = {r[0]: r[2] for r in j["description"]["data"]}
    out = {k: d[k] for k in BC_DESC if d.get(k) not in (None, "")}
    eid = d.get("EMITTER_ID")
    if eid:
        try:
            e = _bc_json("https://iss.moex.com/iss/emitters/%s.json?iss.meta=off&iss.only=emitter" % eid, timeout=15)
            row = dict(zip(e["emitter"]["columns"], (e["emitter"]["data"] or [[]])[0]))
            out["EMITTER"] = row.get("TITLE") or row.get("title")
            out["EMITTER_INN"] = row.get("INN") or row.get("inn")
        except Exception:  # noqa: BLE001
            pass
    return out


def _bc_history(secid):
    key = "bondhist_v1_" + secid
    hit = store().get(key, ttl=6 * 3600)
    if hit:
        return hit
    frm = (date.today() - timedelta(days=370)).isoformat()
    rows, start = [], 0
    while start < 1500:
        j = _bc_json("https://iss.moex.com/iss/history/engines/stock/markets/bonds/securities/%s.json?iss.meta=off"
                     "&history.columns=BOARDID,TRADEDATE,CLOSE,LEGALCLOSEPRICE,WAPRICE,YIELDCLOSE,YIELDATWAP,VALUE"
                     "&from=%s&start=%d" % (secid, frm, start))
        part = _iss_table(j, "history")
        rows += part
        if len(part) < 100:
            break
        start += 100
    boards = defaultdict(int)
    for r in rows:
        boards[r["BOARDID"]] += 1
    main = next((b for b in ("TQCB", "TQOB") if boards.get(b)), max(boards, key=boards.get) if boards else None)
    out = {"d": [], "p": [], "y": [], "v": []}
    for r in sorted((r for r in rows if r["BOARDID"] == main), key=lambda r: r["TRADEDATE"]):
        p = r.get("LEGALCLOSEPRICE") or r.get("CLOSE") or r.get("WAPRICE")
        y = r.get("YIELDCLOSE") or r.get("YIELDATWAP")
        if p is None:
            continue
        out["d"].append(r["TRADEDATE"])
        out["p"].append(round(p, 3))
        out["y"].append(round(y, 2) if y else None)
        out["v"].append(round(r.get("VALUE") or 0))
    if out["d"]:
        store().put(key, out)
    return out


def _bc_norm_table(t):
    if isinstance(t, dict) and "columns" in t:
        return [dict(zip(t["columns"], r)) for r in t["data"]]
    return [x for x in (t or []) if isinstance(x, dict)]


def _bc_flows(isin):
    j = None
    fn = globals().get("moex_bondization")
    if callable(fn):
        try:
            j = fn(isin)
        except Exception:  # noqa: BLE001
            j = None
    if not isinstance(j, dict) or not any(k in j for k in ("coupons", "amort", "amortizations", "offers")):
        j = _bc_json("https://iss.moex.com/iss/securities/%s/bondization.json?iss.meta=off&limit=unlimited"
                     "&iss.only=coupons,amortizations,offers" % isin, timeout=30)
    today = date.today().isoformat()
    ev = []
    for c in _bc_norm_table(j.get("coupons")):
        d = c.get("coupondate")
        if d and d >= today:
            ev.append({"d": d, "t": "coupon", "amt": c.get("value_rub") if c.get("value_rub") is not None else c.get("value"),
                       "pct": c.get("valueprc")})
    # moex_bondization отдаёт график под ключом "amort" (ISS — "amortizations"); последняя строка графика — погашение
    am = [a for a in _bc_norm_table(j.get("amort") if j.get("amort") is not None else j.get("amortizations")) if a.get("amortdate")]
    last = max((a["amortdate"] for a in am), default=None)
    for a in am:
        d = a["amortdate"]
        if d >= today:
            ev.append({"d": d, "t": "redemption" if d == last else "amort",
                       "amt": a.get("value_rub") if a.get("value_rub") is not None else a.get("value"),
                       "pct": a.get("valueprc")})
    for o in _bc_norm_table(j.get("offers")):
        d = o.get("offerdate")
        if d and d >= today:
            ev.append({"d": d, "t": "offer", "amt": o.get("value"), "pct": o.get("price")})
    ev.sort(key=lambda e: e["d"])
    return ev


def _bc_mark_est(flows, isin, floating, face):
    """Купоны флоатера без объявленной ставки: подставляем прогноз (ключевая ставка + спред), помечаем est/base/spread."""
    if not floating or not face or not any(e["t"] == "coupon" and e.get("amt") is None for e in flows):
        return False
    bz = moex_bondization(isin)
    est = fl_estimates(bz, date.today().isoformat(), float(face)) if bz else {}
    done = False
    for e in flows:
        x = est.get(e["d"]) if e["t"] == "coupon" and e.get("amt") is None else None
        if x:
            e.update(amt=x["amt"], pct=x["rate"], est=True, base=round(x["base"], 2), spread=round(x["spread"], 2))
            done = True
    return done


def _bc_issuer_key(r):
    t = name_tokens(_bond_query(r.get("full") or r.get("name") or ""))
    return t


def _bc_universe():
    """screener_rows + рейтинг и данные каталога; кэш 10 минут."""
    if time.time() - _bc_univ["t"] < 600 and _bc_univ["rows"]:
        return _bc_univ["rows"]
    with _bc_lock:
        if time.time() - _bc_univ["t"] < 600 and _bc_univ["rows"]:
            return _bc_univ["rows"]
        src = screener_rows()
        out = []
        for r in src:
            e = dict(r)
            e["_isin"] = r.get("isin") or r["id"]
            e["_ci"] = tcat_info(e["_isin"])
            rt = best_rating(e["_isin"], (e["_ci"] or {}).get("name") or r.get("name") or "")
            e["_rt"] = rt
            e["_iss"] = _bc_issuer_key(r)
            out.append(e)
        _bc_univ.update(t=time.time(), rows=out)
        return out


def _bc_lite(e, base_y):
    rt, ci = e["_rt"], e["_ci"] or {}
    return {"isin": e["_isin"], "id": e["id"], "name": e["name"], "yield": e["yield"], "spread": e.get("spread"),
            "dur": e.get("dur"), "rating": rt["v"] if rt else None, "rating_approx": bool(rt and rt["approx"]),
            "sector": ci.get("sector"), "floating": bool(ci.get("floating")), "amort": bool(ci.get("amort")),
            "turn": e.get("turn"), "price": e.get("price"), "mat": e.get("mat"),
            "dy": round(e["yield"] - base_y, 2) if base_y is not None else None}


def _bc_cost(me, e, ri):
    """Расстояние между выпусками для подбора аналогов (меньше = ближе); None, если не аналог. ri: индекс рейтинга me или None."""
    if e["cur"] != "RUB" or not (0 < e["yield"] < 60) or not e.get("dur") or e["dur"] < 0.1:
        return None
    if e["kind"] != me["kind"]:
        return None
    if me["kind"] == "corp" and me["_iss"] and e["_iss"] and (e["_iss"] == me["_iss"]):
        return None
    ert = e["_rt"]
    d = 0.0
    if ri is not None:
        if not ert:
            return None
        n = abs(RATING_SCALE.index(ert["v"]) - ri)
        if n > 2:
            return None
        d += n * 1.0
    elif ert and me["kind"] == "corp":
        d += 0.5
    ci, eci = me["_ci"] or {}, e["_ci"] or {}
    sec, dur = ci.get("sector"), me.get("dur")
    if sec and eci.get("sector") and sec != eci["sector"]:
        d += 0.7
    if dur:
        rel = abs(e["dur"] - dur) / max(dur, e["dur"], 0.5)
        if rel > 0.6:
            return None
        d += rel * 3
    if bool(eci.get("floating")) != bool(ci.get("floating")):
        d += 1.5
    if bool(eci.get("amort")) != bool(ci.get("amort")):
        d += 0.5
    d -= min(1.0, len(str(int(e.get("turn") or 0))) / 9.0) * 0.6
    return d


def _bc_analogs(me, isin):
    """me: запись из _bc_universe (или None). Возвращает (список аналогов, относительная оценка)."""
    uni = _bc_universe()
    if not me:
        return [], None
    rt = me["_rt"]
    ri = RATING_SCALE.index(rt["v"]) if rt else None
    scored = []
    for e in uni:
        if e["_isin"] == isin:
            continue
        d = _bc_cost(me, e, ri)
        if d is not None:
            scored.append((d, e))
    scored.sort(key=lambda x: x[0])
    sps = sorted(e["spread"] for _, e in scored[:30] if e.get("spread") is not None)
    if len(sps) >= 5:      # отсекаем выбросы (дефолтные выпуски, линкеры) относительно медианы ближайших кандидатов
        m0 = sps[len(sps) // 2]
        scored = [x for x in scored if x[1].get("spread") is None or abs(x[1]["spread"] - m0) <= 8]
    top = [_bc_lite(e, me["yield"]) for _, e in scored[:12]]
    rel = None
    sp = [a["spread"] for a in top if a["spread"] is not None]
    if me.get("spread") is not None and len(sp) >= 3:
        sp.sort()
        med = sp[len(sp) // 2] if len(sp) % 2 else (sp[len(sp) // 2 - 1] + sp[len(sp) // 2]) / 2
        diff = round(me["spread"] - med, 2)
        c2 = lambda x: ("%.2f" % x).replace(".", ",")      # noqa: E731
        txt = ("Доходность в пределах разброса аналогов (спред к КБД %s п.п. против медианы %s п.п.)"
               % (c2(me["spread"]), c2(med))) if abs(diff) < 0.25 else \
            ("Облигация %s аналогов: спред к КБД на %s п.п. %s медианы по %d похожим выпускам" %
             ("дешевле" if diff > 0 else "дороже", c2(abs(diff)), "выше" if diff > 0 else "ниже", len(sp)))
        rel = {"median_spread": round(med, 2), "diff": diff, "n": len(sp), "text": txt}
    return top, rel


def _bc_issuer_curve(me):
    """Все торгуемые выпуски того же эмитента (по ключу названия): дюрация -> доходность, плюс КБД для ориентира."""
    key = me.get("_iss")
    pts = []
    if key and me["kind"] == "corp":
        for e in _bc_universe():
            if e["_iss"] == key and e["cur"] == "RUB" and e.get("dur") and e["yield"] > 0:
                rt = e["_rt"]
                pts.append({"isin": e["_isin"], "name": e["name"], "dur": e["dur"], "yield": e["yield"], "spread": e.get("spread"),
                            "rating": rt["v"] if rt else None, "turn": e.get("turn"), "me": e["_isin"] == me["_isin"],
                            "floating": bool((e["_ci"] or {}).get("floating"))})
    if len(pts) < 2:
        return None
    pts.sort(key=lambda p: p["dur"])
    lo, hi = max(0.0, pts[0]["dur"] - 0.3), pts[-1]["dur"] + 0.5
    kbd = []
    for i in range(13):
        x = lo + (hi - lo) * i / 12
        k = kbd_at(x)
        if k is not None:
            kbd.append([round(x, 2), round(k, 2)])
    return {"points": pts, "kbd": kbd}


def bond_card(isin):
    isin = (isin or "").strip().upper()
    errors = []
    card = {"isin": isin, "found": False, "errors": errors}
    if not re.fullmatch(r"[A-Z0-9]{6,14}", isin):
        errors.append("некорректный ISIN")
        return card
    me = None
    try:
        uni = _bc_universe()
        me = next((e for e in uni if e["_isin"] == isin or e["id"] == isin), None)
    except Exception as e:  # noqa: BLE001
        errors.append("рынок: %s" % str(e)[:120])
        uni = []
    if me:
        isin = me["_isin"]
        card["isin"] = isin
    secid = me["id"] if me else isin

    def run(fn):
        try:
            return fn(), None
        except Exception as e:  # noqa: BLE001
            return None, str(e)[:120]
    (desc, e1), (hist, e2), (flows, e3) = pool_map(
        run, [lambda: _bc_desc(isin), lambda: _bc_history(secid), lambda: _bc_flows(isin)], workers=3)
    for lab, er in (("описание", e1), ("история", e2), ("денежный поток", e3)):
        if er:
            errors.append("%s: %s" % (lab, er))
    ci = tcat_info(isin)
    card["catalog"] = ci
    card["desc"] = desc or {}
    card["history"] = hist or {"d": [], "p": [], "y": [], "v": []}
    card["flows"] = flows or []
    try:
        card["offers"] = [o for o in offers_of_isin(isin) if o["status"] != "cancelled"]
        for e in card["flows"]:
            if e["t"] == "offer":
                e["kind"] = offer_kind_on(card["offers"], e["d"])
    except Exception as e:  # noqa: BLE001
        card["offers"] = []
        errors.append("оферты: %s" % str(e)[:120])
    try:
        face = (desc or {}).get("FACEVALUE") or (me or {}).get("nominal")
        if _bc_mark_est(card["flows"], isin, bool((ci or {}).get("floating")), float(face) if face else 0.0):
            info = keyrate_forecast_info()
            card["keyrate"] = {"source": info["source"], "name": info["source_name"], "as_of": info["as_of"]}
    except Exception as e:  # noqa: BLE001
        errors.append("прогноз купонов: %s" % str(e)[:120])
    try:        # «КС + x %» для флоатера: из кэша спредов, иначе считаем по графику выплат (он уже в кэше после _bc_mark_est)
        if (ci or {}).get("floating"):
            fsp = fl_spread_cached([isin]).get(isin)
            if fsp is None:
                face2 = (desc or {}).get("FACEVALUE") or (me or {}).get("nominal")
                fsp = fl_spread_put(isin, (me or {}).get("full") or (desc or {}).get("ISSUENAME") or card.get("name"),
                                    moex_bondization(isin), float(face2) if face2 else None, (me or {}).get("kind"))
            card["fl_spread"] = fsp
            card["fl_label"] = fl_label(fsp, True)
    except Exception as e:  # noqa: BLE001
        errors.append("спред флоатера: %s" % str(e)[:120])
    try:
        rt = (me["_rt"] if me else None) or best_rating(isin, (desc or {}).get("ISSUENAME") or (ci or {}).get("name") or "")
    except Exception as e:  # noqa: BLE001
        rt = None
        errors.append("рейтинг: %s" % str(e)[:120])
    card["rating"] = rt
    if me:
        card["found"] = True
        card["market"] = {k: me.get(k) for k in ("id", "isin", "name", "full", "kind", "cur", "nominal", "price", "yield",
                                                 "dur", "coupon", "next", "mat", "offer", "level", "turn", "trades",
                                                 "zs", "spread", "size", "nkd")}
        k = kbd_at(me["dur"]) if me.get("dur") else None
        card["kbd"] = round(k, 2) if k is not None else None
        try:
            card["analogs"], card["rel"] = _bc_analogs(me, isin)
        except Exception as e:  # noqa: BLE001
            card["analogs"], card["rel"] = [], None
            errors.append("аналоги: %s" % str(e)[:120])
        try:
            card["issuer_curve"] = _bc_issuer_curve(me)
        except Exception as e:  # noqa: BLE001
            card["issuer_curve"] = None
            errors.append("кривая эмитента: %s" % str(e)[:120])
    else:
        card["market"] = None
        card["analogs"], card["rel"] = [], None
        card["issuer_curve"] = None
        if not errors:
            errors.append("нет торгов на основных режимах Мосбиржи — показаны только справочные данные")
    try:
        card["disclosure"] = disclosure_for_bond(isin, desc=desc)
    except Exception as e:  # noqa: BLE001
        card["disclosure"] = None
        errors.append("раскрытие: %s" % str(e)[:120])
    card["docs"] = bond_doc_links(isin, (me or {}).get("id") or isin, (desc or {}).get("EMITTER_INN"))
    card["name"] = (me or {}).get("full") or (desc or {}).get("ISSUENAME") or (ci or {}).get("name") or isin
    card["short"] = (me or {}).get("name") or (ci or {}).get("name") or isin
    return card
# ═══════════════════════════════ прогноз ключевой ставки ═══════════════════════════════
# Нужен для флоатеров: будущие купоны = прогноз ключевой ставки + спред эмитента (см. bond_flows в 08a_bondcalc.py).
# Источники по убыванию приоритета (первый сработавший):
#   cbr    — «Среднесрочный прогноз Банка России» (PDF на cbr.ru, строка «Ключевая ставка, в среднем за год»; диапазон -> середина);
#   survey — макроэкономический опрос Банка России (HTML-таблица, медиана «Ключевая ставка ... в среднем за год»);
#   market — форвардные ставки КБД Мосбиржи (приближение, см. _kr_market_path);
#   flat   — текущая ключевая ставка без изменений.

KR_TTL, KR_ERR_TTL = 24 * 3600, 3600
KR_MODES = ("cbr", "survey", "market", "flat")
KR_NAMES = {"cbr": "Среднесрочный прогноз Банка России", "survey": "Макроопрос аналитиков (Банк России)",
            "market": "Рыночные ожидания (форварды КБД)", "flat": "Ключевая ставка без изменений"}
KR_HORIZON_M = 48
_kr_mem = {}
_kr_lock = threading.Lock()


# ── минимальный разбор PDF (stdlib): Flate-потоки, ToUnicode, операторы Tf/Tm/Td/TJ ──

def _pdf_inflate(body):
    head, _, rest = body.partition(b"stream")
    if not rest:
        return b""
    rest = rest[1:] if rest[:1] == b"\n" else (rest[2:] if rest[:2] == b"\r\n" else rest[1:] if rest[:1] == b"\r" else rest)
    rest = rest[:rest.rfind(b"endstream")] if b"endstream" in rest else rest
    if b"FlateDecode" in head:
        return zlib.decompressobj().decompress(rest)
    return rest


def _pdf_objects(d):
    objs = {}
    for m in re.finditer(rb"(?<![0-9])(\d+) 0 obj(.*?)endobj", d, re.S):
        objs[int(m.group(1))] = m.group(2)
    for body in list(objs.values()):
        head = body.partition(b"stream")[0]
        if b"/ObjStm" not in head:
            continue
        n = int(re.search(rb"/N\s+(\d+)", head).group(1))
        first = int(re.search(rb"/First\s+(\d+)", head).group(1))
        data = _pdf_inflate(body)
        nums = [int(x) for x in re.findall(rb"\d+", data[:first])]
        pairs = list(zip(nums[0:2 * n:2], nums[1:2 * n:2]))
        for i, (num, off) in enumerate(pairs):
            end = pairs[i + 1][1] if i + 1 < len(pairs) else len(data) - first
            objs.setdefault(num, data[first + off:first + end])
    return objs


def _pdf_cmap(data):
    s = data.decode("latin-1")
    m = re.search(r"begincodespacerange\s*<([0-9A-Fa-f]+)>", s)
    width = len(m.group(1)) // 2 if m else 1
    mp = {}

    def u(h):
        return bytes.fromhex(h).decode("utf-16-be", "replace")
    for blk in re.findall(r"beginbfchar(.*?)endbfchar", s, re.S):
        for a, b in re.findall(r"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", blk):
            mp[int(a, 16)] = u(b)
    for blk in re.findall(r"beginbfrange(.*?)endbfrange", s, re.S):
        for a, b, c in re.findall(r"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*(<[0-9A-Fa-f]+>|\[[^\]]*\])", blk):
            lo, hi = int(a, 16), int(b, 16)
            if c.startswith("["):
                for i, h in enumerate(re.findall(r"<([0-9A-Fa-f]+)>", c)):
                    mp[lo + i] = u(h)
            else:
                base = int(c[1:-1], 16)
                nb = len(c) - 2
                for i in range(hi - lo + 1):
                    mp[lo + i] = u(("%0" + str(nb) + "x") % (base + i))
    return width, mp


def _pdf_tokens(s):
    i, n = 0, len(s)
    out = []
    ws = b" \t\r\n\x00\x0c"
    delim = b"()<>[]/%"
    while i < n:
        c = s[i:i + 1]
        if c in ws:
            i += 1
        elif c == b"%":
            while i < n and s[i:i + 1] not in b"\r\n":
                i += 1
        elif c == b"(":
            depth, j, buf = 1, i + 1, bytearray()
            while j < n and depth:
                ch = s[j:j + 1]
                if ch == b"\\":
                    nx = s[j + 1:j + 2]
                    if nx in b"01234567" and nx:
                        k = j + 1
                        while k < j + 4 and s[k:k + 1] and s[k:k + 1] in b"01234567":
                            k += 1
                        buf.append(int(s[j + 1:k], 8) & 255)
                        j = k
                        continue
                    buf += {b"n": b"\n", b"r": b"\r", b"t": b"\t", b"b": b"\b", b"f": b"\x0c"}.get(nx, nx)
                    j += 2
                    continue
                if ch == b"(":
                    depth += 1
                elif ch == b")":
                    depth -= 1
                    if not depth:
                        j += 1
                        break
                buf += ch
                j += 1
            out.append(("s", bytes(buf)))
            i = j
        elif c == b"<":
            if s[i + 1:i + 2] == b"<":
                out.append(("op", "<<"))
                i += 2
            else:
                j = s.index(b">", i)
                h = re.sub(rb"\s", b"", s[i + 1:j])
                if len(h) % 2:
                    h += b"0"
                out.append(("s", bytes.fromhex(h.decode())))
                i = j + 1
        elif c == b">":
            out.append(("op", ">>"))
            i += 2 if s[i + 1:i + 2] == b">" else 1
        elif c in b"[]":
            out.append(("op", c.decode()))
            i += 1
        elif c == b"/":
            j = i + 1
            while j < n and s[j:j + 1] not in ws and s[j:j + 1] not in delim:
                j += 1
            out.append(("n", s[i + 1:j].decode("latin-1")))
            i = j
        else:
            j = i
            while j < n and s[j:j + 1] not in ws and s[j:j + 1] not in delim:
                j += 1
            t = s[i:j].decode("latin-1")
            try:
                out.append(("num", float(t)))
            except ValueError:
                out.append(("op", t))
            i = max(j, i + 1)
    return out


def pdf_text_fragments(d):
    """[(x, y, size, text)] из PDF (stdlib: Flate + ToUnicode). Для простых однотипных документов ЦБ."""
    objs = _pdf_objects(d)
    fonts = {}
    for body in objs.values():
        head = body.partition(b"stream")[0]
        for m in re.finditer(rb"/Font\s*(?:<<(.*?)>>|(\d+)\s+0\s+R)", head, re.S):
            blk = m.group(1) if m.group(1) is not None else objs.get(int(m.group(2)), b"")
            for nm, num in re.findall(rb"/([A-Za-z0-9_.+-]+)\s+(\d+)\s+0\s+R", blk):
                fb = objs.get(int(num), b"")
                tu = re.search(rb"/ToUnicode\s+(\d+)\s+0\s+R", fb)
                if tu and nm.decode() not in fonts:
                    fonts[nm.decode()] = _pdf_cmap(_pdf_inflate(objs.get(int(tu.group(1)), b"")))
    frags = []
    for body in objs.values():
        head = body.partition(b"stream")[0]
        if b"/Length" not in head or b"/Type" in head and (b"/XObject" in head or b"/ObjStm" in head or b"/XRef" in head):
            continue
        try:
            data = _pdf_inflate(body)
        except Exception:
            continue
        if b"BT" not in data or b" Tf" not in data:
            continue
        stack, font, size = [], None, 10.0
        lm = [0.0, 0.0]
        for kind, v in _pdf_tokens(data):
            if kind != "op" or v in ("[", "]", "<<", ">>"):
                stack.append((kind, v))
                continue
            args = stack
            stack = []
            if v == "Tf":
                nm = [a for a in args if a[0] == "n"]
                nu = [a[1] for a in args if a[0] == "num"]
                font = nm[-1][1] if nm else font
                size = nu[-1] if nu else size
            elif v == "Tm":
                nu = [a[1] for a in args if a[0] == "num"]
                if len(nu) >= 6:
                    lm = [nu[4], nu[5]]
            elif v in ("Td", "TD"):
                nu = [a[1] for a in args if a[0] == "num"]
                if len(nu) >= 2:
                    lm = [lm[0] + nu[-2], lm[1] + nu[-1]]
            elif v in ("TJ", "Tj", "'", '"'):
                width, mp = fonts.get(font, (1, None))
                txt = ""
                for k, a in args:
                    if k != "s":
                        continue
                    if mp is None:
                        txt += a.decode("cp1252", "replace")
                    else:
                        w = width if len(a) % width == 0 else 1
                        for p in range(0, len(a), w):
                            txt += mp.get(int.from_bytes(a[p:p + w], "big"), "")
                if txt:
                    frags.append((lm[0], lm[1], size, txt))
    return frags


# ── источник 1: среднесрочный прогноз Банка России (PDF) ──

KR_CBR_PAGE = "https://www.cbr.ru/dkp/mp_dec/decision_key_rate/"


def _kr_num(s):
    return float(s.replace(",", "."))


def _kr_cells(txt):
    """'19,2 14,6 12,5–13,5 9,0–10,0' -> [(low, high)]. Одиночное значение с двумя знаками (14,61) — сноска, отбрасываем её."""
    toks = re.findall(r"(\d+(?:,\d+)?)(?:\s*[–-]\s*(\d+(?:,\d+)?))?", txt)
    cells = []
    for a, b in toks:
        if not b and re.fullmatch(r"\d+,\d\d", a):
            a = a[:-1]
        cells.append((_kr_num(a), _kr_num(b or a)))
    return cells


def _kr_parse_pdf(data, label="Ключевая ставка", tail=r"годовых(.*)$", need=""):
    """Строка таблицы основных параметров прогноза -> {год: (low, high)}.
    По умолчанию «Ключевая ставка, в среднем за год»; для инфляции — label «Инфляция», need «декабрь», tail r"года(.*)$"."""
    fr = pdf_text_fragments(data)
    big = [f for f in fr if f[2] >= 8]          # мелкий шрифт — сноски и надстрочные индексы

    def row(y, tol=2.5):
        rs = sorted((f for f in big if abs(f[1] - y) <= tol), key=lambda f: f[0])
        return "".join(f[3] for f in rs)
    lab = [f for f in big if f[3].startswith(label) and need in row(f[1])]
    first = [f for f in big if f[3].startswith("Инфляция")]
    if not lab or not first:
        raise ValueError("нет строки таблицы")
    y0 = max(f[1] for f in first)
    m = re.search(tail, row(lab[0][1]))
    cells = _kr_cells(m.group(1) if m else "")
    hdr = "".join(f[3] for f in sorted((f for f in big if y0 + 3 < f[1] < y0 + 45 and f[0] > 150), key=lambda f: (f[0], -f[1])))
    years = sorted({int(y) for y in re.findall(r"20\d\d", hdr)})
    if len(years) != len(cells) or not years:
        raise ValueError("не сошлись годы (%d) и значения (%d)" % (len(years), len(cells)))
    return {y: c for y, c in zip(years, cells)}


def _kr_cbr():
    s = http_text(KR_CBR_PAGE, 30)
    links = re.findall(r'href="(/Content/Document/File/\d+/forecast_(\d\d)(\d\d)(\d\d)\.pdf)"', s)
    if not links:
        raise ValueError("нет ссылки на прогноз")
    path, yy, mm, dd = max(links, key=lambda x: x[1:])
    as_of = "20%s-%s-%s" % (yy, mm, dd)
    st = store()
    ck = "kr_pdf:" + path
    pt = st.get(ck)
    if pt is None:
        yr = _kr_parse_pdf(http_bytes("https://www.cbr.ru" + path, 40))
        pt = {str(k): list(v) for k, v in yr.items()}
        st.put(ck, pt)                     # PDF конкретного заседания не меняется
    years = {int(k): tuple(v) for k, v in pt.items()}
    # в таблице первым идёт последний фактический год: он не прогноз
    return {"as_of": as_of, "url": "https://www.cbr.ru" + path, "years": years}


def inflation_forecast():
    """Прогноз инфляции (декабрь к декабрю) из того же среднесрочного прогноза Банка России.
    {source: 'cbr'|'none', as_of, url, yearly:[{year, low, high, mid}]} — только текущий и будущие годы.
    Кэш 24 часа; при ошибке — source 'none' и пустой yearly (вызывающий код берёт свою оценку, например 4%)."""
    st = store()
    raw = st.get("infl_src", ttl=KR_TTL)
    if raw is None:
        try:
            s = http_text(KR_CBR_PAGE, 30)
            links = re.findall(r'href="(/Content/Document/File/\d+/forecast_(\d\d)(\d\d)(\d\d)\.pdf)"', s)
            if not links:
                raise ValueError("нет ссылки на прогноз")
            path, yy, mm, dd = max(links, key=lambda x: x[1:])
            yr = _kr_parse_pdf(http_bytes("https://www.cbr.ru" + path, 40), "Инфляция", r"года(.*)$", "декабрь")
            raw = {"source": "cbr", "as_of": "20%s-%s-%s" % (yy, mm, dd), "url": "https://www.cbr.ru" + path,
                   "years": {str(k): list(v) for k, v in yr.items()}}
            st.put("infl_src", raw)
        except Exception as e:  # noqa: BLE001
            return {"source": "none", "as_of": "", "url": "", "yearly": [], "error": str(e)[:140]}
    y0 = date.today().year
    yearly = [{"year": int(k), "low": v[0], "high": v[1], "mid": round((v[0] + v[1]) / 2.0, 2)}
              for k, v in sorted(raw["years"].items()) if int(k) >= y0]
    return {"source": raw["source"], "as_of": raw["as_of"], "url": raw["url"], "yearly": yearly}


# ── источник 2: макроопрос Банка России (HTML-таблица) ──

KR_SURVEY_PAGE = "https://cbr.ru/statistics/ddkp/mo_br/"
_MONTHS_RU = ["январ", "феврал", "март", "апрел", "ма", "июн", "июл", "август", "сентябр", "октябр", "ноябр", "декабр"]


def _kr_survey():
    s = http_text(KR_SURVEY_PAGE, 30)
    i = s.find("Ключевая ставка")
    j = s.rfind("<table", 0, i)
    k = s.find("</table>", i)
    if i < 0 or j < 0 or k < 0:
        raise ValueError("нет таблицы опроса")
    rows = []
    for r in re.findall(r"<tr.*?</tr>", s[j:k], re.S):
        rows.append([re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", c)).replace("&nbsp;", " ").strip()
                     for c in re.findall(r"<t[dh][^>]*>(.*?)</t[dh]>", r, re.S)])
    hdr = next(r for r in rows if sum(bool(re.match(r"20\d\d", c)) for c in r) >= 3)
    kr = next(r for r in rows if r and r[0].startswith("Ключевая ставка"))
    years = {}
    for h, v in zip(hdr, kr):
        m, y = re.match(r"(20\d\d)", h), re.match(r"\s*(\d+,\d+|\d+)", v)
        if m and y and "факт" not in h:
            years[int(m.group(1))] = (_kr_num(y.group(1)),) * 2        # медиана; в скобках — прошлый опрос
    if not years:
        raise ValueError("нет прогнозных значений")
    plain = re.sub(r"<[^>]+>", " ", s)
    m = re.search(r"Результаты опроса:\s*([А-Яа-я]+)\s+(20\d\d)", plain)
    as_of = ""
    if m:
        mo = next((n + 1 for n, p in enumerate(_MONTHS_RU) if m.group(1).lower().startswith(p)), 0)
        as_of = "%s-%02d" % (m.group(2), mo) if mo else m.group(2)
    return {"as_of": as_of, "url": KR_SURVEY_PAGE, "years": years}


# ── фактическая ключевая ставка ──

def key_rate_on(series, d):
    """Ключевая ставка, действовавшая на дату d (ISO), по ряду [[дата, %]]; None, если ряд не покрывает дату."""
    if not series or d < series[0][0]:
        return None
    i = bisect.bisect_right([x[0] for x in series], d) - 1
    return series[i][1]


def _kr_current():
    ser = key_rate_series()
    if not ser:
        raise ValueError("нет ключевой ставки")
    return ser, ser[-1][1]


# ── построение месячного пути ──

def _kr_days(a, b):
    return (datetime.strptime(b, "%Y-%m-%d") - datetime.strptime(a, "%Y-%m-%d")).days


def _kr_add(d, n):
    return (datetime.strptime(d, "%Y-%m-%d") + timedelta(days=n)).strftime("%Y-%m-%d")


def _kr_interp(knots, t):
    if t <= knots[0][0]:
        return knots[0][1]
    for (x0, y0), (x1, y1) in zip(knots, knots[1:]):
        if t <= x1:
            return y0 + (y1 - y0) * (t - x0) / ((x1 - x0) or 1)
    return knots[-1][1]


def _kr_month_starts(today, n):
    y, m = int(today[:4]), int(today[5:7])
    out = []
    for _ in range(n):
        m += 1
        if m > 12:
            y, m = y + 1, 1
        out.append("%04d-%02d-01" % (y, m))
    return out


def _kr_path_from_yearly(yearly, k0, today, series):
    """Путь ставки, у которого среднее за год совпадает со срединным значением прогноза.
    Узлы: сегодня = текущая ставка; для текущего года — середина оставшейся части (цель = средняя ставка на остаток года,
    выведенная из годовой средней и уже известной фактической части); для следующих лет — 2 июля.
    Между узлами линейно, после последнего — плоско. Значения узлов подгоняются итерациями так, чтобы дневное среднее
    по году (для текущего — по оставшейся его части) равнялось целевому."""
    cur = int(today[:4])
    spans = []          # [год, t_от, t_до, цель, t_узла] в днях от сегодня
    for y in sorted(yearly):
        if y < cur:
            continue
        lo, hi = yearly[y]
        mid = (lo + hi) / 2.0
        b = _kr_days(today, "%d-12-31" % y)
        if y == cur:
            if b < 20:
                continue
            ny = _kr_days("%d-01-01" % y, "%d-12-31" % y) + 1
            done = _kr_days("%d-01-01" % y, today)
            tot = 0.0
            for i in range(done):
                r = key_rate_on(series, _kr_add("%d-01-01" % y, i))
                if r is None:
                    tot = None
                    break
                tot += r
            if tot is not None and ny > done:
                rest = (mid * ny - tot) / (ny - done)
                if abs(rest - mid) <= 6 and rest > 0.5:
                    mid = rest
            spans.append([y, 0, b, mid, b / 2.0])
        else:
            a = _kr_days(today, "%d-01-01" % y)
            spans.append([y, a, b, mid, float(_kr_days(today, "%d-07-02" % y))])
    if not spans:
        raise ValueError("нет прогнозных лет")
    vals = [s[3] for s in spans]
    for _ in range(40):
        knots = [(0.0, k0)] + [(s[4], v) for s, v in zip(spans, vals)]
        worst = 0.0
        for n_, s in enumerate(spans):
            avg = sum(_kr_interp(knots, t) for t in range(int(s[1]), int(s[2]) + 1)) / (s[2] - s[1] + 1)
            err = s[3] - avg
            worst = max(worst, abs(err))
            vals[n_] = max(0.5, vals[n_] + 0.8 * err)
        if worst < 0.005:
            break
    knots = [(0.0, k0)] + [(s[4], v) for s, v in zip(spans, vals)]
    pts = [(today, round(k0, 3))]
    for d in _kr_month_starts(today, KR_HORIZON_M):
        pts.append((d, round(_kr_interp(knots, _kr_days(today, d)), 3)))
    return pts


def _kr_market_path(k0, today):
    """Путь из форвардных ставок КБД: 3-месячный форвард f(t) на горизонте t (эффективная годовая ставка).
    Ключевая ставка ~ форвард минус срочная премия: премия принята 0,75 п.п. в год горизонта, но не более 1,5 п.п.
    Начало привязано к текущей ставке: сдвиг (k0 - f(0)) затухает линейно за 2 года. Это грубая оценка рыночных
    ожиданий, а не прогноз ЦБ."""
    if not kbd_curve():
        raise ValueError("нет КБД")

    def z(t):
        return (1 + kbd_at(t) / 100.0) ** t

    def fwd(t):
        h = 0.25
        return ((z(t + h) / z(t)) ** (1 / h) - 1) * 100.0
    f0 = fwd(0.0)
    pts = [(today, round(k0, 3))]
    for d in _kr_month_starts(today, KR_HORIZON_M):
        t = _kr_days(today, d) / 365.0
        pts.append((d, round(max(0.5, fwd(t) + (k0 - f0) * max(0.0, 1 - t / 2.0) - min(1.5, 0.75 * t)), 3)))
    return pts


def _kr_flat_path(k0, today):
    return [(today, round(k0, 3))] + [(d, round(k0, 3)) for d in _kr_month_starts(today, KR_HORIZON_M)]


def _kr_yearly_from_path(path):
    by = defaultdict(list)
    for d, v in path:
        by[int(d[:4])].append(v)
    return [{"year": y, "low": round(min(v), 2), "high": round(max(v), 2), "mid": round(sum(v) / len(v), 2)} for y, v in sorted(by.items())]


def _kr_try(src, today):
    """Один источник -> dict с path/yearly/as_of либо исключение."""
    ser, k0 = _kr_current()
    if src in ("cbr", "survey"):
        st = store()
        ck = "kr_src:" + src
        raw = st.get(ck, ttl=KR_TTL)
        if raw is None:
            raw = (_kr_cbr if src == "cbr" else _kr_survey)()
            st.put(ck, {"as_of": raw["as_of"], "url": raw["url"], "years": {str(k): list(v) for k, v in raw["years"].items()}})
        years = {int(k): tuple(v) for k, v in raw["years"].items() if int(k) >= int(today[:4])}     # фактические годы не нужны
        path = _kr_path_from_yearly(years, k0, today, ser)
        yearly = [{"year": y, "low": lo, "high": hi, "mid": round((lo + hi) / 2.0, 2)} for y, (lo, hi) in sorted(years.items())]
        return {"as_of": raw["as_of"], "url": raw["url"], "yearly": yearly, "path": path, "key_rate": k0}
    path = _kr_market_path(k0, today) if src == "market" else _kr_flat_path(k0, today)
    return {"as_of": today, "url": "", "yearly": _kr_yearly_from_path(path), "path": path, "key_rate": k0}


def keyrate_forecast_info(mode=None):
    """{source, source_name, mode, as_of, yearly:[{year, low, high, mid}], path:[(дата, %)], key_rate, tried:{источник: ошибка}}.
    mode — из настройки keyrate_mode; пробуем выбранный источник, затем следующие по цепочке cbr -> survey -> market -> flat.
    Кэш источников 24 часа (в базе), путь на сегодня — в памяти."""
    if mode is None:
        try:
            mode = load_config().get("keyrate_mode")
        except Exception:  # noqa: BLE001
            mode = None
    if mode not in KR_MODES:
        mode = "cbr"
    today = date.today().isoformat()
    ck = (mode, today)
    with _kr_lock:
        hit = _kr_mem.get(ck)
        if hit and time.time() - hit[0] < (KR_TTL if hit[1].get("source") != "none" else KR_ERR_TTL):
            return hit[1]
        tried, res = {}, None
        for src in KR_MODES[KR_MODES.index(mode):]:
            try:
                res = _kr_try(src, today)
                res["source"] = src
                break
            except Exception as e:  # noqa: BLE001
                tried[src] = str(e)[:140] or e.__class__.__name__
        if res is None:
            res = {"source": "none", "as_of": today, "url": "", "yearly": [], "path": [], "key_rate": None}
        res.update(mode=mode, tried=tried, source_name=KR_NAMES.get(res["source"], "нет данных"))
        _kr_mem.clear()
        _kr_mem[ck] = (time.time(), res)
        return res


def keyrate_path():
    """Месячный путь ключевой ставки [(дата ISO, % годовых)] на ~4 года вперёд (первая точка — сегодня).
    Источник — keyrate_forecast_info(); пусто, если ничего не получилось."""
    try:
        return keyrate_forecast_info()["path"]
    except Exception:  # noqa: BLE001
        return []


def keyrate_at(path, d):
    """Прогнозная ставка на дату d (ISO) по пути (линейная интерполяция между месячными точками)."""
    if not path:
        return None
    if d <= path[0][0]:
        return path[0][1]
    ds = [p[0] for p in path]
    i = bisect.bisect_right(ds, d)
    if i >= len(path):
        return path[-1][1]
    (d0, v0), (d1, v1) = path[i - 1], path[i]
    w = _kr_days(d0, d) / float(_kr_days(d0, d1) or 1)
    return v0 + (v1 - v0) * w

# ═══════════════════ сигналы: дороже/дешевле аналогов по всему рынку, история, возможные замены ═══════════════════

SIG_TTL = 900
SIG_HIST_KEY = "sig_hist_v1"
SIG_HIST_DAYS = 120
SIG_EPS = 0.25           # |diff| (п.п.) от которого выпуск считается «дешевле/дороже» аналогов
SIG_OUTLIER = 8.0        # |diff| больше этого, доходность выше SIG_MAX_YIELD или спред < -6: вероятно дефолтный/«битый» выпуск
SIG_MAX_YIELD = 40.0
SIG_MAX_GAIN = 8.0       # разницу доходности больше этого в замены не берём: это уже разница в риске, а не «недооценка»
SIG_MIN_SIGMA = 0.4      # нижняя граница разброса аналогов (п.п.) для z-оценки
_sig = {"t": 0, "rows": [], "meta": {}}
_sig_lock = threading.Lock()
_sig_hist = {"t": 0, "d": None}


def _sig_pool(uni):
    """Выпуски, участвующие в сравнении: рублёвые корпоративные с рейтингом, без флоатеров и бессрочных."""
    out = []
    for e in uni:
        if e["kind"] != "corp" or e["cur"] != "RUB" or not (0 < e["yield"] < 60) or not e.get("dur") or e["dur"] < 0.1:
            continue
        if not e["_rt"] or e.get("spread") is None:
            continue
        ci = e["_ci"] or {}
        if ci.get("floating") or ci.get("perpetual"):
            continue
        out.append(e)
    return out


def _sig_index(pool):
    """Индексы для быстрого перебора кандидатов: по индексу рейтинга, отсортировано по дюрации."""
    by = defaultdict(list)
    for e in pool:
        by[RATING_SCALE.index(e["_rt"]["v"])].append(e)
    idx = {}
    for ri, lst in by.items():
        lst.sort(key=lambda e: e["dur"])
        idx[ri] = (lst, [e["dur"] for e in lst])
    return idx


def _sig_cands(me, ri, idx, rng=2):
    """Кандидаты в аналоги (до применения _bc_cost): рейтинг ±rng ступеней и дюрация в допустимом окне."""
    d = me["dur"]
    lo, hi = d * 0.4, d * 2.5
    for r in range(ri - rng, ri + rng + 1):
        it = idx.get(r)
        if not it:
            continue
        lst, durs = it
        for e in lst[bisect.bisect_left(durs, lo):bisect.bisect_right(durs, hi)]:
            yield e


def _sig_nearest(me, ri, idx, isin_skip=None):
    """Ближайшие аналоги так же, как в карточке: 30 лучших -> отсев выбросов по спреду -> 12 лучших. Возвращает [(cost, e)]."""
    sc = []
    for e in _sig_cands(me, ri, idx):
        if e is me or e["_isin"] == isin_skip:
            continue
        c = _bc_cost(me, e, ri)
        if c is not None:
            sc.append((c, e["_isin"], e))
    sc.sort(key=lambda x: (x[0], x[1]))
    sps = sorted(x[2]["spread"] for x in sc[:30])
    if len(sps) >= 5:
        m0 = sps[len(sps) // 2]
        sc = [x for x in sc if abs(x[2]["spread"] - m0) <= 8]
    return [(c, e) for c, _, e in sc[:12]]


def _sig_median(xs):
    xs = sorted(xs)
    n = len(xs)
    return xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2


def _sig_row(e, near):
    sp = [a["spread"] for _, a in near]
    med = _sig_median(sp)
    mad = _sig_median([abs(x - med) for x in sp]) * 1.4826
    diff = e["spread"] - med
    ci, rt = e["_ci"] or {}, e["_rt"]
    return {"isin": e["_isin"], "id": e["id"], "name": e["name"], "rating": rt["v"], "rating_approx": bool(rt.get("approx")),
            "sector": ci.get("sector"), "yield": e["yield"], "spread": e["spread"], "dur": e["dur"], "price": e.get("price"),
            "mat": e.get("mat"), "med": round(med, 2), "diff": round(diff, 2), "sigma": round(max(mad, SIG_MIN_SIGMA), 2),
            "z": round(diff / max(mad, SIG_MIN_SIGMA), 2), "n": len(sp), "turn": e.get("turn") or 0, "trades": e.get("trades") or 0,
            "amort": bool(ci.get("amort")), "sub": bool(ci.get("subordinated")),
            "outlier": bool(abs(diff) > SIG_OUTLIER or e["yield"] > SIG_MAX_YIELD or e["spread"] < -6),
            "refs": [{"isin": a["_isin"], "name": a["name"], "spread": a["spread"]} for _, a in near[:3]]}


def _sig_hist_load():
    if _sig_hist["d"] is None or time.time() - _sig_hist["t"] > 60:
        _sig_hist["d"] = store().get(SIG_HIST_KEY) or {}
        _sig_hist["t"] = time.time()
    return _sig_hist["d"]


def _sig_snapshot(rows):
    """Сохраняет сегодняшний снимок diff (по будням; ликвидные выпуски), хранит SIG_HIST_DAYS последних дней."""
    h = _sig_hist_load()
    today = date.today()
    if today.weekday() < 5 and rows:
        h[today.isoformat()] = {r["isin"]: r["diff"] for r in rows if r["turn"] >= 2e5}
        for d in sorted(h)[:-SIG_HIST_DAYS]:
            h.pop(d, None)
        try:
            store().put(SIG_HIST_KEY, h)
        except Exception:  # noqa: BLE001
            pass
    return h


def _sig_streak(h, isin, diff):
    """Сколько последних снимков подряд знак и величина diff те же (дешевле/дороже). Возвращает (streak, series[старые..новые])."""
    days = sorted(h)
    ser = [h[d].get(isin) for d in days]
    sgn = 1 if diff >= SIG_EPS else -1 if diff <= -SIG_EPS else 0
    n = 0
    if sgn:
        for v in reversed(ser):
            if v is not None and v * sgn >= SIG_EPS:
                n += 1
            else:
                break
    return n, ser


def _sig_all(force=False):
    """Полный расчёт сигналов по рынку; кэш 15 минут. Возвращает (rows, meta)."""
    if not force and time.time() - _sig["t"] < SIG_TTL and _sig["rows"]:
        return _sig["rows"], _sig["meta"]
    with _sig_lock:
        if not force and time.time() - _sig["t"] < SIG_TTL and _sig["rows"]:
            return _sig["rows"], _sig["meta"]
        t0 = time.time()
        uni = _bc_universe()
        pool = _sig_pool(uni)
        idx = _sig_index(pool)
        rows = []
        for e in pool:
            near = _sig_nearest(e, RATING_SCALE.index(e["_rt"]["v"]), idx)
            if len(near) >= 5:
                rows.append(_sig_row(e, near))
        h = _sig_snapshot(rows)
        days = sorted(h)
        for r in rows:
            n, ser = _sig_streak(h, r["isin"], r["diff"])
            r["streak"] = n
            vals = [v for v in ser if v is not None]
            r["trend"] = round(r["diff"] - vals[-6], 2) if len(vals) >= 6 else (round(r["diff"] - vals[0], 2) if len(vals) >= 2 else None)
            r["hist"] = vals[-30:] if abs(r["z"]) >= 1 and len(vals) >= 2 else None
        meta = {"pool": len(pool), "scored": len(rows), "hist_days": len(days), "hist_from": days[0] if days else None,
                "calc_s": round(time.time() - t0, 2), "updated": time.time()}
        _sig.update(t=time.time(), rows=rows, meta=meta)
        return rows, meta


def _sig_replacements(cfg, acc, pool_idx, rows_by_isin, fee, thr, min_turn, tax_rate):
    """Для каждой облигации портфеля: возможные замены с большей доходностью (по рыночной доходности) с учётом издержек."""
    try:
        pf = build_bonds(cfg, acc, False)["rows"]
    except Exception:  # noqa: BLE001
        return [], []
    uni = {}
    for e in _bc_universe():
        uni[e["_isin"]] = e
        uni[e["id"]] = e
    pool, idx = pool_idx
    held = {r.get("ticker") for r in pf}
    out, skipped = [], []
    for r in pf:
        isin = r.get("ticker")
        V = r.get("value_rub") or 0
        base = {"isin": isin, "name": r.get("name"), "qty": r.get("qty"), "value": round(V, 2), "rating": (r.get("rating") or {}).get("v")}
        me = uni.get(isin)
        if not me or V <= 0 or r.get("cur") not in (None, "rub", "RUB"):
            skipped.append(dict(base, why="нет рыночных данных или не рублёвая"))
            continue
        if me["kind"] != "corp":
            skipped.append(dict(base, why="ОФЗ: сравнение не применяется"))
            continue
        ci = me["_ci"] or {}
        if ci.get("floating") or r.get("floating"):
            skipped.append(dict(base, why="флоатер: спред к КБД не сопоставим"))
            continue
        if not me["_rt"]:
            skipped.append(dict(base, why="нет рейтинга"))
            continue
        ri = RATING_SCALE.index(me["_rt"]["v"])
        y0 = me["yield"]
        mine_sig = rows_by_isin.get(me["_isin"])
        if not mine_sig or mine_sig["outlier"]:
            skipped.append(dict(base, why="нет надёжного сравнения с аналогами (нет спреда или аномальные данные)"))
            continue
        cands = []
        for t in _sig_cands(me, ri, idx):
            if t is me or t["_isin"] in held or t["yield"] <= y0 or (t.get("turn") or 0) < min_turn:
                continue
            c = _bc_cost(me, t, ri)
            if c is None or c > 2.5 or abs(t["dur"] - me["dur"]) / max(t["dur"], me["dur"], 0.5) > 0.35:
                continue
            cands.append((c, t))
        # потолок доходности: цель не должна быть выбросом относительно собственных аналогов
        price, buy, nom, qty = r.get("price_pct"), r.get("buy_pct"), r.get("nominal") or 1000.0, r.get("qty") or 0
        tax = 0.0
        if price and buy and price > buy:
            tax = tax_rate * (price - buy) / 100.0 * nom * qty
        cost_rub = 2 * fee * V + tax
        opts = []
        for c, t in cands:
            tr = rows_by_isin.get(t["_isin"])
            if tr is None or tr["n"] < 5:
                continue
            if tr["outlier"]:
                continue
            gain = t["yield"] - y0
            if gain > SIG_MAX_GAIN:
                continue
            hz = min(5.0, max(0.5, min(me["dur"], t["dur"])))
            net = gain - cost_rub / V * 100.0 / hz
            rt_i = RATING_SCALE.index(t["_rt"]["v"])
            gain_rub = V * gain / 100.0
            opts.append({"isin": t["_isin"], "name": t["name"], "rating": t["_rt"]["v"], "rating_worse": rt_i > ri,
                         "rating_better": rt_i < ri, "sector": (t["_ci"] or {}).get("sector"), "yield": t["yield"], "dur": t["dur"],
                         "spread": t["spread"], "turn": t.get("turn") or 0, "trades": t.get("trades") or 0, "mat": t.get("mat"),
                         "diff": tr["diff"], "z": tr["z"], "gain_pp": round(gain, 2), "net_pp": round(net, 2),
                         "gain_rub_year": round(gain_rub), "net_rub_year": round(V * net / 100.0),
                         "breakeven_months": round(cost_rub / gain_rub * 12, 1) if gain_rub > 0 else None, "horizon": round(hz, 1)})
        opts = [o for o in opts if o["net_pp"] >= thr]
        opts.sort(key=lambda o: -o["net_pp"])
        better = [o for o in opts if not o["rating_worse"]][:3]
        worse = [o for o in opts if o["rating_worse"]][:2]
        if better or worse:
            out.append(dict(base, yield_=y0, dur=me["dur"], spread=me["spread"], price_pct=price, buy_pct=buy, sector=ci.get("sector"),
                            turn=me.get("turn") or 0, diff=mine_sig["diff"] if mine_sig else None, z=mine_sig["z"] if mine_sig else None,
                            cost_rub=round(cost_rub), commission_rub=round(2 * fee * V), tax_rub=round(tax),
                            cost_pp=round(cost_rub / V * 100, 2), options=better, options_worse=worse))
    out.sort(key=lambda x: -((x["options"] or x["options_worse"])[0]["net_rub_year"]))
    return out, skipped


def signals_payload(cfg, acc, q=None):
    q = q or {}

    def num(k, d, lo, hi):
        try:
            return min(hi, max(lo, float(q.get(k, d))))
        except (TypeError, ValueError):
            return d
    min_turn = num("min_turn", 1e6, 0, 1e10)
    fee = num("fee", 0.3, 0, 5) / 100.0
    thr = num("threshold", 1.0, 0, 20)
    tax_rate = num("tax", 13, 0, 50) / 100.0
    rows, meta = _sig_all(q.get("force") == "1")
    liquid = [r for r in rows if r["turn"] >= min_turn]
    n_out = sum(1 for r in liquid if r["outlier"])
    liquid_ok = [r for r in liquid if not r["outlier"]]
    uni = _bc_universe()
    pool = _sig_pool(uni)
    by = {r["isin"]: r for r in rows}
    repl, skipped = _sig_replacements(cfg, acc, (pool, _sig_index(pool)), by, fee, thr, min_turn, tax_rate)
    cheap = sorted((r for r in liquid_ok if r["diff"] >= SIG_EPS), key=lambda r: -r["z"])
    rich = sorted((r for r in liquid_ok if r["diff"] <= -SIG_EPS), key=lambda r: r["z"])
    outl = [r for r in liquid if r["outlier"]]
    keep = {r["isin"] for r in cheap[:150]} | {r["isin"] for r in rich[:150]} | {r["isin"] for r in outl[:60]}
    return {"rows": [r for r in liquid if r["isin"] in keep],
            "kpis": {"universe": len(liquid), "outliers": n_out, "cheap": len(cheap), "rich": len(rich),
                     "cheap_strong": sum(1 for r in cheap if r["z"] >= 2), "rich_strong": sum(1 for r in rich if r["z"] <= -2),
                     "med_diff": round(_sig_median([r["diff"] for r in liquid_ok]), 2) if liquid_ok else None},
            "meta": meta, "params": {"min_turn": min_turn, "fee": fee * 100, "threshold": thr, "tax": tax_rate * 100},
            "replacements": repl, "skipped": skipped, "eps": SIG_EPS}
# ═══════════════════ мониторинг портфеля: тревоги, ликвидность, история спредов ═══════════════════
# Источники: журнал рейтинговых действий (ratings_log_v1, каналы @ru_ratings и @issuerRatings), рейтинги и статус «под наблюдением»
# из каталога T-Invest, история торгов и описание выпуска на Мосбирже (ISS), кривая КБД по датам.
# Чего программа НЕ видит: факт оплаты купона (ISS его не публикует), поэтому «задержка выплаты» определяется
# только косвенно: флаги дефолта в описании выпуска на Мосбирже, дефолтный рейтинг (D/RD/C), остановка торгов.

MON_DEFAULTS = {"mon_drop5": 3.0, "mon_drop30": 7.0, "mon_spread30": 2.0, "mon_sell_days": 5.0, "mon_offer_days": 30}
MON_SNAP_KEY, MON_CURVE_KEY = "mon_snap_v1", "kbd_curves_v1"
MON_RT_DAYS, MON_SPARK_DAYS, MON_PART = 90, 90, 0.2        # окно рейтинговых событий, окно спарклайна, доля оборота
_mon_lock = threading.Lock()
_SEV = {"high": 0, "medium": 1, "info": 2}


def mon_thresholds(cfg):
    out = {}
    for k, d in MON_DEFAULTS.items():
        try:
            out[k] = float(cfg.get(k, d))
        except (TypeError, ValueError):
            out[k] = d
    return out


def _mon_ymd(n):
    return (date.today() - timedelta(days=n)).isoformat()


def _mon_hist_for(secid):
    """История торгов выпуска (кэш 6 ч в kv) или None."""
    try:
        h = _bc_history(secid)
        return h if h and h.get("d") else None
    except Exception:  # noqa: BLE001
        return None


def _mon_flags(isin):
    """Флаги дефолта из описания выпуска на Мосбирже (кэш 12 ч)."""
    key = "mon_desc_v1_" + isin
    hit = store().get(key, ttl=12 * 3600)
    if hit is not None:
        return hit
    try:
        j = json.loads(http_text("https://iss.moex.com/iss/securities/%s.json?iss.meta=off&iss.only=description" % isin, timeout=20))
        d = {r[0]: r[2] for r in j["description"]["data"]}
        out = {"default": str(d.get("HASDEFAULT") or "0") == "1", "tech": str(d.get("HASTECHNICALDEFAULT") or "0") == "1",
               "found": bool(d)}
    except Exception:  # noqa: BLE001
        return {"default": False, "tech": False, "found": False}
    store().put(key, out)
    return out


def _mon_ru(d):
    return d[8:] + "." + d[5:7] + "." + d[:4]


def mon_moex_events(bz, offers, today, horizon):
    """События выпуска по данным Мосбиржи (bondization + оферты): погашение, амортизации, оферты в окне [today, today+horizon] дней.
    Только будущие события. -> {'maturity': дата|None, 'events': [{kind: maturity|amort|offer, date, left, ...}], 'next_offer': дата|None}.
    Погашение — последняя дата в графике амортизаций (при его отсутствии — последний купон); остальные даты амортизаций — частичные."""
    end = (datetime.strptime(today, "%Y-%m-%d") + timedelta(days=int(horizon))).strftime("%Y-%m-%d")
    bz = bz or {}
    am = {}
    for a in bz.get("amort") or []:
        if a.get("amortdate"):
            am[a["amortdate"]] = a
    cps = [c["coupondate"] for c in bz.get("coupons") or [] if c.get("coupondate")]
    mat = max(am) if am else (max(cps) if cps else None)
    ev = []
    for d, a in sorted(am.items()):
        if today < d <= end:
            ev.append({"kind": "maturity" if d == mat else "amort", "date": d, "pct": a.get("valueprc"), "value": a.get("value")})
    if mat and not am and today < mat <= end:
        ev.append({"kind": "maturity", "date": mat})
    live = [o for o in offers or [] if o.get("status") != "cancelled" and o["date"] > today]
    for d in sorted({o["date"] for o in live if o["date"] <= end}):
        ev.append({"kind": "offer", "date": d, "offer_kind": offer_kind_on(live, d)})
    for e in ev:
        e["left"] = (datetime.strptime(e["date"], "%Y-%m-%d").date() - datetime.strptime(today, "%Y-%m-%d").date()).days
    ev.sort(key=lambda e: e["date"])
    return {"maturity": mat, "events": ev, "next_offer": min((o["date"] for o in live), default=None)}


def mon_event_alert(e):
    """Текст тревоги по событию мосбиржевого графика (погашение, амортизация)."""
    ds, left = _mon_ru(e["date"]), e["left"]
    if e["kind"] == "maturity":
        return "Погашение %s (через %d дн.) — по данным Мосбиржи" % (ds, left)
    part = ""
    if e.get("pct"):
        part = " %s %% номинала" % str(e["pct"]).replace(".", ",")
    return "Амортизация%s %s (через %d дн.) — по данным Мосбиржи" % (part, ds, left)


def mon_clean_issuer(s):
    """Название эмитента из поста агентства: убирает висячие кавычки, ПРОПИСНЫЕ -> обычный регистр (аббревиатуры до 4 букв остаются)."""
    s = re.sub(r"\s+", " ", s or "").strip()
    if s.count("«") != s.count("»"):
        s = s.replace("«", "").replace("»", "").strip()
    if s.isupper():
        s = " ".join(w if len(w) <= 4 or "." in w else w.capitalize() for w in s.split(" "))
    return s


def _mon_curve_one(d):
    j = json.loads(http_text("https://iss.moex.com/iss/engines/stock/zcyc.json?iss.meta=off&iss.only=yearyields&date=" + d))
    return d, [[r[2], round(r[3], 3)] for r in sorted(j["yearyields"]["data"], key=lambda r: r[2])]


def _mon_curves(days):
    """Кривые КБД по датам за последние days дней (кэш в kv навсегда; выходные и праздники хранятся пустыми)."""
    st = store()
    cache = st.get(MON_CURVE_KEY) or {}
    need = [_mon_ymd(i) for i in range(1, days + 1) if (date.today() - timedelta(days=i)).weekday() < 5
            and _mon_ymd(i) not in cache]
    if need:
        for d, pts in pool_map(lambda x: _safe(_mon_curve_one, x), need, workers=8):
            if d is not None:
                cache[d] = pts
        keep = _mon_ymd(800)
        cache = {k: v for k, v in cache.items() if k >= keep}
        st.put(MON_CURVE_KEY, cache)
    return cache


def _curve_on(curves, sorted_dates, d):
    """Кривая на дату d: последняя непустая на эту дату или раньше."""
    import bisect
    i = bisect.bisect_right(sorted_dates, d)
    while i > 0:
        i -= 1
        c = curves.get(sorted_dates[i])
        if c:
            return c
    return None


def _at_or_before(ds, target):
    """Индекс последней даты <= target либо None."""
    import bisect
    i = bisect.bisect_right(ds, target) - 1
    return i if i >= 0 else None


def _mon_match(a, b):
    if not a or not b:
        return False
    if a == b:
        return True
    lo, hi = (a, b) if len(a) <= len(b) else (b, a)           # «ЛК Европлан» ~ «Европлан», но «Золото Селигдара» != «Селигдар»
    return lo <= hi and sum(len(x) for x in lo) >= 5 and all(len(x) <= 2 for x in hi - lo)


def _mon_ev_tokens(e):
    """Ключи эмитента события: пересчитываются из названия (в старых журналах сохранены ключи прежнего формата)."""
    return set(name_tokens(e.get("issuer") or "")) or set(e.get("tokens") or ())


def _mon_issuer_keys(row):
    keys = [name_tokens(_bond_query(row.get("name") or ""))]
    b = _tcat_get(row.get("isin") or row.get("ticker"))
    if b:
        for s in (b.get("br"), _bond_query(b.get("n") or "")):
            if s:
                keys.append(name_tokens(s))
    return [k for k in keys if k]


def _mon_rating_state(row, keys, events):
    """Рейтинговое состояние для таблицы: лучший рейтинг, прогноз, флаг «под наблюдением»."""
    rt = row.get("rating")
    watch, outlook, last = False, "", {}
    b = _tcat_get(row.get("isin") or row.get("ticker"))
    if b:
        for ag, lv, dt, fc, w in b["r"]:
            if w:
                watch = True
            if fc and (ag not in last or dt >= last[ag][0]):
                last[ag] = (dt, fc)
    ws = {}
    for e in events:
        if any(_mon_match(_mon_ev_tokens(e), k) for k in keys):
            if e.get("watch") in ("set", "removed"):
                ws[e["agency"]] = e["watch"] == "set"
            if e.get("outlook") and e["agency"] not in last:
                last[e["agency"]] = (e["date"], e["outlook"])
    if any(ws.values()):
        watch = True
    cands = [x for x in (rt or {}).get("all") or []]
    if cands:
        w = max(cands, key=lambda x: RATING_SCALE.index(x["rating"]))
        outlook = (w.get("outlook") or "").split(" · ")[0]
    if not outlook and last:
        outlook = sorted(last.values())[-1][1]
    return {"v": rt["v"] if rt else None, "agency": rt["agency"] if rt else None, "outlook": outlook,
            "watch": watch, "neg": "негатив" in (outlook or "").lower()}


MON_RT_HIGH_DAYS = 30                                      # понижение старше этого срока уже не «высокая» тревога


def _mon_rating_alerts(rows_keys, events, cutoff, today=None):
    """Тревоги по журналу рейтинговых действий: одно событие -> одна тревога на все бумаги этого эмитента.
    Одинаковые действия одного агентства в один день (по эмитенту и по облигациям) склеиваются в одну тревогу.
    Давнее понижение (старше MON_RT_HIGH_DAYS дней) понижается до средней важности."""
    out, seen = [], {}
    old = (datetime.strptime(today, "%Y-%m-%d").date() - timedelta(days=MON_RT_HIGH_DAYS)).isoformat() if today else None
    for e in events:
        if e["date"] < cutoff:
            continue
        et = _mon_ev_tokens(e)
        hit = [r for r, keys in rows_keys if any(_mon_match(et, k) for k in keys)]
        if not hit:
            continue
        act, rt, prev = e["action"], e.get("rating"), e.get("prev")
        sev, msg = None, None
        who = "%s: " % e["agency"]
        lvl = "облигации" if e["level"] == "bond" else "эмитент"
        issuer = mon_clean_issuer(e["issuer"])
        if rt in ("D", "C", "CC") or (act == "понижен" and rt in ("CCC",)):
            sev, msg = "high", who + "дефолтный/преддефолтный уровень рейтинга %s (%s)" % (rt, lvl)
        elif act == "понижен":
            sev, msg = "high", who + "рейтинг понижен%s до %s (%s)" % (" с " + prev if prev else "", rt, lvl)
        elif e.get("watch") == "set" or act == "под наблюдением":
            sev, msg = "medium", who + "рейтинг %s взят «под наблюдение» (%s)" % (rt or "", lvl)
        elif act == "прогноз изменён" and (e.get("outlook") or "") == "негативный":
            sev, msg = "medium", who + "прогноз изменён на негативный, рейтинг %s (%s)" % (rt, lvl)
        elif act == "отозван":
            sev = "medium" if e["level"] == "issuer" else "info"
            msg = who + "рейтинг отозван (%s)%s" % (lvl, "; ранее " + prev if prev else "")
        elif act == "повышен":
            sev, msg = "info", who + "рейтинг повышен%s до %s (%s)" % (" с " + prev if prev else "", rt, lvl)
        elif e.get("outlook") == "негативный":
            sev, msg = "info", who + "рейтинг %s %s, прогноз негативный (%s)" % (rt, act, lvl)
        if not sev:
            continue
        if sev == "high" and old and e["date"] < old and rt not in ("D", "C", "CC"):
            sev = "medium"
        ident = (e["agency"], e["date"], act, rt, prev, e.get("watch"), e.get("outlook") if act == "прогноз изменён" else None, tuple(sorted(h.get("isin") or "" for h in hit)))
        if ident in seen:                              # то же действие по другому уровню (эмитент/облигации)
            if lvl not in seen[ident]["_lvl"]:
                seen[ident]["_lvl"].append(lvl)
                seen[ident]["message"] = seen[ident]["_msg"] % "эмитент и облигации"
            continue
        out.append({"id": "rt|%s|%s%s" % (e["agency"], "rr" if e.get("src") == "ru_ratings" else "", e["post"]), "severity": sev, "kind": "rating", "date": e["date"],
                    "isin": hit[0].get("isin"), "isins": [h.get("isin") for h in hit], "name": issuer,
                    "bonds": [h.get("name") for h in hit], "message": msg, "url": e.get("url") or
                    "https://t.me/%s/%s" % (e.get("src") or "issuerRatings", e["post"]), "_lvl": [lvl], "_msg": msg.replace("(" + lvl + ")", "(%s)")})
        seen[ident] = out[-1]
    for a in out:
        a.pop("_lvl", None)
        a.pop("_msg", None)
    return out


def _mon_snapshots(rows):
    """Ежедневный снимок цены/спреда по ISIN (хранится 400 дней): запасной источник истории спреда."""
    st = store()
    snap = st.get(MON_SNAP_KEY) or {}
    today = date.today().isoformat()
    changed = False
    for r in rows:
        isin = r.get("isin")
        if not isin or r.get("price_pct") is None:
            continue
        d = snap.setdefault(isin, {})
        if today not in d:
            d[today] = [round(r["price_pct"], 3), r.get("spread")]
            changed = True
    keep = _mon_ymd(400)
    if changed:
        for isin in snap:
            snap[isin] = {k: v for k, v in snap[isin].items() if k >= keep}
        st.put(MON_SNAP_KEY, snap)
    return snap


def build_monitor(cfg, acc):
    t0 = time.time()
    th = mon_thresholds(cfg)
    key = ("monitor", token_key(cfg), acc, tuple(sorted(th.items())))
    hit = mem_get(key, 300)
    if hit:
        return hit
    with _mon_lock:
        hit = mem_get(key, 300)
        if hit:
            return hit
        res = _build_monitor(cfg, acc, th, t0)
        mem_put(key, res)
        return res


def _build_monitor(cfg, acc, th, t0):
    tm = {}
    try:
        b = build_bonds(cfg, acc)
    except ApiError as e:
        if e.status != 404:
            raise
        return {"empty": True, "updated": time.time(), "thresholds": th, "alerts": [], "rows": [],
                "summary": {s: 0 for s in _SEV}, "timings": tm,
                "notes": ["Добавьте API-токен в «Настройках» или импортируйте отчёт брокера."],
                "log": {"events": 0, "since": None}, "cal_days": 0}
    tm["bonds"] = round(time.time() - t0, 2)
    rows = [r for r in (b.get("rows") or []) if r.get("isin") and r.get("qty")]
    return _monitor_core(rows, th, t0, tm, [])


def _monitor_core(rows, th, t0, tm, notes, liquidity=True):
    """Проверки мониторинга для произвольного списка бумаг. rows — строки вида build_bonds (isin, name, ticker, value_rub, qty,
    maturity, call, floating, price_pct, dur, spread, ytm, rating). Портфель и список наблюдения идут одним кодом."""
    today = date.today().isoformat()
    # соответствие ISIN -> код на Мосбирже
    t1 = time.time()
    sec = {}
    try:
        for s in screener_rows():
            if s.get("isin"):
                sec[s["isin"]] = s
    except Exception as e:  # noqa: BLE001
        notes.append("Скринер Мосбиржи недоступен: %s" % str(e)[:80])
    tm["screener"] = round(time.time() - t1, 2)
    t1 = time.time()
    secids = {r["isin"]: (sec.get(r["isin"]) or {}).get("id") or r.get("ticker") or r["isin"] for r in rows}
    hists = dict(zip([r["isin"] for r in rows], pool_map(lambda r: _mon_hist_for(secids[r["isin"]]), rows, workers=8)))
    tm["history"] = round(time.time() - t1, 2)
    t1 = time.time()
    flags = dict(zip([r["isin"] for r in rows], pool_map(lambda r: _mon_flags(r["isin"]), rows, workers=8)))
    tm["flags"] = round(time.time() - t1, 2)
    t1 = time.time()
    try:
        curves = _mon_curves(MON_SPARK_DAYS + 40)
    except Exception as e:  # noqa: BLE001
        curves = {}
        notes.append("Кривая КБД по датам недоступна: %s" % str(e)[:80])
    cdates = sorted(curves)
    tm["kbd_curves"] = round(time.time() - t1, 2)
    snap = _mon_snapshots(rows)
    log = store().get(RT_LOG_KEY) or {"events": []}
    events = log.get("events") or []
    if not events:
        notes.append("Журнал рейтинговых действий пока пуст: он наполняется при синхронизации рейтингов (раздел «Облигации» → обновить рейтинги).")
    # окно торгового календаря для среднего оборота
    win_from = _mon_ymd(30)
    cal = set()
    for h in hists.values():
        if h:
            cal.update(d for d in h["d"] if d > win_from)
    ndays = max(len(cal), 15)
    out_rows, alerts = [], []
    rows_keys = []
    for r in rows:
        isin = r["isin"]
        h = hists.get(isin)
        keys = _mon_issuer_keys(r)
        rows_keys.append((r, keys))
        row = {"isin": isin, "name": r.get("name"), "ticker": r.get("ticker"), "value_rub": r.get("value_rub"),
               "qty": r.get("qty"), "maturity": r.get("maturity"), "call": r.get("call"),
               "floating": bool(r.get("floating")), "price_pct": r.get("price_pct"), "flags": []}
        row["rating"] = _mon_rating_state(r, keys, events)
        price = chg5 = chg30 = sp_now = sp_chg = None
        spark = []
        last_d = None
        if h:
            ds, ps, ys, vs = h["d"], h["p"], h["y"], h["v"]
            last_d = ds[-1]
            price = ps[-1]
            for n, nm in ((5, "chg5"), (30, "chg30")):
                i = _at_or_before(ds, _mon_ymd(n))
                if i is not None and ds[i] >= _mon_ymd(n + 10) and ps[i]:
                    v = round((price / ps[i] - 1) * 100, 2)
                    if nm == "chg5":
                        chg5 = v
                    else:
                        chg30 = v
            # спред к КБД по датам: доходность дня минус КБД на дюрации бумаги
            dur = r.get("dur")
            if dur and not r.get("floating") and cdates:
                sp = []
                for d, y in zip(ds, ys):
                    if y is None or d < _mon_ymd(MON_SPARK_DAYS + 35):
                        continue
                    c = _curve_on(curves, cdates, d)
                    k = _interp(c, dur)
                    if k is not None and 0 < y < 80:
                        sp.append((d, round(y - k, 2)))
                if len(sp) >= 5:
                    sd = [x[0] for x in sp]
                    sp_now = sp[-1][1]
                    i = _at_or_before(sd, _mon_ymd(30))
                    if i is not None and sd[i] >= _mon_ymd(40):
                        sp_chg = round(sp_now - sp[i][1], 2)
                    spark = [[d, v] for d, v in sp if d >= _mon_ymd(MON_SPARK_DAYS)]
            tov = sum(v for d, v in zip(ds, vs) if d > win_from)
            avg = tov / ndays
            row["turnover_avg"] = round(avg)
            row["days_to_sell"] = round((r.get("value_rub") or 0) / (MON_PART * avg), 2) if avg > 0 else None
        else:
            row["turnover_avg"] = None
            row["days_to_sell"] = None
        if len(spark) < 5 and isin in snap:        # запасной вариант: накопленные ежедневные снимки
            sp = sorted((d, v[1]) for d, v in snap[isin].items() if v[1] is not None)
            if len(sp) >= 2:
                spark = [[d, v] for d, v in sp if d >= _mon_ymd(MON_SPARK_DAYS)]
                sp_now = sp[-1][1]
        row.update(price=price, chg5=chg5, chg30=chg30, spread=sp_now if sp_now is not None else r.get("spread"),
                   spread_chg30=sp_chg, spark=spark, last_trade=last_d, ytm=r.get("ytm"))
        row["no_history"] = h is None
        base = {"isin": isin, "isins": [isin], "name": r.get("name"), "bonds": [r.get("name")]}
        # --- ценовые тревоги
        parts, sev = [], None
        for chg, lim, lab in ((chg5, th["mon_drop5"], "5 дней"), (chg30, th["mon_drop30"], "30 дней")):
            if chg is not None and chg <= -lim:
                parts.append("%s %% за %s" % (str(chg).replace(".", ","), lab))
                s = "high" if chg <= -2 * lim else "medium"
                sev = s if sev is None or _SEV[s] < _SEV[sev] else sev
        if parts:
            alerts.append(dict(base, id="px|%s|%s" % (isin, today), severity=sev, kind="price", date=last_d or today,
                               message="Цена упала: " + "; ".join(parts) + (" (последняя цена %s %%)" % str(price).replace(".", ",")
                                                                              if price is not None else ""), url=""))
        if sp_chg is not None and sp_chg >= th["mon_spread30"]:
            s = "high" if sp_chg >= 2 * th["mon_spread30"] else "medium"
            alerts.append(dict(base, id="sp|%s|%s" % (isin, today), severity=s, kind="spread", date=last_d or today,
                               message="Спред к КБД вырос на %s п.п. за 30 дней (сейчас %s п.п.)" % (
                                   str(sp_chg).replace(".", ","), str(sp_now).replace(".", ",")), url=""))
        # --- события графика выпуска: даты берём с Мосбиржи (bondization и поля выпуска), а не у брокера
        win = max(int(th["mon_offer_days"]), 30)
        bz = offs = None
        try:
            bz = moex_bondization(isin)
            offs = offers_of_isin(isin, None if bz else r.get("call"), today)
        except Exception:  # noqa: BLE001
            pass
        if bz:
            me = mon_moex_events(bz, offs, today, win)
            row["maturity"] = me["maturity"] or row["maturity"]
            row["call"] = me["next_offer"]
            row["moex_dates"] = True
            for e in me["events"]:
                if e["kind"] == "offer":
                    alerts.append(dict(base, id="of|%s|%s" % (isin, e["date"]), severity="high" if e["left"] <= 7 else "medium",
                                       kind="offer", date=e["date"], message=offer_alert_text(e["offer_kind"], e["left"], _mon_ru(e["date"])) + " — по данным Мосбиржи", url=""))
                else:
                    alerts.append(dict(base, id="%s|%s|%s" % (e["kind"][:2], isin, e["date"]), severity="medium" if e["left"] <= 7 else "info",
                                       kind=e["kind"], date=e["date"], message=mon_event_alert(e), url=""))
        elif offs:                                       # Мосбиржа не отдала график: остаётся дата брокера
            row["call"] = offs[0]["date"]
            for d_ in sorted({o["date"] for o in offs if o["status"] != "cancelled" and o["date"] <= (date.today() + timedelta(days=win)).isoformat()}):
                left = (datetime.strptime(d_, "%Y-%m-%d").date() - date.today()).days
                alerts.append(dict(base, id="of|%s|%s" % (isin, d_), severity="high" if left <= 7 else "medium", kind="offer",
                                   date=d_, message=offer_alert_text(offer_kind_on(offs, d_), left, _mon_ru(d_)) + " (дата брокера)", url=""))
        # --- признаки дефолта
        fl = flags.get(isin) or {}
        if fl.get("default"):
            alerts.append(dict(base, id="df|%s" % isin, severity="high", kind="default", date=today, asof=True,
                               message="По данным Мосбиржи, по выпуску допущен дефолт", url="https://www.moex.com/ru/issue.aspx?code=" + isin))
            row["flags"].append("дефолт")
        elif fl.get("tech"):
            alerts.append(dict(base, id="td|%s" % isin, severity="high", kind="default", date=today, asof=True,
                               message="По данным Мосбиржи, по выпуску был допущен технический дефолт (задержка выплаты). Проверьте, погашена ли задолженность", url="https://www.moex.com/ru/issue.aspx?code=" + isin))
            row["flags"].append("тех. дефолт")
        if last_d and last_d < _mon_ymd(10) and not (r.get("maturity") and r["maturity"] < today):
            alerts.append(dict(base, id="nt|%s|%s" % (isin, last_d), severity="medium", kind="halt", date=last_d,
                               message="Нет торгов с %s: возможна остановка торгов, проверьте выпуск" % (
                                   last_d[8:] + "." + last_d[5:7] + "." + last_d[:4]), url=""))
            row["flags"].append("нет торгов")
        rts = row["rating"]
        if rts["v"] in ("D", "C", "CC"):
            alerts.append(dict(base, id="rd|%s" % isin, severity="high", kind="default", date=today, asof=True,
                               message="Дефолтный/преддефолтный рейтинг %s (%s)" % (rts["v"], rts["agency"]), url=""))
        elif rts["watch"]:
            alerts.append(dict(base, id="wt|%s" % isin, severity="medium", kind="watch", date=today, asof=True,
                               message="Рейтинг эмитента под наблюдением (по данным каталога T-Invest или журнала агентств)", url=""))
        if rts["neg"] and not rts["watch"]:
            alerts.append(dict(base, id="ng|%s" % isin, severity="info", kind="outlook", date=today, asof=True,
                               message="Негативный прогноз по рейтингу (%s)" % (rts["agency"] or ""), url=""))
        # --- ликвидность
        dts = row["days_to_sell"]
        if liquidity and h and (dts is None or dts > th["mon_sell_days"]):
            row["flags"].append("неликвид")
            alerts.append(dict(base, id="lq|%s|%s" % (isin, today[:7]), severity="info", kind="liquidity", date=today, asof=True,
                               message=("Нет оборота за 30 дней: продать позицию быстро не получится" if dts is None else
                                        "Низкая ликвидность: на продажу позиции нужно ~%s дн. (при 20%% дневного оборота)" % str(dts).replace(".", ",")),
                               url=""))
        out_rows.append(row)
    alerts += _mon_rating_alerts(rows_keys, events, _mon_ymd(MON_RT_DAYS), today)
    # дубль «под наблюдением» из каталога не нужен, если журнал уже сообщил о том же эмитенте
    wt_logged = {i for a in alerts if a["kind"] == "rating" for i in a.get("isins") or []}
    alerts = [a for a in alerts if not (a["kind"] in ("watch", "outlook") and a["isin"] in wt_logged)]
    alerts.sort(key=lambda a: (_SEV[a["severity"]], _neg(a["date"])))
    for a in alerts:
        for r in out_rows:
            if r["isin"] in (a.get("isins") or []):
                r["n_" + a["severity"]] = r.get("n_" + a["severity"], 0) + 1
    out_rows.sort(key=lambda r: (-(r.get("n_high") or 0), -(r.get("n_medium") or 0), -(r.get("value_rub") or 0)))
    tm["total"] = round(time.time() - t0, 2)
    return {"updated": time.time(), "thresholds": th, "alerts": alerts, "rows": out_rows,
            "summary": {s: sum(1 for a in alerts if a["severity"] == s) for s in _SEV}, "timings": tm, "notes": notes,
            "log": {"events": len(events), "since": min((e["date"] for e in events), default=None)},
            "cal_days": ndays}


def _neg(d):
    """Ключ для сортировки дат по убыванию."""
    return tuple(-ord(c) for c in d or "")


def monitor_watch_rows(isins):
    """Строки списка наблюдения в формате build_bonds (из строк скринера Мосбиржи и каталога T-Invest)."""
    sec = {}
    for s in screener_rows():
        if s.get("isin"):
            sec[s["isin"]] = s
    rows = []
    for isin in isins:
        s = sec.get(isin)
        if not s:
            continue
        ci = tcat_info(isin) or {}
        rows.append({"isin": isin, "name": s.get("name"), "ticker": s.get("id"), "value_rub": 0, "qty": 1, "maturity": s.get("mat"),
                     "call": s.get("offer"), "call_kind": "put" if s.get("offer") else None, "floating": bool(ci.get("floating")), "price_pct": s.get("price"),
                     "dur": s.get("dur"), "spread": s.get("spread"), "ytm": s.get("yield"),
                     "rating": best_rating(isin, ci.get("name") or s.get("name") or "")})
    return rows


def build_monitor_for(cfg, isins):
    """Те же проверки, что в «Мониторинге», для списка ISIN (без позиции в портфеле: ликвидность и стоимость не считаются)."""
    th = mon_thresholds(cfg)
    isins = sorted(set(i for i in isins if i))
    key = ("monitor_for", tuple(isins), tuple(sorted(th.items())))
    hit = mem_get(key, 300)
    if hit:
        return hit
    with _mon_lock:
        hit = mem_get(key, 300)
        if hit:
            return hit
        t0 = time.time()
        notes = []
        try:
            rows = monitor_watch_rows(isins)
        except Exception as e:  # noqa: BLE001
            rows = []
            notes.append("Скринер Мосбиржи недоступен: %s" % str(e)[:80])
        res = _monitor_core(rows, th, t0, {}, notes, liquidity=False)
        mem_put(key, res)
        return res
