_TG_KIND = {"price": "📉", "spread": "📈", "offer": "🔔", "default": "⛔", "rating": "🏷", "watch": "👁", "outlook": "👁",
            "halt": "⏸", "liquidity": "💧", "goal": "⭐", "reminder": "📝"}
_TG_COOL = {"price": 7 * DAY, "spread": 7 * DAY}      # повтор не раньше, чем через неделю; остальные тревоги — один раз


def _tg_key(a):
    k = a["id"]
    if a.get("kind") in _TG_COOL:
        k = "%s|%s|%s" % (a["kind"], a.get("isin"), "")
    return k


def _tg_alert_line(a):
    """«📉 <b>Бумага</b> — сообщение» и строка со ссылками (пресс-релиз/источник, бумага на Мосбирже)."""
    nm = a.get("name") or ""
    line = "%s <b>%s</b> — %s" % (_TG_KIND.get(a.get("kind"), "•"), _tg_esc(nm), _tg_esc(a.get("message")))
    url = str(a.get("url") or "")
    links = []
    if url and "moex.com/ru/issue" not in url:
        links.append(_tg_link(url, "Пресс-релиз" if a.get("kind") == "rating" else "Подробнее"))
    if a.get("isin"):
        links.append(_tg_moex(a["isin"]))
    links = [x for x in links if x]
    return line + ("\n" + " · ".join(links) if links else "")


def tg_dispatch_plan(title, alerts, sent, now, icon="🔔"):
    """Раскладка ещё не отправленных тревог по сообщениям: до трёх сообщений за проверку, до 10 тревог и в предел длины
    каждое; остальное уйдёт в следующий раз (в последнем сообщении об этом сказано). -> [(текст, [(ключ, тревога)])].
    Чистая функция; зеркало на сервере — alerts.dispatch_plan."""
    fresh = []
    for a in alerts:
        k = _tg_key(a)
        last = sent.get(k)
        if last is not None and now - last < _TG_COOL.get(a.get("kind"), 400 * DAY):
            continue
        fresh.append((k, a))
    if not fresh:
        return []
    head = _tg_head(icon, title)
    room = TG_LIMIT - len(TG_DISCLAIMER) - len(head) - 120
    plan, i = [], 0
    for msg_no in range(3):
        if i >= len(fresh):
            break
        chunk, lines, size = [], [], 0
        while i < len(fresh) and len(chunk) < 10:
            ln = _tg_alert_line(fresh[i][1])
            if chunk and size + len(ln) + 2 > room:
                break
            chunk.append(fresh[i])
            lines.append(ln)
            size += len(ln) + 2
            i += 1
        tail = ("\n\n…и ещё %d — придут при следующей проверке" % (len(fresh) - i)) if msg_no == 2 and i < len(fresh) else ""
        plan.append(("%s\n\n%s%s" % (head, "\n\n".join(lines), tail), chunk))
    return plan


def _tg_dispatch(cfg, title, alerts, sent, now, icon="🔔"):
    """Отправляет план tg_dispatch_plan. Возвращает число отправленных тревог."""
    sent_n = 0
    for text, chunk in tg_dispatch_plan(title, alerts, sent, now, icon):
        tg_send(cfg, text)
        for k, a in chunk:
            sent[k] = now
        sent_n += len(chunk)
    return sent_n


_TG_KIND["default_ok"] = "✅"
TG_DFL_DAYS = 30


def defaults_alerts(cfg, sent=None, rows=None, isins=None):
    """Тревоги о техдефолте/дефолте по бумагам портфеля и списка наблюдения (лента defaults_feed) и «исполнено» после него.
    Неисполненное -> kind default, severity high, id dfl|isin|дата|обязательство (один раз). Исполненное -> kind default_ok,
    id dflx|... — только если о дефолте по этой записи мы уже сообщали (ключ dfl|... есть в sent). Бумаги вне портфеля/наблюдения
    не трогаем. rows/isins передаются в тестах, иначе берутся из defaults_feed и _disc_own_isins."""
    sent = sent or {}
    own = list(isins) if isins is not None else _disc_own_isins(cfg, "all")
    if not own:
        return []
    if rows is None:
        rows = defaults_feed((date.today() - timedelta(days=TG_DFL_DAYS)).isoformat(), own)
    mine = set(own)
    out = []
    for r in rows:
        isin = r.get("isin")
        if isin not in mine:
            continue
        tail = "%s|%s" % (r.get("date") or r.get("basis") or "", r.get("obligation") or r.get("status"))
        base = {"isin": isin, "isins": [isin], "name": r.get("issuer") or isin, "bonds": [r.get("issuer") or isin],
                "date": r.get("date") or date.today().isoformat(), "url": r.get("url") or ""}
        what = "дефолт" if r.get("status") == "default" else "технический дефолт"
        ob = (r.get("obligation") or "обязательство").lower()
        amt = (", %s" % _tg_rub(r["amount"])) if r.get("amount") else ""
        due = (", срок %s" % _tg_date(r["due_date"])) if r.get("due_date") else ""
        kd, kx = "dfl|%s|%s" % (isin, tail), "dflx|%s|%s" % (isin, tail)
        if r.get("executed"):
            if kd in sent:
                out.append(dict(base, id=kx, kind="default_ok", severity="medium",
                                message="%s по бумаге исполнен(о): %s%s, раскрытие о выплате от %s" % (what, ob, amt, _tg_date(r["executed"]))))
        else:
            out.append(dict(base, id=kd, kind="default", severity="high",
                            message="%s по бумаге: %s%s%s (%s)" % (what, ob, amt, due, r.get("basis") or "")))
    return out


TG_OFR_CALL_DAYS, TG_OFR_CLOSE_DAYS, TG_OFR_PUT_HORIZON = 14, 2, 120


def _tg_dmy(d):
    return "%s.%s.%s" % (d[8:10], d[5:7], d[:4])


def tg_offer_due(items, today):
    """Напоминания по офертам портфеля -> [(ключ_дедупликации, текст)]. Чистая функция (today передаётся).
    items: [{isin, name, kind, date, period_start, period_end, coupon_status, new_rate}].
    Ключ 'ofr|isin|дата_оферты|тип', тип: coupon (новый купон после пут-оферты объявлен), open (приём заявок открыт),
    close (осталось <= 2 дней до конца приёма), call (до колла <= 14 дней). Каждый ключ уходит один раз (хранилище TG_SENT_KEY)."""
    out = []
    for it in items:
        isin, kind, od = it.get("isin"), it.get("kind"), it.get("date")
        if not isin or not od or od <= today:
            continue
        nm = _tg_esc(it.get("name") or isin)
        lk = "\n" + _tg_moex(isin)
        ps, pe = it.get("period_start"), it.get("period_end")
        base = "ofr|%s|%s|" % (isin, od)
        if kind == "put":
            if it.get("coupon_status") == "announced" and it.get("new_rate") is not None and (not pe or today <= pe):
                out.append((base + "coupon", "🔔 <b>%s</b> — эмитент объявил купон после пут-оферты (%s): %s годовых. Приём заявок открывается в период предъявления.%s"
                            % (nm, _tg_date(od), _tg_pct(it["new_rate"]), lk)))
            if ps and pe and ps <= today <= pe:
                out.append((base + "open", "🔔 <b>%s</b> — открыт приём заявок по пут-оферте: с %s по %s (выкуп %s). Заявку подаёт брокер.%s"
                            % (nm, _tg_date(ps), _tg_date(pe), _tg_date(od), lk)))
            if pe:
                left = _of_days(today, pe)
                if 0 <= left <= TG_OFR_CLOSE_DAYS and (not ps or ps <= today):
                    t = ("осталось %d дня подать заявку" % left if left >= 2 else "остался 1 день, чтобы подать заявку" if left == 1
                         else "сегодня последний день подачи заявки")
                    out.append((base + "close", "⏰ <b>%s</b> — %s на пут-оферту (последний день %s, выкуп %s).%s" % (nm, t, _tg_date(pe), _tg_date(od), lk)))
        elif kind == "call":
            left = _of_days(today, od)
            if 0 < left <= TG_OFR_CALL_DAYS:
                out.append((base + "call", "🔔 <b>%s</b> — возможное досрочное погашение (колл) %s, через %d дн. Решает эмитент, заявку подавать не нужно.%s"
                            % (nm, _tg_date(od), left, lk)))
    return out


def _tg_offer_items(cfg, today):
    """Оферты облигаций портфеля для напоминаний: ближайшие put (до TG_OFR_PUT_HORIZON дней) и call (до TG_OFR_CALL_DAYS)."""
    rows = [r for r in build_bonds(cfg, "all")["rows"]
            if isinstance(r.get("isin"), str) and re.fullmatch(r"[A-Z0-9]{6,16}", r["isin"]) and r.get("qty")]
    lim = _day_add(today, TG_OFR_PUT_HORIZON)

    def one(r):
        try:
            bz = moex_bondization(r["isin"])
            res = []
            for o in offer_kinds(bz or {}, moex_bond_options(r["isin"]), r.get("call"), today):
                if o["status"] == "cancelled" or o["kind"] == "unknown" or o["date"] > lim:
                    continue
                nc = of_new_coupon((bz or {}).get("coupons") or [], o["date"], r.get("nominal") or 1000.0, bool(r.get("floating")))
                res.append({"isin": r["isin"], "name": r.get("name"), "kind": o["kind"], "date": o["date"], "period_start": o.get("period_start"),
                            "period_end": o.get("period_end"), "coupon_status": nc["status"], "new_rate": nc["rate"]})
            return res
        except Exception:  # noqa: BLE001
            return []
    return [x for lst in pool_map(one, rows, workers=8) for x in lst]


def _tg_payments(cfg, days):
    b = build_bonds(cfg, "all")
    end = (date.today() + timedelta(days=days)).isoformat()
    today = date.today().isoformat()
    ev = [(p["date"], p.get("kind"), p.get("name"), p.get("amount")) for p in (b.get("payments") or []) if today <= p["date"] <= end]
    ev += [(r["call"], "offer", r.get("name"), None) for r in (b.get("rows") or []) if r.get("call") and today <= r["call"] <= end]
    return sorted(ev, key=lambda x: (x[0], str(x[2])))


_TG_EV = {"coupon": "купон", "dividend": "дивиденд", "amortization": "амортизация", "redemption": "погашение",
          "maturity": "погашение", "offer": "оферта", "call": "оферта CALL", "put": "оферта PUT", "buyback": "выкуп"}


def _tg_ev_line(e):
    """«20 ноября · <b>Выпуск</b> — купон, 5 000 ₽»."""
    amt = ", %s" % _tg_rub(e[3]) if e[3] else ""
    return "%s · <b>%s</b> — %s%s" % (_tg_date(e[0]), _tg_esc(e[2]), _TG_EV.get(e[1], "выплата"), amt)


def tg_pay_fresh(ev, sent):
    """Ещё не отправленные выплаты -> [(ключ «pay|дата|вид|название», событие)]. Зеркало на сервере — alerts.pay_fresh."""
    out = []
    for e in ev:
        k = "pay|%s|%s|%s" % (e[0], e[1], e[2])
        if k not in sent:
            out.append((k, e))
    return out


def tg_pay_text(days, fresh):
    return "%s\n\n%s" % (_tg_head("💰", "Ближайшие выплаты", "%d дн." % days), _tg_cap([_tg_ev_line(e) for k, e in fresh], 15))


def tg_digest_text(cfg):
    parts = [_tg_head("📈", "Сводка TAnalytic", _tg_date(date.today().isoformat()))]
    if cfg.get("token") or imports_list():
        try:
            s = build_summary(cfg, "all", "all")
            p = s.get("portfolio") or {}
            if p.get("total") is not None:
                d = p.get("daily")
                parts.append("💼 <b>Портфель</b> — %s%s" % (_tg_rub(p["total"]),
                             (" (за день %s%s)" % ("+" if d >= 0 else "−", _tg_rub(abs(d)))) if d is not None else ""))
        except Exception:  # noqa: BLE001
            pass
        try:
            ev = _tg_payments(cfg, 7)
            if ev:
                parts.append("💰 <b>Ближайшие 7 дней</b>\n" + _tg_cap([_tg_ev_line(e) for e in ev], 8))
            else:
                parts.append("💰 <b>Ближайшие 7 дней</b> — выплат нет")
        except Exception:  # noqa: BLE001
            pass
        try:
            m = build_monitor(cfg, "all")
            parts.append("🔔 <b>Мониторинг</b> — высоких тревог: %d, средних: %d" % (m["summary"]["high"], m["summary"]["medium"]))
        except Exception:  # noqa: BLE001
            pass
    try:
        w = watch_payload(cfg)
        if w["items"]:
            ln = ["<b>%s</b> — %s" % (_tg_esc(r["name"]), ("доходность %s" % _tg_pct(r["yield_"])) if r.get("yield_") is not None else "нет данных")
                  for r in w["items"]]
            parts.append("👁 <b>Наблюдение</b> (бумаг: %d, тревог: %d)\n%s" % (len(w["items"]), len(w["alerts"]), _tg_cap(ln, 8)))
    except Exception:  # noqa: BLE001
        pass
    return "\n\n".join(parts)


def tg_tick(force_digest=False, manual=False):
    """Одна проверка: новые тревоги, выплаты, ежедневная сводка. Возвращает число отправленных пунктов."""
    if not _tg_lock.acquire(False):
        return 0
    try:
        cfg = load_config()
        if not manual and not force_digest and not cfg.get("tg_enabled"):
            return 0
        if not all(ds_conf()):                  # нужен сервер данных и вход по ключу из бота
            return 0
        st = store()
        now = time.time()
        sent = {k: v for k, v in (st.get(TG_SENT_KEY) or {}).items() if now - v < 400 * DAY}
        n = 0
        srv = False
        try:        # серверная проверка: обновить подписку и не дублировать то, что отправит сервер
            if cfg.get("tg_server") and cfg.get("tg_enabled"):
                _tg_srv_sync(cfg, sent, force=not _tg_srv_boot[0])
                _tg_srv_boot[0] = True
            srv = tg_srv_active(cfg)
        except Exception:  # noqa: BLE001
            srv = tg_srv_active(cfg)
        has_port = bool(cfg.get("token") or imports_list())
        try:
            if cfg.get("tg_on_mon", True) and has_port:
                al = [a for a in build_monitor(cfg, "all")["alerts"] if a["severity"] == "high"]
                n += _tg_dispatch(cfg, "Тревоги по портфелю", al, sent, now)
        except Exception:  # noqa: BLE001
            pass
        try:
            if cfg.get("tg_on_mon", True) and has_port and not srv:
                today_ = date.today().isoformat()
                due = [(k, t) for k, t in tg_offer_due(_tg_offer_items(cfg, today_), today_) if k not in sent][:10]
                if due:
                    tg_send(cfg, _tg_head("🔔", "Оферты по портфелю") + "\n\n" + "\n\n".join(t for _k, t in due))
                    for k, _t in due:
                        sent[k] = now
                    n += len(due)
        except Exception:  # noqa: BLE001
            pass
        try:
            if cfg.get("tg_on_watch", True) and (watch_isins() or notes_all()):
                al = [a for a in watch_payload(cfg)["alerts"] if a["severity"] != "info"
                      and not (srv and a.get("kind") in TG_SRV_KINDS)]
                n += _tg_dispatch(cfg, "Наблюдение и цели", al, sent, now, icon="⭐")
        except Exception:  # noqa: BLE001
            pass
        try:        # крупные сделки и всплески объёма по бумагам списка (13v_flows.py; ключ дедупликации — id тревоги)
            if cfg.get("tg_on_watch", True) and watch_isins() and "flows_watch_alerts" in globals():
                n += _tg_dispatch(cfg, "Потоки по списку наблюдения", flows_watch_alerts(cfg), sent, now)
        except Exception:  # noqa: BLE001
            pass
        try:        # техдефолты/дефолты по бумагам портфеля и списка наблюдения + «исполнено» (13q_disclosure.py)
            if cfg.get("tg_on_mon", True) or cfg.get("tg_on_watch", True):
                n += _tg_dispatch(cfg, "Дефолты по бумагам портфеля и наблюдения", defaults_alerts(cfg, sent), sent, now)
        except Exception:  # noqa: BLE001
            pass
        try:
            days = int(cfg.get("tg_pay_days") or 0)
            if days > 0 and has_port and not srv:
                fresh = tg_pay_fresh(_tg_payments(cfg, days), sent)
                if fresh:
                    tg_send(cfg, tg_pay_text(days, fresh))
                    for k, e in fresh:
                        sent[k] = now
                    n += len(fresh)
        except Exception:  # noqa: BLE001
            pass
        try:
            state = st.get(TG_STATE_KEY) or {}
            hh = str(cfg.get("tg_digest_time") or "10:00")
            nowl = datetime.now()
            due = force_digest or (cfg.get("tg_digest") and state.get("digest") != date.today().isoformat()
                                   and nowl.strftime("%H:%M") >= hh)
            if due:
                tg_send(cfg, tg_digest_text(cfg))
                if not force_digest:
                    state["digest"] = date.today().isoformat()
                    st.put(TG_STATE_KEY, state)
                n += 1
        except Exception:  # noqa: BLE001
            pass
        st.put(TG_SENT_KEY, sent)
        return n
    except Exception:  # noqa: BLE001
        return 0            # сеть/Telegram недоступны — попробуем в следующий раз; детали (с токеном) не пишем
    finally:
        _tg_lock.release()


# ═══════════════ проверка на сервере, пока программа закрыта (по желанию, переключатель tg_server) ═══════════════
# Приложение отправляет на сервер данных «подписку» — только правила по публичным данным (см. tg_srv_payload и
# server/alerts.py): цели по бумагам наблюдения, даты напоминаний дневника (без текста), ближайшие оферты и выплаты
# по облигациям портфеля. Токен, номера счетов, стоимость портфеля и остатки денег не отправляются никогда.
# Пока режим включён и сервер принял подписку, эти виды (TG_SRV_KINDS, оферты, выплаты) шлёт только сервер — без дублей:
# ключи уже отправленного передаются в обе стороны (поле sent).

TG_SRV_KEY = "tg_srv_v1"
TG_SRV_KINDS = ("goal", "reminder")
TG_SRV_PREFIX = ("gy|", "gp|", "rm|", "ofr|", "pay|")
TG_SRV_REFRESH = 6 * 3600         # подписку с прежним содержимым обновляем не чаще раза в 6 ч (даты выплат, статус купона после оферты)
TG_SRV_PAY_EXTRA = 8              # выплаты — с запасом на срок жизни подписки (ключ из бота действует 7 дней)
_tg_srv_boot = [False]            # первая проверка после запуска синхронизирует подписку принудительно
_tg_srv_kick_on = [False]


def tg_srv_payload(cfg, sent):
    """Подписка для сервера. Только ISIN, названия бумаг, пороги, даты и суммы ближайших выплат; ничего о счетах."""
    today = date.today().isoformat()
    p = {"v": 1, "goals": [], "reminders": [], "offers": [], "pay_days": 0, "pays": [], "sent": [],
         "weekly_digest": bool(cfg.get("tg_weekly_digest", False))}
    if cfg.get("tg_on_watch", True):
        items = watch_items()
        notes = [n for n in notes_all() if n.get("remind_on")]
        sec = _scr_by_isin() if items or notes else {}
        for it in items:
            g = {k: it[k] for k in ("target_yield", "target_price") if it.get(k) is not None}
            if g:
                p["goals"].append(dict(g, isin=it["isin"], name=str(_bond_name(it["isin"], sec))[:120]))
        for n in notes:
            p["reminders"].append({"id": n["id"], "isin": n["isin"], "name": str(_bond_name(n["isin"], sec))[:120],
                                   "date": n["date"], "remind_on": n["remind_on"]})
    has_port = bool(cfg.get("token") or imports_list())
    if cfg.get("tg_on_mon", True) and has_port:
        try:
            p["offers"] = [{k: o.get(k) for k in ("isin", "name", "kind", "date", "period_start", "period_end", "coupon_status", "new_rate")}
                           for o in _tg_offer_items(cfg, today)]
        except Exception:  # noqa: BLE001
            pass
    days = int(cfg.get("tg_pay_days") or 0)
    if days > 0 and has_port:
        try:
            p["pays"] = [{"date": e[0], "kind": e[1], "name": str(e[2] or "")[:120], "amount": round(e[3], 2) if e[3] else None}
                         for e in _tg_payments(cfg, days + TG_SRV_PAY_EXTRA)][:1000]
            p["pay_days"] = days
        except Exception:  # noqa: BLE001
            pass
    for k in ("offers", "goals", "reminders"):
        p[k] = p[k][:300]
    p["sent"] = sorted(k for k in sent if k.startswith(TG_SRV_PREFIX))[-5000:]
    return p


def tg_srv_req(path, body=None, timeout=20):
    """{сервер}/v1/alerts/<path> -> (код, dict). GET без тела, иначе POST JSON. Бросает исключение при сетевой ошибке."""
    srv, key = ds_conf()
    if not srv or not key:
        raise ApiError("Нужен сервер данных и вход по ключу из бота.", 400)
    data = None if body is None else json.dumps(body, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(srv.rstrip("/") + "/v1/alerts/" + path, data=data, method="GET" if body is None else "POST",
                                 headers={"Content-Type": "application/json", "X-Client-Key": key, "User-Agent": EXT_UA["User-Agent"]})
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=_ssl()) as r:
            code, raw = r.status, r.read()
    except urllib.error.HTTPError as e:
        code, raw = e.code, e.read()
    try:
        j = json.loads(raw.decode("utf-8", "replace"))
    except ValueError:
        j = None
    return code, (j if isinstance(j, dict) else {})


_TG_SRV_ERR = {404: "Сервер данных пока не поддерживает проверку тревог — уведомления отправляет программа, пока она запущена.",
               402: "Проверка на сервере доступна в тарифе Pro.", 401: "Войдите по ключу из бота.", 403: "Войдите по ключу из бота.",
               429: "Слишком частые обновления, повторим позже.",
               409: "Проверка на сервере остановлена в боте (/alerts). Чтобы возобновить, снова включите её здесь."}


def _tg_srv_state():
    return dict(store().get(TG_SRV_KEY) or {})


def tg_srv_active(cfg):
    """Сервер принял подписку и сам шлёт TG_SRV_KINDS, оферты и выплаты: программе их отправлять не нужно."""
    return bool(cfg.get("tg_server") and cfg.get("tg_enabled") and _tg_srv_state().get("active"))


def _tg_srv_merge(sent, keys, now):
    for k in keys or []:
        if isinstance(k, str) and k.startswith(TG_SRV_PREFIX):
            sent.setdefault(k, now)


def _tg_srv_merge_goals(goals, deleted=None):
    """Вливает цели, изменённые в боте, в локальный WATCH_KEY, не перезаписывая локальные поля (note, added и т. д.).
    Снимает цели только у ISIN, явно удалённых в боте (deleted): отсутствие бумаги в ответе сервера — не удаление."""
    if not isinstance(goals, list):
        return False
    deleted = {i for i in (_isin_ok(x) for x in (deleted or []) if isinstance(x, str)) if i}
    by_isin = {}
    for g in goals:
        if not isinstance(g, dict):
            continue
        isin = _isin_ok(g.get("isin"))
        if isin:
            by_isin[isin] = g
    changed = False
    with _watch_lock:
        items = watch_items()
        cur_by = {x["isin"]: x for x in items}
        today = date.today().isoformat()
        for isin, g in by_isin.items():
            cur = cur_by.get(isin)
            if cur is None:
                cur = {"isin": isin, "added": today}
                items.append(cur)
                cur_by[isin] = cur
                changed = True
            for k in ("target_yield", "target_price"):
                if k not in g:
                    v = None
                else:
                    v = _num(g[k]) if g[k] is not None and str(g[k]).strip() != "" else None
                    if v is not None and v <= 0:
                        v = None
                if v is None:
                    if k in cur:
                        cur.pop(k, None)
                        changed = True
                else:
                    rv = round(v, 4)
                    if cur.get(k) != rv:
                        cur[k] = rv
                        changed = True
        kept = []
        for x in items:
            if x["isin"] in deleted and x["isin"] not in by_isin and ("target_yield" in x or "target_price" in x):
                x.pop("target_yield", None)
                x.pop("target_price", None)
                changed = True
                if not x.get("note"):
                    continue
            kept.append(x)
        items = kept
        if changed:
            store().put(WATCH_KEY, items)
    if changed:
        mem_clear_watch()
    return changed


def _tg_srv_sync(cfg, sent, force=False, resume=False):
    """Отправляет подписку, если она изменилась, устарела или force. Состояние — в TG_SRV_KEY. -> True, если подписка на сервере.
    resume=True — только по явному включению пользователем: снимает остановку, сделанную в боте (/alerts)."""
    st, now = _tg_srv_state(), time.time()
    p = tg_srv_payload(cfg, sent)
    if resume:
        p["resume"] = True
    p["bot_goals_rev"] = int((st or {}).get("bot_goals_rev") or 0)
    h = hashlib.sha256(json.dumps({k: v for k, v in p.items() if k not in ("sent", "resume")}, sort_keys=True).encode("utf-8")).hexdigest()
    if not force and st.get("active") and st.get("hash") == h and now - (st.get("ok") or 0) < TG_SRV_REFRESH:
        return True
    try:
        code, j = tg_srv_req("sync", p)
    except ApiError as e:
        st.update(err=str(e), at=now)
        store().put(TG_SRV_KEY, st)
        return bool(st.get("active"))
    except Exception:  # noqa: BLE001
        st.update(err="Сервер недоступен, повторим при следующей проверке.", at=now)
        store().put(TG_SRV_KEY, st)
        return bool(st.get("active"))      # сервер недоступен: и программа отправить не сможет (уведомления идут через него)
    if code == 200 and j.get("ok"):
        _tg_srv_merge(sent, j.get("sent"), now)
        rev, prev_rev = j.get("bot_goals_rev"), st.get("bot_goals_rev")
        # цели из бота вливаем, только если программа сама отправляет цели (иначе пустой список в ответе ничего не значит)
        if cfg.get("tg_on_watch", True) and isinstance(j.get("goals"), list) and rev is not None and rev != (prev_rev or 0):
            _tg_srv_merge_goals(j["goals"], j.get("bot_deleted"))
        st = {"active": True, "ok": now, "hash": h, "err": "", "at": now, "counts": j.get("counts") or {}}
        if rev is not None:
            st["bot_goals_rev"] = rev
        elif prev_rev is not None:
            st["bot_goals_rev"] = prev_rev
    else:
        st.update(err=_TG_SRV_ERR.get(code) or "Сервер не принял подписку (код %s)." % code, at=now)
        if code in (400, 401, 402, 403, 404, 409, 413):     # подписки на сервере нет или она не действует: отправляет программа
            st["active"] = False
        if code == 409:                                     # остановлено в боте: режим выключаем, пока пользователь не включит снова
            c = load_config()
            c["tg_server"] = False
            save_config(c)
    store().put(TG_SRV_KEY, st)
    return bool(st.get("active"))


def tg_srv_delete(sent=None):
    """Удаляет подписку с сервера; ключи отправленного сервером переносятся к себе, чтобы программа их не повторила."""
    try:
        code, j = tg_srv_req("delete", {})
    except ApiError:
        raise
    except Exception:  # noqa: BLE001
        raise ApiError("Сервер недоступен — данные не удалены. Они удалятся автоматически, когда истечёт ключ из бота.", 502)
    if code == 404:
        store().put(TG_SRV_KEY, {})
        return {"deleted": False}
    if code != 200 or not j.get("ok"):
        raise ApiError(_TG_SRV_ERR.get(code) or "Не удалось удалить данные с сервера (код %s)." % code, 502)
    own = sent is None
    if own:
        sent = dict(store().get(TG_SENT_KEY) or {})
    _tg_srv_merge(sent, j.get("sent"), time.time())
    if own:
        store().put(TG_SENT_KEY, sent)
    store().put(TG_SRV_KEY, {})
    return {"deleted": bool(j.get("deleted"))}


def tg_srv_kick():
    """После изменения списка наблюдения, дневника или настроек — обновить подписку в фоне (через 3 с, одним потоком)."""
    try:
        cfg = load_config()
    except Exception:  # noqa: BLE001
        return
    if not (cfg.get("tg_server") and cfg.get("tg_enabled")) or _tg_srv_kick_on[0]:
        return
    _tg_srv_kick_on[0] = True

    def run():
        try:
            time.sleep(3)
            if _tg_lock.acquire(timeout=120):
                try:
                    st = store()
                    sent = dict(st.get(TG_SENT_KEY) or {})
                    _tg_srv_sync(load_config(), sent, force=True)
                    st.put(TG_SENT_KEY, sent)
                finally:
                    _tg_lock.release()
        except Exception:  # noqa: BLE001
            pass
        finally:
            _tg_srv_kick_on[0] = False
    threading.Thread(target=run, daemon=True, name="tg-srv-sync").start()


def tg_srv_get(cfg, acc, q, force):
    st = _tg_srv_state()
    return {"enabled": bool(cfg.get("tg_server")), "active": tg_srv_active(cfg), "ok": st.get("ok"), "error": st.get("err") or "",
            "counts": st.get("counts") or {}}


def tg_srv_post(cfg, body):
    """{action: sync|delete}. sync — сразу отправить подписку; delete — удалить данные с сервера и выключить режим."""
    act = str(body.get("action") or "")
    if act == "delete":
        c = load_config()
        c["tg_server"] = False          # сначала выключаем режим: даже если сервер недоступен, новых данных туда не уйдёт
        save_config(c)
        with _tg_lock:
            r = tg_srv_delete()
        return dict(r, ok=True)
    if act == "sync":
        c = load_config()
        if not (c.get("tg_server") and c.get("tg_enabled")):
            raise ApiError("Включите уведомления и проверку на сервере.", 400)
        with _tg_lock:
            st = store()
            sent = dict(st.get(TG_SENT_KEY) or {})
            ok = _tg_srv_sync(c, sent, force=True, resume=True)
            st.put(TG_SENT_KEY, sent)
        s_ = _tg_srv_state()
        if not ok:
            raise ApiError(s_.get("err") or "Сервер не принял подписку.", 502)
        return {"ok": True, "counts": s_.get("counts") or {}}
    raise ApiError("Неизвестное действие.", 400)


API_GET["/api/tg/server"] = tg_srv_get
API_POST["/api/tg/server"] = tg_srv_post


def _tg_loop():
    time.sleep(90)
    while True:
        try:
            tg_tick()
        except Exception:  # noqa: BLE001
            pass
        time.sleep(int(os.environ.get("TINVEST_TG_PERIOD") or 720))


def tg_start():
    _tg_cleanup()
    threading.Thread(target=_tg_loop, daemon=True, name="tg-notify").start()


STARTUP_HOOKS.append(tg_start)
# ═══════════════════════════════ налоги по лотам: ЛДВ, ИИС, перенос убытков, подсказки ═══════════════════════════════
# Справочный расчёт. Брокер как налоговый агент считает сам; это не налоговая консультация.
# Лоты покупок по каждой бумаге и счёту, продажи списываются FIFO; комиссии входят в расходы; НКД при покупке/продаже
# учитывается отдельно (уменьшает/увеличивает купонный доход); частичные погашения (амортизация) уменьшают стоимость лотов.

TAX_LDV_TYPES = ("share", "bond", "etf")
TAX_SKIP_TYPES = ("currency", "futures", "dfa")
TAX_LDV_FROM = date(2014, 1, 1)
TAX_LDV_LIMIT = 3000000.0
TAX_IIS_LIMIT = 400000.0
TAX_IIS3_EXEMPT_LIMIT = 30000000.0   # ст. 219.2 НК РФ: предел освобождаемого финансового результата по ИИС-3 за весь срок
TAX_SETTINGS_KEY = "tax:settings"
TAX_SPREAD = 0.001


def tx_add_years(d, n):
    try:
        return d.replace(year=d.year + n)
    except ValueError:
        return date(d.year + n, 3, 1)


def tx_full_years(d0, d1):
    y = d1.year - d0.year
    if (d1.month, d1.day) < (d0.month, d0.day):
        y -= 1
    return max(0, y)


def tx_ldv_ok(bd, sd):
    """ЛДВ: куплено с 01.01.2014 и продано строго позже третьей годовщины покупки."""
    return bd is not None and bd >= TAX_LDV_FROM and sd > tx_add_years(bd, 3)


def tx_ndfl(base, year):
    """(налог, часть по 13 %, часть по 15 %): до 2021 — 13 %; 2021–2024 — 15 % свыше 5 млн; с 2025 — 15 % свыше 2,4 млн."""
    base = max(0.0, base)
    if year < 2021:
        return base * 0.13, base, 0.0
    thr = 5000000.0 if year < 2025 else 2400000.0
    lo, hi = min(base, thr), max(0.0, base - thr)
    return lo * 0.13 + hi * 0.15, lo, hi


# ── курсы ЦБ ──

_cbr_mem = {}


def tax_cbr_rate(cur, iso):
    """Курс ЦБ РФ за 1 единицу валюты на дату (ISO). Прошлые даты кэшируются навсегда. None — курс недоступен."""
    cur = (cur or "").upper()
    if cur in ("", "RUB"):
        return 1.0
    key = "cbr:" + iso
    tab = _cbr_mem.get(key)
    if tab is None:
        try:
            tab = store().get(key)
        except Exception:  # noqa: BLE001
            tab = None
    if tab is None:
        try:
            d = datetime.strptime(iso, "%Y-%m-%d")
            raw = http_bytes("https://www.cbr.ru/scripts/XML_daily.asp?date_req=" + d.strftime("%d/%m/%Y"), 20).decode("windows-1251", "replace")
        except Exception:  # noqa: BLE001
            return None
        tab = {}
        for m in re.finditer(r"<CharCode>([A-Z]{3})</CharCode>\s*<Nominal>(\d+)</Nominal>\s*<Name>.*?</Name>\s*<Value>([\d,]+)</Value>", raw, re.S):
            try:
                tab[m.group(1)] = float(m.group(3).replace(",", ".")) / int(m.group(2))
            except ValueError:
                pass
        if not tab:
            return None
        _cbr_mem[key] = tab
        if iso < date.today().isoformat():
            try:
                store().put(key, tab)
            except Exception:  # noqa: BLE001
                pass
    return tab.get(cur)


# ── настройки ──

def tax_settings():
    s = {}
    try:
        s = store().get(TAX_SETTINGS_KEY) or {}
    except Exception:  # noqa: BLE001
        pass
    iis = {}
    for k, v in (s.get("iis") or {}).items():
        if isinstance(v, dict):
            iis[str(k)] = {"type": v.get("type") if v.get("type") in ("A", "B", "3") else "", "opened": str(v.get("opened") or "")[:10]}
    carry = {}
    for k, v in (s.get("loss_carry") or {}).items():
        try:
            if int(k) > 1990 and float(v) > 0:
                carry[str(int(k))] = round(float(v), 2)
        except (TypeError, ValueError):
            pass
    return {"iis": iis, "loss_carry": carry, "offset_coupons": bool(s.get("offset_coupons")),
            "ndfl_rate": 15 if str(s.get("ndfl_rate")) in ("15", "0.15") else 13}


def mem_clear_tax():
    with _mem_lock:
        for k in [k for k in _mem if isinstance(k, tuple) and k and k[0] == "taxst"]:
            _mem.pop(k, None)


def tax_settings_save(cfg, body):
    cur = tax_settings()
    if isinstance(body.get("iis"), dict):
        for k, v in body["iis"].items():
            if isinstance(v, dict):
                op = str(v.get("opened") or "")[:10]
                if op:
                    try:
                        datetime.strptime(op, "%Y-%m-%d")
                    except ValueError:
                        raise ApiError("Дата открытия ИИС должна быть в формате ГГГГ-ММ-ДД", 400)
                cur["iis"][str(k)] = {"type": v.get("type") if v.get("type") in ("A", "B", "3") else "", "opened": op}
    if "ndfl_rate" in body:
        cur["ndfl_rate"] = 15 if str(body["ndfl_rate"]).strip() in ("15", "0.15") else 13
    if "offset_coupons" in body:
        cur["offset_coupons"] = bool(body["offset_coupons"])
    if isinstance(body.get("loss_carry"), dict):
        cur["loss_carry"] = {}
        for k, v in body["loss_carry"].items():
            try:
                y, a = int(k), float(str(v).replace(",", ".").replace(" ", ""))
            except (TypeError, ValueError):
                raise ApiError("Убытки прошлых лет: год и сумма должны быть числами", 400)
            if y < 1990 or y > 2100 or a < 0:
                raise ApiError("Некорректный год или сумма убытка", 400)
            if a > 0:
                cur["loss_carry"][str(y)] = round(a, 2)
    store().put(TAX_SETTINGS_KEY, cur)
    mem_clear_tax()
    return tax_settings()


# ── движок лотов ──

def tx_sell(lots, q, proceeds, fee, sd, base):
    """Списывает q штук из lots по FIFO (мутирует lots). Возвращает (строки продаж, непокрытый остаток)."""
    rows, left = [], float(q)
    up = proceeds / q if q else 0.0
    uf = fee / q if q else 0.0
    can_ldv = base.get("bucket") == "sec" and base.get("type") in TAX_LDV_TYPES
    while left > 1e-9 and lots:
        lot = lots[0]
        t = min(left, lot["qty"])
        r = dict(base)
        r.update(qty=t, bdate=lot["date"], proceeds=t * up, cost=t * lot["unit"], fee=t * uf)
        r["result"] = r["proceeds"] - r["cost"] - r["fee"]
        ok = can_ldv and not lot.get("blind") and tx_ldv_ok(lot["date"], sd)
        r["ldv"] = bool(ok)
        r["yrs"] = tx_full_years(lot["date"], sd) if ok else 0
        rows.append(r)
        lot["qty"] -= t
        left -= t
        if lot["qty"] <= 1e-9:
            lots.pop(0)
    return rows, left


def tx_inc_new():
    return defaultdict(float)


def tax_engine(ops, types=None, fx=None, held=None):
    """ops — операции (с полем _acc). types — {uid: info} (type), fx(cur, iso_day) -> курс или None, held — {uid: кол-во}
    из текущих позиций (для сверки лотов). Возвращает продажи, остатки лотов и денежные потоки по (счёт, год)."""
    types = types or {}
    warns = {}
    fx = fx or (lambda cur, day: 1.0 if cur in ("", "rub", "sur") else None)

    def rate(cur, d):
        if cur in ("", "rub", "sur"):
            return 1.0
        r = fx(cur, d.isoformat())
        if not r:
            warns["fx_" + cur] = "Нет курса ЦБ для %s на часть дат — взят курс 1." % cur.upper()
            return 1.0
        return r

    ops = sorted([o for o in ops if not str(o.get("state") or "").endswith("CANCELED")], key=lambda o: o.get("date") or "")
    fee_parent, fee_key = defaultdict(float), defaultdict(float)

    def fee_k(o):
        return (o.get("_acc") or "", (o.get("date") or "")[:19], o.get("instrumentUid") or o.get("figi") or o.get("_ident") or "")

    for o in ops:
        if classify(o.get("type")) == "fee_broker":
            dt = parse_dt(o.get("date"))
            amt = abs(qf(o.get("payment"))) * rate(cur_of(o.get("payment")), dt.date())
            if o.get("parentOperationId"):
                fee_parent[o["parentOperationId"]] += amt
            else:
                fee_key[fee_k(o)] += amt

    # Без parentOperationId комиссии в одной секунде делятся между сделками без собственной комиссии пропорционально обороту
    fee_trades = defaultdict(list)
    for idx, o in enumerate(ops):
        if classify(o.get("type")) in ("buy", "sell"):
            c = o.get("commission")
            if (c and qf(c)) or (o.get("id") and o["id"] in fee_parent):
                continue
            uid = o.get("instrumentUid") or o.get("figi") or o.get("_ident") or ""
            info = types.get(uid) or {}
            itype = o.get("instrumentType") or info.get("type") or ""
            itype = {"bonds": "bond", "shares": "share"}.get(itype, itype) or "share"
            if itype != "futures" and (itype in TAX_SKIP_TYPES or not uid or not op_qty(o)):
                continue
            k = fee_k(o)
            if k in fee_key:
                dt = parse_dt(o.get("date"))
                fee_trades[k].append((idx, abs(qf(o.get("payment"))) * rate(cur_of(o.get("payment")), dt.date())))

    fee_alloc = {}
    for k, items in fee_trades.items():
        tot_fee = fee_key.get(k, 0.0)
        if not tot_fee or not items:
            continue
        tot_turn = sum(tr for _, tr in items)
        left_fee = tot_fee
        for i, (idx, tr) in enumerate(items):
            if i == len(items) - 1:
                part = left_fee
            elif tot_turn > 0:
                part = min(left_fee, tot_fee * (tr / tot_turn))
            else:
                part = min(left_fee, tot_fee / len(items))
            fee_alloc[idx] = part
            left_fee -= part

    def fee_of(idx, o, dt):
        c = o.get("commission")
        if c and qf(c):
            return abs(qf(c)) * rate(cur_of(c), dt.date())
        if o.get("id") and o["id"] in fee_parent:
            return fee_parent[o["id"]]
        return fee_alloc.pop(idx, 0.0)

    books, sales, meta = {}, [], {}
    moved, convs = {}, []
    inc = defaultdict(tx_inc_new)
    payouts = []
    turn = [0.0, 0.0]

    pay_tax_parent = defaultdict(list)
    pay_tax_key = defaultdict(list)
    for o in ops:
        tk = classify(o.get("type"))
        if tk in ("tax_dividend", "tax_coupon"):
            dt = parse_dt(o.get("date"))
            td = dt.date()
            tcur = cur_of(o.get("payment"))
            tamt = abs(qf(o.get("payment")))
            trub = tamt * rate(tcur, td)
            pkind = "dividends" if tk == "tax_dividend" else "coupons"
            if o.get("parentOperationId"):
                pay_tax_parent[o["parentOperationId"]].append((tcur, tamt, trub))
            else:
                tuid = o.get("instrumentUid") or o.get("figi") or o.get("_ident") or ""
                pay_tax_key[(o.get("_acc") or "", td.isoformat(), tuid, pkind)].append((tcur, tamt, trub))

    for idx, o in enumerate(ops):
        kind = classify(o.get("type"))
        acc = o.get("_acc") or ""
        dt = parse_dt(o.get("date"))
        d = dt.date()
        uid = o.get("instrumentUid") or o.get("figi") or o.get("_ident") or ""
        info = types.get(uid) or {}
        itype = o.get("instrumentType") or info.get("type") or ""
        itype = {"bonds": "bond", "shares": "share"}.get(itype, itype) or "share"
        pay = qf(o.get("payment"))
        cur = cur_of(o.get("payment"))
        raw_fx = 1.0 if cur in ("", "rub", "sur") else fx(cur, d.isoformat())
        r = rate(cur, d)
        I = inc[(acc, d.year)]
        if uid and kind in ("buy", "sell", "sec_in", "repayments") and uid not in meta:
            meta[uid] = {"name": info.get("name") or o.get("name") or o.get("ticker") or uid, "ticker": info.get("ticker") or o.get("ticker") or "", "type": itype}
        if kind in ("dividends", "coupons"):
            if kind == "dividends":
                I["div"] += pay * r
            else:
                I["coupon"] += pay * r
            matched = []
            if o.get("id") and o["id"] in pay_tax_parent:
                matched = pay_tax_parent.pop(o["id"])
            elif pay_tax_key.get((acc, d.isoformat(), uid, kind)):
                matched = [pay_tax_key[(acc, d.isoformat(), uid, kind)].pop(0)]
            tax_orig = sum(a for tc, a, _ in matched if tc == cur)
            tax_rub = sum(tr for _, _, tr in matched)
            src_note = "Рублёвая выплата" if cur in ("", "rub", "sur") else ("ЦБ РФ на дату выплаты" if raw_fx else "Курс ЦБ не найден (взят 1.0)")
            payouts.append({
                "id": o.get("id") or "", "acc": acc, "date": d.isoformat(), "year": d.year, "uid": uid,
                "name": info.get("name") or o.get("name") or o.get("ticker") or uid or "—",
                "ticker": info.get("ticker") or o.get("ticker") or "",
                "kind": "div" if kind == "dividends" else "coupon",
                "cur": (cur or "rub").upper(), "amount": pay, "rate": r, "amount_rub": pay * r,
                "tax_orig": tax_orig, "tax_rub": tax_rub, "source": src_note,
            })
        elif kind == "overnight":
            I["over"] += pay * r
        elif kind in TAXES:
            I["withheld"] += -pay * r
            I["w_" + kind] += -pay * r
        elif kind == "deposits":
            I["dep"] += abs(pay) * r
        elif kind == "withdrawals":
            I["wd"] += abs(pay) * r
        elif kind == "varmargin":
            I["deriv"] += pay * r
        elif kind in ("buy", "sell"):
            q = op_qty(o)
            fee = fee_of(idx, o, dt)
            if itype == "futures":
                I["deriv_fee"] += fee
                continue
            if itype in TAX_SKIP_TYPES or not uid or not q:
                continue
            bucket = "deriv" if itype == "option" else "sec"
            nkd = abs(qf(o.get("accruedInt"))) if o.get("accruedInt") else 0.0
            gross = abs(pay)
            clean = gross - nkd
            if clean < 0:
                clean, nkd = gross, 0.0
            bk = books.setdefault((acc, uid), {"lots": [], "shorts": [], "last_repay": None, "last_unit": 0.0})
            base = {"acc": acc, "uid": uid, "name": meta[uid]["name"], "ticker": meta[uid]["ticker"], "type": itype, "bucket": bucket,
                    "kind": "sell", "sdate": d, "bdate": None}
            turn[0] += gross * r
            turn[1] += fee
            if kind == "buy":
                I["nkd_paid"] += nkd * r
                left = float(q)
                unit_buy = (clean * r + fee) / q
                bk["last_unit"] = unit_buy
                sh = bk["shorts"]
                while left > 1e-9 and sh:
                    s = sh[0]
                    t = min(left, s["qty"])
                    row = dict(base, kind="short", qty=t, bdate=s["date"], sdate=d, proceeds=t * s["up"], cost=t * unit_buy, fee=t * s["uf"], ldv=False, yrs=0)
                    row["result"] = row["proceeds"] - row["cost"] - row["fee"]
                    sales.append(row)
                    s["qty"] -= t
                    left -= t
                    if s["qty"] <= 1e-9:
                        sh.pop(0)
                if left > 1e-9:
                    bk["lots"].append({"qty": left, "unit": unit_buy, "date": d, "cur": cur})
            else:
                I["nkd_recv"] += nkd * r
                yv = o.get("yield")
                if yv and itype != "option":
                    I["bk_yield"] += qf(yv) * rate(cur_of(yv, cur), d)
                rows, left = tx_sell(bk["lots"], q, clean * r, fee, d, base)
                sales.extend(rows)
                if left > 1e-9:
                    warns["short"] = "Есть продажи без покупок в истории (короткие позиции или переводы): учтены упрощённо."
                    bk["shorts"].append({"qty": left, "up": clean * r / q, "uf": fee / q, "date": d})
        elif kind == "sec_in":
            q = op_qty(o)
            if not uid or not q or itype in TAX_SKIP_TYPES:
                continue
            bk = books.setdefault((acc, uid), {"lots": [], "shorts": [], "last_repay": None, "last_unit": 0.0})
            unit = qf(o.get("price")) * rate(cur_of(o.get("price"), cur), d) if o.get("price") and qf(o.get("price")) else (abs(pay) * r / q if pay else bk["last_unit"])
            if not unit:
                warns["unk_cost"] = "У бумаг, зачисленных переводом, нет цены: стоимость принята нулевой (прибыль завышена)."
            bk["lots"].append({"qty": float(q), "unit": unit, "date": d, "cur": cur, "blind": True})
        elif kind == "conv_out":
            # Обмен бумаг (ГДР/АДР на акции российского МКПАО, смена кода и т.п.) не продажа: лоты старой бумаги уходят в «карман» обмена
            cv = o.get("_conv") or {}
            lots, left = [], float(op_qty(o))
            for u in cv.get("old_uids") or [uid]:
                bk = books.get((acc, u))
                while bk and bk["lots"] and left > 1e-9:
                    lot = bk["lots"][0]
                    t = min(left, lot["qty"])
                    lots.append(dict(lot, qty=t))
                    lot["qty"] -= t
                    left -= t
                    if lot["qty"] <= 1e-9:
                        bk["lots"].pop(0)
            lots.sort(key=lambda l: l["date"])
            moved[o.get("id")] = lots
        elif kind == "conv_in":
            # Лоты переходят в новую бумагу: количество × коэффициент, цена за штуку / коэффициент, даты покупки сохраняются.
            # По закону о редомициляции обмен депозитарных расписок на акции не считается реализацией, срок владения для ЛДВ
            # продолжается, поэтому дата покупки не обнуляется.
            cv = o.get("_conv") or {}
            ratio = cv.get("ratio") or 1
            lots = moved.pop((o.get("id") or "")[:-3] + ":out", [])
            left = float(op_qty(o))
            bk = books.setdefault((acc, uid), {"lots": [], "shorts": [], "last_repay": None, "last_unit": 0.0})
            for lot in lots:
                t = min(left, lot["qty"] * ratio)
                if t > 1e-9:
                    bk["lots"].append(dict(lot, qty=t, unit=lot["unit"] / ratio))
                    left -= t
            bk["lots"].sort(key=lambda l: l["date"])
            if uid not in meta:
                meta[uid] = {"name": info.get("name") or cv.get("new_ticker") or uid, "ticker": info.get("ticker") or cv.get("new_ticker") or "", "type": itype}
            convs.append(cv)
        elif kind == "sec_out":
            q = op_qty(o)
            bk = books.get((acc, uid))
            if bk and q:
                tx_sell(bk["lots"], q, 0.0, 0.0, d, {"bucket": "none"})
        elif kind == "repayments":
            bk = books.get((acc, uid))
            amount = abs(pay) * r
            if not bk or not bk["lots"] or itype in TAX_SKIP_TYPES:
                if amount:
                    warns["repay_nolots"] = "Погашение/амортизация по бумаге без покупок в истории — не учтено в расходах."
                continue
            base = {"acc": acc, "uid": uid, "name": meta.get(uid, {}).get("name", ""), "ticker": meta.get(uid, {}).get("ticker", ""),
                    "type": itype, "bucket": "sec", "kind": "repay", "sdate": d, "bdate": None}
            tq = sum(l["qty"] for l in bk["lots"])
            if op_type(o) == "BOND_REPAYMENT_FULL":
                rows, _ = tx_sell(bk["lots"], tq, amount, 0.0, d, base)
                sales.extend(rows)
            else:
                bk["last_repay"] = d
                red = amount / tq if tq else 0.0
                excess = 0.0
                for l in bk["lots"]:
                    if l["unit"] >= red:
                        l["unit"] -= red
                    else:
                        excess += (red - l["unit"]) * l["qty"]
                        l["unit"] = 0.0
                if excess > 0.005:
                    sales.append(dict(base, kind="amort", qty=0.0, proceeds=excess, cost=0.0, fee=0.0, result=excess, ldv=False, yrs=0))
    # сверка с текущими позициями: лишние лоты (проданные/погашенные вне истории) списываются
    if held is not None:
        by_uid = defaultdict(list)
        for (acc, uid), bk in books.items():
            by_uid[uid].append((acc, bk))
        for uid, lst in by_uid.items():
            have = held.get(uid, 0.0)
            tot = sum(l["qty"] for _, bk in lst for l in bk["lots"])
            if tot <= have + 0.5:
                if have - tot > 0.5:
                    warns["more_pos"] = "В позициях бумаг больше, чем в истории покупок: часть бумаг без даты и цены покупки."
                continue
            extra = tot - have
            for acc, bk in lst:
                if extra <= 1e-9:
                    break
                lr = bk["last_repay"]
                if have <= 0.5 and lr is not None and bk["lots"]:
                    cost = sum(l["qty"] * l["unit"] for l in bk["lots"])
                    qq = sum(l["qty"] for l in bk["lots"])
                    mt = meta.get(uid, {})
                    if cost > 0.005:
                        sales.append({"acc": acc, "uid": uid, "name": mt.get("name", ""), "ticker": mt.get("ticker", ""), "type": mt.get("type", "bond"),
                                      "bucket": "sec", "kind": "writeoff", "sdate": lr, "bdate": None, "qty": qq, "proceeds": 0.0, "cost": cost,
                                      "fee": 0.0, "result": -cost, "ldv": False, "yrs": 0})
                    extra -= qq
                    bk["lots"] = []
                else:
                    n = min(extra, sum(l["qty"] for l in bk["lots"]))
                    tx_sell(bk["lots"], n, 0.0, 0.0, date.today(), {"bucket": "none"})
                    extra -= n
                    warns["gap"] = "Часть бумаг исчезла из позиций без операций продажи (например, конвертация или перевод) — лоты списаны без финрезультата."
    opens = []
    for (acc, uid), bk in books.items():
        for l in bk["lots"]:
            if l["qty"] > 1e-9:
                mt = meta.get(uid, {})
                opens.append({"acc": acc, "uid": uid, "name": mt.get("name", ""), "ticker": mt.get("ticker", ""), "type": mt.get("type", "share"),
                              "qty": l["qty"], "unit": l["unit"], "date": l["date"], "blind": bool(l.get("blind")), "cur": l.get("cur", "rub")})
    return {"sales": sales, "open": opens, "inc": dict(inc), "payouts": payouts, "meta": meta, "warnings": sorted(warns.values()),
            "fee_rate": (turn[1] / turn[0]) if turn[0] > 0 else 0.003}


# ── налоговая база по годам для группы счетов ──

def tx_apply_carry(pool, trade_t, year=9999):
    """Погашает положительный результат убытками прошлых лет (старые — первыми). Возвращает (использовано, остаток базы)."""
    used = 0.0
    if trade_t > 0:
        for p in sorted([p for p in pool if p[0] < year], key=lambda p: p[0]):
            u = min(p[1], trade_t - used)
            if u > 0:
                p[1] -= u
                used += u
    return used, max(0.0, trade_t - used)


def tax_group_years(sales, inc, carry_user=None, iis_exempt=False, extra=None, offset_coupons=False,
                    iis_limit=TAX_IIS3_EXEMPT_LIMIT):
    """sales — строки продаж группы; inc — {год: суммы}; carry_user — {"2023": сумма} убытки прошлых лет из деклараций.
    Возвращает (строки по годам, остатки убытков [[год, сумма]])."""
    sales = list(sales) + list(extra or [])
    carry_user = carry_user or {}
    ys = set(r["sdate"].year for r in sales) | set(inc)
    pool = []
    for k, v in carry_user.items():
        if int(k) not in ys:
            pool.append([int(k), float(v)])
    rows, nkd_pool = [], 0.0
    iis_left = iis_limit
    for y in sorted(ys):
        i = inc.get(y, {})
        sec = [s for s in sales if s["bucket"] == "sec" and s["sdate"].year == y]
        dv = [s for s in sales if s["bucket"] == "deriv" and s["sdate"].year == y]
        trade = sum(s["result"] for s in sec)
        elig = [s for s in sec if s["ldv"]]
        elig_res = sum(s["result"] for s in elig)
        wc = sum(max(s["cost"], 0.0) for s in elig)
        wy = (sum(max(s["cost"], 0.0) * s["yrs"] for s in elig) / wc) if wc > 0 else (sum(s["yrs"] for s in elig) / len(elig) if elig else 0.0)
        limit = TAX_LDV_LIMIT * wy
        exempt = min(max(0.0, elig_res), limit)
        pool = [p for p in pool if y - p[0] <= 10 and p[1] > 0.005]
        pool_before = [list(p) for p in pool]
        div = i.get("div", 0.0)
        cg = i.get("coupon", 0.0) + i.get("nkd_recv", 0.0)
        avail = nkd_pool + i.get("nkd_paid", 0.0)
        un = min(avail, max(0.0, cg))
        coupon_net = cg - un
        nkd_pool = avail - un
        trade_t = trade - exempt
        coff = 0.0
        if offset_coupons and trade_t < 0 and coupon_net > 0:
            coff = min(coupon_net, -trade_t)
            coupon_net -= coff
            trade_t += coff
        used, trade_base = tx_apply_carry(pool, trade_t, y)
        new_loss = -trade_t if trade_t < 0 else 0.0
        if str(y) in carry_user:
            new_loss = float(carry_user[str(y)])
        if new_loss > 0.005:
            pool.append([y, new_loss])
        over = i.get("over", 0.0)
        deriv = sum(s["result"] for s in dv) + i.get("deriv", 0.0) - i.get("deriv_fee", 0.0)
        base = trade_base + div + coupon_net + over + max(0.0, deriv)
        tax, lo, hi = tx_ndfl(base, y)
        iis_used = 0.0
        if iis_exempt:
            # вычет ИИС-Б / ИИС-3 не освобождает дивиденды; лимит 30 млн действует только на ИИС-3
            exempt_base = min(max(0.0, base), max(0.0, trade_base + coupon_net + over + max(0.0, deriv)))
            iis_used = exempt_base if iis_left is None else min(exempt_base, iis_left)
            if iis_left is not None:
                iis_left -= iis_used
            tax, lo, hi = tx_ndfl(base - iis_used, y)
        saved = 0.0
        if exempt > 0.005 and not iis_exempt:
            tb0 = tx_apply_carry(pool_before, trade, y)[1]
            saved = max(0.0, tx_ndfl(tb0 + div + coupon_net + over + max(0.0, deriv), y)[0] - tax)
        withheld = i.get("withheld", 0.0)
        rows.append({
            "year": y, "proceeds": sum(s["proceeds"] for s in sec), "cost": sum(s["cost"] for s in sec), "fees": sum(s["fee"] for s in sec),
            "trade": trade, "ldv_exempt": exempt, "ldv_limit": limit if elig else 0.0, "ldv_saved": saved, "ldv_n": len(elig),
            "carry_used": used, "loss_new": new_loss, "carry_pool": [{"year": p[0], "amount": round(p[1], 2)} for p in sorted(pool, key=lambda x: x[0]) if p[1] > 0.005], "trade_base": trade_base,
            "dividends": div, "coupons": coupon_net, "coupons_gross": i.get("coupon", 0.0), "nkd_adj": i.get("nkd_recv", 0.0) - un, "coupon_offset": coff,
            "overnight": over, "deriv": deriv, "base": base, "iis_exempt_used": iis_used, "tax": tax, "tax13": lo * 0.13, "tax15": hi * 0.15,
            "withheld": withheld, "w": {k[2:]: v for k, v in i.items() if k.startswith("w_")},
            "diff": tax - withheld, "diff_pct": ((tax - withheld) / withheld * 100.0) if withheld > 1 else None,
            "broker_trade": i.get("bk_yield", 0.0), "deposits": i.get("dep", 0.0), "withdrawals": i.get("wd", 0.0)})
    return rows, [[p[0], p[1]] for p in pool if p[1] > 0.005]


# ── состояние: группы счетов, ИИС, ЛДВ, подсказки ──

TAX_SUM_KEYS = ("proceeds", "cost", "fees", "trade", "ldv_exempt", "ldv_saved", "carry_used", "loss_new", "trade_base", "dividends", "coupons",
                "overnight", "deriv", "base", "iis_exempt_used", "tax", "tax13", "tax15", "withheld", "broker_trade", "deposits", "withdrawals")


def tx_gkey(a):
    return "iis:" + a["id"] if a.get("type") == "ИИС" else "gen"


def tx_iis_info(a, setting, first_date, today):
    typ = setting.get("type") or ""
    opened = None
    for s in (setting.get("opened"), (a.get("opened") or "")[:10]):
        if s:
            try:
                opened = datetime.strptime(s[:10], "%Y-%m-%d").date()
                break
            except ValueError:
                pass
    if opened is None:
        opened = first_date
    eff = typ or "A"
    term = tx_add_years(opened, 5 if eff == "3" else 3) if opened else None
    return {"id": a["id"], "name": a["name"], "type": eff, "type_set": bool(typ), "opened": opened.isoformat() if opened else "",
            "term": term.isoformat() if term else "", "term_ok": bool(term and today >= term),
            "exempt": eff in ("B", "3") and bool(term and today >= term)}


def tx_sum_rows(per_group, exempt=None):
    """Итоги по годам. exempt — флаги групп, освобождённых от налога (ИИС с соблюдённым сроком): их база в общую не входит.
    Порог 15 % относится к совокупной базе налогоплательщика, а группы считаются по отдельности, поэтому налог по
    совокупной базе пересчитывается заново; превышение над суммой налогов групп — extra_progressive."""
    tot, comb = {}, defaultdict(float)
    for gi, rows in enumerate(per_group):
        for r in rows:
            if not (exempt and exempt[gi]):
                comb[r["year"]] += r["base"]
            elif r.get("iis_exempt_used") is not None:
                comb[r["year"]] += r["base"] - r["iis_exempt_used"]
            t = tot.setdefault(r["year"], {"year": r["year"], "w": defaultdict(float)})
            for k in TAX_SUM_KEYS:
                t[k] = t.get(k, 0.0) + r[k]
            for k, v in r["w"].items():
                t["w"][k] += v
    out = []
    for y in sorted(tot):
        t = tot[y]
        t["w"] = dict(t["w"])
        extra = tx_ndfl(comb[y], y)[0] - t["tax"]
        t["extra_progressive"] = extra if extra > 0.5 else 0.0
        t["diff"] = t["tax"] - t["withheld"]
        t["diff_pct"] = (t["diff"] / t["withheld"] * 100.0) if t["withheld"] > 1 else None
        out.append(t)
    return out


def tx_lines(sales, year):
    agg = {}
    for s in sales:
        if s["bucket"] != "sec" or s["sdate"].year != year:
            continue
        k = (s["uid"], s["kind"])
        a = agg.setdefault(k, {"name": s["name"], "ticker": s["ticker"], "type": s["type"], "kind": s["kind"], "qty": 0.0, "proceeds": 0.0,
                               "cost": 0.0, "fee": 0.0, "result": 0.0, "ldv_result": 0.0})
        for f in ("qty", "proceeds", "cost", "fee", "result"):
            a[f] += s[f]
        if s["ldv"]:
            a["ldv_result"] += s["result"]
    return sorted(agg.values(), key=lambda a: -abs(a["result"]))[:80]


def tx_pos_price(r):
    if not r or not r.get("qty"):
        return None
    p = r.get("price") or 0.0
    if r.get("value") and r.get("value_rub") is not None:
        p = p * r["value_rub"] / r["value"]
    return p or None


def tax_compute(ops, names, positions, sel, settings, fx=None, today=None, resolve=None):
    """Чистая часть расчёта (без сети): ops + позиции + выбранные счета -> структура состояния."""
    today = today or date.today()
    pos = {}
    for r in positions or []:
        if r.get("type") not in ("currency", "futures") and r.get("uid"):
            pos[r["uid"]] = r
    held = {u: r["qty"] for u, r in pos.items()} if pos else None
    events = find_conversions(ops, names, held, resolve=resolve)
    ops = apply_conversions(ops, events)
    eng = tax_engine(ops, names, fx, held)
    accs = {a["id"]: a for a in sel}
    groups = {}
    for a in sel:
        g = groups.setdefault(tx_gkey(a), {"key": tx_gkey(a), "accounts": []})
        g["accounts"].append(a["id"])
    first_by_acc = {}
    for o in ops:
        d = parse_dt(o.get("date")).date()
        k = o.get("_acc") or ""
        if k not in first_by_acc or d < first_by_acc[k]:
            first_by_acc[k] = d
    out_groups, per_rows, iis_list, per_exempt = [], [], [], []
    off = settings.get("offset_coupons", False)
    for gk, g in groups.items():
        ids = set(g["accounts"])
        sales = [s for s in eng["sales"] if s["acc"] in ids]
        inc = defaultdict(lambda: defaultdict(float))
        for (acc, y), v in eng["inc"].items():
            if acc in ids:
                for k, x in v.items():
                    inc[y][k] += x
        exempt = False
        iis_limit = TAX_IIS3_EXEMPT_LIMIT
        if gk == "gen":
            g["name"] = "Обычные счета" if len(ids) > 1 else accs[g["accounts"][0]]["name"]
            g["kind"] = "gen"
        else:
            a = accs[g["accounts"][0]]
            iinfo = tx_iis_info(a, settings["iis"].get(a["id"]) or {}, first_by_acc.get(a["id"]), today)
            iis_list.append(iinfo)
            exempt = iinfo["exempt"]
            iis_limit = TAX_IIS3_EXEMPT_LIMIT if iinfo["type"] == "3" else None
            g["name"] = "ИИС: " + a["name"]
            g["kind"] = "iis"
            g["iis"] = iinfo
            sales = [dict(s, ldv=False, yrs=0) for s in sales]
        rows, pool = tax_group_years(sales, inc, settings["loss_carry"] if gk == "gen" else None, exempt, None, off, iis_limit)
        g["rows"], g["pool"], g["sales"], g["inc"] = rows, pool, sales, inc
        per_rows.append(rows)
        per_exempt.append(exempt)
        out_groups.append(g)
    return {"eng": eng, "groups": out_groups, "years": tx_sum_rows(per_rows, per_exempt), "iis": iis_list, "pos": pos, "today": today, "accs": accs,
            "conversions": conversions_view(events)}


def tx_ldv_tables(st):
    """Будущие и уже наступившие ЛДВ по открытым лотам (только обычные счета: на ИИС ЛДВ не применяется)."""
    today = st["today"]
    gen_ids = set(a for g in st["groups"] if g["kind"] == "gen" for a in g["accounts"])
    cy = today.year
    cur_base = 0.0
    for g in st["groups"]:
        if g["kind"] == "gen":
            for r in g["rows"]:
                if r["year"] == cy:
                    cur_base = r["base"]
    rate = 0.15 if cur_base > (2400000.0 if cy >= 2025 else 5000000.0) else 0.13
    groups, ready = {}, {}
    for l in st["eng"]["open"]:
        if l["acc"] not in gen_ids or l["type"] not in TAX_LDV_TYPES or l["blind"] or not l["date"] or l["date"] < TAX_LDV_FROM:
            continue
        pr = tx_pos_price(st["pos"].get(l["uid"]))
        value = l["qty"] * pr if pr else None
        cost = l["qty"] * l["unit"]
        frm = tx_add_years(l["date"], 3) + timedelta(days=1)
        days = (frm - today).days
        tgt = ready if days <= 0 else groups
        k = l["uid"] if days <= 0 else (l["uid"], frm)
        e = tgt.setdefault(k, {"uid": l["uid"], "name": l["name"], "ticker": l["ticker"], "type": l["type"], "date": frm.isoformat(), "days": days,
                               "qty": 0.0, "cost": 0.0, "value": 0.0, "gain": 0.0, "known": True})
        e["qty"] += l["qty"]
        e["cost"] += cost
        if value is None:
            e["known"] = False
        else:
            e["value"] += value
            e["gain"] += value - cost
    up = sorted(groups.values(), key=lambda e: e["days"])
    for e in up + list(ready.values()):
        e["tax_now"] = max(0.0, e["gain"]) * rate if e["known"] else None
    return up, sorted(ready.values(), key=lambda e: -e["gain"]), rate


def tx_fee_sim(lots, qty, price, fee_rate, today, base):
    cp = [dict(l) for l in sorted(lots, key=lambda l: l["date"] or date(1970, 1, 1))]
    rows, _ = tx_sell(cp, qty, qty * price, qty * price * fee_rate, today, dict(base, sdate=today))
    return rows


def tx_group_open(st, g):
    ids = set(g["accounts"])
    by = defaultdict(list)
    for l in st["eng"]["open"]:
        if l["acc"] in ids:
            by[l["uid"]].append(l)
    return by


def tx_cur_tax(g, extra, cy, settings):
    """Налог текущего года по группе с дополнительными (гипотетическими) продажами."""
    exempt = g["kind"] == "iis" and g["iis"]["exempt"]
    iis_limit = TAX_IIS3_EXEMPT_LIMIT if g["kind"] == "iis" and g["iis"]["type"] == "3" else None
    rows, _ = tax_group_years(g["sales"], g["inc"], settings["loss_carry"] if g["kind"] == "gen" else None, exempt, extra, settings.get("offset_coupons", False), iis_limit)
    for r in rows:
        if r["year"] == cy:
            return r["tax"], r
    return 0.0, None


def tx_hints(st, settings):
    today, cy = st["today"], st["today"].year
    fee_rate = st["eng"]["fee_rate"]
    up, rd, rate = tx_ldv_tables(st)
    out = {"year": cy, "days_left": (date(cy, 12, 31) - today).days, "harvest": [], "harvest_total": 0.0, "ldv_warn": [], "notes": [],
           "spread": TAX_SPREAD, "fee_rate": fee_rate}
    for e in up:
        if e["days"] <= 365 and e["known"] and e["gain"] > 0 and e["tax_now"] and e["tax_now"] > 50:
            out["ldv_warn"].append(e)
    for g in st["groups"]:
        if g["kind"] == "iis" and g["iis"]["type"] != "A":
            continue
        t0, row0 = tx_cur_tax(g, [], cy, settings)
        if not row0 or t0 <= 1:
            continue
        cands = []
        for uid, lots in tx_group_open(st, g).items():
            pr = tx_pos_price(st["pos"].get(uid))
            if not pr or lots[0]["type"] in TAX_SKIP_TYPES:
                continue
            q = sum(l["qty"] for l in lots)
            base = {"acc": lots[0]["acc"], "uid": uid, "name": lots[0]["name"], "ticker": lots[0]["ticker"], "type": lots[0]["type"],
                    "bucket": "deriv" if lots[0]["type"] == "option" else "sec", "kind": "sell", "bdate": None}
            rows = tx_fee_sim(lots, q, pr, fee_rate, today, base)
            res = sum(r["result"] for r in rows)
            if res >= -50:
                continue
            value = q * pr
            t1, _ = tx_cur_tax(g, rows, cy, settings)
            cost = value * (fee_rate + TAX_SPREAD)
            cands.append({"uid": uid, "name": base["name"], "ticker": base["ticker"], "type": base["type"], "group": g["key"], "gname": g["name"],
                          "qty": q, "value": value, "loss": -res, "saving": t0 - t1, "cost": cost, "net": t0 - t1 - cost, "rows": rows,
                          "ldv_lost": any(r["ldv"] for r in rows) or any(l["date"] and (tx_add_years(l["date"], 3) - today).days < 120 for l in lots if not l.get("blind"))})
        cands.sort(key=lambda c: -c["net"])
        chosen, extra = [], []
        for c in cands:
            if c["net"] <= 1:
                continue
            t_prev, _ = tx_cur_tax(g, extra, cy, settings)
            t_new, _ = tx_cur_tax(g, extra + c["rows"], cy, settings)
            if (t_prev - t_new) - c["cost"] > 1:
                extra = extra + c["rows"]
                chosen.append(c)
        if chosen:
            t_all, _ = tx_cur_tax(g, extra, cy, settings)
            out["harvest_total"] += (t0 - t_all) - sum(c["cost"] for c in chosen)
        for c in cands:
            c.pop("rows", None)
            if c["net"] > 1:
                out["harvest"].append(c)
    out["harvest"].sort(key=lambda c: -c["net"])
    out["harvest"] = out["harvest"][:25]
    if not out["harvest"]:
        out["notes"].append("Позиций с убытком, продажа которых уменьшила бы налог текущего года, не найдено (или налога за этот год пока нет).")
    return out


def tx_last_sale_day(year, holidays=()):
    """Последний день года, когда сделка ещё рассчитается в этом году при T+1: последний торговый день минус один торговый день.
    Торговым считаем будний день, не равный 31 декабря (на практике 31.12 — выходной на бирже) и не из holidays (набор date).
    Точный календарь торгов определяет биржа."""
    hol = set(holidays or ())

    def trading(d):
        return d.weekday() < 5 and not (d.month == 12 and d.day == 31) and d not in hol
    d = date(year, 12, 31)
    while not trading(d):
        d -= timedelta(days=1)
    last = d
    d = last - timedelta(days=1)
    while not trading(d):
        d -= timedelta(days=1)
    return d, last


def tx_forecast(st, settings, pays=None, holidays=()):
    """Прогноз налога на конец года по обычным (не ИИС) счетам и подсказки по сбору убытков. pays — прогноз выплат (как на странице «Выплаты»)."""
    today, cy = st["today"], st["today"].year
    end = date(cy, 12, 31).isoformat()
    sale_day, last_day = tx_last_sale_day(cy, holidays)
    gen = [g for g in st["groups"] if g["kind"] == "gen"]
    iis = [g["name"] for g in st["groups"] if g["kind"] == "iis"]
    out = {"year": cy, "available": bool(gen), "iis_excluded": iis, "sale_day": sale_day.isoformat(), "last_trading_day": last_day.isoformat(),
           "days_to_sale": (sale_day - today).days, "pays_known": pays is not None, "harvest": [], "skipped": [], "harvest_saving": 0.0}
    if not gen:
        return out
    g = gen[0]
    row = next((r for r in g["rows"] if r["year"] == cy), None) or {}
    f = lambda k: float(row.get(k, 0.0) or 0.0)
    ec = ed = 0.0
    n = 0
    for p in pays or []:
        if today.isoformat() < (p.get("date") or "") <= end and p.get("kind") in ("coupon", "dividend") and p.get("amount"):
            if p["kind"] == "coupon":
                ec += p["amount"]
            else:
                ed += p["amount"]
            n += 1
    base = f("base")
    tax_now = tx_ndfl(base, cy)[0]
    tax_end, lo, hi = tx_ndfl(base + ec + ed, cy)
    thr = 5000000.0 if cy < 2025 else 2400000.0
    out["forecast"] = {
        "trade": f("trade"), "ldv_exempt": f("ldv_exempt"), "carry_used": f("carry_used"), "trade_base": f("trade_base"), "dividends": f("dividends"),
        "coupons": f("coupons"), "other": f("overnight") + max(0.0, f("deriv")), "base": base, "tax_now": tax_now, "withheld": f("withheld"),
        "exp_coupons": ec, "exp_dividends": ed, "exp_n": n, "base_end": base + ec + ed, "tax_end": tax_end, "tax13": lo * 0.13, "tax15": hi * 0.15,
        "to_withhold": max(0.0, tax_end - f("withheld")), "refund": max(0.0, f("withheld") - tax_end), "threshold": thr,
        "rate": 0.15 if base + ec + ed > thr else 0.13}
    # сбор убытков: позиции обычных счетов с нереализованным убытком
    fee_rate = st["eng"]["fee_rate"]
    t0, _ = tx_cur_tax(g, [], cy, settings)
    cands, skipped = [], []
    for uid, lots in tx_group_open(st, g).items():
        pr = tx_pos_price(st["pos"].get(uid))
        if not pr or lots[0]["type"] in TAX_SKIP_TYPES:
            continue
        q = sum(l["qty"] for l in lots)
        base_r = {"acc": lots[0]["acc"], "uid": uid, "name": lots[0]["name"], "ticker": lots[0]["ticker"], "type": lots[0]["type"],
                  "bucket": "deriv" if lots[0]["type"] == "option" else "sec", "kind": "sell", "bdate": None}
        rows = tx_fee_sim(lots, q, pr, fee_rate, today, base_r)
        res = sum(r["result"] for r in rows)
        if res >= -50:
            continue
        t1, _ = tx_cur_tax(g, rows, cy, settings)
        # лоты с прибылью, которым скоро исполнится 3 года (ЛДВ): продажа всей позиции лишит их льготы
        soon = None
        if lots[0]["type"] in TAX_LDV_TYPES:
            for l in lots:
                if l.get("blind") or not l["date"] or l["date"] < TAX_LDV_FROM or l["unit"] >= pr:
                    continue
                dd = (tx_add_years(l["date"], 3) + timedelta(days=1) - today).days
                if 0 < dd <= 365 and (soon is None or dd < soon):
                    soon = dd
        c = {"uid": uid, "name": base_r["name"], "ticker": base_r["ticker"], "qty": q, "value": q * pr, "loss": -res, "saving": t0 - t1,
             "cost": q * pr * (fee_rate + TAX_SPREAD), "ldv_days": soon, "rows": rows}
        c["net"] = c["saving"] - c["cost"]
        if soon is not None and soon <= 180:
            c["reason"] = "через %d дн. часть лотов получит ЛДВ, продавать невыгодно" % soon
            skipped.append(c)
        elif c["net"] > 1:
            cands.append(c)
    cands.sort(key=lambda c: -c["saving"])
    extra = []
    for c in cands:        # накопительный эффект: каждая следующая продажа уменьшает налог меньше, когда прибыль уже покрыта
        tp, _ = tx_cur_tax(g, extra, cy, settings)
        extra = extra + c["rows"]
        tn, _ = tx_cur_tax(g, extra, cy, settings)
        c["saving_marginal"] = tp - tn
    for c in cands + skipped:
        c.pop("rows", None)
    out["harvest"], out["skipped"] = cands[:25], skipped[:10]
    out["harvest_saving"] = sum(c["saving_marginal"] for c in cands)
    out["base_tax"] = t0
    return out


def tx_decl_sales(sales, year):
    out = []
    for s in sales:
        if s["bucket"] != "sec" or s["sdate"].year != year:
            continue
        out.append({
            "sdate": s["sdate"].isoformat(),
            "bdate": s["bdate"].isoformat() if s.get("bdate") else "",
            "uid": s["uid"],
            "name": s["name"],
            "ticker": s["ticker"],
            "type": s["type"],
            "kind": s["kind"],
            "qty": s["qty"],
            "proceeds": s["proceeds"],
            "cost": s["cost"],
            "fee": s["fee"],
            "result": s["result"],
            "ldv": bool(s.get("ldv")),
            "yrs": s.get("yrs", 0),
        })
    return sorted(out, key=lambda x: (x["sdate"], x["name"]))


def tx_decl(st):
    decl = {}
    all_pays = st.get("eng", {}).get("payouts") or []
    for g in st["groups"]:
        g_accs = set(g.get("accounts") or [])
        for r in g["rows"]:
            y = r["year"]
            d = decl.setdefault(y, {"year": y, "groups": [], "fx_payouts": [], "loss_carry": {"carry_used": 0.0, "loss_new": 0.0, "pool": []}})
            pays = sorted([dict(p) for p in all_pays if p["acc"] in g_accs and p["year"] == y], key=lambda p: (p["date"], p["name"]))
            fx_pays = [p for p in pays if p["cur"] != "RUB"]
            e = dict(r)
            e.update(key=g["key"], name=g["name"], kind=g["kind"], lines=tx_lines(g["sales"], y),
                     sales=tx_decl_sales(g["sales"], y), payouts=pays, fx_payouts=fx_pays)
            d["groups"].append(e)
            d["fx_payouts"].extend(fx_pays)
            d["loss_carry"]["carry_used"] += r.get("carry_used", 0.0)
            d["loss_carry"]["loss_new"] += r.get("loss_new", 0.0)
            if g["kind"] == "gen":
                d["loss_carry"]["pool"] = list(r.get("carry_pool") or [])
    for d in decl.values():
        d["fx_payouts"].sort(key=lambda p: (p["date"], p["name"]))
    return decl


def tx_iis_table(st, settings):
    out = []
    dr = 0.15 if str((settings or {}).get("ndfl_rate")) in ("15", "0.15") else 0.13
    for g in st["groups"]:
        if g["kind"] != "iis":
            continue
        i = g["iis"]
        ded = i["type"] in ("A", "3")
        ys = []
        for r in g["rows"]:
            if r["deposits"] > 0 or r["withdrawals"] > 0:
                b = min(r["deposits"], TAX_IIS_LIMIT)
                ys.append({"year": r["year"], "deposits": r["deposits"], "withdrawals": r["withdrawals"], "deduct_base": b if ded else 0.0,
                           "deduct": b * dr if ded else 0.0, "over": max(0.0, r["deposits"] - TAX_IIS_LIMIT)})
        e = dict(i)
        e.update(years=ys, deduct_rate=dr, deduct_total=sum(y["deduct"] for y in ys),
                 tax_if_closed=sum(r["tax"] for r in g["rows"]) if not i["exempt"] else 0.0,
                 trade_total=sum(r["trade"] for r in g["rows"]), income_total=sum(r["dividends"] + r["coupons"] for r in g["rows"]))
        out.append(e)
    return out


def tax_payload_from(st, settings, pays=None):
    gen = [g for g in st["groups"] if g["kind"] == "gen"]
    cy = st["today"].year
    up, rd, rate = tx_ldv_tables(st)
    sugg = []
    for g in gen:
        for r in g["rows"]:
            if r["year"] < cy and r["loss_new"] > 0.005 and str(r["year"]) not in settings["loss_carry"]:
                sugg.append({"year": r["year"], "loss": r["loss_new"]})
    ldv_years = {}
    for g in gen:
        for r in g["rows"]:
            if r["ldv_exempt"] > 0 or r["ldv_n"]:
                e = ldv_years.setdefault(r["year"], {"year": r["year"], "exempt": 0.0, "saved": 0.0, "n": 0, "limit": 0.0})
                e["exempt"] += r["ldv_exempt"]
                e["saved"] += r["ldv_saved"]
                e["n"] += r["ldv_n"]
                e["limit"] = max(e["limit"], r["ldv_limit"])
    strip = lambda g: {k: v for k, v in g.items() if k not in ("sales", "inc")}
    return {
        "today": st["today"].isoformat(), "settings": settings,
        "groups": [strip(g) for g in st["groups"]], "years": st["years"],
        "ldv": {"upcoming": up[:80], "ready": rd[:40], "years": [ldv_years[y] for y in sorted(ldv_years)],
                "saved_total": sum(e["saved"] for e in ldv_years.values()), "rate": rate, "limit": TAX_LDV_LIMIT},
        "iis": tx_iis_table(st, settings), "hints": tx_hints(st, settings), "forecast": tx_forecast(st, settings, pays), "decl": tx_decl(st),
        "carry_suggest": sugg, "warnings": st["eng"]["warnings"], "conversions": st.get("conversions") or [],
        "assumptions": [
            "Счета без ИИС объединены в одну налоговую базу (сальдирование прибылей и убытков между счетами одного налогоплательщика); каждый ИИС считается отдельно.",
            "Налог по годам сравнивается с удержанным по дате операции удержания; брокер часто удерживает налог за год в декабре или в январе следующего года.",
            "Ставка: 13 % и 15 % с части базы свыше 5 млн ₽ (2021–2024) или свыше 2,4 млн ₽ (с 2025 года). Заработная плата и другие доходы в порог не входят.",
            "ЛДВ применяется к акциям, облигациям и фондам, купленным с 2014 года и проданным после трёх лет владения; бумаги, полученные переводом, не учитываются.",
            "НКД, уплаченный при покупке, уменьшает купонный доход (остаток переносится), НКД при продаже входит в купонный доход.",
            "Фьючерсы и опционы: отдельная база по вариационной марже; валюта и ЦФА в расчёт не входят."]}


def tax_state(cfg, acc, force=False):
    settings = tax_settings()
    key = ("taxst", token_key(cfg), acc, json.dumps(settings, sort_keys=True))
    hit = None if force else mem_get(key, 120)
    if hit:
        return hit, settings
    with key_lock(key):
        hit = None if force else mem_get(key, 120)
        if hit:
            return hit, settings
        client = TInvest(cfg)
        accs, sel, data = selection(cfg, acc, force)
        ops = sorted([o for d in data for o in d["ops"]], key=lambda o: o.get("date") or "")
        keys = {(o.get("instrumentUid"), o.get("figi")) for o in ops
                if (o.get("instrumentUid") or o.get("figi")) and not str(o.get("instrumentUid") or "").startswith("imp:")}
        names = instruments(client, keys)
        positions = build_summary(cfg, acc, "all", force)["portfolio"]["positions"]
        st = tax_compute(ops, names, positions, sel, settings, tax_cbr_rate,
                         resolve=lambda t: benchmark_uid(client, t) if client.ready else None)
        return mem_put(key, st), settings


def tax_get(cfg, acc, q, force):
    st, settings = tax_state(cfg, acc, force)
    pays = None
    if cfg.get("token"):
        try:
            pays = build_bonds(cfg, acc).get("payments") or []
        except Exception:  # noqa: BLE001
            pays = None
    return tax_payload_from(st, settings, pays)


def tax_post_settings(cfg, body):
    return {"settings": tax_settings_save(cfg, body or {})}


def tax_reb_plan(st, settings, sells):
    """sells: {класс: сумма продажи, ₽}. Для каждого класса сравниваем «продать пропорционально» и «сначала убыточные и с ЛДВ»."""
    today, cy = st["today"], st["today"].year
    fee_rate = st["eng"]["fee_rate"]
    out = []
    for cls_, amount in sells.items():
        cands = []
        for g in st["groups"]:
            for uid, lots in tx_group_open(st, g).items():
                if lots[0]["type"] != cls_:
                    continue
                pr = tx_pos_price(st["pos"].get(uid))
                if not pr:
                    continue
                q = sum(l["qty"] for l in lots)
                base = {"acc": lots[0]["acc"], "uid": uid, "name": lots[0]["name"], "ticker": lots[0]["ticker"], "type": cls_,
                        "bucket": "deriv" if cls_ == "option" else "sec", "kind": "sell", "bdate": None}
                rows = tx_fee_sim(lots, q, pr, fee_rate, today, base)
                t0, _ = tx_cur_tax(g, [], cy, settings)
                t1, _ = tx_cur_tax(g, rows, cy, settings)
                value = q * pr
                cands.append({"g": g, "uid": uid, "lots": lots, "price": pr, "qty": q, "value": value, "base": base,
                              "rate": (t1 - t0) / value if value else 0.0})
        if not cands:
            out.append({"cls": cls_, "amount": amount, "plan": [], "tax_plan": None, "tax_naive": None, "note": "Нет данных о лотах по этому классу"})
            continue

        def run(pick):
            per_g, items = defaultdict(list), []
            for c, qq in pick:
                rows = tx_fee_sim(c["lots"], qq, c["price"], fee_rate, today, c["base"])
                per_g[c["g"]["key"]].extend(rows)
                res = sum(r["result"] for r in rows)
                soon = [l for l in c["lots"] if l["date"] and not l.get("blind") and 0 < (tx_add_years(l["date"], 3) + timedelta(days=1) - today).days <= 180]
                why = "убыток" if res < 0 else ("прибыль освобождена по ЛДВ" if rows and all(r["ldv"] for r in rows) and res > 0 else "есть налог")
                items.append({"uid": c["uid"], "name": c["base"]["name"], "ticker": c["base"]["ticker"], "gname": c["g"]["name"], "qty": qq,
                              "sell_rub": qq * c["price"], "result": res, "why": why, "ldv_soon": bool(soon and res > 0)})
            tot = 0.0
            for c in {id(x[0]["g"]): x[0] for x in pick}.values():
                g = c["g"]
                t0, _ = tx_cur_tax(g, [], cy, settings)
                t1, _ = tx_cur_tax(g, per_g[g["key"]], cy, settings)
                tot += t1 - t0
            return tot, items
        total_v = sum(c["value"] for c in cands)
        amt = min(amount, total_v)
        naive = []
        for c in cands:
            qq = int(c["qty"] * amt / total_v)
            if qq > 0:
                naive.append((c, qq))
        tax_naive, items_naive = run(naive) if naive else (0.0, [])
        plan, rem = [], amt
        for c in sorted(cands, key=lambda c: c["rate"]):
            if rem < c["price"]:
                break
            qq = int(min(c["qty"], rem / c["price"]))
            if qq <= 0:
                continue
            plan.append((c, qq))
            rem -= qq * c["price"]
        tax_plan, items = run(plan) if plan else (0.0, [])
        if tax_plan > tax_naive:
            tax_plan, items = tax_naive, items_naive
        out.append({"cls": cls_, "amount": amount, "covered": amt, "tax_plan": tax_plan, "tax_naive": tax_naive,
                    "saving": max(0.0, tax_naive - tax_plan), "plan": items})
    return out


def tax_reb_get(cfg, acc, q, force):
    sells = {}
    for part in (q.get("sells") or "").split(","):
        if ":" in part:
            k, v = part.split(":", 1)
            try:
                if float(v) > 0:
                    sells[k] = float(v)
            except ValueError:
                pass
    st, settings = tax_state(cfg, acc, force)
    return {"items": tax_reb_plan(st, settings, sells), "warnings": st["eng"]["warnings"]}


def tax_decl_csv(decl, year):
    """Формирует UTF-8 BOM CSV (разделитель ';') для 3-НДФЛ по выбранному году."""
    buf = io.StringIO()
    w = csv.writer(buf, delimiter=";")
    w.writerow(["Раздел", "Группа", "Дата", "Дата покупки", "Бумага", "Тикер", "Операция", "Кол-во",
                "Валюта", "Сумма в валюте", "Курс ЦБ", "Сумма / Выручка, ₽", "Расход, ₽", "Комиссия, ₽",
                "Результат, ₽", "ЛДВ", "Налог удержан, ₽", "Примечание"])
    n = lambda x, d=2: "" if x is None else str(round(float(x), d)).replace(".", ",")
    kinds = {"sell": "Продажа", "repay": "Погашение", "amort": "Амортизация", "writeoff": "Списание", "short": "Шорт"}
    d = decl.get(year) or {"year": year, "groups": []}
    for g in d["groups"]:
        gn = g["name"]
        w.writerow(["Итог", gn, str(year), "", "Сделки с ценными бумагами", "", "Итог", "", "RUB", "", "",
                    n(g["proceeds"]), n(g["cost"]), n(g["fees"]), n(g["trade"]),
                    n(g["ldv_exempt"]) if g.get("ldv_exempt", 0) > 0.005 else "",
                    n(g["withheld"]),
                    "База: %s; Налог: %s; Зачёт убытков: %s; Убыток к переносу: %s" % (
                        n(g["base"]), n(g["tax"]), n(g["carry_used"]), n(g["loss_new"]))])
        for s in g.get("sales") or []:
            w.writerow(["Сделка", gn, s["sdate"], s.get("bdate") or "", s["name"], s["ticker"],
                        kinds.get(s["kind"], s["kind"]), n(s["qty"], 6), "RUB", "", "",
                        n(s["proceeds"]), n(s["cost"]), n(s["fee"]), n(s["result"]),
                        "Да (%d г.)" % s["yrs"] if s.get("ldv") else "Нет", "", ""])
        for p in g.get("fx_payouts") or []:
            note = p.get("source") or ""
            if p.get("tax_orig", 0) > 0.005:
                note = ("%s; налог в валюте: %s %s" % (note, n(p["tax_orig"]), p["cur"])).strip("; ")
            w.writerow(["Валютная выплата", gn, p["date"], "", p["name"], p["ticker"],
                        "Дивиденд" if p["kind"] == "div" else "Купон", "",
                        p["cur"], n(p["amount"]), n(p["rate"], 4), n(p["amount_rub"]),
                        "", "", "", "", n(p["tax_rub"]), note])
        for lp in g.get("carry_pool") or []:
            w.writerow(["Перенос убытков", gn, str(lp["year"]), "", "Остаток убытка к переносу", "", "", "",
                        "RUB", "", "", "", "", "", n(lp["amount"]), "", "", "Год возникновения убытка: %s" % lp["year"]])
    return buf.getvalue().encode("utf-8-sig")


def tax_decl_csv_get(cfg, acc, q, force):
    raw_y = (q.get("year") or "").strip()
    year = None
    if raw_y:
        try:
            year = int(raw_y)
        except ValueError:
            raise ApiError("Некорректный год", 400)
    st, _ = tax_state(cfg, acc, force)
    decl = tx_decl(st)
    if year is None:
        year = max(decl) if decl else st["today"].year
    return (200, tax_decl_csv(decl, year), "text/csv; charset=utf-8",
            {"Content-Disposition": 'attachment; filename="3ndfl_%d.csv"' % year})


API_GET["/api/tax"] = tax_get
API_GET["/api/tax/reb"] = tax_reb_get
API_GET["/api/tax/decl.csv"] = tax_decl_csv_get
API_POST["/api/tax/settings"] = tax_post_settings
# ═══════════════════════════════ зашифрованная резервная копия и экспорт ═══════════════════════════════
# Шифрование: стандартный AES-256 (FIPS-197) в режиме CTR (NIST SP 800-38A) на чистом Python + HMAC-SHA256
# (encrypt-then-MAC), ключи из пароля через PBKDF2-HMAC-SHA256. Своих шифров нет.
import hmac
import secrets
import struct
import tempfile


def _aes_tables():
    sbox = [0] * 256
    p = q = 1
    while True:
        p = (p ^ (p << 1) ^ (0x11B if p & 0x80 else 0)) & 0xFF         # p *= 3
        q ^= (q << 1) & 0xFF
        q ^= (q << 2) & 0xFF
        q ^= (q << 4) & 0xFF
        if q & 0x80:
            q ^= 0x09                                                  # q /= 3
        x = q
        for n in (1, 2, 3, 4):
            x ^= ((q << n) | (q >> (8 - n))) & 0xFF
        sbox[p] = x ^ 0x63
        if p == 1:
            break
    sbox[0] = 0x63
    te0, te1, te2, te3 = [], [], [], []
    for s in sbox:
        s2 = ((s << 1) ^ (0x11B if s & 0x80 else 0)) & 0xFF
        s3 = s2 ^ s
        w = (s2 << 24) | (s << 16) | (s << 8) | s3
        te0.append(w)
        te1.append(((w >> 8) | (w << 24)) & 0xFFFFFFFF)
        te2.append(((w >> 16) | (w << 16)) & 0xFFFFFFFF)
        te3.append(((w >> 24) | (w << 8)) & 0xFFFFFFFF)
    return sbox, te0, te1, te2, te3


_SBOX, _TE0, _TE1, _TE2, _TE3 = _aes_tables()


def aes256_expand_key(key):
    """Расписание ключей AES-256: 60 слов по 32 бита."""
    if len(key) != 32:
        raise ValueError("Ключ AES-256 должен быть 32 байта")
    sb = _SBOX
    w = list(struct.unpack(">8I", key))
    rcon = 1
    for i in range(8, 60):
        t = w[i - 1]
        if i % 8 == 0:
            t = ((t << 8) | (t >> 24)) & 0xFFFFFFFF
            t = (sb[t >> 24] << 24) | (sb[(t >> 16) & 255] << 16) | (sb[(t >> 8) & 255] << 8) | sb[t & 255]
            t ^= rcon << 24
            rcon = ((rcon << 1) ^ (0x11B if rcon & 0x80 else 0)) & 0xFF
        elif i % 8 == 4:
            t = (sb[t >> 24] << 24) | (sb[(t >> 16) & 255] << 16) | (sb[(t >> 8) & 255] << 8) | sb[t & 255]
        w.append(w[i - 8] ^ t)
    return w


def aes256_encrypt_block(rk, block):
    return b"".join(_aes_blocks(rk, [struct.unpack(">4I", block)]))


def _aes_blocks(rk, blocks):
    """Шифрует список блоков, каждый — кортеж из четырёх 32-битных слов; возвращает список 16-байтных строк."""
    t0, t1, t2, t3, sb = _TE0, _TE1, _TE2, _TE3, _SBOX
    pack = struct.Struct(">4I").pack
    r0, r1, r2, r3 = rk[0], rk[1], rk[2], rk[3]
    rounds = [rk[4 * i:4 * i + 4] for i in range(1, 14)]
    f0, f1, f2, f3 = rk[56], rk[57], rk[58], rk[59]
    out = []
    for a, b, c, d in blocks:
        a ^= r0
        b ^= r1
        c ^= r2
        d ^= r3
        for k0, k1, k2, k3 in rounds:
            a, b, c, d = (t0[a >> 24] ^ t1[(b >> 16) & 255] ^ t2[(c >> 8) & 255] ^ t3[d & 255] ^ k0,
                          t0[b >> 24] ^ t1[(c >> 16) & 255] ^ t2[(d >> 8) & 255] ^ t3[a & 255] ^ k1,
                          t0[c >> 24] ^ t1[(d >> 16) & 255] ^ t2[(a >> 8) & 255] ^ t3[b & 255] ^ k2,
                          t0[d >> 24] ^ t1[(a >> 16) & 255] ^ t2[(b >> 8) & 255] ^ t3[c & 255] ^ k3)
        out.append(pack(
            ((sb[a >> 24] << 24) | (sb[(b >> 16) & 255] << 16) | (sb[(c >> 8) & 255] << 8) | sb[d & 255]) ^ f0,
            ((sb[b >> 24] << 24) | (sb[(c >> 16) & 255] << 16) | (sb[(d >> 8) & 255] << 8) | sb[a & 255]) ^ f1,
            ((sb[c >> 24] << 24) | (sb[(d >> 16) & 255] << 16) | (sb[(a >> 8) & 255] << 8) | sb[b & 255]) ^ f2,
            ((sb[d >> 24] << 24) | (sb[(a >> 16) & 255] << 16) | (sb[(b >> 8) & 255] << 8) | sb[c & 255]) ^ f3))
    return out


def aes256_ctr(key, iv16, data):
    """AES-256-CTR (шифрование и расшифровка одинаковы): счётчик — 128-битное число, +1 на блок (SP 800-38A F.5.5)."""
    rk = aes256_expand_key(key)
    ctr = int.from_bytes(iv16, "big")
    out = bytearray()
    step = 4096 * 16
    mask = (1 << 128) - 1
    for off in range(0, len(data), step):
        chunk = data[off:off + step]
        n = (len(chunk) + 15) // 16
        blocks = []
        for i in range(n):
            v = (ctr + i) & mask
            blocks.append(((v >> 96) & 0xFFFFFFFF, (v >> 64) & 0xFFFFFFFF, (v >> 32) & 0xFFFFFFFF, v & 0xFFFFFFFF))
        ctr = (ctr + n) & mask
        ks = b"".join(_aes_blocks(rk, blocks))[:len(chunk)]
        out += (int.from_bytes(chunk, "big") ^ int.from_bytes(ks, "big")).to_bytes(len(chunk), "big")
    return bytes(out)


BK_MAGIC = b"TINVBAK1"          # 8 байт: формат + версия
BK_ITER = 300000
BK_EXT = ".tinvbak"
BK_RE = re.compile(r"^tinvest_backup_\d{4}-\d{2}-\d{2}(_\d{6})?" + re.escape(BK_EXT) + "$")


class BackupError(Exception):
    pass


def _bk_keys(password, salt, iters):
    master = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iters, 32)
    return (hmac.new(master, b"tinvest-backup-enc", hashlib.sha256).digest(),
            hmac.new(master, b"tinvest-backup-mac", hashlib.sha256).digest())


def encrypt_bytes(password, plain, iters=BK_ITER):
    """Файл: MAGIC(8) | итерации KDF u32 | соль(16) | nonce(12) | шифртекст | HMAC-SHA256(32) по всему предыдущему."""
    if not password:
        raise BackupError("Не задан пароль.")
    salt, nonce = secrets.token_bytes(16), secrets.token_bytes(12)
    ek, mk = _bk_keys(password, salt, iters)
    head = BK_MAGIC + struct.pack(">I", iters) + salt + nonce
    body = aes256_ctr(ek, nonce + b"\0\0\0\0", plain)
    return head + body + hmac.new(mk, head + body, hashlib.sha256).digest()


def decrypt_bytes(password, blob):
    if len(blob) < 8 + 4 + 16 + 12 + 32 or blob[:8] != BK_MAGIC:
        raise BackupError("Это не файл резервной копии TAnalytic (или он повреждён).")
    iters = struct.unpack(">I", blob[8:12])[0]
    if not 1000 <= iters <= 20000000:
        raise BackupError("Файл повреждён: неверные параметры шифрования.")
    salt, nonce = blob[12:28], blob[28:40]
    body, tag = blob[40:-32], blob[-32:]
    ek, mk = _bk_keys(password or "", salt, iters)
    if not hmac.compare_digest(hmac.new(mk, blob[:-32], hashlib.sha256).digest(), tag):
        raise BackupError("Неверный пароль или файл повреждён (проверка целостности не пройдена).")
    return aes256_ctr(ek, nonce + b"\0\0\0\0", body)


# ───────────── содержимое копии ─────────────

BK_SKIP_RESTORE = {"token", "sandbox", "verify_ssl", "ca_file", "hosts_prod", "hosts_sandbox"}


def backup_plain():
    """Zip: согласованная копия базы + настройки без токена и без секретов."""
    tmp = os.path.join(APP_DIR, "backup.%d.tmp" % threading.get_ident())
    try:
        src = sqlite3.connect(DB_PATH)
        dst = sqlite3.connect(tmp)
        with dst:
            src.backup(dst)
        dst.close()
        src.close()
        cfg = {k: v for k, v in load_config().items() if k not in SECRET_KEYS}
        buf = io.BytesIO()
        with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED, compresslevel=6) as z:
            z.write(tmp, "data.db")
            z.writestr("config.json", json.dumps(cfg, ensure_ascii=False, indent=2))
            z.writestr("README.txt", "Зашифрованная резервная копия TAnalytic. Токен API и пароли в копию не входят.\n")
        return buf.getvalue()
    finally:
        try:
            os.remove(tmp)
        except OSError:
            pass


def backup_dir_check(path):
    """(ok, сообщение): папка существует и доступна для записи."""
    p = os.path.expanduser((path or "").strip())
    if not p:
        return False, "Папка не указана."
    if not os.path.isdir(p):
        return False, "Папка не найдена: " + p
    try:
        fd, name = tempfile.mkstemp(prefix=".tinv_w", dir=p)
        os.close(fd)
        os.remove(name)
    except OSError as e:
        return False, "В папку нельзя записывать: %s" % (e.strerror or e)
    return True, "Папка доступна для записи."


def backup_list(dirpath):
    p = os.path.expanduser((dirpath or "").strip())
    out = []
    try:
        for n in os.listdir(p):
            if BK_RE.match(n):
                st = os.stat(os.path.join(p, n))
                out.append({"name": n, "size": st.st_size, "mtime": st.st_mtime})
    except OSError:
        pass
    return sorted(out, key=lambda x: x["name"], reverse=True)


def backup_prune(dirpath, keep):
    """Удаляет самые старые свои копии сверх лимита (только файлы по шаблону имени)."""
    p = os.path.expanduser(dirpath.strip())
    removed = 0
    for x in backup_list(p)[max(1, int(keep)):]:
        try:
            os.remove(os.path.join(p, x["name"]))
            removed += 1
        except OSError:
            pass
    return removed


_bk_lock = threading.Lock()
_bk_state = {"running": False}


def _bk_status_put(**kw):
    try:
        store().put("backup_status", kw)
    except Exception:  # noqa: BLE001
        pass


def run_backup(cfg, password=None, name_time=True):
    """Делает копию в папку назначения; возвращает словарь статуса. Ошибки — BackupError."""
    pw = password or cfg.get("backup_password") or ""
    if not pw:
        raise BackupError("Не задан пароль для шифрования копии.")
    ok, msg = backup_dir_check(cfg.get("backup_dir"))
    if not ok:
        raise BackupError(msg)
    t0 = time.time()
    plain = backup_plain()
    blob = encrypt_bytes(pw, plain)
    now = datetime.now()
    fname = "tinvest_backup_%s%s" % (now.strftime("%Y-%m-%d_%H%M%S") if name_time else now.strftime("%Y-%m-%d"), BK_EXT)
    d = os.path.expanduser(cfg["backup_dir"].strip())
    final = os.path.join(d, fname)
    tmp = final + ".part"
    with open(tmp, "wb") as f:
        f.write(blob)
    os.replace(tmp, final)
    removed = backup_prune(d, cfg.get("backup_keep") or 14)
    return {"ok": True, "t": time.time(), "file": fname, "size": len(blob), "sec": round(time.time() - t0, 1), "removed": removed}


def _bk_job(cfg, password, name_time):
    if not _bk_lock.acquire(False):
        return
    _bk_state["running"] = True
    try:
        st = run_backup(cfg, password, name_time)
    except BackupError as e:
        st = {"ok": False, "t": time.time(), "error": str(e)}
    except Exception as e:  # noqa: BLE001
        st = {"ok": False, "t": time.time(), "error": "Не удалось сделать копию: %s" % e}
    finally:
        _bk_state["running"] = False
        _bk_lock.release()
    _bk_status_put(**st)


def _bk_clamp_keep(v, default=14):
    try:
        return max(1, min(365, int(v)))
    except (TypeError, ValueError):
        return default


def _bk_suggest():
    home = os.path.expanduser("~")
    cands = []
    for base in ("Yandex.Disk", "YandexDisk", "Yandex Disk", "Яндекс Диск", "Google Drive", "Google Диск", "iCloudDrive",
                 "OneDrive", "Dropbox", os.path.join("Library", "Mobile Documents", "com~apple~CloudDocs")):
        cands.append(("Яндекс Диск" if "andex" in base or "Яндекс" in base else
                      "Google Drive" if "Google" in base else "iCloud Drive" if "iCloud" in base or "CloudDocs" in base else base,
                      os.path.join(home, base)))
    if platform.system() == "Windows":           # OneDrive из переменных окружения, Google Drive — отдельный диск «G:\Мой диск»
        for env, lab in (("OneDrive", "OneDrive"), ("OneDriveConsumer", "OneDrive"), ("OneDriveCommercial", "OneDrive (работа)")):
            v = os.environ.get(env)
            if v:
                cands.append((lab, v))
        for drv in "GHIJ":
            for n in ("Мой диск", "My Drive"):
                cands.append(("Google Drive", "%s:\\%s" % (drv, n)))
        for v in (os.environ.get("YANDEX_DISK"), os.path.join(os.environ.get("USERPROFILE", home), "YandexDisk")):
            if v:
                cands.append(("Яндекс Диск", v))
    cs = os.path.join(home, "Library", "CloudStorage")
    try:
        for n in sorted(os.listdir(cs)):
            lab = "Google Drive" if n.startswith("GoogleDrive") else "Яндекс Диск" if "andex" in n else \
                "iCloud Drive" if "iCloud" in n else n
            cands.append((lab, os.path.join(cs, n)))
    except OSError:
        pass
    out, seen = [], set()
    for a, b in cands:
        k = os.path.normcase(os.path.normpath(b))
        if k not in seen and os.path.isdir(b):
            seen.add(k)
            out.append({"label": a, "path": b, "sep": os.sep})
    return out


def api_backup_status(cfg, acc, q, force):
    st = None
    try:
        st = store().get("backup_status")
    except Exception:  # noqa: BLE001
        pass
    d = (cfg.get("backup_dir") or "").strip()
    ok, msg = backup_dir_check(d) if d else (False, "")
    return {"running": _bk_state["running"], "last": st, "dir": d, "dir_ok": ok, "dir_msg": msg,
            "files": backup_list(d) if ok else [], "suggest": _bk_suggest(), "pw_set": bool(cfg.get("backup_password")),
            "auto": bool(cfg.get("backup_auto")), "keep": _bk_clamp_keep(cfg.get("backup_keep")),
            "home": os.path.expanduser("~"), "windows": platform.system() == "Windows",
            "restore_pending": os.path.exists(DB_PATH + ".restore-pending")}


def api_backup_settings(cfg, body):
    if "backup_dir" in body:
        cfg["backup_dir"] = str(body["backup_dir"] or "").strip()
    if "backup_auto" in body:
        cfg["backup_auto"] = bool(body["backup_auto"])
    if "backup_keep" in body:
        cfg["backup_keep"] = _bk_clamp_keep(body["backup_keep"])
    if body.get("backup_password"):
        pw = str(body["backup_password"])
        if len(pw) < 6:
            raise ApiError("Пароль копии — не короче 6 символов.", 400)
        cfg["backup_password"] = pw
    if body.get("clear_password"):
        cfg["backup_password"] = ""
        cfg["backup_auto"] = False
    if cfg.get("backup_auto") and not cfg.get("backup_password"):
        raise ApiError("Для автоматических копий сохраните пароль.", 400)
    if cfg.get("backup_dir"):
        ok, msg = backup_dir_check(cfg["backup_dir"])
        if not ok and (cfg.get("backup_auto") or "backup_dir" in body):
            raise ApiError(msg, 400)
    save_config(cfg)
    return {"ok": True}


def api_backup_run(cfg, body):
    pw = str(body.get("password") or "") or cfg.get("backup_password") or ""
    if not pw:
        raise ApiError("Введите пароль для шифрования копии.", 400)
    ok, msg = backup_dir_check(cfg.get("backup_dir"))
    if not ok:
        raise ApiError(msg, 400)
    if _bk_state["running"]:
        return {"started": False, "running": True}
    threading.Thread(target=_bk_job, args=(dict(cfg), pw, True), daemon=True).start()
    return {"started": True}


def api_backup_restore(cfg, body):
    try:
        blob = base64.b64decode(body.get("data") or "", validate=False)
    except Exception:  # noqa: BLE001
        raise ApiError("Не удалось прочитать файл.", 400)
    try:
        plain = decrypt_bytes(str(body.get("password") or ""), blob)
        z = zipfile.ZipFile(io.BytesIO(plain))
        if "data.db" not in z.namelist():
            raise BackupError("В копии нет базы данных.")
        db = z.read("data.db")
        cfg_new = json.loads(z.read("config.json").decode("utf-8")) if "config.json" in z.namelist() else {}
    except BackupError as e:
        raise ApiError(str(e), 400)
    except (zipfile.BadZipFile, ValueError, KeyError):
        raise ApiError("Содержимое копии повреждено.", 400)
    pend = DB_PATH + ".restore-pending"
    tmp = pend + ".tmp"
    try:
        with open(tmp, "wb") as f:
            f.write(db)
        c = sqlite3.connect(tmp)
        try:
            tabs = {r[0] for r in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if not {"kv", "ops"} <= tabs or c.execute("PRAGMA integrity_check").fetchone()[0] != "ok":
                raise BackupError("База в копии повреждена или не от этого приложения.")
        finally:
            c.close()
        os.replace(tmp, pend)
    except BackupError as e:
        raise ApiError(str(e), 400)
    except sqlite3.Error:
        raise ApiError("База в копии повреждена.", 400)
    finally:
        try:
            os.remove(tmp)
        except OSError:
            pass
    if isinstance(cfg_new, dict):       # настройки интерфейса возвращаем; токен, секреты и подключение не трогаем
        for k, v in cfg_new.items():
            if k in SECRET_KEYS or k in BK_SKIP_RESTORE or k.startswith("backup_") or k not in DEFAULT_CONFIG:
                continue
            cfg[k] = v
        save_config(cfg)
    return {"ok": True, "restart": True}


def _bk_loop():
    while True:
        try:
            cfg = load_config()
            if cfg.get("backup_auto") and cfg.get("backup_password") and cfg.get("backup_dir"):
                today = date.today().strftime("tinvest_backup_%Y-%m-%d")
                ok, _m = backup_dir_check(cfg["backup_dir"])
                if not ok:
                    _bk_status_put(ok=False, t=time.time(), error=_m)
                elif not any(x["name"].startswith(today) for x in backup_list(cfg["backup_dir"])):
                    _bk_job(cfg, None, False)
        except Exception as e:  # noqa: BLE001
            _bk_status_put(ok=False, t=time.time(), error="Автокопия: %s" % e)
        time.sleep(900)


def backup_start():
    threading.Thread(target=_bk_loop, daemon=True).start()


