# ═══════════════════ арбитраж внутри кривой эмитента, инверсия кривой (EWS) и рубль vs валюта ═══════════════════
# Детерминированный анализ скринера облигаций Мосбиржи без ИИ:
# 1) перекосы доходности внутри кривой одного эмитента при близкой дюрации + срок окупаемости перекладки;
# 2) инверсия кривой одного эмитента (короткий выпуск заметно дороже по YTM длинного — ранний сигнал стресса);
# 3) сравнение рублёвых и валютных (USD/EUR/CNY) выпусков того же эмитента — безубыточная девальвация рубля после НДФЛ.


def _arb_key(r):
    """Ключ группировки эмитента для облигаций скринера."""
    k = issuer_group_key(r.get("name") or "")
    if k:
        return k
    toks = sorted(name_tokens(r.get("name") or ""))
    return " ".join(toks[:2]) if toks else ""


def _arb_rating_str(r):
    rt = r.get("rating")
    if isinstance(rt, dict):
        return rt.get("v")
    return rt if isinstance(rt, str) else None


def arb_compute(rows, fx_rates=None, fee_pct=0.05, tax_rate=0.13):
    """Чистый расчёт по строкам скринера -> {pairs, inversions, fx_vs_rub, stats}."""
    fx_rates = fx_rates or {}
    rub_groups = {}
    fx_groups = {}
    for r in rows or []:
        y = r.get("yield")
        dur = r.get("dur") or r.get("macdur")
        if y is None or dur is None or not (0.5 <= y <= 120.0) or dur < 0.15:
            continue
        if r.get("floating") or r.get("kind") != "corp":
            continue
        cur = (r.get("cur") or "RUB").upper()
        gk = _arb_key(r)
        if not gk:
            continue
        item = {"isin": r.get("isin") or r.get("id"), "name": r.get("name") or r.get("id"),
                "yield": float(y), "dur": float(dur), "price": r.get("price"), "cur": cur,
                "turn": float(r.get("turn") or 0.0), "rating": _arb_rating_str(r),
                "offer": r.get("offer"), "mat": r.get("mat"), "group": gk}
        if cur == "RUB":
            rub_groups.setdefault(gk, []).append(item)
        elif cur in ("USD", "EUR", "CNY"):
            fx_groups.setdefault(gk, []).append(item)

    # 1. Арбитраж внутри кривой одного эмитента (близкая дюрация, разница YTM >= 0.8 п.п.)
    switch_cost_pct = 2.0 * max(0.0, float(fee_pct)) + 0.20    # комиссия продажи+покупки + оценка бид-аск спреда 0.2%
    pairs = []
    for gk, bs in rub_groups.items():
        if len(bs) < 2:
            continue
        best = None
        for i in range(len(bs)):
            for j in range(len(bs)):
                if i == j:
                    continue
                cheap, rich = bs[i], bs[j]
                if cheap["yield"] > 60 or rich["yield"] > 60:
                    continue
                dy = cheap["yield"] - rich["yield"]
                dd = abs(cheap["dur"] - rich["dur"])
                if dy < 0.8 or dd > 1.2:
                    continue
                if cheap["turn"] <= 0 and rich["turn"] <= 0:
                    continue
                net_dy = dy * (1.0 - tax_rate)
                payback_mo = round(switch_cost_pct / net_dy * 12.0, 1) if net_dy > 0 else None
                cand = {"issuer": gk, "rating": cheap["rating"] or rich["rating"],
                        "buy": cheap, "sell": rich,
                        "spread_bp": int(round(dy * 100)), "dur_diff": round(dd, 2),
                        "switch_cost_pct": round(switch_cost_pct, 2), "payback_mo": payback_mo}
                if best is None or cand["spread_bp"] > best["spread_bp"]:
                    best = cand
        if best:
            pairs.append(best)
    pairs.sort(key=lambda x: -x["spread_bp"])

    # 2. Детектор инверсии кривой эмитента (короткий выпуск заметно выше длинного по YTM — стресс ликвидности / EWS)
    inversions = []
    for gk, bs in rub_groups.items():
        if len(bs) < 2:
            continue
        by_d = sorted(bs, key=lambda b: b["dur"])
        short_b = next((b for b in by_d if b["dur"] <= 1.5 and b["yield"] >= 18.0), None)
        if not short_b:
            continue
        long_cands = [b for b in by_d if b["dur"] >= short_b["dur"] + 0.7]
        if not long_cands:
            continue
        long_b = min(long_cands, key=lambda b: b["yield"])
        inv = short_b["yield"] - long_b["yield"]
        if inv >= 2.5:
            inv_bp = int(round(inv * 100))
            sev = "high" if (inv_bp >= 500 or short_b["yield"] >= 30.0) else "warn"
            inversions.append({"issuer": gk, "rating": short_b["rating"] or long_b["rating"],
                               "short": short_b, "long": long_b, "inv_bp": inv_bp,
                               "severity": sev, "n_bonds": len(bs)})
    inversions.sort(key=lambda x: -x["inv_bp"])

    # 3. Рубль vs Валюта у одного эмитента (безубыточная девальвация рубля после НДФЛ)
    fx_vs_rub = []
    for gk, fbs in fx_groups.items():
        rbs = [b for b in rub_groups.get(gk, []) if b["yield"] <= 45.0]
        if not rbs:
            continue
        for cur in ("USD", "CNY", "EUR"):
            cfs = [b for b in fbs if b["cur"] == cur and b["yield"] <= 30.0]
            if not cfs:
                continue
            # Берём пару с минимальной разницей по дюрации
            best_pair = min(((rb, fb, abs(rb["dur"] - fb["dur"])) for rb in rbs for fb in cfs), key=lambda x: x[2])
            rb, fb, dd = best_pair
            if dd > 2.5:
                continue
            yr = rb["yield"] / 100.0
            yf = fb["yield"] / 100.0
            # Без ЛДВ (единая ставка НДФЛ 13% на купон и валютную переоценку): множитель (1-t) сокращается
            be_pre = ((1.0 + yr) / (1.0 + yf) - 1.0) * 100.0
            # С ЛДВ (> 3 лет): валютная переоценка тела освобождается от НДФЛ, а купоны облагаются по 13% -> порог девальвации ниже
            yr_n = yr * (1.0 - tax_rate)
            yf_n = yf * (1.0 - tax_rate)
            be_ldv = ((1.0 + yr_n) / (1.0 + yf_n) - 1.0) * 100.0
            spot = fx_rates.get(cur)
            target_fx = round(spot * (1.0 + be_pre / 100.0), 2) if spot else None
            fx_vs_rub.append({"issuer": gk, "rating": rb["rating"] or fb["rating"], "cur": cur,
                              "rub": rb, "fx": fb, "dur_diff": round(dd, 2),
                              "be_pre_pct": round(be_pre, 2), "be_ldv_pct": round(be_ldv, 2),
                              "fx_now": round(spot, 2) if spot else None, "fx_breakeven_1y": target_fx})
    fx_vs_rub.sort(key=lambda x: x["be_pre_pct"])

    return {"pairs": pairs[:40], "inversions": inversions[:30], "fx_vs_rub": fx_vs_rub[:30],
            "stats": {"issuers_rub": len(rub_groups), "pairs": len(pairs), "inversions": len(inversions), "fx_pairs": len(fx_vs_rub)},
            "fee_pct": fee_pct, "tax_rate": tax_rate}


def _api_arb(cfg, acc, q, force):
    try:
        rows = screener_rows()
    except Exception as e:  # noqa: BLE001
        return {"error": "Не удалось загрузить скринер облигаций: %s" % str(e)[:140], "pairs": [], "inversions": [], "fx_vs_rub": []}
    today = date.today().isoformat()
    fx_rates = {}
    for c in ("USD", "CNY", "EUR"):
        try:
            v = tax_cbr_rate(c, today)
            if v:
                fx_rates[c] = v
        except Exception:  # noqa: BLE001
            pass
    try:
        fee = max(0.0, min(2.0, float(str(q.get("fee", "0.05")).replace(",", "."))))
    except ValueError:
        fee = 0.05
    return arb_compute(rows, fx_rates=fx_rates, fee_pct=fee)


API_GET["/api/arb"] = _api_arb
# ═══════════════════ разбор сделок (Trade Post-Mortem по FIFO) и призрачный портфель (Cashflow-Matched) ═══════════════════
# Детерминированный анализ истории операций без ИИ:
# 1) Trade Post-Mortem: Win Rate, Profit Factor, средний выигрыш/убыток, Disposition Effect (срок удержания убытков vs прибыли);
# 2) Призрачный портфель: моделирование тех же пополнений и выводов в те же даты в фондах LQDT и TMOS.


def pm_trades_stats(sales):
    """Статистика по закрытым сделкам FIFO из tax_state (g['sales']). Группирует частичные исполнения одной продажи (uid, sdate)."""
    grouped = {}
    for s in sales or []:
        if s.get("bucket") != "sec":
            continue
        sd = s.get("sdate")
        bd = s.get("bdate")
        if sd is None:
            continue
        sd_iso = sd.isoformat() if hasattr(sd, "isoformat") else str(sd)[:10]
        key = (s.get("uid") or s.get("ticker") or s.get("name"), sd_iso, s.get("kind") or "sell")
        g = grouped.get(key)
        hold = (sd - bd).days if (bd is not None and hasattr(sd, "__sub__")) else None
        if g is None:
            g = grouped[key] = {"name": s.get("name") or s.get("ticker") or "", "ticker": s.get("ticker") or "",
                                "type": s.get("type") or "other", "sdate": sd_iso, "qty": 0.0,
                                "cost": 0.0, "proceeds": 0.0, "result": 0.0, "hold_num": 0.0, "hold_den": 0.0}
        q = float(s.get("qty") or 0.0)
        c = float(s.get("cost") or 0.0)
        g["qty"] += q
        g["cost"] += c
        g["proceeds"] += float(s.get("proceeds") or 0.0)
        g["result"] += float(s.get("result") or 0.0)
        if hold is not None and hold >= 0:
            w = max(abs(c), q, 1.0)
            g["hold_num"] += hold * w
            g["hold_den"] += w

    trades = []
    for g in grouped.values():
        res = round(g["result"], 2)
        cost = round(g["cost"], 2)
        pct = round(res / cost * 100.0, 2) if cost > 1.0 else None
        hold = round(g["hold_num"] / g["hold_den"], 1) if g["hold_den"] > 0 else None
        trades.append({"name": g["name"], "ticker": g["ticker"], "type": g["type"], "sdate": g["sdate"],
                       "cost": cost, "proceeds": round(g["proceeds"], 2), "result": res, "pct": pct, "hold_days": hold})

    if not trades:
        return {"n": 0, "wins": 0, "losses": 0, "win_rate": None, "profit_factor": None, "net_pnl": 0.0,
                "gross_profit": 0.0, "gross_loss": 0.0, "avg_win": None, "avg_loss": None,
                "avg_hold_win": None, "avg_hold_loss": None, "disposition_ratio": None, "disposition_flag": False,
                "by_type": [], "best": [], "worst": []}

    wins = [t for t in trades if t["result"] > 0.01]
    losses = [t for t in trades if t["result"] < -0.01]
    gp = sum(t["result"] for t in wins)
    gl = sum(t["result"] for t in losses)
    n_dec = len(wins) + len(losses)
    wr = round(len(wins) / n_dec * 100.0, 1) if n_dec else None
    pf = round(gp / abs(gl), 2) if abs(gl) > 1.0 else (None if not wins else 99.9)
    hw = [t["hold_days"] for t in wins if t["hold_days"] is not None]
    hl = [t["hold_days"] for t in losses if t["hold_days"] is not None]
    avg_hw = round(sum(hw) / len(hw), 1) if hw else None
    avg_hl = round(sum(hl) / len(hl), 1) if hl else None
    disp = round(avg_hl / avg_hw, 2) if (avg_hl is not None and avg_hw and avg_hw >= 1.0) else None

    by_t = {}
    for t in trades:
        b = by_t.setdefault(t["type"], {"type": t["type"], "n": 0, "wins": 0, "result": 0.0})
        b["n"] += 1
        if t["result"] > 0.01:
            b["wins"] += 1
        b["result"] += t["result"]
    by_type = sorted((dict(v, result=round(v["result"], 2), win_rate=round(v["wins"] / v["n"] * 100.0, 1))
                      for v in by_t.values()), key=lambda x: -x["n"])

    trades_by_res = sorted(trades, key=lambda t: t["result"])
    return {"n": len(trades), "wins": len(wins), "losses": len(losses), "win_rate": wr,
            "profit_factor": pf, "net_pnl": round(gp + gl, 2), "gross_profit": round(gp, 2), "gross_loss": round(gl, 2),
            "avg_win": round(gp / len(wins), 2) if wins else None,
            "avg_loss": round(gl / len(losses), 2) if losses else None,
            "avg_hold_win": avg_hw, "avg_hold_loss": avg_hl,
            "disposition_ratio": disp, "disposition_flag": bool(disp is not None and disp >= 1.35 and len(losses) >= 3),
            "by_type": by_type,
            "best": list(reversed(trades_by_res[-8:])), "worst": trades_by_res[:8]}


def pm_ghost_portfolio(hist):
    """Призрачный портфель (Cashflow-Matched): те же внешние пополнения/выводы (изменение invested),
    вложенные в те же даты в бенчмарки (LQDT, TMOS)."""
    days = (hist or {}).get("days") or []
    vals = (hist or {}).get("value") or []
    invs = (hist or {}).get("invested") or []
    bench = (hist or {}).get("bench") or {}
    if len(days) < 2 or len(vals) != len(days) or len(invs) != len(days):
        return {"ok": False, "items": [], "days": [], "real": [], "series": {}}

    real_end = float(vals[-1])
    inv_end = float(invs[-1])
    items = []
    series = {}
    for code in ("LQDT", "TMOS"):
        prices = bench.get(code)
        if not prices or len(prices) != len(days):
            continue
        units = 0.0
        cash_wait = 0.0
        curve = []
        valid = False
        for i in range(len(days)):
            flow = float(invs[i]) - (float(invs[i - 1]) if i > 0 else 0.0)
            p = prices[i]
            if p and p > 0:
                valid = True
                if cash_wait:
                    units = max(0.0, units + cash_wait / p)     # минус = выводы до первой цены: продаём юниты (не ниже 0)
                    cash_wait = 0.0
                units = max(0.0, units + flow / p)      # вывод больше стоимости бенчмарка не делает его шортом
                gv = max(0.0, units * p)
            else:
                cash_wait += flow
                gv = max(0.0, cash_wait)
            curve.append(round(gv, 2))
        if not valid:
            continue
        g_end = curve[-1]
        diff = round(real_end - g_end, 2)
        diff_pct = round(diff / g_end * 100.0, 2) if g_end > 100 else None
        items.append({"code": code, "name": "Денежный рынок (LQDT)" if code == "LQDT" else "Индекс МосБиржи (TMOS)",
                      "ghost_val": round(g_end, 2), "real_val": round(real_end, 2), "invested": round(inv_end, 2),
                      "diff_rub": diff, "diff_pct": diff_pct})
        series[code] = curve

    # Прореживаем до ~180 точек для лёгкого графика
    step = max(1, len(days) // 180)
    idx = list(range(0, len(days), step))
    if idx[-1] != len(days) - 1:
        idx.append(len(days) - 1)
    return {"ok": bool(items), "real_val": round(real_end, 2), "invested": round(inv_end, 2),
            "items": items, "days": [days[i] for i in idx], "real": [vals[i] for i in idx],
            "series": {k: [v[i] for i in idx] for k, v in series.items()}}


def _api_postmortem(cfg, acc, q, force):
    try:
        st, _ = tax_state(cfg, acc, force)
        sales = [s for g in st.get("groups") or [] for s in (g.get("sales") or [])]
        trades = pm_trades_stats(sales)
    except Exception as e:  # noqa: BLE001
        trades = {"n": 0, "error": str(e)[:140]}
    try:
        hist = build_history_for(cfg, acc, force)
        ghost = pm_ghost_portfolio(hist)
    except Exception:  # noqa: BLE001
        ghost = {"ok": False, "items": [], "days": [], "real": [], "series": {}}
    return {"trades": trades, "ghost": ghost}


API_GET["/api/postmortem"] = _api_postmortem
# ═══════════════════ дивидендные гэпы: лаборатория отсечки, радар по портфелю, оценка надёжности дивидендов ═══════════════════
# Чистая математика (без сети): dl_gaps / dl_stats / dl_payoff / dl_safety. Сеть — только в _dl_analyze (свечи ISS, дивиденды T-Invest/сервер, МСФО).
# Описательная статистика по прошлым отсечкам, не инвестиционная рекомендация.

DL_HORIZON = 250                      # торговых дней на закрытие гэпа
DL_WINDOWS = (30, 60, 90)
DL_T1_FROM = "2023-07-31"            # Мосбиржа перешла с расчётов T+2 на T+1
DL_TTL = 12 * 3600
DL_HIST = [("в день отсечки", 0, 0), ("1–5 дн.", 1, 5), ("6–20 дн.", 6, 20), ("21–60 дн.", 21, 60), ("61–120 дн.", 61, 120), ("121–250 дн.", 121, 250)]


def _dl_num(v):
    try:
        x = float(v)
    except (TypeError, ValueError):
        return None
    return x if x == x and x not in (float("inf"), float("-inf")) else None


def dl_median(vals):
    v = sorted(x for x in vals if x is not None)
    if not v:
        return None
    n = len(v)
    return float(v[n // 2]) if n % 2 else (v[n // 2 - 1] + v[n // 2]) / 2.0


def dl_gaps(divs, candles, horizon=DL_HORIZON):
    """Прошлые рублёвые дивиденды × дневные свечи -> гэпы отсечки.
    divs: [{record, value, cur?, last_buy?}], candles: [{t, o, h, l, c}] (t — ГГГГ-ММ-ДД). Результат — по возрастанию даты фиксации."""
    cs = sorted((c for c in candles or [] if c.get("t") and _dl_num(c.get("c")) is not None), key=lambda c: c["t"])
    if len(cs) < 3:
        return []
    ds = [c["t"][:10] for c in cs]
    out, seen = [], set()
    for d in sorted(divs or [], key=lambda x: x.get("record") or ""):
        rec, val = (d.get("record") or "")[:10], _dl_num(d.get("value"))
        if not rec or not val or val <= 0 or str(d.get("cur") or "RUB").upper() not in ("RUB", "RUR") or rec in seen:
            continue
        seen.add(rec)
        if rec > ds[-1] or rec <= ds[0]:
            continue
        lb = (d.get("last_buy") or "")[:10]
        if lb and ds[0] <= lb < rec and rec >= DL_T1_FROM:   # для отсечек эпохи T+2 T-Invest отдаёт last_buy по правилу T+1 — не верим
            i_last = bisect.bisect_right(ds, lb) - 1          # последний торговый день не позже last_buy
        else:
            # последний день покупки: за 1 торговый день до фиксации (T+1 с 31.07.2023), раньше — за 2 (T+2)
            i_last = bisect.bisect_left(ds, rec) - (1 if rec >= DL_T1_FROM else 2)
        if i_last < 0 or i_last + 1 >= len(cs):
            continue
        try:
            if (datetime.strptime(rec, "%Y-%m-%d") - datetime.strptime(ds[i_last], "%Y-%m-%d")).days > 10:
                continue                                      # дыра в данных: свечи не покрывают отсечку
        except ValueError:
            continue
        pre = _dl_num(cs[i_last]["c"])
        i_gap = i_last + 1
        post = _dl_num(cs[i_gap].get("o")) or _dl_num(cs[i_gap]["c"])
        if not pre or not post:
            continue
        gap = pre - post
        n_after = len(cs) - 1 - i_gap                         # торговых дней после дня гэпа в данных
        closed, days, mx = False, None, post
        for k in range(0, min(horizon, n_after) + 1):
            h = _dl_num(cs[i_gap + k].get("h")) or _dl_num(cs[i_gap + k]["c"])
            if h is not None and h > mx:
                mx = h
            if h is not None and h >= pre:
                closed, days = True, k
                break
        rec_pct = 100.0 if closed else (round((mx - post) / gap * 100.0, 1) if gap > 0 else 0.0)
        out.append({"record": rec, "last_buy": ds[i_last], "gap_day": ds[i_gap], "div": val, "p_pre": round(pre, 4), "p_post": round(post, 4),
                    "gap": round(gap, 4), "gap_pct": round(gap / pre * 100.0, 2), "div_pct": round(val / pre * 100.0, 2), "k": round(gap / val, 3),
                    "closed": closed, "days": days, "recovery_pct": rec_pct, "n_after": n_after})
    return out


def dl_stats(gaps, horizon=DL_HORIZON):
    """Сводка по гэпам: медиана дней до закрытия (только закрытые), доли закрытых за 30/60/90 дней (среди событий, по которым уже можно судить),
    число «ещё открытых» (слишком свежих), средняя k = гэп / дивиденд, гистограмма сроков закрытия."""
    gs = gaps or []
    closed = [g for g in gs if g["closed"]]
    win = {}
    for w in DL_WINDOWS:
        den = [g for g in gs if g["closed"] or g["n_after"] >= w]
        num = [g for g in den if g["closed"] and g["days"] <= w]
        win[str(w)] = {"n": len(num), "of": len(den), "pct": round(len(num) / len(den) * 100.0, 1) if den else None}
    still_open = [g for g in gs if not g["closed"] and g["n_after"] < DL_WINDOWS[-1]]
    ks = [g["k"] for g in gs]
    hist = [{"label": lb, "n": sum(1 for g in closed if lo <= g["days"] <= hi)} for lb, lo, hi in DL_HIST]
    hist.append({"label": "не закрыт", "n": sum(1 for g in gs if not g["closed"] and g["n_after"] >= DL_WINDOWS[-1])})
    hist.append({"label": "ещё открыт", "n": len(still_open)})
    return {"count": len(gs), "closed": len(closed), "median_days": dl_median([g["days"] for g in closed]), "within": win, "still_open": len(still_open),
            "avg_k": round(sum(ks) / len(ks), 3) if ks else None, "median_k": round(dl_median(ks), 3) if ks else None,
            "avg_gap_pct": round(sum(g["gap_pct"] for g in gs) / len(gs), 2) if gs else None, "hist": hist}


def dl_payoff(div, p_pre, p_post_est, cost, tax_rate, fee_rate):
    """На одну акцию, изменение стоимости от цены накануне p_pre: удержание = дивиденд после налога − гэп;
    продажа накануне и обратная покупка по p_buy (на 0,1 гэпа выше открытия) = −(p_buy − p_post) − комиссии − налог с продажи."""
    div, p_pre, p_post_est = float(div), float(p_pre), float(p_post_est)
    tax, fee = float(tax_rate or 0.0), float(fee_rate or 0.0)
    gap = p_pre - p_post_est
    hold = div * (1.0 - tax) - gap
    p_buy = p_post_est + 0.1 * gap
    tax_sale = tax * max(0.0, p_pre - cost) if cost is not None else 0.0
    sell = (p_post_est - p_buy) - 2.0 * fee * p_pre - tax_sale   # продали по p_pre, откупили по p_buy: в итоге та же акция по p_post_est плюс разница
    return {"div": round(div, 4), "p_pre": round(p_pre, 4), "p_post_est": round(p_post_est, 4), "gap": round(gap, 4),
            "gap_pct": round(gap / p_pre * 100.0, 2) if p_pre else None, "p_buy": round(p_buy, 4), "hold": round(hold, 4),
            "sell_rebuy": round(sell, 4), "diff": round(sell - hold, 4), "tax_sale": round(tax_sale, 4), "fees": round(2.0 * fee * p_pre, 4),
            "cost_known": cost is not None, "tax_rate": tax, "fee_rate": fee}


def dl_streak(years, today_year):
    """Подряд идущие календарные годы с выплатами, оканчивающиеся текущим или прошлым годом."""
    ys = set(years)
    y = today_year if today_year in ys else today_year - 1
    n = 0
    while y in ys:
        n += 1
        y -= 1
    return n


DL_ZONES = [(80, "надёжно", "pos"), (50, "умеренно", "warn"), (0, "высокий риск", "neg")]


def dl_zone(score):
    if score is None:
        return None
    return next(z for z in DL_ZONES if score >= z[0])


def dl_safety(fin):
    """Оценка надёжности дивиденда 0–100. fin: {fcf, div_total (оба млн ₽), nd_ebitda, roe (%), pay_years (подряд), bank}.
    Компонент без данных исключается, баллы пересчитываются на доступный вес; при доступных <50 % веса оценки нет."""
    fin = fin or {}
    comps, flags = [], []

    def add(cid, name, w, pts, val, note):
        comps.append({"id": cid, "name": name, "weight": w, "points": pts, "value": val, "note": note, "available": pts is not None})

    fcf, dt = _dl_num(fin.get("fcf")), _dl_num(fin.get("div_total"))
    if fin.get("bank"):
        net = _dl_num(fin.get("net"))
        if net is None or dt is None or dt <= 0:
            add("fcf", "Покрытие дивидендов прибылью", 40, None, None, "нет данных" if dt is None or net is None else "нет выплат за 12 мес.")
        elif net <= 0:
            flags.append("дивиденды выплачиваются при убытке")
            add("fcf", "Покрытие дивидендов прибылью", 40, 0, None, "чистая прибыль не положительна")
        else:
            po = dt / net
            pts = 40 if po <= 0.5 else 28 if po <= 0.7 else 16 if po <= 0.9 else 8 if po <= 1.0 else 0
            if pts == 0:
                flags.append("дивиденды больше чистой прибыли")
            add("fcf", "Покрытие дивидендов прибылью", 40, pts, round(po, 2), "дивиденды / чистая прибыль = %d %%" % round(po * 100))
    elif fcf is None or dt is None or dt <= 0:
        add("fcf", "Покрытие дивидендов свободным денежным потоком", 40, None, None, "нет данных" if dt is None or fcf is None else "нет выплат за 12 мес.")
    else:
        cov = fcf / dt
        pts = 40 if cov >= 1.3 else 30 if cov >= 1.0 else 15 if cov >= 0.7 else 0
        if pts == 0:
            flags.append("дивиденды больше свободного денежного потока")
        add("fcf", "Покрытие дивидендов свободным денежным потоком", 40, pts, round(cov, 2), "FCF / дивиденды = ×%.2f" % cov)
    nd = _dl_num(fin.get("nd_ebitda"))
    if fin.get("bank"):
        add("nd", "Чистый долг / EBITDA", 30, None, None, "не применимо к банкам и финансовым компаниям")
    elif nd is None:
        add("nd", "Чистый долг / EBITDA", 30, None, None, "нет данных")
    else:
        pts = 30 if nd < 1.5 else 20 if nd < 2.5 else 10 if nd < 3.5 else 0
        add("nd", "Чистый долг / EBITDA", 30, pts, round(nd, 2), "×%.2f" % nd)
    py = fin.get("pay_years")
    if py is None:
        add("track", "Стабильность выплат", 20, None, None, "нет данных")
    else:
        pts = 20 if py >= 5 else 15 if py >= 3 else 5
        add("track", "Стабильность выплат", 20, pts, py, "лет подряд с выплатами: %d" % py)
    roe = _dl_num(fin.get("roe"))
    if roe is None:
        add("roe", "Рентабельность капитала (ROE)", 10, None, None, "нет данных")
    else:
        pts = 10 if roe >= 20 else 5 if roe >= 10 else 0
        add("roe", "Рентабельность капитала (ROE)", 10, pts, round(roe, 1), "%.1f %%" % roe)
    avail = sum(c["weight"] for c in comps if c["available"])
    if avail < 50:
        return {"score": None, "zone": None, "label": None, "available_weight": avail, "components": comps, "flags": flags,
                "note": "Недостаточно данных для оценки (доступно %d %% веса)." % avail}
    score = int(round(sum(c["points"] for c in comps if c["available"]) / float(avail) * 100.0))
    z = dl_zone(score)
    return {"score": score, "zone": z[2], "label": z[1], "available_weight": avail, "components": comps, "flags": flags, "note": None}


def dl_cagr(a, b, years):
    """Среднегодовой рост от a к b за years лет, % (None, если базы нет)."""
    if not a or not b or a <= 0 or b <= 0 or years <= 0:
        return None
    return round(((b / a) ** (1.0 / years) - 1.0) * 100.0, 1)


def dl_regularity(counts):
    """Сколько выплат в год обычно (по последним полным годам с выплатами): {per_year, label}."""
    c = [n for n in counts if n]
    if not c:
        return {"per_year": None, "label": "нет выплат"}
    m = int(round(dl_median(c)))
    same = sum(1 for n in c if n == m) / float(len(c))
    lab = {1: "раз в год", 2: "два раза в год", 3: "три раза в год", 4: "раз в квартал"}.get(m, "%d раз в год" % m)
    if len(c) >= 3 and same < 0.6:
        lab = "нерегулярно (обычно %s)" % lab
    return {"per_year": m, "label": lab}


def dl_div_profile(divs, price, today=None, qty=None, tax=0.13):
    """Сводный анализ дивидендов бумаги по полной истории (рублёвые выплаты, по году даты фиксации реестра).
    divs: [{record, value, ...}]. Годовые суммы, рост за 5/10 лет (CAGR), доходности, серии лет с выплатами и с ростом,
    регулярность, пропущенные годы, ближайшая выплата на позицию qty (до и после налога)."""
    today = today or date.today().isoformat()
    ty = int(today[:4])
    rows = sorted((d for d in divs or [] if d.get("record") and _dl_num(d.get("value"))), key=lambda d: d["record"])
    by = {}
    for d in rows:
        y = int(d["record"][:4])
        b = by.setdefault(y, {"year": y, "sum": 0.0, "n": 0, "announced": 0.0})
        if d["record"] >= today:
            b["announced"] += float(d["value"])
        else:
            b["sum"] += float(d["value"])
            b["n"] += 1
    years = []
    if by:
        for y in range(min(by), max(max(by), ty) + 1):
            b = by.get(y) or {"year": y, "sum": 0.0, "n": 0, "announced": 0.0}
            years.append({"year": y, "sum": round(b["sum"], 4), "n": b["n"], "announced": round(b["announced"], 4),
                          "yield_pct": round((b["sum"] + b["announced"]) / price * 100.0, 2) if price else None})
    sums = {r["year"]: r["sum"] for r in years}
    last_full = ty - 1
    paid_years = {y for y, v in sums.items() if v > 0}
    grow = 0
    y = last_full
    while sums.get(y, 0) > 0 and sums.get(y - 1, 0) > 0 and sums[y] > sums[y - 1] * 1.0001:
        grow += 1
        y -= 1
    nodecl = 0
    y = last_full
    while sums.get(y, 0) > 0 and sums.get(y - 1, 0) > 0 and sums[y] >= sums[y - 1] * 0.9999:
        nodecl += 1
        y -= 1
    first = min(paid_years) if paid_years else None
    skipped = [y for y in range(first, last_full + 1) if y not in paid_years] if first else []
    y1 = (datetime.strptime(today, "%Y-%m-%d") - timedelta(days=365)).strftime("%Y-%m-%d")
    y1f = (datetime.strptime(today, "%Y-%m-%d") + timedelta(days=365)).strftime("%Y-%m-%d")
    ttm = sum(float(d["value"]) for d in rows if y1 < d["record"] < today)
    fwd = sum(float(d["value"]) for d in rows if today <= d["record"] <= y1f)
    cnt = {r["year"]: r["n"] for r in years}
    recent = [cnt.get(y, 0) for y in range(last_full - 4, last_full + 1)]
    pct = lambda v: round(v / price * 100.0, 2) if price and v else None  # noqa: E731
    nx = _dl_next(rows, today) if rows else None
    nx_pos = None
    if nx and nx.get("upcoming") and qty:
        g = float(nx["value"]) * float(qty)
        nx_pos = {"qty": qty, "gross": round(g, 2), "net": round(g * (1.0 - tax), 2), "tax_rate": tax}
    return {"years": years, "first_year": first, "count": len([d for d in rows if d["record"] < today]),
            "ttm": round(ttm, 4), "yield_ttm": pct(ttm), "last_year": round(sums.get(last_full, 0.0), 4), "yield_last_year": pct(sums.get(last_full, 0.0)),
            "forward": round(fwd, 4) if fwd else None, "yield_forward": pct(fwd),
            "cagr5": dl_cagr(sums.get(last_full - 5), sums.get(last_full), 5), "cagr10": dl_cagr(sums.get(last_full - 10), sums.get(last_full), 10),
            "streak_paid": dl_streak(paid_years, ty) if paid_years else 0, "streak_growth": grow, "streak_nodecline": nodecl,
            "skipped": skipped, "regularity": dl_regularity(recent), "last_full_year": last_full, "next": nx, "next_pos": nx_pos}


def dl_received(ops, secid, alt=None, names=()):
    """Полученные дивиденды по бумаге из операций сводки (строки [дата, тип, вид, имя, тикер, кол-во, цена, сумма, валюта, …]).
    Налог с дивидендов вычитается; группировка по дате зачисления и по годам. Только рубли.
    alt — второй идентификатор (ISIN); names — полные названия: для строк импорта без тикера сверяем название."""
    ids = {x.upper() for x in (secid, alt) if x}
    nms = {str(n).strip().lower() for n in names or () if n}
    by = {}
    for o in ops or []:
        try:
            dt, kind, tk, amt, cur = (o[0] or "")[:10], o[2], (o[4] or "").upper(), float(o[7] or 0), (o[8] or "rub").lower()
        except (IndexError, TypeError, ValueError):
            continue
        if not (tk in ids or (not tk and str(o[3] or "").strip().lower() in nms)) or cur != "rub" or kind not in ("dividends", "tax_dividend") or not dt:
            continue
        b = by.setdefault(dt, {"date": dt, "gross": 0.0, "tax": 0.0})
        if kind == "dividends":
            b["gross"] += amt
        else:
            b["tax"] += -amt
    items = sorted(by.values(), key=lambda b: b["date"], reverse=True)
    yrs = {}
    for b in items:
        b["gross"], b["tax"] = round(b["gross"], 2), round(b["tax"], 2)
        b["net"] = round(b["gross"] - b["tax"], 2)
        y = yrs.setdefault(b["date"][:4], {"year": int(b["date"][:4]), "gross": 0.0, "net": 0.0})
        y["gross"] = round(y["gross"] + b["gross"], 2)
        y["net"] = round(y["net"] + b["net"], 2)
    return {"items": items, "years": sorted(yrs.values(), key=lambda y: y["year"]), "gross": round(sum(b["gross"] for b in items), 2),
            "tax": round(sum(b["tax"] for b in items), 2), "net": round(sum(b["net"] for b in items), 2)}


# ── сеть: сбор данных по бумаге ──

def _dl_rub_divs(items):
    return [d for d in items or [] if str(d.get("cur") or "RUB").upper() in ("RUB", "RUR") and _dl_num(d.get("value"))]


def _dl_fin_inputs(secid, q, dv, divs, cfg):
    """Входы dl_safety: МСФО (FCF, долг) + мультипликаторы (ND/EBITDA, ROE) + число лет подряд с выплатами. Любой сбой -> компонент без данных."""
    today = date.today()
    out = {"fcf": None, "net": None, "div_total": None, "nd_ebitda": None, "roe": None, "bank": (q or {}).get("sector") == "Банки и финансы", "pay_years": None}
    years = {int(d["record"][:4]) for d in divs if d.get("record") and d["record"] <= today.isoformat()}
    if years:
        out["pay_years"] = dl_streak(years, today.year)
    try:
        fin = ifrs_fin(secid)
        if fin.get("bank"):
            out["bank"] = True
        c = (fin.get("ltm") or (fin.get("years") or [None])[-1]) if fin.get("status") == "ok" else None
        if c:
            out["fcf"] = c.get("fcf")
            out["net"] = c.get("net")
            out["nd_ebitda"] = c.get("nd_ebitda")
            if c.get("roe") is not None:
                out["roe"] = c["roe"] * 100
    except Exception:  # noqa: BLE001
        pass
    try:
        m = stock_multiples(secid, (q or {}).get("cap"), (q or {}).get("asset_uid"), cfg) or {}
        if m.get("nd_ebitda") is not None:
            out["nd_ebitda"] = m["nd_ebitda"]
        if m.get("roe") is not None:
            out["roe"] = m["roe"]
    except Exception:  # noqa: BLE001
        pass
    price, cap, ttm = (q or {}).get("price"), (q or {}).get("cap"), (dv or {}).get("ttm_value")
    if price and cap and ttm:
        out["div_total"] = ttm * (cap / price) / 1e6
    return out


def _dl_analyze(secid, cfg, q=None, force=False):
    """Тяжёлый расчёт по одной бумаге (кэш 12 ч): дивиденды, гэпы, надёжность. Ошибки сети — в поле error, не исключением."""
    secid = (secid or "").strip().upper()
    key = "dl_v6_%s_%d" % (secid, 1 if (cfg or {}).get("token") else 0)
    if not force:
        hit = store().get(key, DL_TTL)
        if hit:
            return hit
    err = []
    kind = "share"
    if q is None:
        try:
            q, kind = stk_lookup(secid, cfg)                 # акции, затем биржевые фонды (у фонда дивиденды — с сервера данных и dohod.ru)
        except Exception as e:  # noqa: BLE001
            q = None
            err.append("список акций недоступен: %s" % str(e)[:80])
    q = q or {}
    kind = kind or "share"
    candles = []
    try:
        candles = stock_candles(secid, 24, days=2400)
    except Exception as e:  # noqa: BLE001
        err.append("свечи Мосбиржи недоступны: %s" % str(e)[:80])
    price = q.get("price") or (candles[-1]["c"] if candles else None)
    dv = {}
    try:
        dv = stock_dividends(secid, price, q.get("uid"), cfg, history=True) or {}
    except Exception as e:  # noqa: BLE001
        err.append("дивиденды недоступны: %s" % str(e)[:80])
    divs = sorted(_dl_rub_divs(dv.get("items")), key=lambda d: d["record"])
    gaps = dl_gaps(divs, candles)
    safety = dl_safety(_dl_fin_inputs(secid, q, dv, divs, cfg)) if kind != "fund" else None   # у фонда нет отчётности эмитента
    res = {"secid": secid, "kind": kind, "isin": q.get("isin"), "full_name": q.get("name"), "name": q.get("shortname") or q.get("name") or secid, "sector": q.get("sector"), "price": price,
           "divs": [{k: d.get(k) for k in ("record", "payment", "last_buy", "declared", "value", "src")} for d in divs], "gaps": gaps, "safety": safety,
           "div_source": dv.get("source"), "div_hist": dv.get("hist"), "candles_to": candles[-1]["t"][:10] if candles else None, "candles_n": len(candles), "error": "; ".join(err) or None}
    if candles and divs and not err:
        try:
            store().put(key, res)
        except Exception:  # noqa: BLE001
            pass
    return res


def _dl_next(divs, today):
    """Ближайший будущий дивиденд (по дате фиксации); если нет — последний прошедший."""
    fut = sorted((d for d in divs if d["record"] >= today), key=lambda d: d["record"])
    past = sorted((d for d in divs if d["record"] < today), key=lambda d: d["record"])
    x = dict(fut[0], upcoming=True) if fut else dict(past[-1], upcoming=False) if past else None
    if x and not x.get("last_buy"):
        try:                                                  # оценка: предыдущий будний день (праздники не учтены)
            d = datetime.strptime(x["record"], "%Y-%m-%d") - timedelta(days=1)
            while d.weekday() > 4:
                d -= timedelta(days=1)
            x["last_buy"], x["last_buy_est"] = d.strftime("%Y-%m-%d"), True
        except ValueError:
            pass
    return x


def _dl_cost_map(cfg, acc, summ=None):
    """Позиции-акции (и фонды) счёта: {тикер: {qty, avg, name}}. Без токена/счёта — пусто. summ — готовая сводка build_summary."""
    out = {}
    try:
        for r in (summ or build_summary(cfg, acc, "all"))["portfolio"]["positions"]:
            if r.get("type") in ("share", "etf") and (r.get("qty") or 0) > 0 and r.get("ticker"):
                o = out.setdefault(r["ticker"], {"qty": 0.0, "cost": 0.0, "name": r.get("name") or r["ticker"], "price": r.get("price")})
                o["qty"] += r["qty"]
                o["cost"] += (r.get("avg") or 0.0) * r["qty"]
    except Exception:  # noqa: BLE001
        return None
    for o in out.values():
        o["avg"] = o["cost"] / o["qty"] if o["qty"] else None
    return out


def _dl_stock_view(secid, cfg, acc, tax, fee, force):
    secid = (secid or "").strip().upper()
    if not re.fullmatch(r"[A-Z0-9._-]{1,16}", secid):
        raise ApiError("Некорректный тикер.", 400)
    a = _dl_analyze(secid, cfg, force=force)
    gaps = a["gaps"]
    st = dl_stats(gaps)
    today = date.today().isoformat()
    nx = _dl_next(a["divs"], today)
    summ = None
    if acc:
        try:
            summ = build_summary(cfg, acc, "all")
        except Exception:  # noqa: BLE001 — нет токена/счёта: анализ без позиции
            summ = None
    cmap = (_dl_cost_map(cfg, acc, summ) or {}) if summ else {}
    pos = cmap.get(secid) or (cmap.get(a["isin"]) if a.get("isin") else None)    # импортированные отчёты: тикер бывает равен ISIN
    received = dl_received(summ.get("ops"), secid, a.get("isin"), (a.get("full_name"),)) if summ else None
    profile = dl_div_profile(a["divs"], a.get("price"), today, pos["qty"] if pos else None, tax)
    px = a.get("price")
    divs = [dict(d, future=d["record"] >= today, yield_pct=round(d["value"] / px * 100.0, 2) if px else None) for d in reversed(a["divs"])]
    payoff = None
    if nx and a.get("price"):
        k = st["median_k"] if st["median_k"] is not None else 1.0
        payoff = dl_payoff(nx["value"], a["price"], a["price"] - k * nx["value"], pos["avg"] if pos else None, tax, fee)
        payoff.update(record=nx["record"], upcoming=nx["upcoming"], k_used=round(k, 3), k_fallback=st["median_k"] is None,
                      qty=pos["qty"] if pos else None, held=bool(pos))
    return {"ok": True, "mode": "stock", "secid": secid, "name": a["name"], "sector": a["sector"], "price": a["price"], "gaps": list(reversed(gaps)),
            "stats": st, "safety": a["safety"], "next": nx, "payoff": payoff, "tax": tax, "fee": fee, "div_source": a["div_source"], "div_hist": a.get("div_hist"),
            "candles_to": a["candles_to"], "error": a["error"], "kind": a.get("kind") or "share", "divs": divs, "profile": profile,
            "position": {"qty": pos["qty"], "avg": pos["avg"]} if pos else None, "received": received if received and received["items"] else None}


def _dl_portfolio_view(cfg, acc, tax, force):
    pos = _dl_cost_map(cfg, acc)
    if pos is None:
        return {"ok": True, "mode": "portfolio", "rows": [], "held": 0, "error": "Не удалось получить позиции счёта.", "token": bool(cfg.get("token"))}
    if not pos:
        return {"ok": True, "mode": "portfolio", "rows": [], "held": 0, "error": None, "token": bool(cfg.get("token"))}
    try:
        uni = {r["secid"]: r for r in stocks_universe(cfg=cfg)}
    except Exception:  # noqa: BLE001
        uni = {}
    by_isin = {r.get("isin"): k for k, r in uni.items() if r.get("isin")}
    for t in [t for t in pos if t not in uni and t in by_isin]:   # импортированные отчёты: вместо тикера ISIN
        o = pos.pop(t)
        k = by_isin[t]
        if k in pos:
            q0 = pos[k]
            q0["cost"] = q0.get("cost", 0.0) + o.get("cost", 0.0)
            q0["qty"] += o["qty"]
            q0["avg"] = q0["cost"] / q0["qty"] if q0["qty"] else None
        else:
            pos[k] = o
    tickers = sorted(pos)

    def one(t):
        try:
            return _dl_analyze(t, cfg, uni.get(t), force)
        except Exception as e:  # noqa: BLE001
            return {"secid": t, "divs": [], "gaps": [], "safety": {"score": None}, "error": str(e)[:100], "name": pos[t]["name"], "price": pos[t].get("price")}
    res = pool_map(one, tickers, workers=6)
    today = date.today().isoformat()
    rows = []
    for t, a in zip(tickers, res):
        if not a.get("divs") and not a.get("gaps") and not a.get("price") and uni and t not in uni:
            continue                                            # не акция TQBR (например, зарубежная) — радар её не видит
        nx = _dl_next(a.get("divs") or [], today)
        st = dl_stats(a.get("gaps") or [])
        p = pos[t]
        row = {"secid": t, "name": a.get("name") or p["name"], "qty": p["qty"], "avg": p["avg"], "price": a.get("price") or p.get("price"),
               "next": nx if nx and nx["upcoming"] else None, "last": nx if nx and not nx["upcoming"] else None,
               "safety": (a.get("safety") or {}).get("score"), "zone": (a.get("safety") or {}).get("zone"), "label": (a.get("safety") or {}).get("label"),
               "median_days": st["median_days"], "events": st["count"], "median_k": st["median_k"], "within90": st["within"]["90"]["pct"], "error": a.get("error")}
        if row["next"]:
            row["net_total"] = round(row["next"]["value"] * p["qty"] * (1.0 - tax), 2)
            row["gross_total"] = round(row["next"]["value"] * p["qty"], 2)
        rows.append(row)
    rows.sort(key=lambda r: (0 if r["next"] else 1, r["next"]["record"] if r["next"] else "", r["secid"]))
    return {"ok": True, "mode": "portfolio", "rows": rows, "held": len(pos), "tax": tax, "error": None, "token": bool(cfg.get("token"))}


def _api_divlab(cfg, acc, q, force):
    def num(k, d, lo, hi):
        v = _dl_num(str(q.get(k) or "").replace(",", "."))
        return d if v is None else min(hi, max(lo, v))
    tax = num("tax", 13.0, 0.0, 35.0) / 100.0
    fee = num("fee", 0.05, 0.0, 2.0) / 100.0
    secid = (q.get("secid") or "").strip()
    try:
        if secid:
            return _dl_stock_view(secid, cfg, acc if q.get("account") else None, tax, fee, bool(force))
        return _dl_portfolio_view(cfg, acc, tax, bool(force))
    except ApiError:
        raise
    except Exception as e:  # noqa: BLE001
        return {"ok": True, "mode": "stock" if secid else "portfolio", "rows": [], "gaps": [], "error": "Данные временно недоступны: %s" % str(e)[:120]}


API_GET["/api/divlab"] = _api_divlab
# ═══════════════════ длинная история дивидендов: dohod.ru (с 2000-х) + слияние с данными T-Invest / сервера ═══════════════════
# T-Invest GetDividends отдаёт ~6 лет, у компаний история 20+ лет. Добираем более ранние годы со страницы
# https://www.dohod.ru/ik/analytics/dividend/<тикер> (публичная, без входа; robots.txt разрешает /ik/). Запрос — обычный GET без личных данных,
# через сервер данных (белый список хостов) или напрямую. Разбор устойчив к смене порядка колонок (колонки ищутся по заголовкам).
# Строки «прогноз» и «рекомендовано» (запись реестра ещё не утверждена) в историю не смешиваются — они лежат отдельно в upcoming.
# Описательная статистика по прошлым выплатам, не инвестиционная рекомендация.

DH_BASE = "https://www.dohod.ru/ik/analytics/dividend/%s"
DH_TTL = 7 * 86400                    # история прошлых лет неизменна: неделя
DH_ERR_TTL = 3600                     # сбой сети: повтор не чаще раза в час, пока отдаём прошлый успешный ответ
DH_NF_TTL = 3 * 86400                 # на dohod.ru нет страницы тикера (облигации, ETF, новые бумаги)
DH_SRC = "dohod"
DH_SRC_NAME = "dohod.ru"
DH_DATE_TOL = 3                       # дедупликация: даты фиксации реестра ±3 дня
DH_SUM_TOL = 0.01                     # ... и суммы ±1 %
DH_LIMIT = 200                        # строк в сводке с полной историей
_dh_lock = threading.Lock()
_dh_last = [0.0]
_DH_CUR = {"руб": "RUB", "rub": "RUB", "usd": "USD", "$": "USD", "долл": "USD", "eur": "EUR", "€": "EUR", "cny": "CNY", "юан": "CNY",
           "hkd": "HKD", "гонкон": "HKD", "kzt": "KZT", "тенге": "KZT"}


def dh_slug(secid):
    s = (secid or "").strip()
    return s.lower() if re.fullmatch(r"[A-Za-z0-9]{1,12}", s) else None


def _dh_text(frag):
    t = re.sub(r"<[^>]+>", " ", frag or "")
    t = t.replace("&nbsp;", " ").replace("&#160;", " ").replace("\xa0", " ").replace("&amp;", "&").replace("&quot;", '"')
    return re.sub(r"\s+", " ", t).strip()


def _dh_date(t):
    m = re.search(r"(\d{1,2})\.(\d{1,2})\.(\d{4})", t or "")
    if not m:
        return None
    try:
        return date(int(m.group(3)), int(m.group(2)), int(m.group(1))).isoformat()
    except ValueError:
        return None


def _dh_amount(t):
    m = re.search(r"-?\d[\d ]*(?:[.,]\d+)?", (t or "").replace(" ", " "))
    if not m:
        return None
    try:
        v = float(m.group(0).replace(" ", "").replace(",", "."))
    except ValueError:
        return None
    return v if v == v and v not in (float("inf"), float("-inf")) else None


def _dh_currency(page):
    """Валюта из заголовков вида «Дивиденд (руб.)»; по умолчанию рубли."""
    for m in re.finditer(r"Дивиденд[^<]{0,12}\(([^)<]{1,12})\)", page or "", re.I):
        c = m.group(1).strip().lower()
        for k, v in _DH_CUR.items():
            if k in c:
                return v
    return "RUB"


def dh_parse(page, today=None):
    """HTML страницы dohod.ru -> {rows, upcoming, currency, title} или None (страница в неожиданном формате).
    rows — фактические и утверждённые выплаты [{record, declared, value, cur, status paid|approved, src}], от новых к старым;
    upcoming — рекомендации и прогнозы (status recommended|forecast), в историю не идут."""
    if not page or not isinstance(page, str):
        return None
    today = today or date.today().isoformat()
    cur = _dh_currency(page)
    tbl = None
    for m in re.finditer(r"<table\b[^>]*>(.*?)</table>", page, re.S | re.I):
        body = m.group(1)
        head = _dh_text(" ".join(re.findall(r"<th\b[^>]*>(.*?)</th>", body, re.S | re.I))).lower()
        if "закрытия реестра" in head and "дивиденд" in head:
            tbl = body
            break
    if tbl is None:
        return None
    cols = {"declared": 0, "record": 1, "amount": 3}
    for tr in re.finditer(r"<tr\b([^>]*)>(.*?)</tr>", tbl, re.S | re.I):
        ths = [_dh_text(x).lower() for x in re.findall(r"<th\b[^>]*>(.*?)</th>", tr.group(2), re.S | re.I)]
        if ths:
            for i, h in enumerate(ths):
                if "закрытия реестра" in h:
                    cols["record"] = i
                elif "объявлен" in h:
                    cols["declared"] = i
                elif h.startswith("дивиденд"):
                    cols["amount"] = i
            break
    rows, upcoming, seen = [], [], set()
    for tr in re.finditer(r"<tr\b([^>]*)>(.*?)</tr>", tbl, re.S | re.I):
        cells = re.findall(r"<td\b[^>]*>(.*?)</td>", tr.group(2), re.S | re.I)
        if len(cells) <= max(cols.values()):
            continue
        rec = _dh_date(_dh_text(cells[cols["record"]]))
        val = _dh_amount(_dh_text(cells[cols["amount"]]))
        if not rec or not val or val <= 0:
            continue
        decl = _dh_date(_dh_text(cells[cols["declared"]]))
        raw = tr.group(2).lower()
        is_fc = "forecast" in tr.group(1).lower() or "(прогноз)" in raw
        if is_fc:
            status = "recommended" if ("рекоменд" in raw and "(прогноз)" not in raw) else "forecast"
        elif rec >= today:
            status = "approved" if decl else "recommended"
        else:
            status = "paid"
        item = {"record": rec, "declared": decl, "value": round(val, 6), "cur": cur, "status": status, "src": DH_SRC}
        if status in ("paid", "approved"):
            k = (rec, item["value"])
            if k in seen:
                continue                                      # у источника встречаются дубли строк
            seen.add(k)
            rows.append(item)
        else:
            upcoming.append(item)
    if not rows and not upcoming and "<td" not in tbl:
        return None
    rows.sort(key=lambda x: x["record"], reverse=True)
    upcoming.sort(key=lambda x: x["record"])
    h1 = re.search(r"<h1[^>]*>(.*?)</h1>", page, re.S | re.I)
    return {"rows": rows, "upcoming": upcoming, "currency": cur, "title": _dh_text(h1.group(1)) if h1 else ""}


def _dh_http(url):
    with _dh_lock:                                            # не чаще одного запроса в секунду на всё приложение
        wait = 1.0 - (time.time() - _dh_last[0])
        if wait > 0:
            time.sleep(wait)
        _dh_last[0] = time.time()
    return ext_open(url, timeout=20)[1].decode("utf-8", "replace")


def dh_history(secid, today=None, fetch=None):
    """Тикер -> {status ok|nodata|parse|err, rows, upcoming, fetched, ...}. Кэш в store: 7 суток; сбой сети отдаёт прошлый успешный ответ.
    Не бросает исключений. fetch(url) -> html подменяется в тестах."""
    slug = dh_slug(secid)
    empty = {"status": "nodata", "rows": [], "upcoming": [], "currency": "RUB", "url": None, "source": DH_SRC_NAME}
    if not slug:
        return empty
    key = "dh_v1_" + slug
    now = time.time()
    try:
        hit = store().get(key)
    except Exception:  # noqa: BLE001
        hit = None
    if hit:
        age = now - (hit.get("fetched") or 0)
        ttl = DH_TTL if hit.get("status") == "ok" else DH_NF_TTL if hit.get("status") == "nodata" else DH_ERR_TTL
        if age < ttl and now >= (hit.get("retry_at") or 0):
            return hit
        if hit.get("status") == "ok" and now < (hit.get("retry_at") or 0):
            return hit                                        # недавний сбой при обновлении: пока отдаём прошлую историю
    url = DH_BASE % slug
    try:
        page = (fetch or _dh_http)(url)
        parsed = dh_parse(page, today)
        if parsed is None:
            res = dict(empty, status="parse", url=url, fetched=now, note="Страница dohod.ru в неожиданном формате.")
        else:
            res = {"status": "ok" if parsed["rows"] or parsed["upcoming"] else "nodata", "rows": parsed["rows"], "upcoming": parsed["upcoming"],
                   "currency": parsed["currency"], "title": parsed["title"], "url": url, "source": DH_SRC_NAME, "fetched": now}
    except urllib.error.HTTPError as e:
        if e.code == 404:
            res = dict(empty, url=url, fetched=now, note="На dohod.ru нет страницы дивидендов этого тикера.")
        else:
            res = dh_err(hit, empty, url, now, "dohod.ru временно недоступен (HTTP %s)." % e.code)
    except Exception as e:  # noqa: BLE001
        res = dh_err(hit, empty, url, now, "dohod.ru недоступен: %s" % str(e)[:80])
    if res["status"] == "parse" and hit and hit.get("status") == "ok":
        res = dict(hit, retry_at=now + DH_ERR_TTL)            # разметка поменялась, а старая история есть — не затираем
    try:
        store().put(key, res)
    except Exception:  # noqa: BLE001
        pass
    return res


def dh_err(hit, empty, url, now, note):
    """Сетевая ошибка: есть прошлая успешная история — отдаём её (повтор через час), иначе запись об ошибке."""
    if hit and hit.get("status") == "ok":
        return dict(hit, retry_at=now + DH_ERR_TTL, note=note)
    return dict(empty, status="err", url=url, fetched=now, note=note)


def _dh_days(a, b):
    try:
        return abs((datetime.strptime(a[:10], "%Y-%m-%d") - datetime.strptime(b[:10], "%Y-%m-%d")).days)
    except (TypeError, ValueError):
        return 10 ** 6


def _dh_same(a, b):
    """Одна и та же выплата: дата фиксации ±3 дня и сумма ±1 % (валюта, если указана, совпадает)."""
    if _dh_days(a["record"], b["record"]) > DH_DATE_TOL:
        return False
    if str(a.get("cur") or "RUB").upper() != str(b.get("cur") or "RUB").upper():
        return False
    x, y = float(a["value"]), float(b["value"])
    return abs(x - y) <= DH_SUM_TOL * max(abs(x), abs(y))


def dh_merge(items, hist_rows, today=None):
    """Слияние: items (T-Invest / сервер данных) сохраняются как есть; из hist_rows добираются выплаты вне периода, который покрывают items
    (раньше самой ранней и позже самой поздней с запасом ±3 дня). Внутри покрытого периода дубликаты по дате/сумме отбрасываются и
    ничего нового не добавляется (данные брокера точнее). Если единицы расходятся целым коэффициентом (сплит акций) — на совпавших датах
    он определяется и применяется к добираемым строкам. Возвращает (items + новые, сколько добавлено, коэффициент пересчёта или None)."""
    today = today or date.today().isoformat()
    base = [dict(x) for x in items or []]
    hist = [h for h in hist_rows or [] if h.get("record") and h.get("value") and h.get("status", "paid") in ("paid", "approved")]
    if not hist:
        return base, 0, None
    scale = None
    pairs = []
    for h in hist:
        for b in base:
            if _dh_days(h["record"], b["record"]) <= DH_DATE_TOL and str(b.get("cur") or "RUB").upper() == str(h.get("cur") or "RUB").upper() and b.get("value"):
                pairs.append(float(b["value"]) / float(h["value"]))
                break
    if pairs and all(abs(r - 1) > DH_SUM_TOL for r in pairs):
        lo, hi = min(pairs), max(pairs)
        if hi / lo <= 1.03 and (lo >= 2 or hi <= 0.5):
            scale = sorted(pairs)[len(pairs) // 2]
    if base:
        lo_d = min(b["record"] for b in base)
        hi_d = max(b["record"] for b in base)
        cover = (( datetime.strptime(lo_d[:10], "%Y-%m-%d") - timedelta(days=DH_DATE_TOL)).strftime("%Y-%m-%d"),
                 (datetime.strptime(hi_d[:10], "%Y-%m-%d") + timedelta(days=DH_DATE_TOL)).strftime("%Y-%m-%d"))
    else:
        cover = None
    added = []
    for h in sorted(hist, key=lambda x: x["record"]):
        x = dict(h)
        if scale:
            x["value"] = round(float(x["value"]) * scale, 6)
            x["scaled"] = round(scale, 6)
        if cover and cover[0] <= x["record"] <= cover[1]:
            continue                                          # покрыто основным источником
        if any(_dh_same(x, b) for b in base + added):
            continue
        x["src"] = DH_SRC
        x.setdefault("payment", None)
        x.setdefault("last_buy", None)
        added.append(x)
    return base + added, len(added), scale


def dh_enrich(items, secid, today=None, fetch=None):
    """items основного источника + история dohod.ru -> (items, meta). meta: {src, added, from, years, status, note}. Не бросает исключений."""
    meta = {"src": DH_SRC_NAME, "added": 0, "status": "off", "from": None, "years": None, "url": None, "note": None, "scaled": None}
    try:
        h = dh_history(secid, today, fetch)
        meta.update(status=h.get("status"), url=h.get("url"), note=h.get("note"))
        if h.get("status") != "ok":
            return items, meta
        merged, n, scale = dh_merge(items, h.get("rows"), today)
        meta.update(added=n, scaled=scale)
        if n:
            recs = [x["record"] for x in merged if x.get("src") == DH_SRC]
            meta["from"] = min(recs)
        return merged, meta
    except Exception as e:  # noqa: BLE001
        meta.update(status="err", note=str(e)[:80])
        return items, meta
# ═══════════════════════════════ бегущая строка котировок ═══════════════════════════════
# /api/ticker -> {"items":[{id,label,price,chg,unit,kind}], "updated": ts}. Проценты — в процентных пунктах.
# Каждый источник тянется независимо: сбой одного не убирает остальные.

TK_ISS = "https://iss.moex.com/iss/"
TK_BLUE = ("SBER", "GAZP", "LKOH", "ROSN", "NVTK", "GMKN", "YDEX", "T", "PLZL", "VTBR", "MGNT", "TATN", "CHMF", "MTSS")
TK_UA = "Mozilla/5.0 (compatible; tanalytic)"


def tk_f(x):
    try:
        v = float(x)
    except (TypeError, ValueError):
        return None
    return v if v == v else None


def tk_table(j, name):
    t = (j or {}).get(name) or {}
    cols = t.get("columns") or []
    return [dict(zip(cols, r)) for r in (t.get("data") or [])]


def tk_item(id_, label, price, chg, unit, kind):
    price = tk_f(price)
    if not price:
        return None
    chg = tk_f(chg)
    return {"id": id_, "label": label, "price": price, "chg": None if chg is None else round(chg, 2), "unit": unit, "kind": kind}


def tk_parse_index(j):
    for r in tk_table(j, "marketdata"):
        it = tk_item("IMOEX", "IMOEX", r.get("CURRENTVALUE"), r.get("LASTCHANGEPRC"), "", "index")
        if it:
            return it
    return None


def tk_parse_stocks(rows):
    by = {r.get("secid"): r for r in rows or []}
    out = []
    for s in TK_BLUE:
        r = by.get(s)
        it = r and tk_item(s, s, r.get("price"), r.get("chg_d"), "₽", "stock")
        if it:
            out.append(it)
    return out


TK_CETS = (("USD000UTSTOM", "USD/RUB", "USD", "fx"), ("CNYRUB_TOM", "CNY/RUB", "CNY", "fx"),
           ("EUR_RUB__TOM", "EUR/RUB", "EUR", "fx"), ("GLDRUB_TOM", "Золото, ₽/г", "GOLD", "metal"))


def tk_parse_cets(j):
    """{id: item}; бумаги без сделок за сессию (USD после санкций) пропускаем — для них есть запасной ЦБ."""
    out = {}
    names = {c[0]: c for c in TK_CETS}
    prev = {r.get("SECID"): tk_f(r.get("PREVPRICE")) for r in tk_table(j, "securities")}
    for r in tk_table(j, "marketdata"):
        c = names.get(r.get("SECID"))
        if not c:
            continue
        nt = tk_f(r.get("NUMTRADES"))
        last = tk_f(r.get("LAST"))
        if not last or (nt is not None and nt <= 0):
            continue
        chg = tk_f(r.get("LASTCHANGEPRC"))
        if chg is None and prev.get(r.get("SECID")):
            chg = (last / prev[r["SECID"]] - 1) * 100
        it = tk_item(c[2], c[1], last, chg, "₽", c[3])
        if it:
            out[c[2]] = it
    return out


def tk_parse_cbr(xml):
    """XML_daily ЦБ -> {'USD': 90.5, ...} (курс за единицу)."""
    out = {}
    for m in re.finditer(r"<Valute[^>]*>(.*?)</Valute>", xml or "", re.S):
        b = m.group(1)
        code = re.search(r"<CharCode>(\w+)</CharCode>", b)
        nom = re.search(r"<Nominal>(\d+)</Nominal>", b)
        val = re.search(r"<Value>([\d.,]+)</Value>", b)
        if code and nom and val:
            out[code.group(1)] = float(val.group(1).replace(",", ".")) / float(nom.group(1))
    return out


def tk_cbr_items(cur, prev, want):
    out = {}
    labels = {"USD": "USD/RUB", "CNY": "CNY/RUB", "EUR": "EUR/RUB"}
    for code in want:
        v = cur.get(code)
        if not v:
            continue
        p = prev.get(code)
        out[code] = tk_item(code, labels[code] + " (ЦБ)", v, (v / p - 1) * 100 if p else None, "₽", "fx")
    return {k: v for k, v in out.items() if v}


def tk_parse_btc(j, src):
    """coingecko: {'bitcoin':{'usd':..,'usd_24h_change':..}}; binance: {'lastPrice','priceChangePercent'}."""
    if src == "coingecko":
        b = (j or {}).get("bitcoin") or {}
        return tk_item("BTC", "Bitcoin", b.get("usd"), b.get("usd_24h_change"), "$", "crypto")
    return tk_item("BTC", "Bitcoin", (j or {}).get("lastPrice"), (j or {}).get("priceChangePercent"), "$", "crypto")


def _tk_get(url, timeout=12):
    return ext_open(url, headers={"User-Agent": TK_UA, "Accept": "application/json"}, timeout=timeout)[1].decode("utf-8", "replace")


def tk_fetch_index():
    return tk_parse_index(json.loads(http_text(TK_ISS + "engines/stock/markets/index/securities/IMOEX.json?iss.meta=off&iss.only=marketdata"
                                               "&marketdata.columns=SECID,CURRENTVALUE,LASTCHANGEPRC", timeout=15)))


def tk_fetch_cets():
    return tk_parse_cets(json.loads(http_text(TK_ISS + "engines/currency/markets/selt/boards/CETS/securities.json?iss.meta=off&iss.only=marketdata,securities"
                                              "&marketdata.columns=SECID,LAST,LASTCHANGEPRC,NUMTRADES&securities.columns=SECID,PREVPRICE", timeout=15)))


def tk_fetch_cbr(want):
    def get(d):
        url = "https://www.cbr.ru/scripts/XML_daily.asp" + ("?date_req=" + d.strftime("%d/%m/%Y") if d else "")
        return tk_parse_cbr(http_bytes(url, 15).decode("windows-1251", "replace"))
    cur = get(None)
    try:
        prev = get(date.today() - timedelta(days=1))
    except Exception:  # noqa: BLE001
        prev = {}
    return tk_cbr_items(cur, prev, want)


def tk_fetch_btc():
    mem = mem_get(("tk_btc",), 60)
    if mem is not None:
        return mem or None
    it = None
    try:
        it = tk_parse_btc(json.loads(_tk_get("https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd,rub&include_24hr_change=true")), "coingecko")
    except Exception:  # noqa: BLE001
        pass
    if not it:
        try:
            it = tk_parse_btc(json.loads(_tk_get("https://api.binance.com/api/v3/ticker/24hr?symbol=BTCUSDT")), "binance")
        except Exception:  # noqa: BLE001
            pass
    mem_put(("tk_btc",), it or {})
    return it


def ticker_payload(force=False):
    ttl = 60 if _stk_trading() else 600
    key = ("tk_payload",)
    hit = None if force else mem_get(key, ttl)
    if hit is not None:
        res = dict(hit)
        btc = tk_fetch_btc()      # BTC торгуется круглосуточно: свой кэш 60 с
        res["items"] = [btc if i["id"] == "BTC" and btc else i for i in hit["items"]]
        if btc and not any(i["id"] == "BTC" for i in res["items"]):
            res["items"].append(btc)
        return res
    def _run(fn):
        try:
            return fn()
        except Exception:  # noqa: BLE001
            return None

    idx_it, stk_rows, cets_raw, btc_it = pool_map(
        _run,
        [tk_fetch_index, lambda: tk_parse_stocks(stocks_universe(force)), tk_fetch_cets, tk_fetch_btc],
        workers=4,
    )
    items = []
    if idx_it:
        items.append(idx_it)
    if stk_rows:
        items += stk_rows
    cets = dict(cets_raw or {})
    miss = [c for c in ("USD", "CNY", "EUR") if c not in cets]
    if miss:
        cbr = _run(lambda: tk_fetch_cbr(miss))
        if cbr:
            cets.update(cbr)
    for c in ("USD", "CNY", "EUR", "GOLD"):
        if c in cets:
            items.append(cets[c])
    if btc_it:
        items.append(btc_it)
    res = {"items": items, "updated": time.time()}
    if items:
        mem_put(key, res)
    return res


def _api_ticker(cfg, acc, q, force):
    return ticker_payload(bool(force))


API_GET["/api/ticker"] = _api_ticker

# ── оболочка (собранное приложение .app/.exe): устарела ли она ──
# Автообновление меняет только tinvest_analytics.py; окно, иконка и экран обновления живут в самой оболочке.
# Оболочка сообщает свою ревизию через TINVEST_SHELL_REV (с ревизии 2); старые оболочки её не передают.
# Ревизия 3 — заставка на pywebview с бесшовным переходом в окно программы.
# Ревизия 4 — установщик Windows (onedir), значок в трее, автозапуск и обновление оболочки из программы.
SHELL_REV_LATEST = 4
SHELL_RELEASES = "https://github.com/Kos5o4ka/tinvest-analytics/releases/latest"


DEFAULT_CONFIG.setdefault("tray_close", False)      # «При закрытии окна сворачивать в трей» (Windows); по умолчанию выключено
AUTOSTART_KEY = r"Software\Microsoft\Windows\CurrentVersion\Run"
AUTOSTART_NAME = "TAnalytic"                         # то же имя значения пишет установщик (packaging/TAnalytic.iss)


def shell_rev(env=None):
    env = os.environ if env is None else env
    try:
        return int(env.get("TINVEST_SHELL_REV") or 0)
    except ValueError:
        return 0


def tray_supported(env=None, frozen=None, plat=None):
    """Трей и автозапуск — только у собранной оболочки ревизии 4+ на Windows (на macOS пункты скрыты)."""
    frozen = bool(getattr(sys, "frozen", False)) if frozen is None else frozen
    return bool(frozen and (sys.platform if plat is None else plat) == "win32" and shell_rev(env) >= 4)


def autostart_command(exe=None):
    return '"%s" --tray' % (exe or sys.executable)


def autostart_get(reg=None):
    """Включён ли запуск вместе с Windows: есть ли значение TAnalytic в HKCU\\...\\Run. reg — модуль winreg (подменяется в тестах)."""
    try:
        reg = reg or __import__("winreg")
        k = reg.OpenKey(reg.HKEY_CURRENT_USER, AUTOSTART_KEY, 0, reg.KEY_READ)
        try:
            reg.QueryValueEx(k, AUTOSTART_NAME)
            return True
        finally:
            reg.CloseKey(k)
    except Exception:  # noqa: BLE001 — нет ключа, нет winreg (macOS), нет прав
        return False


def autostart_set(on, reg=None, exe=None):
    """Включает или выключает запуск вместе с Windows (запись текущего пользователя, права администратора не нужны)."""
    reg = reg or __import__("winreg")
    if on:
        k = reg.CreateKeyEx(reg.HKEY_CURRENT_USER, AUTOSTART_KEY, 0, reg.KEY_SET_VALUE)
        try:
            reg.SetValueEx(k, AUTOSTART_NAME, 0, reg.REG_SZ, autostart_command(exe))
        finally:
            reg.CloseKey(k)
        return True
    try:
        k = reg.OpenKey(reg.HKEY_CURRENT_USER, AUTOSTART_KEY, 0, reg.KEY_SET_VALUE)
    except OSError:
        return False                                  # ключа нет — выключать нечего
    try:
        reg.DeleteValue(k, AUTOSTART_NAME)
    except OSError:
        pass                                          # значения уже нет
    finally:
        reg.CloseKey(k)
    return False


def tray_close_wanted():
    """Читает лаунчер при закрытии окна (sys.tanalytic_tray)."""
    try:
        return bool(load_config().get("tray_close"))
    except Exception:  # noqa: BLE001
        return False


def shell_status(env=None, frozen=None, cfg=None, reg=None):
    env = os.environ if env is None else env
    frozen = bool(getattr(sys, "frozen", False)) if frozen is None else frozen
    rev = shell_rev(env)
    asset = {"darwin": "TAnalytic-mac-arm64.zip" if platform.machine() == "arm64" else "TAnalytic-mac-x64.zip",
             "win32": "TAnalytic-Setup-win.exe"}.get(sys.platform)
    tray = tray_supported(env, frozen)
    return {"frozen": frozen, "rev": rev, "latest": SHELL_REV_LATEST, "outdated": bool(frozen and rev < SHELL_REV_LATEST),
            "url": SHELL_RELEASES, "asset": asset,
            "tray": tray, "tray_close": bool(tray and (cfg or {}).get("tray_close")),
            "autostart": bool(tray and autostart_get(reg))}


def api_shell_tray(cfg, body):
    if not tray_supported():
        raise ApiError("Трей и автозапуск доступны только в установленной версии для Windows.", 400)
    if "tray_close" in body:
        cfg["tray_close"] = bool(body["tray_close"])
        save_config(cfg)
        hook = getattr(sys, "tanalytic_tray_sync", None)       # лаунчер показывает или убирает значок в трее
        if callable(hook):
            try:
                hook()
            except Exception:  # noqa: BLE001
                pass
    if "autostart" in body:
        try:
            autostart_set(bool(body["autostart"]))
        except Exception as e:  # noqa: BLE001
            raise ApiError("Не удалось изменить автозапуск: %s" % e, 500)
    return shell_status(cfg=cfg)


API_GET["/api/shell"] = lambda cfg, acc, q, force: shell_status(cfg=cfg)
API_POST["/api/shell/tray"] = api_shell_tray
sys.tanalytic_tray = tray_close_wanted               # лаунчер спрашивает при закрытии окна: свернуть в трей или выйти
# ═══════════════════════════════ HTTP-сервер ═══════════════════════════════

_ping = [0.0]
# секреты, которые окно настроек может показать по кнопке «глаз» (GET /api/config/secret)
UI_SECRET_NAMES = ("token", "data_key", "backup_password")


class Handler(BaseHTTPRequestHandler):
    server_version = "TAnalytic/3.0"

    def log_message(self, *a):
        pass

    def send(self, code, body, ctype="application/json; charset=utf-8", headers=None):
        if isinstance(body, (dict, list)):
            body = json.dumps(body, ensure_ascii=False, separators=(",", ":"), default=str).encode()
        elif isinstance(body, str):
            body = body.encode()
        gz = len(body) > 2048 and ctype.startswith(("application/json", "text/")) and \
            "gzip" in (self.headers.get("Accept-Encoding") or "")
        if gz:
            body = gzip.compress(body, 5)
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "max-age=604800" if ctype == "image/png" else "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Content-Security-Policy",
                         "default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' data:")
        if gz:
            self.send_header("Content-Encoding", "gzip")
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def ok_host(self):
        port = self.server.server_address[1]
        return self.headers.get("Host", "") in ("127.0.0.1:%d" % port, "localhost:%d" % port, "[::1]:%d" % port)

    def guard(self, fn):
        try:
            fn()
        except ApiError as e:
            self.send(e.status if 400 <= e.status < 600 else 502, {"error": str(e)})
        except (BrokenPipeError, ConnectionResetError):
            pass
        except Exception as e:  # noqa: BLE001
            import traceback
            traceback.print_exc()
            self.send(500, {"error": "%s: %s" % (type(e).__name__, e)})

    def _reply(self, res):
        if isinstance(res, tuple):
            code, body = res[0], res[1]
            ctype = res[2] if len(res) > 2 and res[2] else "application/json; charset=utf-8"
            return self.send(code, body, ctype, res[3] if len(res) > 3 else None)
        return self.send(200, res)

    def do_GET(self):
        if not self.ok_host():
            return self.send(403, {"error": "forbidden"})
        u = urlparse(self.path)
        if u.path.startswith("/api/") and self.headers.get("Sec-Fetch-Site") not in (None, "same-origin", "none"):
            return self.send(403, {"error": "forbidden"})
        q = {k: v[0] for k, v in parse_qs(u.query).items()}

        def run():
            if u.path == "/":
                return self.send(200, PAGE, "text/html; charset=utf-8")
            if u.path.startswith("/logo/"):
                data = logo_bytes(unquote(u.path[6:]))
                return self.send(200, data, "image/png") if data else self.send(404, {"error": "no logo"})
            if u.path == "/api/ping":
                _ping[0] = time.time()
                return self.send(200, {"ok": True, "app": APP_NAME})
            cfg = load_config()
            f = q.get("force") == "1"
            acc = q.get("account", "all") or "all"
            if u.path == "/api/config":
                pub = {k: v for k, v in cfg.items() if k not in SECRET_KEYS}
                pub["secret_set"] = {k: bool(cfg.get(k)) for k in SECRET_KEYS if k != "token"}
                pub.update(token_set=bool(cfg["token"]), token_hint=("…" + cfg["token"][-4:]) if cfg["token"] else "",
                           imports=[dict(x, broker_id=broker_of_account(x)[0]) for x in imports_list()],
                           brokers=BROKERS, data_dir=APP_DIR, version=APP_VERSION)
                return self.send(200, pub)
            if u.path == "/api/config/secret":
                # Сохранённый секрет — только своему окну: Host проверен выше, плюс собственный заголовок
                # (чужая страница не может его поставить без CORS-preflight, который мы не разрешаем). Не логируем.
                if self.headers.get("X-TA-Secret") != "1" or \
                        self.headers.get("Sec-Fetch-Site") not in (None, "same-origin"):
                    return self.send(403, {"error": "forbidden"})
                name = q.get("name", "")
                if name not in UI_SECRET_NAMES or name not in SECRET_KEYS:
                    return self.send(400, {"error": "unknown secret"})
                return self.send(200, {"name": name, "value": str(cfg.get(name) or "")})
            if u.path == "/api/summary":
                return self.send(200, build_summary(cfg, acc, q.get("period", "all"), f))
            if u.path == "/api/bonds":
                return self.send(200, build_bonds(cfg, acc, f))
            if u.path == "/api/history":
                return self.send(200, build_history_for(cfg, acc, f))
            if u.path == "/api/operations.csv":
                data = build_summary(cfg, acc, q.get("period", "all"))
                return self.send(200, operations_csv(data), "text/csv; charset=utf-8",
                                 {"Content-Disposition": 'attachment; filename="operations.csv"'})
            if u.path == "/api/screener":
                return self.send(200, screener_payload())
            if u.path == "/api/spark":
                try:
                    return self.send(200, spark_payload([x for x in (q.get("ids") or "").split(",") if x][:SPARK_MAX_IDS]))
                except Exception:  # noqa: BLE001
                    return self.send(200, {})
            if u.path == "/api/bond":
                return self.send(200, bond_card(q.get("isin", "")))
            if u.path == "/api/primary":
                return self.send(200, primary_payload())
            if u.path == "/api/ratings":
                return self.send(200, ratings_status())
            if u.path == "/api/keyrate":
                return self.send(200, keyrate_brief() or {"source": "none", "name": "", "yearly": []})
            if u.path == "/api/risk":
                return self.send(200, build_risk(cfg, acc, q))
            if u.path == "/api/signals":
                return self.send(200, signals_payload(cfg, acc, q))
            if u.path == "/api/monitor":
                return self.send(200, build_monitor(cfg, acc))
            if u.path == "/api/bench":
                return self.send(200, bench_payload(cfg, acc, q))
            if u.path == "/api/calc":
                return self.send(200, calc_params(cfg, acc))
            if u.path == "/api/offers":
                return self.send(200, offers_payload(cfg, acc))
            if u.path == "/api/ladder":
                return self.send(200, ladder_payload(cfg, q))
            if u.path == "/api/rates":
                return self.send(200, rates_payload(q.get("days", "365"), q.get("terms", "2")))
            if u.path == "/api/backup":
                return self.send(200, make_backup(), "application/zip",
                                 {"Content-Disposition": 'attachment; filename="tinvest_backup_%s.zip"' % date.today().isoformat()})
            if u.path == "/api/import/template.csv":
                return self.send(200, TEMPLATE_CSV.encode("utf-8-sig"), "text/csv; charset=utf-8",
                                 {"Content-Disposition": 'attachment; filename="import_template.csv"'})
            fn = API_GET.get(u.path)
            if fn:
                return self._reply(fn(cfg, acc, q, f))
            self.send(404, {"error": "not found"})
        self.guard(run)

    def do_POST(self):
        # Sec-Fetch-Site: запросы с чужих сайтов отклоняем (защита от CSRF; старые браузеры заголовок не шлют)
        if not self.ok_host() or "application/json" not in (self.headers.get("Content-Type") or "") \
                or self.headers.get("Sec-Fetch-Site") not in (None, "same-origin", "none"):
            return self.send(403, {"error": "forbidden"})
        path = urlparse(self.path).path

        def run():
            try:
                n = int(self.headers.get("Content-Length") or 0)
            except (TypeError, ValueError):
                raise ApiError("Некорректный заголовок Content-Length.", 400)
            if n < 0 or n > 80 * 1024 * 1024:
                raise ApiError("Файл слишком большой (больше 60 МБ)." if n > 0 else "Некорректный заголовок Content-Length.", 400)
            try:
                body = json.loads(self.rfile.read(n) or b"{}") if n else {}
            except (ValueError, UnicodeDecodeError):
                raise ApiError("Некорректный JSON.", 400)
            if not isinstance(body, dict):
                raise ApiError("Ожидался JSON-объект.", 400)
            cfg = load_config()
            if path == "/api/config":
                if body.get("token"):
                    cfg["token"] = "".join(str(body["token"]).split())
                if body.get("clear_token"):
                    cfg["token"] = ""
                for k in ("sandbox", "verify_ssl"):
                    if k in body:
                        cfg[k] = bool(body[k])
                if "ca_file" in body:
                    cfg["ca_file"] = str(body["ca_file"]).strip()
                if body.get("theme") in ("auto", "dark", "light"):
                    cfg["theme"] = body["theme"]
                if isinstance(body.get("targets"), dict):
                    tg = {}
                    for k, v in body["targets"].items():
                        try:
                            x = float(v)
                        except (TypeError, ValueError):
                            continue
                        if 0 < x <= 100:
                            tg[str(k)[:24]] = round(x, 2)
                    cfg["targets"] = tg
                if isinstance(body.get("ui_seen"), dict):
                    seen = dict(cfg.get("ui_seen") if isinstance(cfg.get("ui_seen"), dict) else {})
                    for k, v in body["ui_seen"].items():
                        k = str(k)[:40]
                        if isinstance(v, bool) or (isinstance(v, (int, float)) and abs(v) < 1e15):
                            seen[k] = v
                        elif isinstance(v, str):
                            seen[k] = v[:64]
                        elif isinstance(v, dict):
                            seen[k] = {str(a)[:40]: (1 if b else 0) for a, b in list(v.items())[:80]}
                    cfg["ui_seen"] = dict(list(seen.items())[:40])
                if isinstance(body.get("broker_tariffs"), dict):
                    bt = dict(cfg.get("broker_tariffs") if isinstance(cfg.get("broker_tariffs"), dict) else {})
                    for k, v in list(body["broker_tariffs"].items())[:200]:
                        k = str(k)[:64]
                        if not v:
                            bt.pop(k, None)
                        elif isinstance(v, str) and re.fullmatch(r"[a-z0-9_]{1,40}", v):
                            bt[k] = v
                    cfg["broker_tariffs"] = bt
                if body.get("keyrate_mode") in KR_MODES:
                    cfg["keyrate_mode"] = body["keyrate_mode"]
                if "notify_days" in body:
                    try:
                        cfg["notify_days"] = max(0, min(60, int(body["notify_days"])))
                    except (TypeError, ValueError):
                        pass
                for k, lo, hi in (("mon_drop5", 0.1, 50), ("mon_drop30", 0.1, 90), ("mon_spread30", 0.1, 50),
                                  ("mon_sell_days", 0.5, 365), ("mon_offer_days", 1, 365)):
                    if k in body:
                        try:
                            cfg[k] = max(lo, min(hi, float(body[k])))
                        except (TypeError, ValueError):
                            pass
                for k in ("hosts_prod", "hosts_sandbox"):
                    if isinstance(body.get(k), list):
                        hosts = [str(h).strip() for h in body[k] if str(h).strip()]
                        if hosts:
                            cfg[k] = hosts
                if str(cfg.get("data_server") or "").strip().lower() == "off":
                    cfg["data_server"] = ""         # «off» из прежних версий: сервер данных теперь не отключается
                if body.get("data_key"):
                    cfg["data_key"] = "".join(str(body["data_key"]).split())
                if body.get("clear_data_key"):
                    cfg["data_key"] = ""
                if cfg["ca_file"] and not os.path.isfile(cfg["ca_file"]):
                    raise ApiError("Файл сертификата не найден: " + cfg["ca_file"], 400)
                save_config(cfg)
                ds_reset()
                mem_clear(persist=False)        # сохранённые отчёты привязаны к токену (token_key): настройки их не портят
                return self.send(200, {"ok": True, "app": APP_NAME})
            if path == "/api/ratings/refresh":
                return self.send(200, {"started": ratings_start(force=True), **ratings_status()})
            client = TInvest(cfg)
            if path == "/api/test":
                tcli = client
                if body.get("token"):
                    tcfg = dict(cfg, token="".join(str(body["token"]).split()))
                    if "sandbox" in body:
                        tcfg["sandbox"] = bool(body["sandbox"])
                    tcli = TInvest(tcfg)
                return self.send(200, {"ok": True, "accounts": len(tcli.accounts())})
            if path == "/api/cache/clear":
                clear_local_cache()
                st = store()
                with st.wlock:
                    c = st.conn()
                    c.execute("DELETE FROM ops WHERE acc NOT LIKE 'imp-%'")
                    c.commit()
                mem_clear()
                return self.send(200, {"ok": True, "app": APP_NAME})
            if path == "/api/import/preview":
                raw = base64.b64decode(body.get("data") or "")
                pv = import_preview_any(body.get("filename") or "", raw)
                bid = broker_detect_import(body.get("filename") or "", raw, pv.get("format") or "")
                pv["broker_id"], pv["broker_name"] = bid, BROKERS[bid]
                return self.send(200, pv)
            if path == "/api/import/parse":
                return self.send(200, import_parse_info(body))
            if path == "/api/import/commit":
                return self.send(200, import_commit(client, body))
            if path == "/api/import/broker":
                bid = str(body.get("broker_id") or "")
                if bid not in BROKERS:
                    raise ApiError("Неизвестный брокер.", 400)
                lst = imports_list()
                ex = next((x for x in lst if x["id"] == body.get("id")), None)
                if ex is None:
                    raise ApiError("Импортированный счёт не найден.", 404)
                ex["broker_id"] = bid
                store().put("imports", lst)
                mem_clear()
                return self.send(200, {"ok": True, "broker_id": bid})
            if path == "/api/import/delete":
                lst = [x for x in imports_list() if x["id"] != body.get("id")]
                store().put("imports", lst)
                store().ops_clear(body.get("id") or "")
                mem_clear()
                return self.send(200, {"ok": True, "app": APP_NAME})
            if path in ("/api/sandbox/open", "/api/sandbox/payin"):
                if not cfg["sandbox"]:
                    raise ApiError("Доступно только в режиме песочницы.", 400)
                mem_clear()
                if path.endswith("open"):
                    return self.send(200, client.call("SandboxService", "OpenSandboxAccount", {"name": "Analytics"}))
                amount = Decimal(str(body.get("amount") or 0))
                if amount <= 0:
                    raise ApiError("Сумма должна быть больше нуля.", 400)
                acc = body.get("accountId")
                if not acc or acc == "all" or str(acc).startswith("imp-"):
                    raise ApiError("Выберите счёт песочницы в списке слева.", 400)
                return self.send(200, client.call("SandboxService", "SandboxPayIn", {"accountId": acc, "amount": to_money(amount)}))
            fn = API_POST.get(path)
            if fn:
                return self._reply(fn(cfg, body))
            self.send(404, {"error": "not found"})
        self.guard(run)


